-- ============================================================
-- apply_006_to_047.sql — applies migrations 006 through 047 in order.
--
-- Paste this whole file into the Supabase SQL editor and run it once.
--
-- Safe to run on a database at any point in this range, and safe to run
-- twice: every migration drops what it recreates and creates nothing
-- unconditionally. Wrapped in a single transaction as well, so an
-- interruption leaves the schema where it started rather than half-way.
--
-- Generated by scripts/build-migration-bundle.sh. Regenerate rather than
-- editing this by hand.
-- ============================================================

begin;


-- ============================================================
-- 006_report_access.sql
-- ============================================================
-- ============================================================
-- 006_report_access.sql
--
-- M3 puts the reports on screen. Before they can be shown to anyone, two
-- things about who may read what have to be fixed.
--
-- 1. A LEAK. `church_account_activity` (002) is a view, and in Postgres 15+ a
--    view runs as its owner unless told otherwise. Its owner is the role that
--    created the tables, which bypasses RLS — so selecting from the view
--    returned every org's daily totals to anybody who asked, including a
--    caller holding nothing but the publishable key, which is public by
--    design and ships inside the web build.
--
--    Every policy in 004 was intact and none of them ever ran. The proof in
--    test_rls.sql was true and beside the point: it tested the tables, and
--    this was a view over them.
--
-- 2. VISIBILITY WAS DECORATION. `memberships.visibility` has meant 'summary'
--    since the first schema, and nothing enforced it. The observer granted
--    summary access — the quieter investor in the schema comment — could read
--    every individual transaction through the API whatever the app drew on
--    screen.
--
-- The second fix forces a change in the reports themselves. Once raw entries
-- are closed to a summary observer, a report that reads those tables as the
-- caller returns nothing at all — including the totals they ARE entitled to.
-- So the three report functions become SECURITY DEFINER and check entitlement
-- themselves: totals for any member, line items only with full visibility.
-- ============================================================

-- ------------------------------------------------------------
-- 1. THE VIEW
-- ------------------------------------------------------------
-- security_invoker makes the view run as whoever selects from it, so the
-- policies on journal_entries, journal_lines and accounts finally apply.
-- Nothing else about the view changes.
alter view church_account_activity set (security_invoker = on);

-- ------------------------------------------------------------
-- 2. WHAT 'summary' MEANS
-- ------------------------------------------------------------
-- Full visibility is held, not inferred: a person with several grants in one
-- org gets the widest of them, which is the same rule my_orgs() already uses
-- when it decides what to send the client.
create or replace function has_full_visibility(p_org_id uuid)
returns boolean
language sql
stable
security definer
set search_path = public, auth
as $$
    select exists (
        select 1 from memberships m
        where m.user_id = auth.uid()
          and m.org_id = p_org_id
          and m.visibility = 'full'
    );
$$;

-- ------------------------------------------------------------
-- 3. LINE ITEMS ARE FOR FULL VISIBILITY ONLY
-- ------------------------------------------------------------
-- Each of these replaces a policy that asked only "are you in this org?".
-- Nothing is widened: every caller who could read these rows before and holds
-- full visibility still can.

drop policy if exists "read within your org" on journal_entries;

drop policy if exists "entries readable with full visibility" on journal_entries;
create policy "entries readable with full visibility"
on journal_entries for select
using (has_full_visibility(org_id));

drop policy if exists "lines readable with their entry" on journal_lines;

drop policy if exists "lines readable with full visibility" on journal_lines;
create policy "lines readable with full visibility"
on journal_lines for select
using (
    exists (
        select 1 from journal_entries je
        where je.id = journal_lines.journal_entry_id
          and has_full_visibility(je.org_id)
    )
);

drop policy if exists "attributions readable with their entry" on contribution_attributions;

-- Who gave what, by name. If anything in this schema is line-item detail,
-- it is this.
drop policy if exists "attributions readable with full visibility" on contribution_attributions;
create policy "attributions readable with full visibility"
on contribution_attributions for select
using (
    exists (
        select 1 from journal_entries je
        where je.id = contribution_attributions.journal_entry_id
          and has_full_visibility(je.org_id)
    )
);

drop policy if exists "documents readable within org" on documents;

-- A receipt is a transaction with a photograph attached.
drop policy if exists "documents readable with full visibility" on documents;
create policy "documents readable with full visibility"
on documents for select
using (has_full_visibility(org_id));

-- ------------------------------------------------------------
-- 4. THE REPORTS
-- ------------------------------------------------------------
-- SECURITY DEFINER, because a summary observer can no longer read the tables
-- these are computed from and is still entitled to the total. Each one
-- therefore checks entitlement itself rather than leaning on RLS underneath,
-- and each is gated inside the query so a non-member gets an empty result
-- instead of an error that would confirm the org exists.

-- Totals and per-account lines for the week. Any member may call it; the
-- caller decides how much of the answer to show, and RLS no longer can,
-- so the line detail is gated here too.
create or replace function church_weekly_summary(
    p_org_id uuid,
    p_week_ending date default current_date
)
returns table (
    category text,
    label    text,
    amount   numeric
)
language sql
stable
security definer
set search_path = public, auth
as $$
    with access as (
        select is_org_member(p_org_id) as member,
               has_full_visibility(p_org_id) as detailed
    ),
    window_bounds as (
        select (p_week_ending - interval '6 days')::date as start_date,
               p_week_ending as end_date
    ),
    lines as (
        select a.type, a.name, jl.debit, jl.credit
        from journal_entries je
        join journal_lines jl on jl.journal_entry_id = je.id
        join accounts a on a.id = jl.account_id
        cross join window_bounds w
        cross join access x
        where x.member
          and je.org_id = p_org_id
          and je.created_at::date between w.start_date and w.end_date
    )
    -- Per-account detail: withheld from a summary observer.
    select 'income'::text, name, sum(credit - debit)
    from lines cross join access x
    where type = 'income' and x.detailed
    group by name having sum(credit - debit) <> 0

    union all

    select 'expense'::text, name, sum(debit - credit)
    from lines cross join access x
    where type = 'expense' and x.detailed
    group by name having sum(debit - credit) <> 0

    union all

    -- The two totals: the whole of what a summary observer was granted.
    select 'total'::text, 'Total received', coalesce(sum(credit - debit), 0)
    from lines where type = 'income'

    union all

    select 'total'::text, 'Total spent', coalesce(sum(debit - credit), 0)
    from lines where type = 'expense'

    order by 1, 2;
$$;

-- Cash position. A balance is a total by definition, so any member of the org
-- may see it whatever their visibility.
create or replace function church_balances(p_org_id uuid)
returns table (account_name text, balance numeric)
language sql
stable
security definer
set search_path = public, auth
as $$
    select a.name, coalesce(sum(jl.debit - jl.credit), 0)
    from accounts a
    left join journal_lines jl on jl.account_id = a.id
    where a.org_id = p_org_id
      and a.type = 'asset'
      and is_org_member(p_org_id)
    group by a.name
    order by a.name;
$$;

-- One named person's giving. This is the most private thing the church module
-- holds, so it needs full visibility and not merely membership.
create or replace function member_giving_statement(
    p_member_id uuid,
    p_year      int default extract(year from current_date)::int
)
returns table (contribution_date date, kind text, amount numeric)
language sql
stable
security definer
set search_path = public, auth
as $$
    select je.created_at::date, a.name, jl.credit
    from contribution_attributions ca
    join church_members cm on cm.id = ca.member_id
    join journal_entries je on je.id = ca.journal_entry_id
    join journal_lines jl on jl.journal_entry_id = je.id
    join accounts a on a.id = jl.account_id
    where ca.member_id = p_member_id
      and has_full_visibility(cm.org_id)
      and a.type = 'income'
      and jl.credit > 0
      and extract(year from je.created_at) = p_year
    order by 1;
$$;

-- ------------------------------------------------------------
-- 5. GRANTS
-- ------------------------------------------------------------
-- These are SECURITY DEFINER now, so the PUBLIC default that Postgres applies
-- to a new function would hand them to `anon`. Each one already refuses a
-- caller with no session — auth.uid() is null, so no membership matches — but
-- the grant is made deliberate rather than inherited.
revoke execute on function church_weekly_summary(uuid, date) from public;
revoke execute on function church_balances(uuid) from public;
revoke execute on function member_giving_statement(uuid, int) from public;

-- has_full_visibility() is deliberately left on the PUBLIC default, exactly
-- like the scope helpers in 004. It is named by the policies above, so every
-- role that can attempt a select has to be able to run it — revoking it from
-- anon turns "you may see no rows" into "permission denied for function",
-- which is a worse answer to the same question and breaks the reads an
-- anonymous caller is legitimately allowed to make. It answers only about the
-- caller's own memberships, so it discloses nothing.

do $$
begin
    if exists (select 1 from pg_roles where rolname = 'authenticated') then
        grant execute on function church_weekly_summary(uuid, date) to authenticated;
        grant execute on function church_balances(uuid) to authenticated;
        grant execute on function member_giving_statement(uuid, int) to authenticated;
    end if;
end $$;


-- ============================================================
-- 007_accounting.sql
-- ============================================================
-- ============================================================
-- 007_accounting.sql
--
-- Two things this file is for, and they turn out to be the same thing.
--
-- 1. EVERY ENTRY GETS A NAME. Until now the only entries the app could make
--    were the ones 002 had anticipated: four kinds of contribution and seven
--    expense categories, all hard-coded, in both the SQL and the Flutter
--    sheets. Anything a person actually needed to record that was not on that
--    list had to be filed under whichever category was least wrong. The
--    picker was defended as protecting the books from seven spellings of
--    "Loyer" — but a category list nobody can add to does not produce clean
--    books, it produces books where "Fournitures" means eleven different
--    things and no report can tell them apart.
--
--    So `record_entry()` takes the name the person typed, and
--    `ensure_account()` turns a name into a real account in the chart the
--    first time it is used and finds that same account every time after. The
--    picker survives as what it should always have been: a list of the names
--    already in use, offered first because most entries repeat.
--
-- 2. THE BOOKS BECOME READABLE. The ledger has been double-entry since the
--    first schema and nothing has ever been able to show it as one — no trial
--    balance, no income statement, no balance sheet, no account history.
--    Those are the four reports that make a ledger an accounting system
--    rather than a list, and every one of them is a query over tables that
--    already existed.
--
-- The access rule is the one 006 established and is not widened here:
-- per-account detail needs `visibility = 'full'`, totals are for any member,
-- and line items need full visibility too. Every function below is SECURITY
-- DEFINER for the same reason the reports in 006 are — a summary observer
-- cannot read the tables these are computed from and is still entitled to the
-- total — so every one of them checks entitlement itself.
-- ============================================================

-- ------------------------------------------------------------
-- 1. WHAT AN ENTRY CAN CARRY
-- ------------------------------------------------------------

-- The name the person typed, kept apart from `memo`. They are different
-- things: the label is what this entry IS ("Réparation du toit") and is what
-- every list and report shows; the memo is what someone wanted to say about
-- it ("moitié payée d'avance, reste dû à Kaboré"). Collapsing them, which is
-- what the app did by writing the category name into memo, means a report can
-- either show a useful sentence or group by category, never both.
alter table journal_entries add column if not exists label text;

-- The characteristics. Anything the entry needs that the schema did not
-- anticipate: a supplier, an invoice number, a beneficiary, a quantity, the
-- name of the road that was repaired. jsonb rather than columns because the
-- whole point is that nobody has to have predicted the key.
--
-- Deliberately not indexed and deliberately not queried by the reports below.
-- This is a place to record what happened, not a second schema growing in the
-- dark; anything that earns a report earns a column.
alter table journal_entries
    add column if not exists details jsonb not null default '{}'::jsonb;

-- The date range on every report below filters on created_at, so it stops
-- being a full scan the first year the books get busy.
create index if not exists journal_entries_by_org_date
    on journal_entries (org_id, created_at desc);

-- ------------------------------------------------------------
-- 2. WHAT AN ACCOUNT CAN CARRY
-- ------------------------------------------------------------

-- What this account is for, in the words of whoever created it. A chart of
-- accounts is only self-explanatory to the person who wrote it.
alter table accounts add column if not exists description text;

-- Retired, not deleted. An account with history in it can never be removed —
-- the entries reference it and the reports would lose their labels — so the
-- only honest way to stop offering "Loyer" once the building is bought is to
-- take it off the list and leave the past intact.
alter table accounts add column if not exists is_active boolean not null default true;

alter table accounts add column if not exists created_at timestamptz not null default now();

-- Null for the seeded chart, which nobody created. Set for everything typed
-- into the app afterwards, so a category that turns out to be a duplicate can
-- be traced to the person who needed it.
alter table accounts add column if not exists created_by uuid references profiles(id);

-- ensure_account() finds by name, so the lookup wants an index and the name
-- wants to be matched the way a person means it: case and surrounding spaces
-- are typing, not meaning.
--
-- Not a UNIQUE index, on purpose. A unique constraint here would be the
-- correct model and could fail this migration against books that already
-- contain a duplicate — and refusing to migrate somebody's live database over
-- two accounts both called "Divers" is a worse outcome than tolerating them.
-- ensure_account() takes the oldest match, so a pre-existing duplicate keeps
-- receiving entries where it always did and never becomes the reason a new
-- entry fails.
create index if not exists accounts_by_org_type_name
    on accounts (org_id, type, lower(btrim(name)));

-- ------------------------------------------------------------
-- 3. MINTING AN ACCOUNT
-- ------------------------------------------------------------

-- Codes are banded by type, the way every chart of accounts is: assets in the
-- 1000s, liabilities 2000s, equity 3000s, income 4000s, expenses 5000s. The
-- seeded church chart in 002 already follows this, so a church that has been
-- running since before this migration keeps its numbering and new accounts
-- continue it.
create or replace function account_code_band(p_type text)
returns int
language sql
immutable
as $$
    select case p_type
        when 'asset'     then 1000
        when 'liability' then 2000
        when 'equity'    then 3000
        when 'income'    then 4000
        when 'expense'   then 5000
    end;
$$;

-- The next free code in the type's band, in tens — leaving room to slot an
-- account between two others later, which is the one thing you always want
-- from a numbering scheme and can never retrofit.
create or replace function next_account_code(p_org_id uuid, p_type text)
returns text
language plpgsql
stable
as $$
declare
    v_band int := account_code_band(p_type);
    v_next int;
begin
    if v_band is null then
        raise exception 'Unknown account type: %', p_type;
    end if;

    -- Codes are text and a hand-entered chart may hold codes that are not
    -- numbers at all. Those are left alone rather than crashing the count.
    select coalesce(max(a.code::int), v_band - 10) + 10
      into v_next
      from accounts a
     where a.org_id = p_org_id
       and a.code ~ '^[0-9]+$'
       and a.code::int between v_band and v_band + 999;

    if v_next > v_band + 999 then
        raise exception
            'No free % code left for org % — the % band is full',
            p_type, p_org_id, v_band;
    end if;

    return v_next::text;
end;
$$;

-- Find by name, create if absent. This is the function that makes a typed
-- name into real accounting.
--
-- Not SECURITY DEFINER and not granted to anybody: it is an internal helper
-- called from inside the definer functions below, which have already
-- established that the caller may write to this org. Called directly by an
-- authenticated user it would insert under RLS, where the policy in 004 lets
-- only an org admin add an account — which is the correct answer to a caller
-- who arrived by a route with no permission check in it.
create or replace function ensure_account(
    p_org_id  uuid,
    p_name    text,
    p_type    text,
    p_actor   uuid default null
)
returns uuid
language plpgsql
as $$
declare
    v_name text := btrim(coalesce(p_name, ''));
    v_id   uuid;
begin
    if v_name = '' then
        raise exception 'An account needs a name';
    end if;

    if account_code_band(p_type) is null then
        raise exception 'Unknown account type: %', p_type;
    end if;

    -- Oldest match wins, so books that already hold two accounts of the same
    -- name keep posting to the one that has the history.
    select a.id into v_id
      from accounts a
     where a.org_id = p_org_id
       and a.type = p_type
       and lower(btrim(a.name)) = lower(v_name)
     order by a.created_at, a.code
     limit 1;

    if v_id is not null then
        return v_id;
    end if;

    insert into accounts (org_id, code, name, type, created_by)
    values (p_org_id, next_account_code(p_org_id, p_type), v_name, p_type, p_actor)
    returning id into v_id;

    return v_id;
end;
$$;

-- The same, for the three accounts whose code the app relies on. A church
-- seeded by 002 already has them; an org created any other way may not, and
-- "record what you were paid in cash" should not fail because nobody ran the
-- seeder.
create or replace function ensure_account_by_code(
    p_org_id uuid,
    p_code   text,
    p_name   text,
    p_type   text,
    p_actor  uuid default null
)
returns uuid
language plpgsql
as $$
declare
    v_id uuid;
begin
    select id into v_id from accounts where org_id = p_org_id and code = p_code;
    if v_id is not null then
        return v_id;
    end if;

    insert into accounts (org_id, code, name, type, created_by)
    values (p_org_id, p_code, p_name, p_type, p_actor)
    returning id into v_id;

    return v_id;
end;
$$;

-- Where the money physically sits. The three known methods keep the codes 002
-- seeded so a church's existing balances stay on the accounts they are on;
-- anything else the caller sends is a name someone typed — a second till, a
-- named agent, a savings box — and becomes an asset account of its own.
create or replace function resolve_cash_account(
    p_org_id uuid,
    p_method text,
    p_actor  uuid default null
)
returns uuid
language plpgsql
as $$
begin
    return case btrim(lower(coalesce(p_method, 'cash')))
        when 'cash'         then ensure_account_by_code(p_org_id, '1000', 'Cash on Hand', 'asset', p_actor)
        when 'bank'         then ensure_account_by_code(p_org_id, '1010', 'Bank Account', 'asset', p_actor)
        when 'mobile_money' then ensure_account_by_code(p_org_id, '1020', 'Mobile Money', 'asset', p_actor)
        else ensure_account(p_org_id, p_method, 'asset', p_actor)
    end;
end;
$$;

-- ------------------------------------------------------------
-- 4. RECORDING ANYTHING
-- ------------------------------------------------------------
-- record_contribution() and record_expense() in 002 stay exactly as they are.
-- Books recorded through them are already in the ledger and the church tests
-- cover them; this is the general form, and it is what the app posts now.
--
-- SECURITY DEFINER because it does two things RLS would refuse on the
-- caller's behalf: it mints an account (admin-only under 004) and it writes a
-- ledger row for an org whose scope the caller may hold at department level.
-- So it makes the check itself, first, and the check is the same one the
-- policy would have made.
create or replace function record_entry(
    p_org_id        uuid,
    p_amount        numeric,
    p_direction     text,                       -- 'in' | 'out'
    p_label         text,                       -- what the person typed. Required.
    p_recorded_by   uuid        default null,   -- must be the caller; the app sends it
    p_category      text        default null,   -- income/expense account name; defaults to the label
    p_method        text        default 'cash', -- 'cash' | 'bank' | 'mobile_money' | any account name
    p_member_id     uuid        default null,
    p_memo          text        default null,
    p_details       jsonb       default '{}'::jsonb,
    p_entity_id     uuid        default null,
    p_department_id uuid        default null,
    p_client_uuid   uuid        default null,
    p_device_id     text        default null,
    p_occurred_at   timestamptz default now()
)
returns uuid
language plpgsql
security definer
set search_path = public, auth
as $$
declare
    v_actor        uuid := auth.uid();
    v_label        text := btrim(coalesce(p_label, ''));
    v_category     text;
    v_entry_id     uuid;
    v_cash_acct    uuid;
    v_result_acct  uuid;
    v_existing     uuid;
begin
    if v_actor is null then
        raise exception 'record_entry() needs a signed-in caller';
    end if;

    -- The app sends the user id it thinks it is, and a mismatch means the
    -- device is confused about who is holding it — which is exactly the case
    -- the handover guard in the Flutter app exists to prevent. Refuse rather
    -- than quietly record the work under the wrong name.
    if p_recorded_by is not null and p_recorded_by <> v_actor then
        raise exception 'record_entry() cannot record on behalf of another user';
    end if;

    -- The same test the insert policy on journal_entries makes: everyone but
    -- an observer. Made here because the definer context skips the policy.
    if not can_write_org(p_org_id) then
        raise exception 'You cannot record entries for this business';
    end if;

    if p_amount is null or p_amount <= 0 then
        raise exception 'Amount must be greater than zero (got %)', p_amount;
    end if;

    if p_direction not in ('in', 'out') then
        raise exception 'Direction must be in or out (got %)', p_direction;
    end if;

    if v_label = '' then
        raise exception 'An entry needs a name';
    end if;

    -- Idempotency, identical to 002: a retried sync returns the original
    -- entry. This is what lets the device fire and forget.
    if p_client_uuid is not null then
        select id into v_existing
          from journal_entries
         where org_id = p_org_id and client_uuid = p_client_uuid;
        if found then
            return v_existing;
        end if;
    end if;

    -- No category typed means the name IS the category. Someone recording
    -- "Réparation du toit" once wants a line in the books; someone recording
    -- it monthly wants a category, and by the second month they have one.
    v_category := coalesce(nullif(btrim(coalesce(p_category, '')), ''), v_label);

    v_cash_acct := resolve_cash_account(p_org_id, p_method, v_actor);
    v_result_acct := ensure_account(
        p_org_id,
        v_category,
        case p_direction when 'in' then 'income' else 'expense' end,
        v_actor
    );

    insert into journal_entries (
        org_id, entity_id, department_id, label, memo, details,
        created_by, created_at, device_id, client_uuid
    )
    values (
        p_org_id, p_entity_id, p_department_id, v_label, p_memo,
        coalesce(p_details, '{}'::jsonb),
        v_actor, p_occurred_at, p_device_id, p_client_uuid
    )
    returning id into v_entry_id;

    if p_direction = 'in' then
        -- Money in: the asset grows, the income account is credited.
        insert into journal_lines (journal_entry_id, account_id, debit, credit) values
            (v_entry_id, v_cash_acct,   p_amount, 0),
            (v_entry_id, v_result_acct, 0,        p_amount);
    else
        -- Money out: the expense is incurred, the asset it came from shrinks.
        insert into journal_lines (journal_entry_id, account_id, debit, credit) values
            (v_entry_id, v_result_acct, p_amount, 0),
            (v_entry_id, v_cash_acct,   0,        p_amount);
    end if;

    if p_member_id is not null then
        insert into contribution_attributions (journal_entry_id, member_id)
        values (v_entry_id, p_member_id);
    end if;

    return v_entry_id;
end;
$$;

-- Money that moved without being earned or spent: cash banked, a withdrawal
-- for the week's purchases, a top-up of the mobile money float.
--
-- This exists because without it every deposit gets recorded as an expense
-- from cash and income to the bank, which inflates both sides of the income
-- statement by the same amount and makes the books say the business earned
-- money by moving its own money.
create or replace function record_transfer(
    p_org_id      uuid,
    p_amount      numeric,
    p_from_method text,
    p_to_method   text,
    p_recorded_by uuid        default null,
    p_label       text        default null,
    p_memo        text        default null,
    p_client_uuid uuid        default null,
    p_device_id   text        default null,
    p_occurred_at timestamptz default now()
)
returns uuid
language plpgsql
security definer
set search_path = public, auth
as $$
declare
    v_actor    uuid := auth.uid();
    v_from     uuid;
    v_to       uuid;
    v_entry_id uuid;
    v_existing uuid;
begin
    if v_actor is null then
        raise exception 'record_transfer() needs a signed-in caller';
    end if;
    if p_recorded_by is not null and p_recorded_by <> v_actor then
        raise exception 'record_transfer() cannot record on behalf of another user';
    end if;
    if not can_write_org(p_org_id) then
        raise exception 'You cannot record entries for this business';
    end if;
    if p_amount is null or p_amount <= 0 then
        raise exception 'Amount must be greater than zero (got %)', p_amount;
    end if;

    if p_client_uuid is not null then
        select id into v_existing
          from journal_entries
         where org_id = p_org_id and client_uuid = p_client_uuid;
        if found then
            return v_existing;
        end if;
    end if;

    v_from := resolve_cash_account(p_org_id, p_from_method, v_actor);
    v_to   := resolve_cash_account(p_org_id, p_to_method, v_actor);

    -- Both sides the same account is a no-op that would still write two lines
    -- and a row in the day's list, which reads as money having moved.
    if v_from = v_to then
        raise exception 'A transfer needs two different accounts';
    end if;

    insert into journal_entries (
        org_id, label, memo, created_by, created_at, device_id, client_uuid
    )
    values (
        p_org_id,
        coalesce(nullif(btrim(coalesce(p_label, '')), ''), 'Transfert'),
        p_memo, v_actor, p_occurred_at, p_device_id, p_client_uuid
    )
    returning id into v_entry_id;

    insert into journal_lines (journal_entry_id, account_id, debit, credit) values
        (v_entry_id, v_to,   p_amount, 0),
        (v_entry_id, v_from, 0,        p_amount);

    return v_entry_id;
end;
$$;

-- Adding a category deliberately, from the admin screen, rather than as a
-- side effect of recording something. Admin-only: this is the chart of
-- accounts being designed, not used.
create or replace function create_account(
    p_org_id      uuid,
    p_name        text,
    p_type        text,
    p_description text default null,
    p_code        text default null
)
returns uuid
language plpgsql
security definer
set search_path = public, auth
as $$
declare
    v_name text := btrim(coalesce(p_name, ''));
    v_id   uuid;
begin
    if not is_org_admin(p_org_id) then
        raise exception 'Only an administrator may change the chart of accounts';
    end if;
    if v_name = '' then
        raise exception 'An account needs a name';
    end if;
    if account_code_band(p_type) is null then
        raise exception 'Unknown account type: %', p_type;
    end if;

    if exists (
        select 1 from accounts a
        where a.org_id = p_org_id
          and a.type = p_type
          and lower(btrim(a.name)) = lower(v_name)
    ) then
        raise exception 'An account called % already exists', v_name;
    end if;

    insert into accounts (org_id, code, name, type, description, created_by)
    values (
        p_org_id,
        coalesce(nullif(btrim(coalesce(p_code, '')), ''), next_account_code(p_org_id, p_type)),
        v_name, p_type, nullif(btrim(coalesce(p_description, '')), ''), auth.uid()
    )
    returning id into v_id;

    return v_id;
end;
$$;

-- ------------------------------------------------------------
-- 5. THE CHART, AS A LIST WITH MONEY ON IT
-- ------------------------------------------------------------
-- Balances are shown in each type's natural direction — an expense account of
-- 40,000 reads as 40,000 spent, not as -40,000 — because this list is for
-- people choosing a category, not for proving the books balance. That proof
-- is trial_balance(), one function down, and it keeps the raw signs.
create or replace function chart_of_accounts(p_org_id uuid)
returns table (
    account_id  uuid,
    code        text,
    name        text,
    type        text,
    description text,
    is_active   boolean,
    balance     numeric,
    entry_count bigint
)
language sql
stable
security definer
set search_path = public, auth
as $$
    select
        a.id, a.code, a.name, a.type, a.description, a.is_active,
        coalesce(sum(
            case when a.type in ('asset', 'expense')
                 then jl.debit - jl.credit
                 else jl.credit - jl.debit
            end
        ), 0),
        count(jl.id)
    from accounts a
    left join journal_lines jl on jl.account_id = a.id
    where a.org_id = p_org_id
      and is_org_member(p_org_id)
    group by a.id, a.code, a.name, a.type, a.description, a.is_active
    order by a.code;
$$;

-- ------------------------------------------------------------
-- 6. TRIAL BALANCE — the proof
-- ------------------------------------------------------------
-- Raw debits and credits, no interpretation. The one thing it exists to show
-- is that the two columns are equal; a difference means something wrote to
-- the ledger without going through the functions, and no other report will
-- tell you that.
--
-- Any member may read it. A trial balance is entirely totals, and a summary
-- observer is entitled to totals — that is what 006 decided 'summary' means.
create or replace function trial_balance(
    p_org_id uuid,
    p_from   date default null,
    p_to     date default null
)
returns table (
    code         text,
    name         text,
    type         text,
    total_debit  numeric,
    total_credit numeric,
    balance      numeric
)
language sql
stable
security definer
set search_path = public, auth
as $$
    select
        a.code, a.name, a.type,
        coalesce(sum(jl.debit), 0),
        coalesce(sum(jl.credit), 0),
        coalesce(sum(jl.debit - jl.credit), 0)
    from accounts a
    left join journal_lines jl on jl.account_id = a.id
    left join journal_entries je
           on je.id = jl.journal_entry_id
          and (p_from is null or je.created_at::date >= p_from)
          and (p_to   is null or je.created_at::date <= p_to)
    where a.org_id = p_org_id
      and is_org_member(p_org_id)
      -- A line whose entry fell outside the window must not contribute its
      -- amount; the left join keeps the account visible with zeroes.
      and (jl.id is null or je.id is not null)
    group by a.code, a.name, a.type
    having a.type is not null
    order by a.code;
$$;

-- ------------------------------------------------------------
-- 7. INCOME STATEMENT — did it earn or lose
-- ------------------------------------------------------------
-- Per-account detail for full visibility; the three totals for any member.
-- Same split as church_weekly_summary in 006, and for the same reason: the
-- investor entitled to know whether the business is sound is not thereby
-- entitled to read every line in it.
create or replace function income_statement(
    p_org_id uuid,
    p_from   date default null,
    p_to     date default null
)
returns table (
    section text,     -- 'income' | 'expense' | 'total'
    code    text,
    name    text,
    amount  numeric
)
language sql
stable
security definer
set search_path = public, auth
as $$
    with access as (
        select is_org_member(p_org_id) as member,
               has_full_visibility(p_org_id) as detailed
    ),
    lines as (
        select a.type, a.code, a.name, jl.debit, jl.credit
        from journal_entries je
        join journal_lines jl on jl.journal_entry_id = je.id
        join accounts a on a.id = jl.account_id
        cross join access x
        where x.member
          and je.org_id = p_org_id
          and a.type in ('income', 'expense')
          and (p_from is null or je.created_at::date >= p_from)
          and (p_to   is null or je.created_at::date <= p_to)
    )
    select 'income'::text, code, name, sum(credit - debit)
    from lines cross join access x
    where type = 'income' and x.detailed
    group by code, name having sum(credit - debit) <> 0

    union all

    select 'expense'::text, code, name, sum(debit - credit)
    from lines cross join access x
    where type = 'expense' and x.detailed
    group by code, name having sum(debit - credit) <> 0

    union all

    select 'total'::text, '1'::text, 'Produits'::text,
           coalesce(sum(credit - debit) filter (where type = 'income'), 0)
    from lines

    union all

    select 'total'::text, '2'::text, 'Charges'::text,
           coalesce(sum(debit - credit) filter (where type = 'expense'), 0)
    from lines

    union all

    -- The number the whole report is for.
    select 'total'::text, '3'::text, 'Résultat'::text,
           coalesce(sum(credit - debit) filter (where type = 'income'), 0)
         - coalesce(sum(debit - credit) filter (where type = 'expense'), 0)
    from lines

    order by 1, 2;
$$;

-- ------------------------------------------------------------
-- 8. BALANCE SHEET — what it owns and what it owes
-- ------------------------------------------------------------
-- The ledger has no closing entries and no retained-earnings account, so the
-- accumulated result is computed here as income minus expense to date and
-- shown as a line under equity. That is what makes the two sides equal, and
-- inventing a real closing process would be a much larger change for a
-- business whose books are eight months old.
create or replace function balance_sheet(
    p_org_id uuid,
    p_as_of  date default null
)
returns table (
    section text,     -- 'asset' | 'liability' | 'equity' | 'total'
    code    text,
    name    text,
    amount  numeric
)
language sql
stable
security definer
set search_path = public, auth
as $$
    with access as (
        select is_org_member(p_org_id) as member,
               has_full_visibility(p_org_id) as detailed
    ),
    lines as (
        select a.type, a.code, a.name, jl.debit, jl.credit
        from journal_entries je
        join journal_lines jl on jl.journal_entry_id = je.id
        join accounts a on a.id = jl.account_id
        cross join access x
        where x.member
          and je.org_id = p_org_id
          and (p_as_of is null or je.created_at::date <= p_as_of)
    ),
    result as (
        select coalesce(sum(credit - debit) filter (where type = 'income'), 0)
             - coalesce(sum(debit - credit) filter (where type = 'expense'), 0) as amount
        from lines
    )
    select 'asset'::text, code, name, sum(debit - credit)
    from lines cross join access x
    where type = 'asset' and x.detailed
    group by code, name having sum(debit - credit) <> 0

    union all

    select 'liability'::text, code, name, sum(credit - debit)
    from lines cross join access x
    where type = 'liability' and x.detailed
    group by code, name having sum(credit - debit) <> 0

    union all

    select 'equity'::text, code, name, sum(credit - debit)
    from lines cross join access x
    where type = 'equity' and x.detailed
    group by code, name having sum(credit - debit) <> 0

    union all

    -- Not an account, and labelled so nobody goes looking for it in the chart.
    select 'equity'::text, 'zzz'::text, 'Résultat accumulé'::text, r.amount
    from result r cross join access x
    where x.detailed and r.amount <> 0

    union all

    select 'total'::text, '1'::text, 'Total actif'::text,
           coalesce(sum(debit - credit) filter (where type = 'asset'), 0)
    from lines

    union all

    select 'total'::text, '2'::text, 'Total passif'::text,
           coalesce(sum(credit - debit) filter (where type in ('liability', 'equity')), 0)
         + (select amount from result)
    from lines

    order by 1, 2;
$$;

-- ------------------------------------------------------------
-- 9. GENERAL LEDGER — one account, every movement
-- ------------------------------------------------------------
-- Line items, so full visibility and not merely membership.
--
-- The running balance is the reason this exists rather than a filtered list:
-- "the till says 43,500 and the app says 61,000" is answered by reading down
-- a column until the two stop agreeing, and by nothing else.
create or replace function account_ledger(
    p_org_id     uuid,
    p_account_id uuid,
    p_from       date default null,
    p_to         date default null,
    p_limit      int  default 200
)
returns table (
    entry_id    uuid,
    occurred_at timestamptz,
    label       text,
    memo        text,
    debit       numeric,
    credit      numeric,
    balance     numeric,
    reversed    boolean,
    recorded_by text
)
language sql
stable
security definer
set search_path = public, auth
as $$
    with access as (
        select has_full_visibility(p_org_id) as detailed
    ),
    opening as (
        -- Everything before the window, collapsed into the number the first
        -- row starts from. Without it the running balance is only correct
        -- when the window reaches back to the first entry ever made.
        select coalesce(sum(jl.debit - jl.credit), 0) as amount
        from journal_lines jl
        join journal_entries je on je.id = jl.journal_entry_id
        cross join access x
        where x.detailed
          and jl.account_id = p_account_id
          and je.org_id = p_org_id
          and p_from is not null
          and je.created_at::date < p_from
    ),
    movements as (
        select
            je.id as entry_id,
            je.created_at as occurred_at,
            coalesce(je.label, je.memo, 'Entrée') as label,
            je.memo,
            jl.debit,
            jl.credit,
            exists (
                select 1 from journal_entries r where r.reverses_entry_id = je.id
            ) as reversed,
            coalesce(pr.full_name, 'Inconnu') as recorded_by
        from journal_lines jl
        join journal_entries je on je.id = jl.journal_entry_id
        left join profiles pr on pr.id = je.created_by
        cross join access x
        where x.detailed
          and jl.account_id = p_account_id
          and je.org_id = p_org_id
          and (p_from is null or je.created_at::date >= p_from)
          and (p_to   is null or je.created_at::date <= p_to)
    )
    select
        m.entry_id, m.occurred_at, m.label, m.memo, m.debit, m.credit,
        coalesce((select amount from opening), 0)
            + sum(m.debit - m.credit) over (
                order by m.occurred_at, m.entry_id
                rows between unbounded preceding and current row
            ),
        m.reversed, m.recorded_by
    from movements m
    order by m.occurred_at desc, m.entry_id desc
    limit greatest(coalesce(p_limit, 200), 1);
$$;

-- ------------------------------------------------------------
-- 10. THE JOURNAL — every entry, newest first
-- ------------------------------------------------------------
-- What the day list on the home screen shows for today, for any range and
-- with both sides of each entry named. Line items again, so full visibility.
create or replace function journal_page(
    p_org_id uuid,
    p_from   date default null,
    p_to     date default null,
    p_limit  int  default 100,
    p_offset int  default 0
)
returns table (
    entry_id     uuid,
    occurred_at  timestamptz,
    label        text,
    memo         text,
    details      jsonb,
    amount       numeric,
    debit_names  text,
    credit_names text,
    direction    text,        -- 'in' | 'out' | 'transfer'
    reversed     boolean,
    is_reversal  boolean,
    recorded_by  text
)
language sql
stable
security definer
set search_path = public, auth
as $$
    select
        je.id,
        je.created_at,
        coalesce(je.label, je.memo, 'Entrée'),
        je.memo,
        je.details,
        coalesce(sum(jl.debit), 0),
        string_agg(distinct a.name, ', ') filter (where jl.debit > 0),
        string_agg(distinct a.name, ', ') filter (where jl.credit > 0),
        case
            when bool_or(a.type = 'income'  and jl.credit > 0) then 'in'
            when bool_or(a.type = 'expense' and jl.debit  > 0) then 'out'
            else 'transfer'
        end,
        exists (select 1 from journal_entries r where r.reverses_entry_id = je.id),
        je.reverses_entry_id is not null,
        coalesce(pr.full_name, 'Inconnu')
    from journal_entries je
    join journal_lines jl on jl.journal_entry_id = je.id
    join accounts a on a.id = jl.account_id
    left join profiles pr on pr.id = je.created_by
    where je.org_id = p_org_id
      and has_full_visibility(p_org_id)
      and (p_from is null or je.created_at::date >= p_from)
      and (p_to   is null or je.created_at::date <= p_to)
    group by je.id, je.created_at, je.label, je.memo, je.details,
             je.reverses_entry_id, pr.full_name
    order by je.created_at desc, je.id desc
    limit greatest(coalesce(p_limit, 100), 1)
    offset greatest(coalesce(p_offset, 0), 0);
$$;

-- ------------------------------------------------------------
-- 11. GRANTS
-- ------------------------------------------------------------
-- Everything above that is SECURITY DEFINER starts life granted to PUBLIC,
-- which includes anon. Each one already refuses a caller with no session —
-- auth.uid() is null, so no membership matches — but the same discipline as
-- 005 and 006 applies: the grant is made deliberate rather than inherited.
revoke execute on function record_entry(uuid, numeric, text, text, uuid, text, text, uuid, text, jsonb, uuid, uuid, uuid, text, timestamptz) from public;
revoke execute on function record_transfer(uuid, numeric, text, text, uuid, text, text, uuid, text, timestamptz) from public;
revoke execute on function create_account(uuid, text, text, text, text) from public;
revoke execute on function chart_of_accounts(uuid) from public;
revoke execute on function trial_balance(uuid, date, date) from public;
revoke execute on function income_statement(uuid, date, date) from public;
revoke execute on function balance_sheet(uuid, date) from public;
revoke execute on function account_ledger(uuid, uuid, date, date, int) from public;
revoke execute on function journal_page(uuid, date, date, int, int) from public;

-- The helpers are not SECURITY DEFINER and are not for callers at all. They
-- run inside the functions above, which have already established permission;
-- reached directly they would insert under RLS and be refused, but there is
-- no reason to offer them at all.
revoke execute on function ensure_account(uuid, text, text, uuid) from public;
revoke execute on function ensure_account_by_code(uuid, text, text, text, uuid) from public;
revoke execute on function resolve_cash_account(uuid, text, uuid) from public;

do $$
begin
    if exists (select 1 from pg_roles where rolname = 'authenticated') then
        grant execute on function record_entry(uuid, numeric, text, text, uuid, text, text, uuid, text, jsonb, uuid, uuid, uuid, text, timestamptz) to authenticated;
        grant execute on function record_transfer(uuid, numeric, text, text, uuid, text, text, uuid, text, timestamptz) to authenticated;
        grant execute on function create_account(uuid, text, text, text, text) to authenticated;
        grant execute on function chart_of_accounts(uuid) to authenticated;
        grant execute on function trial_balance(uuid, date, date) to authenticated;
        grant execute on function income_statement(uuid, date, date) to authenticated;
        grant execute on function balance_sheet(uuid, date) to authenticated;
        grant execute on function account_ledger(uuid, uuid, date, date, int) to authenticated;
        grant execute on function journal_page(uuid, date, date, int, int) to authenticated;
    end if;
end $$;


-- ============================================================
-- 008_audit_log.sql
-- ============================================================
-- ============================================================
-- 008_audit_log.sql
--
-- What happened, who did it, and what the database actually holds.
--
-- The ledger has been its own audit trail since the first schema: entries are
-- never edited or deleted, and an undo is a reversing entry. That covers
-- money and nothing else. Everything that decides who may touch the money —
-- a role granted, an invitation issued, a category renamed, a business
-- renamed — has been silently mutable this whole time. An admin could grant
-- themselves ownership, do something, and revoke it again, and there would be
-- no trace anywhere that it had happened.
--
-- So: one append-only table, one generic trigger, and two functions that let
-- a super admin read the log and see the shape of the data underneath it.
--
-- Three decisions worth stating.
--
--   * The trigger is generic. A per-table audit function is a per-table thing
--     to forget to write, and the tables it would have to be written for are
--     exactly the ones somebody adds in a hurry. This one reads the row as
--     jsonb and works out the org, the subject and the changed columns
--     without knowing which table it is on.
--
--   * The log is append-only in the strongest sense available: RLS is enabled
--     with a select policy and no insert, update or delete policy at all. RLS
--     denies what it is not told to allow, so no caller can write to it,
--     amend it or clear it. The rows arrive because the trigger function is
--     SECURITY DEFINER and runs outside policy — which is the only door in,
--     and it is not a door anyone can knock on.
--
--   * Reading it needs admin. The log names people and says what they did,
--     which is precisely the thing an ordinary employee has no business
--     browsing about their colleagues.
-- ============================================================

-- ------------------------------------------------------------
-- 1. THE LOG
-- ------------------------------------------------------------
create table if not exists audit_log (
    id          bigint generated always as identity primary key,

    -- Null only for a row whose org could not be resolved, which should never
    -- happen and is kept visible rather than dropped if it does.
    org_id      uuid references orgs(id) on delete cascade,

    -- Who. Nullable because a row written by a migration, a seeder or a
    -- server-side job has no signed-in user behind it, and "the system did
    -- it" is a true and useful answer.
    actor_id    uuid references profiles(id) on delete set null,

    -- The name as it read at the time. Denormalised on purpose: a log entry
    -- that says "Aminata revoked Salif" must keep saying that after Aminata
    -- has changed her name and Salif's profile has been deleted.
    actor_label text,

    action      text not null check (action in ('insert', 'update', 'delete')),
    table_name  text not null,
    row_id      uuid,

    -- One human-readable line, resolved at write time for the same reason as
    -- actor_label: the log has to stay readable after its subject is gone.
    summary     text,

    -- For an update, {column: [before, after]} for the columns that actually
    -- changed. For an insert or a delete, the whole row.
    changed     jsonb,

    at          timestamptz not null default now()
);

-- The console reads one org's log newest-first, which is the only access
-- pattern there is.
create index if not exists audit_log_by_org on audit_log (org_id, id desc);
create index if not exists audit_log_by_actor on audit_log (org_id, actor_id, id desc);

-- ------------------------------------------------------------
-- 2. THE TRIGGER
-- ------------------------------------------------------------
-- SECURITY DEFINER so it can write the log from under a policy that lets
-- nobody write the log. search_path is pinned so a caller cannot shadow
-- `audit_log` or `profiles` with tables of their own and redirect the trail.
create or replace function audit_row()
returns trigger
language plpgsql
security definer
set search_path = public, auth
as $$
declare
    v_row     jsonb;
    v_old     jsonb;
    v_org     uuid;
    v_changed jsonb;
    v_actor   uuid := auth.uid();
    v_label   text;
    v_summary text;
begin
    if TG_OP = 'DELETE' then
        v_row := to_jsonb(OLD);
    else
        v_row := to_jsonb(NEW);
    end if;

    -- Which business this belongs to. Most tables carry org_id; orgs itself is
    -- its own org; departments reach it through their entity.
    v_org := nullif(v_row ->> 'org_id', '')::uuid;

    if v_org is null and TG_TABLE_NAME = 'orgs' then
        v_org := nullif(v_row ->> 'id', '')::uuid;
    end if;

    if v_org is null and v_row ? 'entity_id' then
        select e.org_id into v_org
          from entities e
         where e.id = nullif(v_row ->> 'entity_id', '')::uuid;
    end if;

    if v_actor is not null then
        select p.full_name into v_label from profiles p where p.id = v_actor;
    end if;

    -- Whichever of these the table happens to have, in the order a person
    -- would recognise the row by. A log that says "membership 8f2c…" is a log
    -- nobody reads twice.
    --
    -- This list is the one part of a generic trigger that cannot be generic:
    -- every table names its subject differently, and a table whose naming
    -- column is not here logs a null summary rather than failing — which is
    -- quiet, and is how it went unnoticed until 009 added `flocks` and its
    -- batch codes stopped appearing. A new table with a new naming column
    -- belongs on this list.
    v_summary := coalesce(
        v_row ->> 'name',
        v_row ->> 'label',
        v_row ->> 'full_name',
        v_row ->> 'batch_code',   -- flocks (009)
        v_row ->> 'number',       -- invoices (009)
        v_row ->> 'role',
        v_row ->> 'code',
        v_row ->> 'memo',
        v_row ->> 'description'
    );

    if TG_OP = 'UPDATE' then
        v_old := to_jsonb(OLD);
        -- Only the columns that moved. A diff listing every column is a diff
        -- nobody can read, and updated_at noise is how audit logs die.
        select jsonb_object_agg(e.key, jsonb_build_array(v_old -> e.key, e.value))
          into v_changed
          from jsonb_each(v_row) e
         where e.value is distinct from v_old -> e.key;

        -- Nothing actually changed. Postgres fires the trigger anyway on an
        -- UPDATE that sets a column to the value it already had.
        if v_changed is null then
            return coalesce(NEW, OLD);
        end if;
    else
        v_changed := v_row;
    end if;

    insert into audit_log (
        org_id, actor_id, actor_label, action, table_name, row_id, summary, changed
    )
    values (
        v_org,
        v_actor,
        coalesce(v_label, case when v_actor is null then 'Système' else 'Inconnu' end),
        lower(TG_OP),
        TG_TABLE_NAME,
        nullif(v_row ->> 'id', '')::uuid,
        v_summary,
        v_changed
    );

    return coalesce(NEW, OLD);
end;
$$;

-- ------------------------------------------------------------
-- 3. WHAT IS WATCHED
-- ------------------------------------------------------------
-- Everything that decides who may see or touch a business's money, plus the
-- ledger itself so the log is a single place to look rather than two.
--
-- journal_lines is deliberately absent: it has no independent life, an entry's
-- lines are written in the same transaction as the entry, and logging them
-- would double the busiest table in the schema to record nothing that the
-- entry's own row does not already say.
do $$
declare
    v_table text;
begin
    foreach v_table in array array[
        'orgs',
        'memberships',
        'entities',
        'departments',
        'accounts',
        'pending_invitations',
        'journal_entries',
        'church_members'
    ]
    loop
        execute format('drop trigger if exists audit_%1$s on %1$I', v_table);
        execute format(
            'create trigger audit_%1$s after insert or update or delete on %1$I
             for each row execute function audit_row()',
            v_table
        );
    end loop;
end $$;

-- ------------------------------------------------------------
-- 4. RLS — readable by admins, writable by nobody
-- ------------------------------------------------------------
alter table audit_log enable row level security;

drop policy if exists "audit log readable by org admins" on audit_log;

create policy "audit log readable by org admins"
on audit_log for select
using (is_org_admin(org_id));

-- No insert, update or delete policy. That omission is the whole guarantee:
-- the only writer is audit_row(), which runs as definer and outside policy.

-- ------------------------------------------------------------
-- 5. READING THE LOG
-- ------------------------------------------------------------
-- Keyset pagination on the identity column rather than OFFSET: the log grows
-- at the top while somebody is reading down it, and OFFSET would show them
-- the same row twice.
create or replace function audit_log_page(
    p_org_id  uuid,
    p_limit   int    default 50,
    p_before  bigint default null,   -- the id of the oldest row already shown
    p_table   text   default null,
    p_actor   uuid   default null,
    p_action  text   default null
)
returns table (
    id          bigint,
    at          timestamptz,
    actor_id    uuid,
    actor_label text,
    action      text,
    table_name  text,
    row_id      uuid,
    summary     text,
    changed     jsonb
)
language sql
stable
security definer
set search_path = public, auth
as $$
    select l.id, l.at, l.actor_id, l.actor_label, l.action,
           l.table_name, l.row_id, l.summary, l.changed
    from audit_log l
    where l.org_id = p_org_id
      and is_org_admin(p_org_id)
      and (p_before is null or l.id < p_before)
      and (p_table  is null or l.table_name = p_table)
      and (p_actor  is null or l.actor_id = p_actor)
      and (p_action is null or l.action = p_action)
    order by l.id desc
    limit greatest(coalesce(p_limit, 50), 1);
$$;

-- The names to put in the filter, and how busy each has been. Reading a log
-- usually starts with "who has been doing things", not with a date.
create or replace function audit_log_actors(p_org_id uuid)
returns table (actor_id uuid, actor_label text, events bigint, last_seen timestamptz)
language sql
stable
security definer
set search_path = public, auth
as $$
    select l.actor_id, max(l.actor_label), count(*), max(l.at)
    from audit_log l
    where l.org_id = p_org_id
      and is_org_admin(p_org_id)
    group by l.actor_id
    order by 4 desc;
$$;

-- ------------------------------------------------------------
-- 6. THE DATABASE, AS A THING YOU CAN LOOK AT
-- ------------------------------------------------------------
-- A super admin who cannot see what the database holds has to trust the
-- screens, and the screens are the thing they are checking. This is the
-- shape of the data for one business: every table that holds anything of
-- theirs, what it is for, how many rows of it are theirs, and when it last
-- moved.
--
-- Written as a static UNION rather than dynamic SQL over the catalog on
-- purpose. Every count below is scoped to p_org_id by a WHERE clause someone
-- had to write, which is what makes this safe to expose; a loop over
-- information_schema counting whole tables would hand one client's row counts
-- to another's admin, and there would be no clause to point at and check.
create or replace function org_database_overview(p_org_id uuid)
returns table (
    table_name  text,
    label       text,
    purpose     text,
    row_count   bigint,
    last_change timestamptz
)
language sql
stable
security definer
set search_path = public, auth
as $$
    with allowed as (select is_org_admin(p_org_id) as ok),
    counts(table_name, label, purpose, row_count) as (
        select 'orgs', 'Activité', 'La fiche de l''activité elle-même',
               (select count(*) from orgs o where o.id = p_org_id)
        union all
        select 'entities', 'Sites', 'Campus, fermes, boutiques',
               (select count(*) from entities e where e.org_id = p_org_id)
        union all
        select 'departments', 'Départements', 'Sous-unités d''un site',
               (select count(*) from departments d
                 join entities e on e.id = d.entity_id where e.org_id = p_org_id)
        union all
        select 'memberships', 'Accès', 'Qui détient quel rôle, et sur quoi',
               (select count(*) from memberships m where m.org_id = p_org_id)
        union all
        select 'pending_invitations', 'Invitations', 'Codes émis, utilisés ou expirés',
               (select count(*) from pending_invitations i where i.org_id = p_org_id)
        union all
        select 'accounts', 'Plan comptable', 'Les catégories dans lesquelles l''argent tombe',
               (select count(*) from accounts a where a.org_id = p_org_id)
        union all
        select 'journal_entries', 'Écritures', 'Chaque enregistrement, jamais modifié',
               (select count(*) from journal_entries je where je.org_id = p_org_id)
        union all
        select 'journal_lines', 'Lignes d''écriture', 'Les débits et crédits sous chaque écriture',
               (select count(*) from journal_lines jl
                 join journal_entries je on je.id = jl.journal_entry_id
                where je.org_id = p_org_id)
        union all
        select 'church_members', 'Fidèles', 'Les personnes à qui une offrande peut être attribuée',
               (select count(*) from church_members cm where cm.org_id = p_org_id)
        union all
        select 'contribution_attributions', 'Attributions', 'Quelle écriture appartient à quel fidèle',
               (select count(*) from contribution_attributions ca
                 join journal_entries je on je.id = ca.journal_entry_id
                where je.org_id = p_org_id)
        union all
        select 'documents', 'Pièces jointes', 'Photos et factures liées aux écritures',
               (select count(*) from documents doc where doc.org_id = p_org_id)
        union all
        select 'audit_log', 'Journal d''activité', 'Ce que chacun a modifié, et quand',
               (select count(*) from audit_log al where al.org_id = p_org_id)
    )
    select c.table_name, c.label, c.purpose, c.row_count,
           (select max(l.at) from audit_log l
             where l.org_id = p_org_id and l.table_name = c.table_name)
    from counts c cross join allowed a
    where a.ok
    order by c.table_name;
$$;

-- The tables a super admin may inspect the structure of. Anything not on this
-- list — auth.users above all — is not describable through this function at
-- any privilege level, because the answer would be the same for every tenant
-- and there is nothing an org admin learns from it that they need.
create or replace function is_inspectable_table(p_table text)
returns boolean
language sql
immutable
as $$
    select p_table = any (array[
        'orgs', 'entities', 'departments', 'memberships', 'pending_invitations',
        'profiles', 'accounts', 'journal_entries', 'journal_lines',
        'church_members', 'contribution_attributions', 'documents', 'audit_log'
    ]);
$$;

-- What a table is made of: columns, types, what may be empty, what points
-- where. This is the schema browser behind the console's Database tab.
--
-- It returns structure and never a row of data, so it discloses nothing about
-- any tenant — but it is still gated on being an admin of some business,
-- because a schema is a map of what is worth attacking.
create or replace function org_table_columns(p_org_id uuid, p_table text)
returns table (
    column_name  text,
    data_type    text,
    is_nullable  boolean,
    has_default  boolean,
    is_key       boolean,
    references_table text
)
language sql
stable
security definer
set search_path = public, auth
as $$
    select
        c.column_name::text,
        c.data_type::text,
        c.is_nullable = 'YES',
        c.column_default is not null,
        exists (
            select 1
            from information_schema.key_column_usage k
            join information_schema.table_constraints tc
              on tc.constraint_name = k.constraint_name
             and tc.constraint_schema = k.constraint_schema
            where tc.constraint_type = 'PRIMARY KEY'
              and k.table_schema = 'public'
              and k.table_name = c.table_name
              and k.column_name = c.column_name
        ),
        (
            select ccu.table_name::text
            from information_schema.key_column_usage k
            join information_schema.table_constraints tc
              on tc.constraint_name = k.constraint_name
             and tc.constraint_schema = k.constraint_schema
            join information_schema.constraint_column_usage ccu
              on ccu.constraint_name = tc.constraint_name
             and ccu.constraint_schema = tc.constraint_schema
            where tc.constraint_type = 'FOREIGN KEY'
              and k.table_schema = 'public'
              and k.table_name = c.table_name
              and k.column_name = c.column_name
            limit 1
        )
    from information_schema.columns c
    where c.table_schema = 'public'
      and c.table_name = p_table
      and is_inspectable_table(p_table)
      and is_org_admin(p_org_id)
    order by c.ordinal_position;
$$;

-- ------------------------------------------------------------
-- 7. GRANTS
-- ------------------------------------------------------------
revoke execute on function audit_log_page(uuid, int, bigint, text, uuid, text) from public;
revoke execute on function audit_log_actors(uuid) from public;
revoke execute on function org_database_overview(uuid) from public;
revoke execute on function org_table_columns(uuid, text) from public;

-- audit_row() is a trigger function. It cannot be called directly — Postgres
-- refuses a trigger function invoked as a plain function — but it is SECURITY
-- DEFINER and the default grant is to PUBLIC, so it is revoked with the rest.
revoke execute on function audit_row() from public;

do $$
begin
    if exists (select 1 from pg_roles where rolname = 'authenticated') then
        grant execute on function audit_log_page(uuid, int, bigint, text, uuid, text) to authenticated;
        grant execute on function audit_log_actors(uuid) to authenticated;
        grant execute on function org_database_overview(uuid) to authenticated;
        grant execute on function org_table_columns(uuid, text) to authenticated;
        -- Select only. There is no policy that would let an insert through
        -- anyway, and the grant should not suggest otherwise.
        grant select on audit_log to authenticated;
    end if;
end $$;


-- ============================================================
-- 009_farm_profile.sql
-- ============================================================
-- ============================================================
-- 009_farm_profile.sql
-- Ignace's module: the farm profile.
--
-- BUILD_PLAN.md numbers this 005; that slot went to invitations while the
-- farm waited, so it lands here. Nothing else about the plan changes.
--
-- Same design rule as 002: Ignace never sees a debit or a credit. He taps
-- "20 sacs d'aliment reçus" and the function underneath writes a stock
-- movement and a balanced journal entry. Every public function here takes
-- plain-language inputs and hides the accounting completely.
--
-- Two things this module does that the church module did not have to.
--
--   1. IT COUNTS THINGS AS WELL AS MONEY. A sack of feed is an event in two
--      ledgers at once — the money one and the physical one — and they are
--      not the same ledger. Feed bought is an expense AND stock arriving;
--      feed eaten is stock leaving and no money at all; a bird dying is
--      neither, and is the single most important number on the farm. So
--      `stock_movements` and `flock_events` are append-only in exactly the
--      way `journal_entries` is, for exactly the same reason: a count you can
--      edit is a count nobody can audit.
--
--   2. IT SELLS ON CREDIT. A church is paid when it is paid. A farm delivers
--      thirty trays to a hotel and gets paid in three weeks, and the money
--      is real income the day it is invoiced. That needs a receivable, which
--      is the first thing in this project that is neither cash nor an
--      expense, and it is why `post_ledger_pair()` exists below.
--
-- ONE ACCOUNTING DECISION WORTH STATING. Feed is expensed when it is bought,
-- not when it is eaten. The strictly correct treatment capitalises it as
-- inventory and expenses it on consumption, which would make the income
-- statement smoother and the stock account meaningful. It is not done here
-- because BUILD_PLAN.md says "feed purchased is both a stock movement and an
-- expense", and because it matches how the money actually feels to the person
-- paying for it: the day twenty sacks arrive is the day the money is gone.
-- `stock_on_hand()` still counts the sacks. If this farm ever needs a real
-- inventory valuation, that is a later migration and a conversation with an
-- accountant, not a thing to guess at now.
-- ============================================================

-- ------------------------------------------------------------
-- 1. A SHARED WAY TO POST TWO SIDES
-- ------------------------------------------------------------
-- `record_entry()` in 007 covers everything whose other side is cash, which
-- is every entry the church module can produce. An invoice is the first thing
-- here whose other side is a customer who has not paid yet, and a payment is
-- the first thing whose other side is that same customer settling up.
--
-- So: the general form, taking two account ids. Not exposed to any caller —
-- it makes no permission check of its own, and every function that uses it
-- has already made one.
create or replace function post_ledger_pair(
    p_org_id       uuid,
    p_debit_acct   uuid,
    p_credit_acct  uuid,
    p_amount       numeric,
    p_label        text,
    p_actor        uuid,
    p_memo         text        default null,
    p_details      jsonb       default '{}'::jsonb,
    p_client_uuid  uuid        default null,
    p_device_id    text        default null,
    p_occurred_at  timestamptz default now()
)
returns uuid
language plpgsql
as $$
declare
    v_entry_id uuid;
begin
    if p_amount is null or p_amount <= 0 then
        raise exception 'Amount must be greater than zero (got %)', p_amount;
    end if;
    if p_debit_acct = p_credit_acct then
        raise exception 'An entry needs two different accounts';
    end if;

    insert into journal_entries (
        org_id, label, memo, details, created_by, created_at, device_id, client_uuid
    )
    values (
        p_org_id, p_label, p_memo, coalesce(p_details, '{}'::jsonb),
        p_actor, p_occurred_at, p_device_id, p_client_uuid
    )
    returning id into v_entry_id;

    insert into journal_lines (journal_entry_id, account_id, debit, credit) values
        (v_entry_id, p_debit_acct,  p_amount, 0),
        (v_entry_id, p_credit_acct, 0,        p_amount);

    return v_entry_id;
end;
$$;

-- The chart a farm starts with. Continues the bands 007 established, and
-- leaves the church's 4000s and 5000s alone so one org can run both.
create or replace function seed_farm_accounts(p_org_id uuid)
returns void
language plpgsql
as $$
begin
    insert into accounts (org_id, code, name, type) values
        (p_org_id, '1000', 'Cash on Hand',        'asset'),
        (p_org_id, '1010', 'Bank Account',        'asset'),
        (p_org_id, '1020', 'Mobile Money',        'asset'),
        -- What customers owe. The first asset in this project that is not
        -- money you can hold.
        (p_org_id, '1300', 'Créances clients',    'asset'),
        (p_org_id, '4100', 'Ventes d''œufs',      'income'),
        (p_org_id, '4110', 'Ventes de volailles', 'income'),
        (p_org_id, '4120', 'Autres ventes',       'income'),
        (p_org_id, '5100', 'Aliment',             'expense'),
        (p_org_id, '5110', 'Vétérinaire',         'expense'),
        (p_org_id, '5120', 'Main-d''œuvre',       'expense'),
        (p_org_id, '5130', 'Fournitures ferme',   'expense')
    on conflict (org_id, code) do nothing;
end;
$$;

-- ------------------------------------------------------------
-- 2. WHAT THE FARM CONSUMES
-- ------------------------------------------------------------
-- Things bought to be used up: feed, medicine, sawdust, gas. Not the same as
-- the `products` M5 will add for Esperance, which are things bought to be
-- sold and carry a barcode, an expiry and a selling price. Consumables have
-- none of that and need a reorder level, which products do not.
create table if not exists items (
    id            uuid primary key default gen_random_uuid(),
    org_id        uuid not null references orgs(id) on delete cascade,
    name          text not null,
    unit          text not null default 'sac',   -- sac | kg | litre | dose | unité
    -- Below this, the home screen says so. Null means nobody has decided yet,
    -- which is most items on the day they are created and is not a problem
    -- worth a required field.
    reorder_level numeric(14,2),
    is_active     boolean not null default true,
    created_at    timestamptz not null default now(),
    created_by    uuid references profiles(id)
);

create index if not exists items_by_org on items (org_id) where is_active;

-- Matched the way ensure_account() matches, and for the same reason: "Aliment
-- ponte", "aliment ponte" and " Aliment Ponte " are one thing to the person
-- typing them.
create index if not exists items_by_name on items (org_id, lower(btrim(name)));

-- Append-only, exactly like journal_lines. A stock count that can be edited
-- after the fact is a stock count that cannot be reconciled against anything.
-- A miscount is corrected the way a miscounted offering is: by a further
-- movement that says so, not by rewriting the first one.
create table if not exists stock_movements (
    id          uuid primary key default gen_random_uuid(),
    org_id      uuid not null references orgs(id) on delete cascade,
    item_id     uuid not null references items(id) on delete cascade,

    -- received: arrived and was paid for.   consumed: used as intended.
    -- wasted:   spoiled, spilled, stolen.   adjusted: a physical count
    --           disagreed with the running total and the count wins.
    kind        text not null check (kind in ('received', 'consumed', 'wasted', 'adjusted')),

    -- Signed for 'adjusted' and positive for everything else; the direction
    -- of the other three is carried by `kind`. stock_on_hand() below is the
    -- one place that turns them into a running total.
    quantity    numeric(14,3) not null,
    unit_cost   numeric(14,2),

    -- Set for 'received', which is the only kind that moves money.
    journal_entry_id uuid references journal_entries(id),

    memo        text,
    occurred_at timestamptz not null default now(),
    created_by  uuid not null references profiles(id),
    device_id   text,
    client_uuid uuid
);

create index if not exists stock_movements_by_item
    on stock_movements (org_id, item_id, occurred_at desc);

-- The offline safety net, identical to journal_entries: a phone that retries
-- a sync must not double-count twenty sacks of feed.
create unique index if not exists stock_movements_client_uuid_key
    on stock_movements (org_id, client_uuid)
    where client_uuid is not null;

-- ------------------------------------------------------------
-- 3. THE BIRDS
-- ------------------------------------------------------------
-- A flock is a batch that arrived together and is managed together. Its bird
-- count is the number that ARRIVED and is never edited; how many are alive is
-- that number minus the mortality events, which is what flock_status()
-- computes. Storing a mutable "current count" instead would lose the one
-- piece of information the farm actually runs on, which is how fast birds are
-- dying and when that changed.
create table if not exists flocks (
    id          uuid primary key default gen_random_uuid(),
    org_id      uuid not null references orgs(id) on delete cascade,
    entity_id   uuid references entities(id) on delete set null,  -- which site
    batch_code  text not null,
    breed       text,
    bird_count  int not null check (bird_count > 0),
    arrived_on  date not null default current_date,
    -- Set when the batch is sold off or cleared out. A closed flock stops
    -- appearing on the home screen and keeps all its history.
    closed_on   date,
    created_at  timestamptz not null default now(),
    created_by  uuid references profiles(id),
    unique (org_id, batch_code)
);

create index if not exists flocks_open on flocks (org_id) where closed_on is null;

create table if not exists flock_events (
    id          uuid primary key default gen_random_uuid(),
    flock_id    uuid not null references flocks(id) on delete cascade,

    -- mortality: birds died.  weight: a sample weighing, in grams.
    -- vaccination: a dose given.  sold: birds left the flock alive.
    kind        text not null check (kind in ('mortality', 'weight', 'vaccination', 'sold')),

    -- Birds for mortality and sold, grams for weight, doses for vaccination.
    -- One column because the unit is decided by `kind` and a column per kind
    -- would be three nulls on every row.
    quantity    numeric(14,3) not null,

    note        text,
    occurred_at timestamptz not null default now(),
    created_by  uuid not null references profiles(id),
    device_id   text,
    client_uuid uuid
);

create index if not exists flock_events_by_flock
    on flock_events (flock_id, occurred_at desc);

create unique index if not exists flock_events_client_uuid_key
    on flock_events (flock_id, client_uuid)
    where client_uuid is not null;

-- What the birds produced. Not money: eggs become income when they are sold,
-- and a great many of them are eaten, given away or broken first. Recording
-- production as revenue is how a farm convinces itself it is profitable.
create table if not exists egg_production (
    id          uuid primary key default gen_random_uuid(),
    org_id      uuid not null references orgs(id) on delete cascade,
    flock_id    uuid references flocks(id) on delete set null,
    produced_on date not null default current_date,
    grade       text not null default 'normal',   -- normal | petit | fêlé
    egg_count   int not null check (egg_count >= 0),
    created_at  timestamptz not null default now(),
    created_by  uuid not null references profiles(id),
    device_id   text,
    client_uuid uuid
);

create index if not exists egg_production_by_day
    on egg_production (org_id, produced_on desc);

create unique index if not exists egg_production_client_uuid_key
    on egg_production (org_id, client_uuid)
    where client_uuid is not null;

-- ------------------------------------------------------------
-- 4. WHO BUYS, AND WHO HAS NOT PAID
-- ------------------------------------------------------------
create table if not exists customers (
    id         uuid primary key default gen_random_uuid(),
    org_id     uuid not null references orgs(id) on delete cascade,
    name       text not null,
    phone      text,
    note       text,
    is_active  boolean not null default true,
    created_at timestamptz not null default now(),
    created_by uuid references profiles(id)
);

create index if not exists customers_by_org on customers (org_id) where is_active;
create index if not exists customers_by_name on customers (org_id, lower(btrim(name)));

create table if not exists invoices (
    id          uuid primary key default gen_random_uuid(),
    org_id      uuid not null references orgs(id) on delete cascade,
    customer_id uuid not null references customers(id) on delete restrict,
    number      text not null,
    issued_on   date not null default current_date,
    due_on      date,
    total       numeric(14,2) not null check (total > 0),

    -- The entry that recognised the income and created the receivable. An
    -- invoice without one would be a promise the books know nothing about.
    journal_entry_id uuid references journal_entries(id),

    -- Withdrawn rather than deleted, like everything else here: a cancelled
    -- invoice is a fact about the relationship with that customer.
    cancelled_at timestamptz,

    created_at  timestamptz not null default now(),
    created_by  uuid not null references profiles(id),
    client_uuid uuid,
    unique (org_id, number)
);

create index if not exists invoices_by_customer
    on invoices (org_id, customer_id, issued_on desc);

create table if not exists invoice_lines (
    id          uuid primary key default gen_random_uuid(),
    invoice_id  uuid not null references invoices(id) on delete cascade,
    description text not null,
    quantity    numeric(14,3) not null default 1,
    unit_price  numeric(14,2) not null,
    amount      numeric(14,2) not null
);

create index if not exists invoice_lines_by_invoice on invoice_lines (invoice_id);

-- Payments are rows, not a status column. A hotel that pays a third now and
-- the rest next month is the normal case, and "paid: true/false" cannot
-- describe it. What is outstanding is the invoice total minus the sum of
-- these, which is what outstanding_invoices() computes.
create table if not exists invoice_payments (
    id          uuid primary key default gen_random_uuid(),
    invoice_id  uuid not null references invoices(id) on delete cascade,
    amount      numeric(14,2) not null check (amount > 0),
    method      text not null default 'cash',
    paid_on     date not null default current_date,
    journal_entry_id uuid references journal_entries(id),
    created_at  timestamptz not null default now(),
    created_by  uuid not null references profiles(id),
    client_uuid uuid
);

create index if not exists invoice_payments_by_invoice
    on invoice_payments (invoice_id, paid_on);

-- ------------------------------------------------------------
-- 5. FINDING OR CREATING THE THINGS PEOPLE NAME
-- ------------------------------------------------------------
-- Same rule as ensure_account() in 007, applied to the two other things a
-- farmer types the name of. An item list nobody can add to has exactly the
-- problem the category list had.
create or replace function ensure_item(
    p_org_id uuid,
    p_name   text,
    p_unit   text default 'sac',
    p_actor  uuid default null
)
returns uuid
language plpgsql
as $$
declare
    v_name text := btrim(coalesce(p_name, ''));
    v_id   uuid;
begin
    if v_name = '' then
        raise exception 'An item needs a name';
    end if;

    select id into v_id
      from items
     where org_id = p_org_id and lower(btrim(name)) = lower(v_name)
     order by created_at
     limit 1;

    if v_id is not null then
        return v_id;
    end if;

    insert into items (org_id, name, unit, created_by)
    values (p_org_id, v_name, coalesce(nullif(btrim(p_unit), ''), 'sac'), p_actor)
    returning id into v_id;

    return v_id;
end;
$$;

create or replace function ensure_customer(
    p_org_id uuid,
    p_name   text,
    p_phone  text default null,
    p_actor  uuid default null
)
returns uuid
language plpgsql
as $$
declare
    v_name text := btrim(coalesce(p_name, ''));
    v_id   uuid;
begin
    if v_name = '' then
        raise exception 'A customer needs a name';
    end if;

    select id into v_id
      from customers
     where org_id = p_org_id and lower(btrim(name)) = lower(v_name)
     order by created_at
     limit 1;

    if v_id is not null then
        return v_id;
    end if;

    insert into customers (org_id, name, phone, created_by)
    values (p_org_id, v_name, nullif(btrim(coalesce(p_phone, '')), ''), p_actor)
    returning id into v_id;

    return v_id;
end;
$$;

-- ------------------------------------------------------------
-- 6. WHAT IGNACE TAPS
-- ------------------------------------------------------------
-- All SECURITY DEFINER, all checking `can_write_org()` themselves first, all
-- idempotent on a device-generated client_uuid — the same three properties
-- every recording function in this project has, for the same three reasons.

-- Feed, medicine, sawdust arriving. One tap; two ledgers.
create or replace function receive_stock(
    p_org_id      uuid,
    p_item_name   text,
    p_quantity    numeric,
    p_unit_cost   numeric     default null,
    p_unit        text        default 'sac',
    p_category    text        default 'Aliment',   -- the expense account
    p_method      text        default 'cash',
    p_recorded_by uuid        default null,
    p_memo        text        default null,
    p_client_uuid uuid        default null,
    p_device_id   text        default null,
    p_occurred_at timestamptz default now()
)
returns uuid
language plpgsql
security definer
set search_path = public, auth
as $$
declare
    v_actor    uuid := auth.uid();
    v_item     uuid;
    v_entry    uuid;
    v_total    numeric;
    v_id       uuid;
    v_existing uuid;
begin
    if v_actor is null then
        raise exception 'receive_stock() needs a signed-in caller';
    end if;
    if p_recorded_by is not null and p_recorded_by <> v_actor then
        raise exception 'receive_stock() cannot record on behalf of another user';
    end if;
    if not can_write_org(p_org_id) then
        raise exception 'You cannot record stock for this business';
    end if;
    if p_quantity is null or p_quantity <= 0 then
        raise exception 'Quantity must be greater than zero (got %)', p_quantity;
    end if;

    if p_client_uuid is not null then
        select id into v_existing
          from stock_movements
         where org_id = p_org_id and client_uuid = p_client_uuid;
        if found then
            return v_existing;
        end if;
    end if;

    v_item := ensure_item(p_org_id, p_item_name, p_unit, v_actor);
    v_total := p_quantity * coalesce(p_unit_cost, 0);

    -- Money only moves if somebody said what it cost. A delivery logged
    -- without a price is still a delivery, and refusing it would mean the
    -- sacks go uncounted because the invoice is in the truck.
    if v_total > 0 then
        v_entry := record_entry(
            p_org_id      => p_org_id,
            p_amount      => v_total,
            p_direction   => 'out',
            p_label       => btrim(p_item_name) || ' — ' || p_quantity || ' ' ||
                             coalesce(nullif(btrim(p_unit), ''), 'sac'),
            p_recorded_by => v_actor,
            p_category    => p_category,
            p_method      => p_method,
            p_memo        => p_memo,
            p_details     => jsonb_build_object(
                'quantité', p_quantity,
                'unité', coalesce(nullif(btrim(p_unit), ''), 'sac'),
                'prix unitaire', p_unit_cost
            ),
            p_client_uuid => p_client_uuid,
            p_device_id   => p_device_id,
            p_occurred_at => p_occurred_at
        );
    end if;

    insert into stock_movements (
        org_id, item_id, kind, quantity, unit_cost, journal_entry_id,
        memo, occurred_at, created_by, device_id, client_uuid
    )
    values (
        p_org_id, v_item, 'received', p_quantity, p_unit_cost, v_entry,
        p_memo, p_occurred_at, v_actor, p_device_id, p_client_uuid
    )
    returning id into v_id;

    return v_id;
end;
$$;

-- Feed eaten, medicine given, sawdust spread — and the same function for
-- what spoiled, because the only difference is which word is true.
--
-- No ledger entry: the money left when the sacks arrived. What this moves is
-- the count, and the count is what tells you the feed is running out on
-- Thursday rather than on the Thursday you run out.
create or replace function move_stock(
    p_org_id      uuid,
    p_item_name   text,
    p_quantity    numeric,
    p_kind        text        default 'consumed',  -- consumed | wasted | adjusted
    p_unit        text        default 'sac',
    p_recorded_by uuid        default null,
    p_memo        text        default null,
    p_client_uuid uuid        default null,
    p_device_id   text        default null,
    p_occurred_at timestamptz default now()
)
returns uuid
language plpgsql
security definer
set search_path = public, auth
as $$
declare
    v_actor    uuid := auth.uid();
    v_item     uuid;
    v_id       uuid;
    v_existing uuid;
begin
    if v_actor is null then
        raise exception 'move_stock() needs a signed-in caller';
    end if;
    if p_recorded_by is not null and p_recorded_by <> v_actor then
        raise exception 'move_stock() cannot record on behalf of another user';
    end if;
    if not can_write_org(p_org_id) then
        raise exception 'You cannot record stock for this business';
    end if;
    if p_kind not in ('consumed', 'wasted', 'adjusted') then
        raise exception 'Use receive_stock() for arrivals (got kind %)', p_kind;
    end if;
    -- An adjustment may be negative: it is the difference between what the
    -- running total said and what counting the sacks found, and that
    -- difference goes both ways.
    if p_quantity is null or (p_kind <> 'adjusted' and p_quantity <= 0) then
        raise exception 'Quantity must be greater than zero (got %)', p_quantity;
    end if;

    if p_client_uuid is not null then
        select id into v_existing
          from stock_movements
         where org_id = p_org_id and client_uuid = p_client_uuid;
        if found then
            return v_existing;
        end if;
    end if;

    v_item := ensure_item(p_org_id, p_item_name, p_unit, v_actor);

    insert into stock_movements (
        org_id, item_id, kind, quantity, memo, occurred_at,
        created_by, device_id, client_uuid
    )
    values (
        p_org_id, v_item, p_kind, p_quantity, p_memo, p_occurred_at,
        v_actor, p_device_id, p_client_uuid
    )
    returning id into v_id;

    return v_id;
end;
$$;

-- A batch of birds arriving.
create or replace function open_flock(
    p_org_id     uuid,
    p_batch_code text,
    p_bird_count int,
    p_breed      text default null,
    p_entity_id  uuid default null,
    p_arrived_on date default current_date
)
returns uuid
language plpgsql
security definer
set search_path = public, auth
as $$
declare
    v_actor uuid := auth.uid();
    v_id    uuid;
begin
    if v_actor is null then
        raise exception 'open_flock() needs a signed-in caller';
    end if;
    if not can_write_org(p_org_id) then
        raise exception 'You cannot manage flocks for this business';
    end if;
    if p_bird_count is null or p_bird_count <= 0 then
        raise exception 'A flock needs at least one bird (got %)', p_bird_count;
    end if;
    if btrim(coalesce(p_batch_code, '')) = '' then
        raise exception 'A flock needs a batch name';
    end if;

    insert into flocks (org_id, entity_id, batch_code, breed, bird_count, arrived_on, created_by)
    values (
        p_org_id, p_entity_id, btrim(p_batch_code),
        nullif(btrim(coalesce(p_breed, '')), ''), p_bird_count, p_arrived_on, v_actor
    )
    returning id into v_id;

    return v_id;
end;
$$;

-- Mortality, a weighing, a vaccination, birds sold off.
--
-- Mortality is the reason this function is used every day and the reason it
-- takes no money: a dead bird costs what it cost to raise, which is already
-- in the books as feed, and posting a second expense for it would count the
-- same loss twice.
create or replace function record_flock_event(
    p_flock_id    uuid,
    p_kind        text,
    p_quantity    numeric,
    p_recorded_by uuid        default null,
    p_note        text        default null,
    p_client_uuid uuid        default null,
    p_device_id   text        default null,
    p_occurred_at timestamptz default now()
)
returns uuid
language plpgsql
security definer
set search_path = public, auth
as $$
declare
    v_actor    uuid := auth.uid();
    v_org      uuid;
    v_alive    numeric;
    v_id       uuid;
    v_existing uuid;
begin
    if v_actor is null then
        raise exception 'record_flock_event() needs a signed-in caller';
    end if;
    if p_recorded_by is not null and p_recorded_by <> v_actor then
        raise exception 'record_flock_event() cannot record on behalf of another user';
    end if;

    select org_id into v_org from flocks where id = p_flock_id;
    if v_org is null then
        raise exception 'No such flock';
    end if;
    if not can_write_org(v_org) then
        raise exception 'You cannot record events for this business';
    end if;
    if p_kind not in ('mortality', 'weight', 'vaccination', 'sold') then
        raise exception 'Unknown flock event: %', p_kind;
    end if;
    if p_quantity is null or p_quantity <= 0 then
        raise exception 'Quantity must be greater than zero (got %)', p_quantity;
    end if;

    if p_client_uuid is not null then
        select id into v_existing
          from flock_events
         where flock_id = p_flock_id and client_uuid = p_client_uuid;
        if found then
            return v_existing;
        end if;
    end if;

    -- More birds leaving than ever arrived means somebody has typed 300
    -- instead of 3, and a flock of -297 birds is a number every report
    -- downstream will carry for the rest of the batch's life.
    if p_kind in ('mortality', 'sold') then
        select f.bird_count - coalesce(sum(e.quantity) filter (
                   where e.kind in ('mortality', 'sold')
               ), 0)
          into v_alive
          from flocks f
          left join flock_events e on e.flock_id = f.id
         where f.id = p_flock_id
         group by f.bird_count;

        if p_quantity > v_alive then
            raise exception
                'Only % birds left in this flock, cannot record % as %',
                v_alive, p_quantity, p_kind;
        end if;
    end if;

    insert into flock_events (
        flock_id, kind, quantity, note, occurred_at, created_by, device_id, client_uuid
    )
    values (
        p_flock_id, p_kind, p_quantity, p_note, p_occurred_at,
        v_actor, p_device_id, p_client_uuid
    )
    returning id into v_id;

    return v_id;
end;
$$;

-- The morning collection. No money: eggs are income when they are sold, and
-- plenty are eaten, given away or broken first.
create or replace function record_eggs(
    p_org_id      uuid,
    p_egg_count   int,
    p_flock_id    uuid        default null,
    p_grade       text        default 'normal',
    p_recorded_by uuid        default null,
    p_produced_on date        default current_date,
    p_client_uuid uuid        default null,
    p_device_id   text        default null
)
returns uuid
language plpgsql
security definer
set search_path = public, auth
as $$
declare
    v_actor    uuid := auth.uid();
    v_id       uuid;
    v_existing uuid;
begin
    if v_actor is null then
        raise exception 'record_eggs() needs a signed-in caller';
    end if;
    if p_recorded_by is not null and p_recorded_by <> v_actor then
        raise exception 'record_eggs() cannot record on behalf of another user';
    end if;
    if not can_write_org(p_org_id) then
        raise exception 'You cannot record production for this business';
    end if;
    if p_egg_count is null or p_egg_count < 0 then
        raise exception 'Egg count cannot be negative (got %)', p_egg_count;
    end if;

    if p_client_uuid is not null then
        select id into v_existing
          from egg_production
         where org_id = p_org_id and client_uuid = p_client_uuid;
        if found then
            return v_existing;
        end if;
    end if;

    insert into egg_production (
        org_id, flock_id, produced_on, grade, egg_count,
        created_by, device_id, client_uuid
    )
    values (
        p_org_id, p_flock_id, p_produced_on,
        coalesce(nullif(btrim(coalesce(p_grade, '')), ''), 'normal'),
        p_egg_count, v_actor, p_device_id, p_client_uuid
    )
    returning id into v_id;

    return v_id;
end;
$$;

-- ------------------------------------------------------------
-- 7. SELLING
-- ------------------------------------------------------------
-- Paid on the spot: this is just record_entry() with the farm's income
-- account, and exists so the app has one obvious call rather than making the
-- screen know which account name to send.
create or replace function record_farm_sale(
    p_org_id       uuid,
    p_amount       numeric,
    p_label        text,
    p_recorded_by  uuid        default null,
    p_category     text        default 'Ventes d''œufs',
    p_method       text        default 'cash',
    p_customer_name text       default null,
    p_memo         text        default null,
    p_client_uuid  uuid        default null,
    p_device_id    text        default null,
    p_occurred_at  timestamptz default now()
)
returns uuid
language plpgsql
security definer
set search_path = public, auth
as $$
declare
    v_actor uuid := auth.uid();
    v_name  text := nullif(btrim(coalesce(p_customer_name, '')), '');
begin
    if v_actor is null then
        raise exception 'record_farm_sale() needs a signed-in caller';
    end if;
    if not can_write_org(p_org_id) then
        raise exception 'You cannot record sales for this business';
    end if;

    -- The buyer's name, when there is one, rides along as a characteristic
    -- rather than as a customer row. A cash sale at the gate does not need a
    -- customer record, and creating one for every passer-by would bury the
    -- three hotels that actually matter.
    return record_entry(
        p_org_id      => p_org_id,
        p_amount      => p_amount,
        p_direction   => 'in',
        p_label       => p_label,
        p_recorded_by => v_actor,
        p_category    => p_category,
        p_method      => p_method,
        p_memo        => p_memo,
        p_details     => case when v_name is null then '{}'::jsonb
                              else jsonb_build_object('client', v_name) end,
        p_client_uuid => p_client_uuid,
        p_device_id   => p_device_id,
        p_occurred_at => p_occurred_at
    );
end;
$$;

-- Delivered now, paid later. The income is real the day it is invoiced; what
-- is missing is the cash, and that gap is the receivable.
--
-- Lines arrive as jsonb — [{"description": "...", "quantity": 30,
-- "unit_price": 2500}] — because an invoice has an unknown number of them and
-- a function signature cannot hold a list.
create or replace function create_invoice(
    p_org_id        uuid,
    p_customer_name text,
    p_lines         jsonb,
    p_recorded_by   uuid        default null,
    p_category      text        default 'Ventes d''œufs',
    p_customer_phone text       default null,
    p_due_on        date        default null,
    p_number        text        default null,
    p_memo          text        default null,
    p_client_uuid   uuid        default null,
    p_issued_on     date        default current_date
)
returns uuid
language plpgsql
security definer
set search_path = public, auth
as $$
declare
    v_actor      uuid := auth.uid();
    v_customer   uuid;
    v_invoice    uuid;
    v_entry      uuid;
    v_total      numeric := 0;
    v_number     text;
    v_line       jsonb;
    v_qty        numeric;
    v_price      numeric;
    v_amount     numeric;
    v_recv_acct  uuid;
    v_inc_acct   uuid;
    v_existing   uuid;
begin
    if v_actor is null then
        raise exception 'create_invoice() needs a signed-in caller';
    end if;
    if p_recorded_by is not null and p_recorded_by <> v_actor then
        raise exception 'create_invoice() cannot record on behalf of another user';
    end if;
    if not can_write_org(p_org_id) then
        raise exception 'You cannot invoice for this business';
    end if;
    if p_lines is null or jsonb_array_length(p_lines) = 0 then
        raise exception 'An invoice needs at least one line';
    end if;

    if p_client_uuid is not null then
        select id into v_existing
          from invoices where org_id = p_org_id and client_uuid = p_client_uuid;
        if found then
            return v_existing;
        end if;
    end if;

    for v_line in select * from jsonb_array_elements(p_lines) loop
        v_qty   := coalesce((v_line ->> 'quantity')::numeric, 1);
        v_price := coalesce((v_line ->> 'unit_price')::numeric, 0);
        if v_qty <= 0 or v_price <= 0 then
            raise exception 'Every invoice line needs a quantity and a price';
        end if;
        v_total := v_total + (v_qty * v_price);
    end loop;

    if v_total <= 0 then
        raise exception 'An invoice cannot be for nothing';
    end if;

    -- Numbering is per org and gapless-ish: the count of invoices already
    -- issued, plus one. Not a sequence, because a sequence is global and two
    -- businesses sharing this database would interleave their invoice
    -- numbers, which is the sort of thing an auditor asks about.
    v_number := nullif(btrim(coalesce(p_number, '')), '');
    if v_number is null then
        select to_char(p_issued_on, 'YYYY') || '-' ||
               lpad((count(*) + 1)::text, 4, '0')
          into v_number
          from invoices
         where org_id = p_org_id
           and extract(year from issued_on) = extract(year from p_issued_on);
    end if;

    v_customer := ensure_customer(p_org_id, p_customer_name, p_customer_phone, v_actor);

    v_recv_acct := ensure_account_by_code(
        p_org_id, '1300', 'Créances clients', 'asset', v_actor
    );
    v_inc_acct := ensure_account(p_org_id, p_category, 'income', v_actor);

    -- The customer owes us (asset up), and we have earned it (income up).
    -- No cash account is touched, which is the whole point.
    v_entry := post_ledger_pair(
        p_org_id      => p_org_id,
        p_debit_acct  => v_recv_acct,
        p_credit_acct => v_inc_acct,
        p_amount      => v_total,
        p_label       => 'Facture ' || v_number || ' — ' || btrim(p_customer_name),
        p_actor       => v_actor,
        p_memo        => p_memo,
        p_details     => jsonb_build_object('facture', v_number,
                                            'client', btrim(p_customer_name)),
        p_occurred_at => p_issued_on::timestamptz
    );

    insert into invoices (
        org_id, customer_id, number, issued_on, due_on, total,
        journal_entry_id, created_by, client_uuid
    )
    values (
        p_org_id, v_customer, v_number, p_issued_on, p_due_on, v_total,
        v_entry, v_actor, p_client_uuid
    )
    returning id into v_invoice;

    for v_line in select * from jsonb_array_elements(p_lines) loop
        v_qty    := coalesce((v_line ->> 'quantity')::numeric, 1);
        v_price  := coalesce((v_line ->> 'unit_price')::numeric, 0);
        v_amount := v_qty * v_price;
        insert into invoice_lines (invoice_id, description, quantity, unit_price, amount)
        values (
            v_invoice,
            coalesce(nullif(btrim(coalesce(v_line ->> 'description', '')), ''), 'Article'),
            v_qty, v_price, v_amount
        );
    end loop;

    return v_invoice;
end;
$$;

-- The hotel settles up, in full or in part.
create or replace function record_invoice_payment(
    p_invoice_id  uuid,
    p_amount      numeric,
    p_method      text        default 'cash',
    p_recorded_by uuid        default null,
    p_paid_on     date        default current_date,
    p_client_uuid uuid        default null
)
returns uuid
language plpgsql
security definer
set search_path = public, auth
as $$
declare
    v_actor      uuid := auth.uid();
    v_org        uuid;
    v_number     text;
    v_total      numeric;
    v_paid       numeric;
    v_cash_acct  uuid;
    v_recv_acct  uuid;
    v_entry      uuid;
    v_id         uuid;
    v_existing   uuid;
begin
    if v_actor is null then
        raise exception 'record_invoice_payment() needs a signed-in caller';
    end if;
    if p_recorded_by is not null and p_recorded_by <> v_actor then
        raise exception 'record_invoice_payment() cannot record on behalf of another user';
    end if;

    select org_id, number, total into v_org, v_number, v_total
      from invoices where id = p_invoice_id and cancelled_at is null;
    if v_org is null then
        raise exception 'No such invoice, or it has been cancelled';
    end if;
    if not can_write_org(v_org) then
        raise exception 'You cannot record payments for this business';
    end if;
    if p_amount is null or p_amount <= 0 then
        raise exception 'Amount must be greater than zero (got %)', p_amount;
    end if;

    if p_client_uuid is not null then
        select id into v_existing
          from invoice_payments
         where invoice_id = p_invoice_id and client_uuid = p_client_uuid;
        if found then
            return v_existing;
        end if;
    end if;

    select coalesce(sum(amount), 0) into v_paid
      from invoice_payments where invoice_id = p_invoice_id;

    -- Overpaying is a real thing that happens and it is not a payment against
    -- this invoice. Refusing it keeps the receivable account honest; the
    -- extra is a separate conversation and, for now, a separate entry.
    if v_paid + p_amount > v_total then
        raise exception
            'Invoice % is for % and % has already been paid; % is too much',
            v_number, v_total, v_paid, p_amount;
    end if;

    v_cash_acct := resolve_cash_account(v_org, p_method, v_actor);
    v_recv_acct := ensure_account_by_code(
        v_org, '1300', 'Créances clients', 'asset', v_actor
    );

    -- Cash arrives, and the customer stops owing it. No income: that was
    -- recognised the day the invoice was raised, and recognising it again
    -- here would double every credit sale in the books.
    v_entry := post_ledger_pair(
        p_org_id      => v_org,
        p_debit_acct  => v_cash_acct,
        p_credit_acct => v_recv_acct,
        p_amount      => p_amount,
        p_label       => 'Règlement facture ' || v_number,
        p_actor       => v_actor,
        p_details     => jsonb_build_object('facture', v_number),
        p_occurred_at => p_paid_on::timestamptz
    );

    insert into invoice_payments (
        invoice_id, amount, method, paid_on, journal_entry_id, created_by, client_uuid
    )
    values (
        p_invoice_id, p_amount, p_method, p_paid_on, v_entry, v_actor, p_client_uuid
    )
    returning id into v_id;

    return v_id;
end;
$$;

-- ------------------------------------------------------------
-- 8. WHAT THE FARM LOOKS LIKE
-- ------------------------------------------------------------
-- Line-item detail, so these need full visibility — the same rule 006
-- established. An investor granted 'summary' gets the money reports and not
-- the operational ones, which is the correct reading: how many birds died on
-- Tuesday is running the farm, not overseeing it.

create or replace function stock_on_hand(p_org_id uuid)
returns table (
    item_id       uuid,
    name          text,
    unit          text,
    on_hand       numeric,
    reorder_level numeric,
    below_reorder boolean,
    last_movement timestamptz
)
language sql
stable
security definer
set search_path = public, auth
as $$
    select
        i.id, i.name, i.unit,
        coalesce(sum(
            case sm.kind
                when 'received' then sm.quantity
                when 'consumed' then -sm.quantity
                when 'wasted'   then -sm.quantity
                -- Signed already: a count that found fewer sacks than the
                -- running total is a negative adjustment.
                when 'adjusted' then sm.quantity
            end
        ), 0),
        i.reorder_level,
        i.reorder_level is not null and coalesce(sum(
            case sm.kind
                when 'received' then sm.quantity
                when 'consumed' then -sm.quantity
                when 'wasted'   then -sm.quantity
                when 'adjusted' then sm.quantity
            end
        ), 0) <= i.reorder_level,
        max(sm.occurred_at)
    from items i
    left join stock_movements sm on sm.item_id = i.id
    where i.org_id = p_org_id
      and i.is_active
      and has_full_visibility(p_org_id)
    group by i.id, i.name, i.unit, i.reorder_level
    order by 6 desc nulls last, i.name;
$$;

-- Birds alive, how old, and whether they are laying as they should.
--
-- `lay_rate` is eggs in the last seven days divided by (birds alive × 7). It
-- is the number that tells a farmer something is wrong days before the money
-- does, which is the entire argument for making somebody count eggs every
-- morning.
create or replace function flock_status(p_org_id uuid, p_include_closed boolean default false)
returns table (
    flock_id    uuid,
    batch_code  text,
    breed       text,
    arrived_on  date,
    age_days    int,
    started     int,
    alive       int,
    died        int,
    sold        int,
    eggs_7d     bigint,
    lay_rate    numeric,
    closed_on   date
)
language sql
stable
security definer
set search_path = public, auth
as $$
    with counts as (
        select
            f.id,
            coalesce(sum(e.quantity) filter (where e.kind = 'mortality'), 0) as died,
            coalesce(sum(e.quantity) filter (where e.kind = 'sold'), 0) as sold
        from flocks f
        left join flock_events e on e.flock_id = f.id
        where f.org_id = p_org_id
        group by f.id
    ),
    eggs as (
        select ep.flock_id, sum(ep.egg_count) as n
        from egg_production ep
        where ep.org_id = p_org_id
          and ep.produced_on > current_date - 7
        group by ep.flock_id
    )
    select
        f.id, f.batch_code, f.breed, f.arrived_on,
        (current_date - f.arrived_on)::int,
        f.bird_count,
        (f.bird_count - c.died - c.sold)::int,
        c.died::int,
        c.sold::int,
        coalesce(e.n, 0),
        case
            when (f.bird_count - c.died - c.sold) > 0
            then round(coalesce(e.n, 0)::numeric
                       / ((f.bird_count - c.died - c.sold) * 7), 3)
            else 0
        end,
        f.closed_on
    from flocks f
    join counts c on c.id = f.id
    left join eggs e on e.flock_id = f.id
    where f.org_id = p_org_id
      and has_full_visibility(p_org_id)
      and (p_include_closed or f.closed_on is null)
    order by f.closed_on nulls first, f.arrived_on desc;
$$;

-- The home screen's day.
create or replace function farm_daily_summary(
    p_org_id uuid,
    p_day    date default current_date
)
returns table (
    eggs        bigint,
    deaths      numeric,
    feed_used   numeric,
    money_in    numeric,
    money_out   numeric
)
language sql
stable
security definer
set search_path = public, auth
as $$
    select
        (select coalesce(sum(ep.egg_count), 0)
           from egg_production ep
          where ep.org_id = p_org_id and ep.produced_on = p_day),

        (select coalesce(sum(fe.quantity), 0)
           from flock_events fe
           join flocks f on f.id = fe.flock_id
          where f.org_id = p_org_id
            and fe.kind = 'mortality'
            and fe.occurred_at::date = p_day),

        (select coalesce(sum(sm.quantity), 0)
           from stock_movements sm
          where sm.org_id = p_org_id
            and sm.kind = 'consumed'
            and sm.occurred_at::date = p_day),

        (select coalesce(sum(jl.credit - jl.debit), 0)
           from journal_entries je
           join journal_lines jl on jl.journal_entry_id = je.id
           join accounts a on a.id = jl.account_id
          where je.org_id = p_org_id
            and a.type = 'income'
            and je.created_at::date = p_day),

        (select coalesce(sum(jl.debit - jl.credit), 0)
           from journal_entries je
           join journal_lines jl on jl.journal_entry_id = je.id
           join accounts a on a.id = jl.account_id
          where je.org_id = p_org_id
            and a.type = 'expense'
            and je.created_at::date = p_day)
    where has_full_visibility(p_org_id);
$$;

-- Who has not paid, and how late they are.
create or replace function outstanding_invoices(p_org_id uuid)
returns table (
    invoice_id    uuid,
    number        text,
    customer_name text,
    customer_phone text,
    issued_on     date,
    due_on        date,
    total         numeric,
    paid          numeric,
    outstanding   numeric,
    days_overdue  int
)
language sql
stable
security definer
set search_path = public, auth
as $$
    select
        i.id, i.number, c.name, c.phone, i.issued_on, i.due_on, i.total,
        coalesce(p.paid, 0),
        i.total - coalesce(p.paid, 0),
        case
            when i.due_on is null then 0
            else greatest((current_date - i.due_on)::int, 0)
        end
    from invoices i
    join customers c on c.id = i.customer_id
    left join (
        select invoice_id, sum(amount) as paid
        from invoice_payments group by invoice_id
    ) p on p.invoice_id = i.id
    where i.org_id = p_org_id
      and i.cancelled_at is null
      and has_full_visibility(p_org_id)
      and i.total - coalesce(p.paid, 0) > 0
    order by 10 desc, i.issued_on;
$$;

-- ------------------------------------------------------------
-- 9. RLS
-- ------------------------------------------------------------
-- The same shape as everything else: readable within the org, writable by
-- anyone who is not an observer, and — for the two append-only tables —
-- carrying no update or delete policy at all. That omission is what makes
-- them append-only, exactly as it does for journal_entries.

alter table items enable row level security;
alter table stock_movements enable row level security;
alter table flocks enable row level security;
alter table flock_events enable row level security;
alter table egg_production enable row level security;
alter table customers enable row level security;
alter table invoices enable row level security;
alter table invoice_lines enable row level security;
alter table invoice_payments enable row level security;

drop policy if exists "items readable within org" on items;
create policy "items readable within org"
on items for select using (is_org_member(org_id));

-- Renaming an item and setting its reorder level are ordinary work, not
-- administration: the person who notices the feed runs out early is the
-- person feeding the birds.
drop policy if exists "items managed by non-observers" on items;
create policy "items managed by non-observers"
on items for all using (can_write_org(org_id)) with check (can_write_org(org_id));

-- Operational detail, not a total: the same visibility test the reports use.
drop policy if exists "stock movements readable with full visibility" on stock_movements;
create policy "stock movements readable with full visibility"
on stock_movements for select using (has_full_visibility(org_id));

drop policy if exists "stock movements written by non-observers" on stock_movements;
create policy "stock movements written by non-observers"
on stock_movements for insert with check (can_write_org(org_id));
-- No update, no delete. A miscount is corrected by an 'adjusted' movement.

drop policy if exists "flocks readable within org" on flocks;
create policy "flocks readable within org"
on flocks for select using (is_org_member(org_id));

drop policy if exists "flocks managed by non-observers" on flocks;
create policy "flocks managed by non-observers"
on flocks for all using (can_write_org(org_id)) with check (can_write_org(org_id));

drop policy if exists "flock events readable with full visibility" on flock_events;
create policy "flock events readable with full visibility"
on flock_events for select
using (
    exists (
        select 1 from flocks f
        where f.id = flock_events.flock_id and has_full_visibility(f.org_id)
    )
);

drop policy if exists "flock events written by non-observers" on flock_events;
create policy "flock events written by non-observers"
on flock_events for insert
with check (
    exists (
        select 1 from flocks f
        where f.id = flock_events.flock_id and can_write_org(f.org_id)
    )
);
-- No update, no delete: how many birds died is not a number anybody edits.

drop policy if exists "egg production readable with full visibility" on egg_production;
create policy "egg production readable with full visibility"
on egg_production for select using (has_full_visibility(org_id));

drop policy if exists "egg production written by non-observers" on egg_production;
create policy "egg production written by non-observers"
on egg_production for insert with check (can_write_org(org_id));

drop policy if exists "customers readable within org" on customers;
create policy "customers readable within org"
on customers for select using (is_org_member(org_id));

drop policy if exists "customers managed by non-observers" on customers;
create policy "customers managed by non-observers"
on customers for all using (can_write_org(org_id)) with check (can_write_org(org_id));

drop policy if exists "invoices readable with full visibility" on invoices;
create policy "invoices readable with full visibility"
on invoices for select using (has_full_visibility(org_id));

drop policy if exists "invoices written by non-observers" on invoices;
create policy "invoices written by non-observers"
on invoices for insert with check (can_write_org(org_id));

-- Cancelling is an update, and it is the only one. There is no delete
-- policy: a cancelled invoice is a fact about a customer relationship.
drop policy if exists "invoices cancelled by non-observers" on invoices;
create policy "invoices cancelled by non-observers"
on invoices for update using (can_write_org(org_id)) with check (can_write_org(org_id));

drop policy if exists "invoice lines readable with their invoice" on invoice_lines;
create policy "invoice lines readable with their invoice"
on invoice_lines for select
using (
    exists (
        select 1 from invoices i
        where i.id = invoice_lines.invoice_id and has_full_visibility(i.org_id)
    )
);

drop policy if exists "invoice lines written with their invoice" on invoice_lines;
create policy "invoice lines written with their invoice"
on invoice_lines for insert
with check (
    exists (
        select 1 from invoices i
        where i.id = invoice_lines.invoice_id and can_write_org(i.org_id)
    )
);

drop policy if exists "payments readable with their invoice" on invoice_payments;
create policy "payments readable with their invoice"
on invoice_payments for select
using (
    exists (
        select 1 from invoices i
        where i.id = invoice_payments.invoice_id and has_full_visibility(i.org_id)
    )
);

drop policy if exists "payments written with their invoice" on invoice_payments;
create policy "payments written with their invoice"
on invoice_payments for insert
with check (
    exists (
        select 1 from invoices i
        where i.id = invoice_payments.invoice_id and can_write_org(i.org_id)
    )
);
-- No update, no delete: a payment received is not a thing to un-receive.

-- ------------------------------------------------------------
-- 10. THE LOG WATCHES THIS TOO
-- ------------------------------------------------------------
-- 008 attached its trigger to a fixed list of tables, which by definition
-- could not include tables that did not exist yet. Flocks and customers are
-- structural — who the farm sells to, and what it is raising — and belong in
-- the same trail as the chart of accounts.
--
-- The two high-volume append-only tables are left out for the same reason
-- journal_lines is: they are already unmodifiable, so a log of them would
-- record only that they were written, which they say themselves.
do $$
declare
    v_table text;
begin
    foreach v_table in array array['items', 'flocks', 'customers', 'invoices']
    loop
        execute format('drop trigger if exists audit_%1$s on %1$I', v_table);
        execute format(
            'create trigger audit_%1$s after insert or update or delete on %1$I
             for each row execute function audit_row()',
            v_table
        );
    end loop;
end $$;

-- invoices reaches its org through org_id, items and customers likewise, and
-- flocks likewise — so audit_row() resolves all four without changes.

-- ------------------------------------------------------------
-- 11. GRANTS
-- ------------------------------------------------------------
revoke execute on function post_ledger_pair(uuid, uuid, uuid, numeric, text, uuid, text, jsonb, uuid, text, timestamptz) from public;
revoke execute on function ensure_item(uuid, text, text, uuid) from public;
revoke execute on function ensure_customer(uuid, text, text, uuid) from public;

revoke execute on function receive_stock(uuid, text, numeric, numeric, text, text, text, uuid, text, uuid, text, timestamptz) from public;
revoke execute on function move_stock(uuid, text, numeric, text, text, uuid, text, uuid, text, timestamptz) from public;
revoke execute on function open_flock(uuid, text, int, text, uuid, date) from public;
revoke execute on function record_flock_event(uuid, text, numeric, uuid, text, uuid, text, timestamptz) from public;
revoke execute on function record_eggs(uuid, int, uuid, text, uuid, date, uuid, text) from public;
revoke execute on function record_farm_sale(uuid, numeric, text, uuid, text, text, text, text, uuid, text, timestamptz) from public;
revoke execute on function create_invoice(uuid, text, jsonb, uuid, text, text, date, text, text, uuid, date) from public;
revoke execute on function record_invoice_payment(uuid, numeric, text, uuid, date, uuid) from public;
revoke execute on function stock_on_hand(uuid) from public;
revoke execute on function flock_status(uuid, boolean) from public;
revoke execute on function farm_daily_summary(uuid, date) from public;
revoke execute on function outstanding_invoices(uuid) from public;

do $$
begin
    if exists (select 1 from pg_roles where rolname = 'authenticated') then
        grant execute on function receive_stock(uuid, text, numeric, numeric, text, text, text, uuid, text, uuid, text, timestamptz) to authenticated;
        grant execute on function move_stock(uuid, text, numeric, text, text, uuid, text, uuid, text, timestamptz) to authenticated;
        grant execute on function open_flock(uuid, text, int, text, uuid, date) to authenticated;
        grant execute on function record_flock_event(uuid, text, numeric, uuid, text, uuid, text, timestamptz) to authenticated;
        grant execute on function record_eggs(uuid, int, uuid, text, uuid, date, uuid, text) to authenticated;
        grant execute on function record_farm_sale(uuid, numeric, text, uuid, text, text, text, text, uuid, text, timestamptz) to authenticated;
        grant execute on function create_invoice(uuid, text, jsonb, uuid, text, text, date, text, text, uuid, date) to authenticated;
        grant execute on function record_invoice_payment(uuid, numeric, text, uuid, date, uuid) to authenticated;
        grant execute on function stock_on_hand(uuid) to authenticated;
        grant execute on function flock_status(uuid, boolean) to authenticated;
        grant execute on function farm_daily_summary(uuid, date) to authenticated;
        grant execute on function outstanding_invoices(uuid) to authenticated;
        grant execute on function seed_farm_accounts(uuid) to authenticated;

        grant select, insert, update, delete on
            items, stock_movements, flocks, flock_events, egg_production,
            customers, invoices, invoice_lines, invoice_payments
            to authenticated;
    end if;
end $$;


-- ============================================================
-- 010_platform_admin.sql
-- ============================================================
-- ============================================================
-- 010_platform_admin.sql
--
-- Numbered 010, after 009_farm_profile.sql, because this was written as 006
-- on a branch while 006_report_access.sql was being written on another. The
-- order matters beyond avoiding a name collision: the four helpers replaced
-- below are the ones 006's policies call, so this has to be the last word on
-- them. Applied before 006 it would be silently undone.
--
-- Two problems, one column. Right now:
--   1. Seeing every business takes a manual membership grant per org —
--      admin@kajapp.com has to be re-granted every time a new one is made.
--   2. Nothing can create a new org at all. orgs has no INSERT policy, and
--      a naive INSERT would be blocked outright — you can't be "admin of
--      an org" that doesn't exist yet to grant you that role.
--
-- is_platform_admin on profiles solves both, added as one extra OR clause
-- to each existing SECURITY DEFINER helper below. Every signature, column
-- name, and column type matches 004_rls_policies.sql exactly — nothing
-- that already calls these changes, only what they return for this one
-- flag.
--
-- NOT changed here, on purpose: can_write_org's original body excludes
-- only 'observer', not 'approver' too. An approver being able to write
-- seems like it may be a pre-existing gap against the role's intended
-- read-plus-signoff meaning — worth a look on its own, not silently
-- folded into this migration.
-- ============================================================

alter table profiles add column if not exists is_platform_admin boolean not null default false;

create or replace function my_org_ids()
returns setof uuid
language sql
stable
security definer
set search_path = public, auth
as $$
    select id from orgs
    where exists(select 1 from profiles where id = auth.uid() and is_platform_admin)
    union
    select distinct m.org_id
    from memberships m
    where m.user_id = auth.uid();
$$;

create or replace function is_org_member(p_org_id uuid)
returns boolean
language sql
stable
security definer
set search_path = public, auth
as $$
    select
        exists(select 1 from profiles where id = auth.uid() and is_platform_admin)
        or exists (
            select 1 from memberships m
            where m.user_id = auth.uid() and m.org_id = p_org_id
        );
$$;

create or replace function is_org_admin(p_org_id uuid)
returns boolean
language sql
stable
security definer
set search_path = public, auth
as $$
    select
        exists(select 1 from profiles where id = auth.uid() and is_platform_admin)
        or exists (
            select 1 from memberships m
            where m.user_id = auth.uid()
              and m.org_id = p_org_id
              and m.role in ('owner', 'super_admin', 'admin')
        );
$$;

create or replace function can_write_org(p_org_id uuid)
returns boolean
language sql
stable
security definer
set search_path = public, auth
as $$
    select
        exists(select 1 from profiles where id = auth.uid() and is_platform_admin)
        or exists (
            select 1 from memberships m
            where m.user_id = auth.uid()
              and m.org_id = p_org_id
              and m.role <> 'observer'
        );
$$;

-- CREATE OR REPLACE cannot change a table-returning function's output
-- columns, and dropping is required even though this one's shape matches
-- the original exactly, in case a future edit doesn't.
drop function if exists my_orgs();

create or replace function my_orgs()
returns table (
    org_id           uuid,
    name             text,
    slug             text,
    profile          text,
    default_currency text,
    roles            text[],
    visibility       text
)
language sql
stable
security definer
set search_path = public, auth
as $$
    select
        o.id, o.name, o.slug, o.profile, o.default_currency,
        array['platform_admin'::text],
        'full'::text
    from orgs o
    where exists(select 1 from profiles where id = auth.uid() and is_platform_admin)

    union all

    select
        o.id, o.name, o.slug, o.profile, o.default_currency,
        array_agg(distinct m.role::text order by m.role::text),
        case when bool_or(m.visibility = 'full') then 'full' else 'summary' end
    from memberships m
    join orgs o on o.id = m.org_id
    where m.user_id = auth.uid()
      and not exists(select 1 from profiles where id = auth.uid() and is_platform_admin)
    group by o.id, o.name, o.slug, o.profile, o.default_currency

    order by name;
$$;

-- ------------------------------------------------------------
-- Creating a business. SECURITY DEFINER on purpose, unlike
-- record_contribution/record_expense: RLS cannot gate an INSERT into orgs
-- on membership in an org that does not exist until this statement runs, so
-- the is_platform_admin check below IS the authorization, not a backstop.
-- ------------------------------------------------------------

create or replace function create_org(
    p_name     text,
    p_slug     text,
    p_profile  text default 'generic',
    p_currency text default 'XOF'
)
returns uuid
language plpgsql
security definer
set search_path = public, auth
as $$
declare
    v_org_id uuid;
begin
    if not exists(select 1 from profiles where id = auth.uid() and is_platform_admin) then
        raise exception 'Only a platform admin can create a new business';
    end if;

    insert into orgs (name, slug, profile, default_currency)
    values (p_name, p_slug, p_profile, p_currency)
    returning id into v_org_id;

    -- Ownership on the new org, even though platform-admin bypass already
    -- grants access — so the person who made it shows up as its owner, not
    -- an invisible ghost with access nobody can see the source of.
    insert into memberships (org_id, user_id, role, scope_kind, scope_id)
    values (v_org_id, auth.uid(), 'owner', 'org', v_org_id);

    -- Starter data by profile. Only 'church' has a dedicated module today
    -- (002_church_profile.sql); everything else gets a minimal generic
    -- chart of accounts so the org isn't empty before its own module exists.
    if p_profile = 'church' then
        perform seed_church_accounts(v_org_id);
    else
        insert into accounts (org_id, code, name, type) values
            (v_org_id, '1000', 'Cash on Hand',        'asset'),
            (v_org_id, '1010', 'Bank Account',        'asset'),
            (v_org_id, '1020', 'Mobile Money',        'asset'),
            (v_org_id, '4000', 'Sales',                'income'),
            (v_org_id, '5000', 'Purchases',            'expense'),
            (v_org_id, '5010', 'Operating Expenses',   'expense')
        on conflict (org_id, code) do nothing;
    end if;

    return v_org_id;
end;
$$;


-- ============================================================
-- 011_retail_profile.sql
-- ============================================================
-- ============================================================
-- 011_retail_profile.sql — Esperance's store.
--
-- The retail profile: products that expire, sales that decrement them, and
-- returns that put them back. Everything money-shaped goes through
-- `record_entry()` from 007 rather than writing journal lines here, so a sale
-- in a shop and an offering in a church land in the same ledger and the same
-- income statement reads both.
--
-- Three decisions worth knowing before reading the rest.
--
-- 1. **Stock is a column, not a derived total.** `products.quantity` is
--    written by the functions below. The farm does the opposite — it derives
--    counts from append-only `stock_movements` — and that is the better model
--    for a place where mortality and waste have to stay visible. A shop
--    counts differently: Esperance needs "how many do I have right now" on a
--    screen in a market with no signal, and a running sum over every sale
--    ever made is not that. Every movement is still recorded in `sale_lines`,
--    so the column can be rebuilt from history if it ever drifts.
--
-- 2. **A return is a sale with kind = 'return'.** Not a deletion, not an
--    edit, and not a negative row hidden inside the same kind. It posts its
--    own reversing ledger entry, so the books show both the sale and the
--    return rather than a number that quietly shrank.
--
-- 3. **Cost is snapshotted onto the line.** `sale_lines.unit_cost` copies
--    `products.cost_price` at the moment of sale. Without it, changing a
--    product's cost price would silently rewrite the margin on every sale
--    already made.
--
-- Not here, and deliberately: the camera, the R2 upload, the on-device OCR
-- and the barcode scanner that M5 also asks for. `products.barcode` and the
-- existing `documents` table are the seams they attach to; none of them can
-- be built or tested without a device in a hand.
-- ============================================================

-- ------------------------------------------------------------
-- What is on the shelves
-- ------------------------------------------------------------

create table if not exists products (
    id            uuid primary key default gen_random_uuid(),
    org_id        uuid not null references orgs(id) on delete cascade,
    name          text not null,
    -- Scanned, not typed. Null until a barcode is read, which is most of them.
    barcode       text,
    -- The shop's own reference, when it has one.
    sku           text,
    -- What it cost to buy. Drives margin and the value at risk on expiry.
    cost_price    numeric(14,2) not null default 0 check (cost_price >= 0),
    sale_price    numeric(14,2) not null default 0 check (sale_price >= 0),
    quantity      numeric(14,3) not null default 0,
    -- The whole point of the module for Esperance: stock that dies on a date.
    expires_on    date,
    -- Below this, the home screen says so. Null means never mention it.
    low_stock_at  numeric(14,3),
    is_active     boolean not null default true,
    created_at    timestamptz not null default now(),
    created_by    uuid references profiles(id)
);

-- One product per name per shop, matched the way a name arrives from a phone
-- keyboard: case-insensitively, on trimmed text. Same rule as ensure_account()
-- in 007 and ensure_item() in 009.
create unique index if not exists products_by_name
    on products (org_id, lower(btrim(name)));

-- A barcode identifies exactly one product within a shop. Partial, because
-- most products never get one and null is not a duplicate.
create unique index if not exists products_by_barcode
    on products (org_id, barcode) where barcode is not null;

create index if not exists products_active
    on products (org_id) where is_active;

-- The expiry alert query, which runs on every home screen open.
create index if not exists products_by_expiry
    on products (org_id, expires_on)
    where expires_on is not null and is_active;

-- ------------------------------------------------------------
-- What was sold
-- ------------------------------------------------------------

create table if not exists sales (
    id           uuid primary key default gen_random_uuid(),
    org_id       uuid not null references orgs(id) on delete cascade,
    kind         text not null default 'sale' check (kind in ('sale', 'return')),
    occurred_at  timestamptz not null default now(),
    total        numeric(14,2) not null default 0,
    -- 'cash' | 'bank' | 'mobile_money', or any account name. Passed straight
    -- to record_entry(), which resolves it to a cash account.
    method       text not null default 'cash',
    note         text,
    -- The ledger entry this sale posted. Null only for a sale recorded
    -- against a shop with no accounts, which cannot happen through the
    -- functions below.
    entry_id     uuid references journal_entries(id),
    -- The sale being undone, for kind = 'return'.
    reverses_id  uuid references sales(id),
    recorded_by  uuid references profiles(id),
    device_id    text,
    -- Two phones in a market both retrying the same sale must produce one
    -- sale. Same contract as record_contribution() in 002.
    client_uuid  uuid,
    created_at   timestamptz not null default now()
);

create unique index if not exists sales_client_uuid_key
    on sales (org_id, client_uuid) where client_uuid is not null;

create index if not exists sales_by_day
    on sales (org_id, occurred_at desc);

create table if not exists sale_lines (
    id          uuid primary key default gen_random_uuid(),
    sale_id     uuid not null references sales(id) on delete cascade,
    product_id  uuid references products(id),
    -- The name as it was at the time of sale. A product renamed next month
    -- must not rewrite last month's receipt.
    name        text not null,
    quantity    numeric(14,3) not null check (quantity > 0),
    unit_price  numeric(14,2) not null check (unit_price >= 0),
    -- Snapshotted; see the header.
    unit_cost   numeric(14,2) not null default 0,
    line_total  numeric(14,2) not null
);

create index if not exists sale_lines_by_sale on sale_lines (sale_id);
create index if not exists sale_lines_by_product on sale_lines (product_id);

-- ------------------------------------------------------------
-- Putting a product on the shelf
-- ------------------------------------------------------------

-- Finds the product by name the first time and every time after, so a shop
-- that types "Sucre 1kg" twice has one product with two sales rather than two
-- products with one each.
create or replace function ensure_product(
    p_org_id     uuid,
    p_name       text,
    p_sale_price numeric default null,
    p_cost_price numeric default null,
    p_barcode    text    default null,
    p_expires_on date    default null,
    p_actor      uuid    default null
)
returns uuid
language plpgsql
as $$
declare
    v_name text := btrim(coalesce(p_name, ''));
    v_id   uuid;
begin
    if v_name = '' then
        raise exception 'A product needs a name';
    end if;

    select id into v_id from products
    where org_id = p_org_id and lower(btrim(name)) = lower(v_name);

    if v_id is null then
        -- p_actor rather than auth.uid(): this runs as the caller, and the
        -- `authenticated` role has no rights in the auth schema. Every
        -- SECURITY DEFINER function that calls this passes the actor down,
        -- the same way ensure_item() works in 009.
        insert into products (org_id, name, sale_price, cost_price, barcode,
                              expires_on, created_by)
        values (p_org_id, v_name,
                coalesce(p_sale_price, 0), coalesce(p_cost_price, 0),
                p_barcode, p_expires_on, p_actor)
        returning id into v_id;
    else
        -- Only fill in what was missing. A price passed on a later sale must
        -- not silently rewrite the shelf price somebody set on purpose.
        update products set
            sale_price = case when sale_price = 0 and p_sale_price is not null
                              then p_sale_price else sale_price end,
            cost_price = case when cost_price = 0 and p_cost_price is not null
                              then p_cost_price else cost_price end,
            barcode    = coalesce(barcode, p_barcode),
            expires_on = coalesce(expires_on, p_expires_on)
        where id = v_id;
    end if;

    return v_id;
end;
$$;

-- Stock arriving. Increases the count and posts the purchase as an expense,
-- the same treatment the farm gives feed: the day the goods arrive is the day
-- the money is gone.
create or replace function receive_products(
    p_org_id      uuid,
    p_product_id  uuid,
    p_quantity    numeric,
    p_unit_cost   numeric     default null,
    p_expires_on  date        default null,
    p_method      text        default 'cash',
    p_client_uuid uuid        default null,
    p_device_id   text        default null,
    p_occurred_at timestamptz default now()
)
returns uuid
language plpgsql
security definer
set search_path = public, auth
as $$
declare
    v_actor   uuid := auth.uid();
    v_name    text;
    v_cost    numeric;
    v_entry   uuid;
begin
    if p_quantity is null or p_quantity <= 0 then
        raise exception 'A delivery needs a quantity';
    end if;

    select name, cost_price into v_name, v_cost
    from products where id = p_product_id and org_id = p_org_id;

    if v_name is null then
        raise exception 'No such product in this business';
    end if;

    v_cost := coalesce(p_unit_cost, v_cost, 0);

    update products set
        quantity   = quantity + p_quantity,
        cost_price = case when p_unit_cost is not null then p_unit_cost
                          else cost_price end,
        expires_on = coalesce(p_expires_on, expires_on)
    where id = p_product_id;

    -- Only money that actually moved gets a ledger entry. Stock received on
    -- credit, or with no cost recorded, still updates the count.
    if v_cost > 0 then
        v_entry := record_entry(
            p_org_id      => p_org_id,
            p_amount      => v_cost * p_quantity,
            p_direction   => 'out',
            p_label       => 'Achat de marchandise',
            p_recorded_by => v_actor,
            p_category    => 'Achats de marchandises',
            p_method      => p_method,
            p_memo        => v_name,
            p_details     => jsonb_build_object('product', v_name,
                                                'quantity', p_quantity),
            p_client_uuid => p_client_uuid,
            p_device_id   => p_device_id,
            p_occurred_at => p_occurred_at
        );
    end if;

    return v_entry;
end;
$$;

-- ------------------------------------------------------------
-- Selling
-- ------------------------------------------------------------

-- One sale, one or more lines, one ledger entry.
--
-- [p_lines] is a json array of {product_id?, name, quantity, unit_price}.
-- A line with no product_id and a name creates the product, so somebody can
-- sell a thing that was never entered without stopping to enter it first —
-- the capture-first rule M5 is built around.
create or replace function record_sale(
    p_org_id      uuid,
    p_lines       jsonb,
    p_method      text        default 'cash',
    p_note        text        default null,
    p_client_uuid uuid        default null,
    p_device_id   text        default null,
    p_occurred_at timestamptz default now()
)
returns uuid
language plpgsql
security definer
set search_path = public, auth
as $$
declare
    v_actor    uuid := auth.uid();
    v_sale_id  uuid;
    v_existing uuid;
    v_line     jsonb;
    v_product  uuid;
    v_name     text;
    v_qty      numeric;
    v_price    numeric;
    v_cost     numeric;
    v_total    numeric := 0;
    v_entry    uuid;
begin
    if p_lines is null or jsonb_typeof(p_lines) <> 'array'
       or jsonb_array_length(p_lines) = 0 then
        raise exception 'A sale needs at least one line';
    end if;

    -- A retried sale returns the original rather than selling twice. The
    -- phone in a market retries whenever signal returns, which is often.
    if p_client_uuid is not null then
        select id into v_existing from sales
        where org_id = p_org_id and client_uuid = p_client_uuid;
        if v_existing is not null then
            return v_existing;
        end if;
    end if;

    insert into sales (org_id, kind, occurred_at, method, note, recorded_by,
                       device_id, client_uuid)
    values (p_org_id, 'sale', p_occurred_at, p_method, p_note, v_actor,
            p_device_id, p_client_uuid)
    returning id into v_sale_id;

    for v_line in select * from jsonb_array_elements(p_lines)
    loop
        v_name  := btrim(coalesce(v_line ->> 'name', ''));
        v_qty   := coalesce((v_line ->> 'quantity')::numeric, 0);
        v_price := coalesce((v_line ->> 'unit_price')::numeric, 0);

        if v_qty <= 0 then
            raise exception 'Every line needs a quantity greater than zero';
        end if;

        v_product := nullif(v_line ->> 'product_id', '')::uuid;

        if v_product is null then
            if v_name = '' then
                raise exception 'Every line needs a product or a name';
            end if;
            v_product := ensure_product(p_org_id, v_name,
                                        p_sale_price => v_price,
                                        p_actor      => v_actor);
        end if;

        select name, cost_price into v_name, v_cost
        from products where id = v_product and org_id = p_org_id;

        if v_name is null then
            raise exception 'No such product in this business';
        end if;

        insert into sale_lines (sale_id, product_id, name, quantity,
                                unit_price, unit_cost, line_total)
        values (v_sale_id, v_product, v_name, v_qty, v_price,
                coalesce(v_cost, 0), v_qty * v_price);

        -- Stock can go negative. That is deliberate: refusing the sale
        -- because the count is wrong would make the count more important than
        -- the customer standing there, and the count is the thing more likely
        -- to be wrong.
        update products set quantity = quantity - v_qty where id = v_product;

        v_total := v_total + (v_qty * v_price);
    end loop;

    if v_total > 0 then
        v_entry := record_entry(
            p_org_id      => p_org_id,
            p_amount      => v_total,
            p_direction   => 'in',
            p_label       => 'Vente',
            p_recorded_by => v_actor,
            p_category    => 'Ventes',
            p_method      => p_method,
            p_memo        => p_note,
            p_details     => jsonb_build_object('sale_id', v_sale_id),
            p_client_uuid => p_client_uuid,
            p_device_id   => p_device_id,
            p_occurred_at => p_occurred_at
        );
    end if;

    update sales set total = v_total, entry_id = v_entry where id = v_sale_id;

    return v_sale_id;
end;
$$;

-- Undoing a sale, by writing another one rather than erasing it.
create or replace function record_return(
    p_sale_id     uuid,
    p_note        text default null,
    p_client_uuid uuid default null
)
returns uuid
language plpgsql
security definer
set search_path = public, auth
as $$
declare
    v_actor    uuid := auth.uid();
    v_org      uuid;
    v_method   text;
    v_total    numeric;
    v_kind     text;
    v_return   uuid;
    v_existing uuid;
    v_line     record;
    v_entry    uuid;
begin
    select org_id, method, total, kind
      into v_org, v_method, v_total, v_kind
    from sales where id = p_sale_id;

    if v_org is null then
        raise exception 'No such sale';
    end if;
    if v_kind = 'return' then
        raise exception 'That is already a return';
    end if;
    if exists (select 1 from sales where reverses_id = p_sale_id) then
        raise exception 'That sale has already been returned';
    end if;

    if p_client_uuid is not null then
        select id into v_existing from sales
        where org_id = v_org and client_uuid = p_client_uuid;
        if v_existing is not null then
            return v_existing;
        end if;
    end if;

    insert into sales (org_id, kind, method, note, total, reverses_id,
                       recorded_by, client_uuid)
    values (v_org, 'return', v_method, p_note, v_total, p_sale_id,
            v_actor, p_client_uuid)
    returning id into v_return;

    -- The goods come back onto the shelf, and the lines are copied so the
    -- return says what was returned rather than only how much money moved.
    for v_line in select * from sale_lines where sale_id = p_sale_id
    loop
        insert into sale_lines (sale_id, product_id, name, quantity,
                                unit_price, unit_cost, line_total)
        values (v_return, v_line.product_id, v_line.name, v_line.quantity,
                v_line.unit_price, v_line.unit_cost, v_line.line_total);

        update products set quantity = quantity + v_line.quantity
        where id = v_line.product_id;
    end loop;

    if v_total > 0 then
        v_entry := record_entry(
            p_org_id      => v_org,
            p_amount      => v_total,
            p_direction   => 'out',
            p_label       => 'Retour de vente',
            p_recorded_by => v_actor,
            p_category    => 'Ventes',
            p_method      => v_method,
            p_memo        => p_note,
            p_details     => jsonb_build_object('reverses', p_sale_id),
            p_client_uuid => p_client_uuid
        );
        update sales set entry_id = v_entry where id = v_return;
    end if;

    return v_return;
end;
$$;

-- ------------------------------------------------------------
-- What the shopkeeper looks at
-- ------------------------------------------------------------

-- Stock that dies soon, and what it cost. The second number is the one that
-- makes anybody act: "3 articles, 82 000 en jeu" beats a list of dates.
create or replace function expiring_products(
    p_org_id uuid,
    p_within int default 14
)
returns table (
    product_id  uuid,
    name        text,
    quantity    numeric,
    expires_on  date,
    days_left   int,
    value_at_risk numeric
)
language sql
stable
security invoker
set search_path = public, auth
as $$
    select
        p.id, p.name, p.quantity, p.expires_on,
        (p.expires_on - current_date)::int,
        round(p.quantity * p.cost_price, 2)
    from products p
    where p.org_id = p_org_id
      and p.is_active
      and p.expires_on is not null
      and p.quantity > 0
      and p.expires_on <= current_date + p_within
    order by p.expires_on, p.name;
$$;

-- The day, as one row: what came in, what went out, how many sales.
create or replace function store_day(
    p_org_id uuid,
    p_on     date default current_date
)
returns table (
    sales_total   numeric,
    returns_total numeric,
    net_sales     numeric,
    sale_count    int,
    items_sold    numeric
)
language sql
stable
security invoker
set search_path = public, auth
as $$
    select
        coalesce(sum(s.total) filter (where s.kind = 'sale'), 0),
        coalesce(sum(s.total) filter (where s.kind = 'return'), 0),
        coalesce(sum(s.total) filter (where s.kind = 'sale'), 0)
          - coalesce(sum(s.total) filter (where s.kind = 'return'), 0),
        count(*) filter (where s.kind = 'sale')::int,
        coalesce((
            select sum(l.quantity)
            from sale_lines l
            join sales s2 on s2.id = l.sale_id
            where s2.org_id = p_org_id
              and s2.kind = 'sale'
              and (s2.occurred_at at time zone 'UTC')::date = p_on
        ), 0)
    from sales s
    where s.org_id = p_org_id
      and (s.occurred_at at time zone 'UTC')::date = p_on;
$$;

-- The number that renews the subscription: cost value of stock that was sold
-- while it was within the expiry window rather than thrown away.
--
-- This is a definition, not a measurement, and it is deliberately the modest
-- one: it counts only goods sold in the last [p_within] days of their life,
-- which is stock that was at real risk of becoming waste. It cannot know what
-- would have happened without the app, and does not pretend to.
create or replace function losses_avoided(
    p_org_id uuid,
    p_within int default 14
)
returns numeric
language sql
stable
security invoker
set search_path = public, auth
as $$
    select coalesce(round(sum(l.quantity * l.unit_cost), 2), 0)
    from sale_lines l
    join sales s   on s.id = l.sale_id and s.kind = 'sale'
    join products p on p.id = l.product_id
    where s.org_id = p_org_id
      and p.expires_on is not null
      and (s.occurred_at at time zone 'UTC')::date
            between p.expires_on - p_within and p.expires_on;
$$;

-- ------------------------------------------------------------
-- Seeding a new shop
-- ------------------------------------------------------------

-- Called by create_org() for profile = 'retail'. The generic six accounts do
-- not name what a shop actually does with money.
create or replace function seed_retail_accounts(p_org_id uuid)
returns void
language plpgsql
as $$
begin
    insert into accounts (org_id, code, name, type) values
        (p_org_id, '1000', 'Caisse',                 'asset'),
        (p_org_id, '1010', 'Banque',                 'asset'),
        (p_org_id, '1020', 'Mobile Money',           'asset'),
        (p_org_id, '4000', 'Ventes',                 'income'),
        (p_org_id, '5000', 'Achats de marchandises', 'expense'),
        (p_org_id, '5010', 'Loyer',                  'expense'),
        (p_org_id, '5020', 'Transport',              'expense'),
        (p_org_id, '5030', 'Salaires',               'expense')
    on conflict (org_id, code) do nothing;
end;
$$;

-- create_org() seeds the church chart for a church and a generic one for
-- everything else. A shop now gets its own, without touching the platform
-- admin migration: same body, one more branch.
create or replace function create_org(
    p_name     text,
    p_slug     text,
    p_profile  text default 'generic',
    p_currency text default 'XOF'
)
returns uuid
language plpgsql
security definer
set search_path = public, auth
as $$
declare
    v_org_id uuid;
begin
    if not exists(select 1 from profiles where id = auth.uid() and is_platform_admin) then
        raise exception 'Only a platform admin can create a new business';
    end if;

    insert into orgs (name, slug, profile, default_currency)
    values (p_name, p_slug, p_profile, p_currency)
    returning id into v_org_id;

    insert into memberships (org_id, user_id, role, scope_kind, scope_id)
    values (v_org_id, auth.uid(), 'owner', 'org', v_org_id);

    if p_profile = 'church' then
        perform seed_church_accounts(v_org_id);
    elsif p_profile = 'retail' then
        perform seed_retail_accounts(v_org_id);
    else
        insert into accounts (org_id, code, name, type) values
            (v_org_id, '1000', 'Cash on Hand',        'asset'),
            (v_org_id, '1010', 'Bank Account',        'asset'),
            (v_org_id, '1020', 'Mobile Money',        'asset'),
            (v_org_id, '4000', 'Sales',                'income'),
            (v_org_id, '5000', 'Purchases',            'expense'),
            (v_org_id, '5010', 'Operating Expenses',   'expense')
        on conflict (org_id, code) do nothing;
    end if;

    return v_org_id;
end;
$$;

-- ------------------------------------------------------------
-- Row level security
--
-- Same shape as every other module: reading needs membership, writing needs a
-- role that is not observer, and neither is decided by the client.
-- ------------------------------------------------------------

alter table products   enable row level security;
alter table sales      enable row level security;
alter table sale_lines enable row level security;

drop policy if exists "products readable within org" on products;
create policy "products readable within org"
on products for select using (is_org_member(org_id));

drop policy if exists "products writable by staff" on products;
create policy "products writable by staff"
on products for insert with check (can_write_org(org_id));

drop policy if exists "products updatable by staff" on products;
create policy "products updatable by staff"
on products for update using (can_write_org(org_id))
with check (can_write_org(org_id));

drop policy if exists "sales readable within org" on sales;
create policy "sales readable within org"
on sales for select using (is_org_member(org_id));

drop policy if exists "sales writable by staff" on sales;
create policy "sales writable by staff"
on sales for insert with check (can_write_org(org_id));

-- No update and no delete policy on sales, on purpose. A sale that was wrong
-- is corrected by a return, which leaves both rows visible. This is the same
-- rule the ledger has had since the first schema.

drop policy if exists "sale lines readable with their sale" on sale_lines;
create policy "sale lines readable with their sale"
on sale_lines for select using (
    exists (select 1 from sales s where s.id = sale_id and is_org_member(s.org_id))
);

drop policy if exists "sale lines writable with their sale" on sale_lines;
create policy "sale lines writable with their sale"
on sale_lines for insert with check (
    exists (select 1 from sales s where s.id = sale_id and can_write_org(s.org_id))
);

comment on table products is
    'What a shop sells: prices, count on hand, and the date stock dies.';
comment on table sales is
    'One sale or one return. Never edited; a mistake is corrected by a return.';
comment on table sale_lines is
    'The products on a sale, with the name and cost as they were at the time.';


-- ============================================================
-- 012_employees.sql
-- ============================================================
-- ============================================================
-- 012_employees.sql — the people a business pays.
--
-- M5 asks for "employees: permanent and temporary, shifts, salary/wage,
-- payments". This is that, and it is deliberately not a payroll system.
--
-- The distinction that shapes everything below: an *employee* is a person the
-- business pays, and a *membership* is an account with access to the books.
-- They are different sets and conflating them is the mistake this schema
-- exists to avoid. Esperance's Sunday helper is paid and must never see the
-- takings; her accountant sees everything and is not on the payroll. So
-- `employees.user_id` is nullable and usually null — most people who get paid
-- never install the app at all.
--
-- Two kinds of person, one table:
--
--   'permanent' — paid a salary for a period. Hours are not counted.
--   'casual'    — paid a rate for time worked, so the shifts are the record
--                 and the money follows from them.
--
-- Every payment posts through `record_entry()` like everything else, so wages
-- appear in the income statement beside rent and stock without a second
-- ledger to reconcile.
--
-- What is not here, on purpose: tax, social contributions, and payslips.
-- Those are jurisdiction-specific, they are what an accountant is for, and
-- guessing at them would produce numbers that look official and are wrong.
-- ============================================================

create table if not exists employees (
    id           uuid primary key default gen_random_uuid(),
    org_id       uuid not null references orgs(id) on delete cascade,
    full_name    text not null,
    phone        text,
    role_title   text,
    -- 'permanent' | 'casual'
    kind         text not null default 'casual'
                 check (kind in ('permanent', 'casual')),
    -- A monthly salary for permanent staff; ignored for casuals.
    salary       numeric(14,2) not null default 0 check (salary >= 0),
    -- What a casual earns per hour. Ignored for permanent staff.
    hourly_rate  numeric(14,2) not null default 0 check (hourly_rate >= 0),
    -- Null when this person has no account, which is the common case: being
    -- paid and being able to open the books are different things.
    user_id      uuid references profiles(id),
    started_on   date not null default current_date,
    ended_on     date,
    is_active    boolean not null default true,
    created_at   timestamptz not null default now(),
    created_by   uuid references profiles(id)
);

create index if not exists employees_active on employees (org_id) where is_active;
create unique index if not exists employees_by_name
    on employees (org_id, lower(btrim(full_name)));

-- Time worked. Only meaningful for casuals, but recorded for anyone, because
-- "who was in the shop on the day the till was short" is a question worth
-- being able to answer about permanent staff too.
create table if not exists shifts (
    id           uuid primary key default gen_random_uuid(),
    org_id       uuid not null references orgs(id) on delete cascade,
    employee_id  uuid not null references employees(id) on delete cascade,
    worked_on    date not null default current_date,
    hours        numeric(6,2) not null check (hours > 0 and hours <= 24),
    note         text,
    -- Set when this shift has been included in a payment. Null means unpaid,
    -- which is what the "à payer" figure on screen counts.
    payment_id   uuid,
    recorded_by  uuid references profiles(id),
    client_uuid  uuid,
    created_at   timestamptz not null default now()
);

create unique index if not exists shifts_client_uuid_key
    on shifts (org_id, client_uuid) where client_uuid is not null;
create index if not exists shifts_by_employee
    on shifts (employee_id, worked_on desc);
create index if not exists shifts_unpaid
    on shifts (org_id) where payment_id is null;

create table if not exists staff_payments (
    id           uuid primary key default gen_random_uuid(),
    org_id       uuid not null references orgs(id) on delete cascade,
    employee_id  uuid not null references employees(id),
    amount       numeric(14,2) not null check (amount > 0),
    -- What the money was for, in the words a shopkeeper would use.
    label        text not null default 'Salaire',
    method       text not null default 'cash',
    paid_on      date not null default current_date,
    -- The ledger entry this payment posted.
    entry_id     uuid references journal_entries(id),
    paid_by      uuid references profiles(id),
    client_uuid  uuid,
    created_at   timestamptz not null default now()
);

create unique index if not exists staff_payments_client_uuid_key
    on staff_payments (org_id, client_uuid) where client_uuid is not null;
create index if not exists staff_payments_by_employee
    on staff_payments (employee_id, paid_on desc);

-- ------------------------------------------------------------
-- Recording
-- ------------------------------------------------------------

create or replace function add_employee(
    p_org_id      uuid,
    p_full_name   text,
    p_kind        text    default 'casual',
    p_hourly_rate numeric default null,
    p_salary      numeric default null,
    p_phone       text    default null,
    p_role_title  text    default null,
    p_actor       uuid    default null
)
returns uuid
language plpgsql
as $$
declare
    v_name text := btrim(coalesce(p_full_name, ''));
    v_id   uuid;
begin
    if v_name = '' then
        raise exception 'An employee needs a name';
    end if;

    select id into v_id from employees
    where org_id = p_org_id and lower(btrim(full_name)) = lower(v_name);

    if v_id is not null then
        -- Re-adding somebody who left brings them back rather than making a
        -- second row: the shifts they worked last season are theirs.
        update employees set
            is_active   = true,
            ended_on    = null,
            kind        = coalesce(nullif(p_kind, ''), kind),
            hourly_rate = coalesce(p_hourly_rate, hourly_rate),
            salary      = coalesce(p_salary, salary),
            phone       = coalesce(p_phone, phone),
            role_title  = coalesce(p_role_title, role_title)
        where id = v_id;
        return v_id;
    end if;

    insert into employees (org_id, full_name, kind, hourly_rate, salary,
                           phone, role_title, created_by)
    values (p_org_id, v_name, coalesce(nullif(p_kind, ''), 'casual'),
            coalesce(p_hourly_rate, 0), coalesce(p_salary, 0),
            p_phone, p_role_title, p_actor)
    returning id into v_id;

    return v_id;
end;
$$;

-- A day worked. Idempotent by client_uuid like every other recording call, so
-- a phone that retries does not pay somebody twice for one afternoon.
create or replace function record_shift(
    p_org_id      uuid,
    p_employee_id uuid,
    p_hours       numeric,
    p_worked_on   date default current_date,
    p_note        text default null,
    p_client_uuid uuid default null
)
returns uuid
language plpgsql
security definer
set search_path = public, auth
as $$
declare
    v_actor    uuid := auth.uid();
    v_id       uuid;
    v_existing uuid;
begin
    if not exists (select 1 from employees
                   where id = p_employee_id and org_id = p_org_id) then
        raise exception 'No such employee in this business';
    end if;

    if p_client_uuid is not null then
        select id into v_existing from shifts
        where org_id = p_org_id and client_uuid = p_client_uuid;
        if v_existing is not null then
            return v_existing;
        end if;
    end if;

    insert into shifts (org_id, employee_id, worked_on, hours, note,
                        recorded_by, client_uuid)
    values (p_org_id, p_employee_id, p_worked_on, p_hours, p_note,
            v_actor, p_client_uuid)
    returning id into v_id;

    return v_id;
end;
$$;

-- What is owed to a casual for shifts nobody has paid for yet.
create or replace function unpaid_shifts(p_org_id uuid)
returns table (
    employee_id uuid,
    full_name   text,
    hours       numeric,
    shifts      int,
    owed        numeric
)
language sql
stable
security invoker
set search_path = public, auth
as $$
    select
        e.id, e.full_name,
        coalesce(sum(s.hours), 0),
        count(s.id)::int,
        round(coalesce(sum(s.hours), 0) * e.hourly_rate, 2)
    from employees e
    join shifts s on s.employee_id = e.id and s.payment_id is null
    where e.org_id = p_org_id
    group by e.id, e.full_name, e.hourly_rate
    having coalesce(sum(s.hours), 0) > 0
    order by e.full_name;
$$;

-- Paying somebody. Posts the money and, for a casual, marks the shifts it
-- covers so the same hours cannot be paid a second time.
--
-- [p_cover_shifts] settles every unpaid shift for that employee. It is the
-- default because the alternative — paying a casual and leaving their shifts
-- marked unpaid — produces a figure on screen that says they are still owed
-- money they have just been handed.
create or replace function pay_employee(
    p_org_id       uuid,
    p_employee_id  uuid,
    p_amount       numeric default null,
    p_label        text    default null,
    p_method       text    default 'cash',
    p_paid_on      date    default current_date,
    p_cover_shifts boolean default true,
    p_client_uuid  uuid    default null
)
returns uuid
language plpgsql
security definer
set search_path = public, auth
as $$
declare
    v_actor    uuid := auth.uid();
    v_name     text;
    v_kind     text;
    v_rate     numeric;
    v_salary   numeric;
    v_amount   numeric;
    v_payment  uuid;
    v_existing uuid;
    v_entry    uuid;
begin
    select full_name, kind, hourly_rate, salary
      into v_name, v_kind, v_rate, v_salary
    from employees where id = p_employee_id and org_id = p_org_id;

    if v_name is null then
        raise exception 'No such employee in this business';
    end if;

    if p_client_uuid is not null then
        select id into v_existing from staff_payments
        where org_id = p_org_id and client_uuid = p_client_uuid;
        if v_existing is not null then
            return v_existing;
        end if;
    end if;

    -- Work out what is owed when the caller did not say. A casual is paid for
    -- the hours nobody has paid for yet; a permanent employee is paid their
    -- salary.
    v_amount := p_amount;
    if v_amount is null then
        if v_kind = 'casual' then
            select round(coalesce(sum(s.hours), 0) * v_rate, 2) into v_amount
            from shifts s
            where s.employee_id = p_employee_id and s.payment_id is null;
        else
            v_amount := v_salary;
        end if;
    end if;

    if v_amount is null or v_amount <= 0 then
        raise exception 'There is nothing to pay %', v_name;
    end if;

    insert into staff_payments (org_id, employee_id, amount, label, method,
                                paid_on, paid_by, client_uuid)
    values (p_org_id, p_employee_id, v_amount,
            coalesce(nullif(btrim(coalesce(p_label, '')), ''),
                     case when v_kind = 'casual' then 'Journées' else 'Salaire' end),
            p_method, p_paid_on, v_actor, p_client_uuid)
    returning id into v_payment;

    if p_cover_shifts then
        update shifts set payment_id = v_payment
        where employee_id = p_employee_id and payment_id is null;
    end if;

    v_entry := record_entry(
        p_org_id      => p_org_id,
        p_amount      => v_amount,
        p_direction   => 'out',
        p_label       => 'Salaires',
        p_recorded_by => v_actor,
        p_category    => 'Salaires',
        p_method      => p_method,
        p_memo        => v_name,
        p_details     => jsonb_build_object('employee', v_name,
                                            'payment_id', v_payment),
        p_client_uuid => p_client_uuid,
        p_occurred_at => p_paid_on::timestamptz
    );

    update staff_payments set entry_id = v_entry where id = v_payment;

    return v_payment;
end;
$$;

-- ------------------------------------------------------------
-- Row level security
--
-- Wages are the most sensitive numbers in a small business — more than the
-- takings, because everybody in the shop knows what the takings look like and
-- nobody is supposed to know what anybody else earns. So reading these three
-- tables needs an admin, not merely membership. That is stricter than every
-- other module here, and deliberately so.
-- ------------------------------------------------------------

alter table employees      enable row level security;
alter table shifts         enable row level security;
alter table staff_payments enable row level security;

drop policy if exists "employees readable by org admins" on employees;
create policy "employees readable by org admins"
on employees for select using (is_org_admin(org_id));

drop policy if exists "employees managed by org admins" on employees;
create policy "employees managed by org admins"
on employees for insert with check (is_org_admin(org_id));

drop policy if exists "employees amended by org admins" on employees;
create policy "employees amended by org admins"
on employees for update using (is_org_admin(org_id))
with check (is_org_admin(org_id));

drop policy if exists "shifts readable by org admins" on shifts;
create policy "shifts readable by org admins"
on shifts for select using (is_org_admin(org_id));

drop policy if exists "shifts recorded by staff" on shifts;
create policy "shifts recorded by staff"
on shifts for insert with check (can_write_org(org_id));

drop policy if exists "payments readable by org admins" on staff_payments;
create policy "payments readable by org admins"
on staff_payments for select using (is_org_admin(org_id));

drop policy if exists "payments made by org admins" on staff_payments;
create policy "payments made by org admins"
on staff_payments for insert with check (is_org_admin(org_id));

-- No update or delete on staff_payments. A payment made in error is corrected
-- the way every other mistake in this schema is: by recording the correction,
-- not by erasing the record.

comment on table employees is
    'People the business pays. Not the same set as the people who can open '
    'its books — user_id is null for most of them.';
comment on table shifts is
    'Time worked, and the basis for what a casual is owed.';
comment on table staff_payments is
    'Wages and salaries paid, each posting its own ledger entry.';


-- ============================================================
-- 013_capture.sql
-- ============================================================
-- ============================================================
-- 013_capture.sql — the photo, and everything that is not typed.
--
-- M5's premise: Esperance's losses come from data that is never captured, and
-- every required field at capture time loses a user. So the primary action in
-- the app is a camera button that writes a row with **zero** required fields
-- beyond the photo itself and the business it belongs to. Details later, or
-- never.
--
-- `documents` already existed (schema.sql, RLS in 004, visibility in 006).
-- What it was missing was everything that makes a capture usable afterwards:
-- a way to retry an upload without creating a second row, the text a phone
-- read off the picture, and a link to the thing the picture turns out to be
-- about.
--
-- Four decisions worth knowing.
--
-- 1. **The row is written after the bytes land, not before.** `r2_key` is not
--    null and never has been. The device uploads to the Worker, gets a key
--    back, and only then records it. A row pointing at an object that does
--    not exist is worse than no row: it puts a broken thumbnail in a gallery
--    and there is nothing the person holding the phone can do about it. The
--    cost is orphaned objects in R2 when the app dies in between, which is a
--    bucket lifecycle rule's problem, not a schema problem.
--
-- 2. **OCR is advisory and never authoritative.** `ocr_text` is stored as the
--    phone read it, and nothing else in this schema reads it. It exists to
--    pre-fill a form that a person then confirms. A misread expiry date that
--    silently became `products.expires_on` would produce exactly the loss
--    this module is meant to prevent, with the app's name on it.
--
-- 3. **A capture belongs to at most one thing, and usually to nothing.**
--    `linked_journal_entry_id` was already there; `product_id` is added
--    beside it. Both null is the normal state and the queue on the home
--    screen is built from it — `unfiled_documents()` is that queue.
--
-- 4. **Idempotency by `client_uuid`, same as everywhere else.** A phone in a
--    market retries. Two rows for one photograph is the retail version of
--    paying the same wage twice.
--
-- Not here: the bytes. No image ever passes through Postgres. See
-- workers/uploads/ for the only thing that may write to the bucket, and why
-- it verifies membership through PostgREST under the caller's own token
-- rather than trusting the org id in the request.
-- ============================================================

-- ------------------------------------------------------------
-- 1. WHAT A CAPTURE CARRIES
-- ------------------------------------------------------------
-- All `if not exists`, all nullable: 013 runs against a live database that
-- already holds documents, and any of these being required would mean the
-- migration has to invent values for rows that were captured before the
-- column existed.

alter table documents add column if not exists client_uuid   uuid;
alter table documents add column if not exists caption       text;
alter table documents add column if not exists content_type  text;
alter table documents add column if not exists byte_size     bigint;
alter table documents add column if not exists captured_at   timestamptz;
alter table documents add column if not exists product_id    uuid;
alter table documents add column if not exists ocr_text      text;
alter table documents add column if not exists ocr_at        timestamptz;
alter table documents add column if not exists barcode       text;
alter table documents add column if not exists device_id     text;

-- Added separately from the column so re-running finds it already there.
-- `on delete set null`: deleting a product must not take the photograph of
-- the delivery it arrived on with it — that picture is the evidence.
do $$
begin
    if not exists (
        select 1 from pg_constraint where conname = 'documents_product_id_fkey'
    ) then
        alter table documents
            add constraint documents_product_id_fkey
            foreign key (product_id) references products(id) on delete set null;
    end if;
end $$;

-- One photograph, however many times the phone sends it. Partial because
-- captures made before 013 have no client_uuid and null is not a duplicate.
create unique index if not exists documents_by_client_uuid
    on documents (org_id, client_uuid) where client_uuid is not null;

-- The gallery, newest first.
create index if not exists documents_by_capture
    on documents (org_id, captured_at desc);

-- The queue: captured and still about nothing.
create index if not exists documents_unfiled
    on documents (org_id, created_at desc)
    where linked_journal_entry_id is null and product_id is null;

-- An object lives at exactly one key, and a second row pointing at the same
-- bytes would double every count on the gallery.
create unique index if not exists documents_by_key on documents (r2_key);

comment on column documents.client_uuid is
    'Client-generated. A retried upload returns the first row rather than making a second.';
comment on column documents.ocr_text is
    'What the phone read off the picture. Advisory: nothing in this schema reads it, a person confirms it.';
comment on column documents.captured_at is
    'When the photograph was taken, which is not when it reached the server. Ignace is offline for days.';

-- ------------------------------------------------------------
-- 2. RECORDING A CAPTURE
-- ------------------------------------------------------------
-- Security definer, like record_entry() and for the same reason: it makes the
-- membership test itself (`can_write_org`, everyone but an observer) so the
-- error is a sentence rather than a policy violation, and it needs auth.uid()
-- which the `authenticated` role cannot reach on its own.
--
-- Every parameter after the key is optional. That is the whole design.
create or replace function record_document(
    p_org_id       uuid,
    p_r2_key       text,
    p_kind         text        default 'photo',
    p_caption      text        default null,
    p_content_type text        default null,
    p_byte_size    bigint      default null,
    p_captured_at  timestamptz default null,
    p_client_uuid  uuid        default null,
    p_device_id    text        default null,
    p_entry_id     uuid        default null,
    p_product_id   uuid        default null
)
returns uuid
language plpgsql
security definer
set search_path = public, auth
as $$
declare
    v_actor    uuid := auth.uid();
    v_key      text := btrim(coalesce(p_r2_key, ''));
    v_existing uuid;
    v_id       uuid;
begin
    if v_actor is null then
        raise exception 'record_document() needs a signed-in caller';
    end if;

    if not can_write_org(p_org_id) then
        raise exception 'You cannot add documents to this business';
    end if;

    if v_key = '' then
        raise exception 'A document needs the key of the object that was uploaded';
    end if;

    -- The Worker writes under org/<org_id>/…, and only ever for the business
    -- the caller proved membership of. Checking the prefix here as well means
    -- a device cannot record somebody else's object into its own gallery and
    -- read it back through the download route.
    if v_key not like ('org/' || p_org_id::text || '/%') then
        raise exception 'That object does not belong to this business';
    end if;

    if p_client_uuid is not null then
        select id into v_existing
          from documents
         where org_id = p_org_id and client_uuid = p_client_uuid;
        if found then
            return v_existing;
        end if;
    end if;

    -- Same key sent twice without a client_uuid: still one document.
    select id into v_existing from documents where r2_key = v_key;
    if found then
        return v_existing;
    end if;

    if p_product_id is not null and not exists (
        select 1 from products where id = p_product_id and org_id = p_org_id
    ) then
        raise exception 'That product belongs to another business';
    end if;

    if p_entry_id is not null and not exists (
        select 1 from journal_entries where id = p_entry_id and org_id = p_org_id
    ) then
        raise exception 'That entry belongs to another business';
    end if;

    insert into documents (
        org_id, r2_key, kind, caption, content_type, byte_size,
        captured_at, client_uuid, device_id, uploaded_by,
        linked_journal_entry_id, product_id, ocr_status
    )
    values (
        p_org_id, v_key,
        nullif(btrim(coalesce(p_kind, '')), ''),
        nullif(btrim(coalesce(p_caption, '')), ''),
        nullif(btrim(coalesce(p_content_type, '')), ''),
        p_byte_size,
        coalesce(p_captured_at, now()),
        p_client_uuid, p_device_id, v_actor,
        p_entry_id, p_product_id, 'pending'
    )
    returning id into v_id;

    return v_id;
end;
$$;

comment on function record_document(uuid, text, text, text, text, bigint, timestamptz, uuid, text, uuid, uuid) is
    'Records a photograph that has already been uploaded. Every field but the org and the key is optional, on purpose.';

-- ------------------------------------------------------------
-- 3. THE DETAILS THAT ARRIVE LATER
-- ------------------------------------------------------------
-- Filing a capture: giving it a name, or saying what it is about. Split from
-- record_document() because these happen minutes or weeks apart, sometimes on
-- a different phone.
create or replace function file_document(
    p_document_id uuid,
    p_caption     text default null,
    p_kind        text default null,
    p_entry_id    uuid default null,
    p_product_id  uuid default null
)
returns uuid
language plpgsql
security definer
set search_path = public, auth
as $$
declare
    v_actor  uuid := auth.uid();
    v_org_id uuid;
begin
    if v_actor is null then
        raise exception 'file_document() needs a signed-in caller';
    end if;

    select org_id into v_org_id from documents where id = p_document_id;
    if not found then
        raise exception 'No such document';
    end if;

    if not can_write_org(v_org_id) then
        raise exception 'You cannot change documents in this business';
    end if;

    if p_product_id is not null and not exists (
        select 1 from products where id = p_product_id and org_id = v_org_id
    ) then
        raise exception 'That product belongs to another business';
    end if;

    if p_entry_id is not null and not exists (
        select 1 from journal_entries where id = p_entry_id and org_id = v_org_id
    ) then
        raise exception 'That entry belongs to another business';
    end if;

    -- coalesce, not overwrite-with-null: passing one field must not erase the
    -- other three. Unfiling is a different act and is not offered here.
    update documents
       set caption                 = coalesce(nullif(btrim(coalesce(p_caption, '')), ''), caption),
           kind                    = coalesce(nullif(btrim(coalesce(p_kind, '')), ''), kind),
           linked_journal_entry_id = coalesce(p_entry_id, linked_journal_entry_id),
           product_id              = coalesce(p_product_id, product_id)
     where id = p_document_id;

    return p_document_id;
end;
$$;

-- What the phone read. Kept apart from file_document() so the audit trail can
-- tell a machine's guess from a person's confirmation.
create or replace function set_document_ocr(
    p_document_id uuid,
    p_text        text,
    p_barcode     text default null,
    p_status      text default 'done'
)
returns uuid
language plpgsql
security definer
set search_path = public, auth
as $$
declare
    v_actor  uuid := auth.uid();
    v_org_id uuid;
begin
    if v_actor is null then
        raise exception 'set_document_ocr() needs a signed-in caller';
    end if;

    select org_id into v_org_id from documents where id = p_document_id;
    if not found then
        raise exception 'No such document';
    end if;

    if not can_write_org(v_org_id) then
        raise exception 'You cannot change documents in this business';
    end if;

    if coalesce(p_status, '') not in ('pending', 'done', 'failed', 'skipped') then
        raise exception 'Unknown OCR status: %', p_status;
    end if;

    update documents
       set ocr_text   = nullif(btrim(coalesce(p_text, '')), ''),
           barcode    = coalesce(nullif(btrim(coalesce(p_barcode, '')), ''), barcode),
           ocr_status = p_status,
           ocr_at     = now()
     where id = p_document_id;

    return p_document_id;
end;
$$;

-- ------------------------------------------------------------
-- 4. READING THEM BACK
-- ------------------------------------------------------------
-- Security invoker throughout: these are reads, and the select policy on
-- documents — which since 006 also honours an observer's summary/full
-- visibility — is exactly the rule that should apply. A definer here would
-- hand an observer the line items the 006 policy exists to withhold.

create or replace function org_documents(
    p_org_id uuid,
    p_kind   text default null,
    p_limit  int  default 60,
    p_offset int  default 0
)
returns table (
    id            uuid,
    r2_key        text,
    kind          text,
    caption       text,
    content_type  text,
    byte_size     bigint,
    captured_at   timestamptz,
    ocr_status    text,
    ocr_text      text,
    barcode       text,
    product_id    uuid,
    product_name  text,
    entry_id      uuid,
    entry_label   text,
    uploaded_by   uuid,
    uploaded_name text
)
language sql
stable
security invoker
set search_path = public
as $$
    select d.id, d.r2_key, d.kind, d.caption, d.content_type, d.byte_size,
           coalesce(d.captured_at, d.created_at), d.ocr_status, d.ocr_text,
           d.barcode, d.product_id, p.name, d.linked_journal_entry_id, je.label,
           d.uploaded_by, pr.full_name
    from documents d
    left join products p        on p.id  = d.product_id
    left join journal_entries je on je.id = d.linked_journal_entry_id
    left join profiles pr       on pr.id = d.uploaded_by
    where d.org_id = p_org_id
      and (p_kind is null or d.kind = p_kind)
    order by coalesce(d.captured_at, d.created_at) desc, d.id desc
    limit greatest(coalesce(p_limit, 60), 1)
    offset greatest(coalesce(p_offset, 0), 0);
$$;

-- The pile on the counter. A capture that is about nothing yet is not a
-- mistake — it is the design working — but it is also the only thing in this
-- app that asks a person for a minute of their time, so it needs a number
-- somebody can see going down.
create or replace function unfiled_documents(p_org_id uuid, p_limit int default 60)
returns table (
    id           uuid,
    r2_key       text,
    kind         text,
    content_type text,
    captured_at  timestamptz,
    ocr_status   text,
    ocr_text     text,
    barcode      text
)
language sql
stable
security invoker
set search_path = public
as $$
    select d.id, d.r2_key, d.kind, d.content_type,
           coalesce(d.captured_at, d.created_at), d.ocr_status, d.ocr_text, d.barcode
    from documents d
    where d.org_id = p_org_id
      and d.linked_journal_entry_id is null
      and d.product_id is null
      and coalesce(btrim(d.caption), '') = ''
    order by coalesce(d.captured_at, d.created_at) desc, d.id desc
    limit greatest(coalesce(p_limit, 60), 1);
$$;

-- Scanning something at the counter. Returns the product if this shop already
-- knows the barcode, and nothing if it does not — which is the signal to open
-- the "new product" form with the barcode already in it.
create or replace function product_by_barcode(p_org_id uuid, p_barcode text)
returns table (
    id          uuid,
    name        text,
    sale_price  numeric,
    cost_price  numeric,
    quantity    numeric,
    expires_on  date
)
language sql
stable
security invoker
set search_path = public
as $$
    select p.id, p.name, p.sale_price, p.cost_price, p.quantity, p.expires_on
    from products p
    where p.org_id = p_org_id
      and p.barcode = nullif(btrim(coalesce(p_barcode, '')), '')
    limit 1;
$$;

-- ------------------------------------------------------------
-- 5. RLS
-- ------------------------------------------------------------
-- documents already has select (004, replaced by 006), insert and update
-- policies. Two things 013 needs on top.
--
-- First: the update policy from 004 restricted who may amend a document, but
-- there is still no delete policy anywhere and there deliberately is not one
-- here. A photograph of a delivery is evidence; unfiling it is an update.

-- Second: a document may now point at a product, and a document row must not
-- become a way to learn that another business has a product with a given id.
-- The functions above check it; the policy is what holds when somebody writes
-- to the table directly, which is the whole reason RLS exists.
drop policy if exists "documents point only at their own org" on documents;
create policy "documents point only at their own org"
on documents for update
using (can_write_org(org_id))
with check (
    can_write_org(org_id)
    and (product_id is null or exists (
        select 1 from products p where p.id = product_id and p.org_id = documents.org_id
    ))
    and (linked_journal_entry_id is null or exists (
        select 1 from journal_entries je
        where je.id = linked_journal_entry_id and je.org_id = documents.org_id
    ))
);

-- The 004 update policy is now the weaker of two and would let a direct write
-- past the check above, since Postgres ORs permissive policies together.
drop policy if exists "documents amendable by non-observers" on documents;

-- ------------------------------------------------------------
-- 6. GRANTS
-- ------------------------------------------------------------
-- Every SECURITY DEFINER function starts life executable by PUBLIC, which
-- includes anon. Each refuses a caller with no session already; the revoke
-- makes it deliberate rather than inherited. Same discipline as 005–007.
revoke execute on function record_document(uuid, text, text, text, text, bigint, timestamptz, uuid, text, uuid, uuid) from public;
revoke execute on function file_document(uuid, text, text, uuid, uuid) from public;
revoke execute on function set_document_ocr(uuid, text, text, text) from public;

-- Guarded, the same way 005, 006 and 007 guard theirs: `authenticated` is a
-- Supabase role and does not exist on a bare Postgres, which is what CI
-- starts from. Roles are cluster-wide, so a developer whose cluster has run
-- a test suite before already has it and would never see this fail.
do $$
begin
    if exists (select 1 from pg_roles where rolname = 'authenticated') then
        grant execute on function record_document(uuid, text, text, text, text, bigint, timestamptz, uuid, text, uuid, uuid) to authenticated;
        grant execute on function file_document(uuid, text, text, uuid, uuid) to authenticated;
        grant execute on function set_document_ocr(uuid, text, text, text) to authenticated;
        grant execute on function org_documents(uuid, text, int, int) to authenticated;
        grant execute on function unfiled_documents(uuid, int) to authenticated;
        grant execute on function product_by_barcode(uuid, text) to authenticated;
    end if;
end $$;

-- PostgREST caches the functions it exposes; without this the app gets
-- "Could not find the function public.record_document in the schema cache"
-- for a minute after the migration lands.
notify pgrst, 'reload schema';


-- ============================================================
-- 014_org_lifecycle.sql
-- ============================================================
-- ============================================================
-- 014_org_lifecycle.sql — changing a business, putting it away, and the one
-- act in this schema that actually destroys something.
--
-- `create_org()` has existed since 010 and there has never been a way to
-- undo it. A platform admin could make a business and then had to live with
-- the name they typed, the profile they picked, and every test business they
-- ever created, forever.
--
-- Four decisions, and the third is the one that matters.
--
-- 1. **Editing is not a new power.** 004 already lets an org's own admins
--    update their `orgs` row, and 010 already counts a platform admin as an
--    admin of every org. `update_org()` adds validation, not access: it
--    refuses a slug that would not survive as a hostname, refuses a profile
--    this build has never heard of, and refuses to rename an archived
--    business. Doing it through a function also means one audit_log row that
--    says what changed instead of a bare UPDATE.
--
-- 2. **Archiving is the ordinary way to make a business go away.** It is
--    reversible, it keeps every entry, and it is what "delete" should mean
--    nine times out of ten — the business closed, nobody should see it in
--    their list, and the books still have to exist because a tax office may
--    still ask. An archived org disappears from `my_orgs()` for its members
--    and stays visible to a platform admin, who is the only person who can
--    bring it back.
--
-- 3. **Deleting is permanent, destroys the books, and is deliberately hard.**
--    Everything in this schema is append-only on purpose: undo is a reversing
--    entry, a document cannot be deleted, the audit log has no delete policy.
--    `delete_org()` is the one exception, and it exists because a platform
--    admin genuinely does need to remove the business they created twice by
--    accident. So it is fenced:
--
--      - platform admin only, never an org's own owner;
--      - the business must already be archived, so deletion is never the
--        first thing that happens to it;
--      - the exact name has to be typed back, because a business id in a
--        confirmation dialog is not something anybody reads;
--      - and it refuses outright if the books hold anything at all, unless
--        the caller passes `p_force` — a test business with no entries can
--        go quietly, a real one takes a second, deliberate act.
--
-- 4. **A deleted business leaves a tombstone.** `audit_log.org_id` cascades,
--    so an org's own audit trail dies with it and the deletion would be the
--    one event in this system that erases its own record. `deleted_orgs` is
--    not org-scoped and nothing cascades into it: it keeps the name, the
--    slug, who deleted it, when, and what was in the books at the time.
--    Readable by platform admins, writable by nobody.
-- ============================================================

-- ------------------------------------------------------------
-- 1. ARCHIVED, NOT GONE
-- ------------------------------------------------------------

alter table orgs add column if not exists archived_at timestamptz;
alter table orgs add column if not exists archived_by uuid;

do $$
begin
    if not exists (
        select 1 from pg_constraint where conname = 'orgs_archived_by_fkey'
    ) then
        alter table orgs
            add constraint orgs_archived_by_fkey
            foreign key (archived_by) references profiles(id) on delete set null;
    end if;
end $$;

comment on column orgs.archived_at is
    'Set when a business is put away. It keeps every entry and disappears from my_orgs() for its members; a platform admin can still see it and restore it.';

create index if not exists orgs_active on orgs (id) where archived_at is null;

-- ------------------------------------------------------------
-- 2. THE TOMBSTONE
-- ------------------------------------------------------------
-- Deliberately not referencing orgs: the row it describes is gone. Nothing
-- cascades into this table and nothing may delete from it, which is the whole
-- point — otherwise deleting a business would also delete the record that it
-- was deleted.

create table if not exists deleted_orgs (
    id            uuid primary key,
    name          text not null,
    slug          text not null,
    profile       text,
    deleted_at    timestamptz not null default now(),
    deleted_by    uuid references profiles(id) on delete set null,
    deleted_label text,
    -- What was destroyed, counted at the moment of destruction. Somebody will
    -- ask, and by then there is nothing left to count.
    entry_count   int not null default 0,
    member_count  int not null default 0,
    created_at    timestamptz
);

comment on table deleted_orgs is
    'One row per business that was permanently deleted. Nothing cascades into it and nothing may delete from it: the record of a deletion must outlive the thing deleted.';

alter table deleted_orgs enable row level security;

-- Select only, and only for platform admins. No insert, update or delete
-- policy at all — the only writer is delete_org(), which is SECURITY DEFINER
-- and runs outside policy, exactly like the audit trigger in 008.
drop policy if exists "tombstones readable by platform admins" on deleted_orgs;
create policy "tombstones readable by platform admins"
on deleted_orgs for select
using (exists (select 1 from profiles where id = auth.uid() and is_platform_admin));

-- ------------------------------------------------------------
-- 2b. THE ONE TRIGGER THAT CANNOT COVER ITS OWN CASE
-- ------------------------------------------------------------
-- 008 puts a generic audit trigger on `orgs` for insert, update and delete.
-- The delete arm cannot work and never could: it fires AFTER the row is gone
-- and inserts `audit_log(org_id = <that id>)`, which fails the foreign key.
-- Nothing noticed because until now nothing deleted an org.
--
-- Making the column nullable for this one case would produce a log line that
-- belongs to no business, and `audit_log.org_id` cascades anyway — so even a
-- row that inserted cleanly would be deleted by the same statement that
-- created it. An audit trail cannot record its own erasure.
--
-- So `orgs` keeps its insert and update auditing and loses the delete arm,
-- and `deleted_orgs` above is where a deletion is recorded instead. That
-- table is not org-scoped and nothing cascades into it, which is the only
-- shape that survives.
drop trigger if exists audit_orgs on orgs;
create trigger audit_orgs
    after insert or update on orgs
    for each row execute function audit_row();

-- The same collision, one level down and worse: deleting an org cascades to
-- memberships, accounts, entities, departments, journal_entries,
-- church_members and pending_invitations — every one of them audited, every
-- one firing AFTER DELETE and inserting `audit_log(org_id = <the org just
-- deleted>)`. The cascade cannot complete.
--
-- The alternative to what follows was rewriting audit_row() here to skip a
-- vanishing org, which means carrying a hundred-line copy of 008's trigger in
-- this file and hoping the two never drift. Instead the foreign key is made
-- DEFERRABLE, and delete_org() defers it for its own transaction and sweeps
-- the doomed rows before committing. Nothing else in the schema changes
-- behaviour: the constraint is still INITIALLY IMMEDIATE, so every other
-- write is checked exactly when it was before.
do $$
begin
    if not exists (
        select 1 from pg_constraint
        where conname = 'audit_log_org_id_fkey' and condeferrable
    ) then
        alter table audit_log drop constraint if exists audit_log_org_id_fkey;
        alter table audit_log
            add constraint audit_log_org_id_fkey
            foreign key (org_id) references orgs(id) on delete cascade
            deferrable initially immediate;
    end if;
end $$;

-- ------------------------------------------------------------
-- 3. WHAT A BUSINESS MAY BE CALLED
-- ------------------------------------------------------------
-- Shared by update_org() and worth having on its own: the app's Dart
-- `slugProblem()` makes the same checks so the button can be dead before
-- anything is sent, and two copies of a rule drift unless one of them is the
-- one that actually decides.

create or replace function org_slug_problem(p_slug text)
returns text
language sql
immutable
as $$
    select case
        when p_slug is null or btrim(p_slug) = ''
            then 'Une adresse est nécessaire.'
        when length(btrim(p_slug)) < 3
            then 'Trop court : au moins 3 caractères.'
        when length(btrim(p_slug)) > 63
            then 'Trop long : 63 caractères au maximum.'
        -- Lowercase letters, digits and single hyphens, not at either end.
        -- That is what survives as a subdomain, which is what a slug is for.
        when btrim(p_slug) !~ '^[a-z0-9]+(-[a-z0-9]+)*$'
            then 'Lettres minuscules, chiffres et tirets seulement.'
        else null
    end;
$$;

-- ------------------------------------------------------------
-- 4. CHANGING ONE
-- ------------------------------------------------------------
-- Security definer for the same reason as record_entry(): so the refusal is
-- a sentence rather than "0 rows updated", which is what an RLS-blocked
-- UPDATE looks like from the app and is indistinguishable from success.
--
-- Null means "leave it alone" for every field. Passing one thing must not
-- blank the other four.
create or replace function update_org(
    p_org_id   uuid,
    p_name     text default null,
    p_slug     text default null,
    p_profile  text default null,
    p_currency text default null
)
returns uuid
language plpgsql
security definer
set search_path = public, auth
as $$
declare
    v_actor   uuid := auth.uid();
    v_name    text := nullif(btrim(coalesce(p_name, '')), '');
    v_slug    text := nullif(lower(btrim(coalesce(p_slug, ''))), '');
    v_profile text := nullif(btrim(coalesce(p_profile, '')), '');
    v_problem text;
begin
    if v_actor is null then
        raise exception 'update_org() needs a signed-in caller';
    end if;

    -- is_org_admin() is true for an org's own owner/super_admin/admin and,
    -- since 010, for a platform admin of every org. Both are intended here:
    -- a business owner renaming their own shop is not an escalation.
    if not is_org_admin(p_org_id) then
        raise exception 'You cannot change this business';
    end if;

    if not exists (select 1 from orgs where id = p_org_id) then
        raise exception 'No such business';
    end if;

    -- An archived business is a closed one. Editing it would put a name on
    -- something nobody is looking at, and the restore is one call away.
    if exists (select 1 from orgs where id = p_org_id and archived_at is not null) then
        raise exception 'This business is archived. Restore it before changing it.';
    end if;

    if v_slug is not null then
        v_problem := org_slug_problem(v_slug);
        if v_problem is not null then
            raise exception '%', v_problem;
        end if;
        if exists (select 1 from orgs where slug = v_slug and id <> p_org_id) then
            raise exception 'That address is already taken.';
        end if;
    end if;

    -- The profile decides which home screen opens. An unknown one lands
    -- everybody on the pending screen with no way back, so it is refused
    -- here rather than discovered by the person it happened to.
    if v_profile is not null and v_profile not in ('church', 'farm', 'retail', 'generic') then
        raise exception 'Unknown profile: %', v_profile;
    end if;

    update orgs set
        name             = coalesce(v_name, name),
        slug             = coalesce(v_slug, slug),
        profile          = coalesce(v_profile, profile),
        default_currency = coalesce(nullif(btrim(coalesce(p_currency, '')), ''),
                                    default_currency)
    where id = p_org_id;

    return p_org_id;
end;
$$;

-- ------------------------------------------------------------
-- 5. PUTTING ONE AWAY, AND GETTING IT BACK
-- ------------------------------------------------------------

create or replace function archive_org(p_org_id uuid)
returns uuid
language plpgsql
security definer
set search_path = public, auth
as $$
declare
    v_actor uuid := auth.uid();
begin
    if v_actor is null then
        raise exception 'archive_org() needs a signed-in caller';
    end if;

    -- Deliberately stricter than update_org(): archiving takes a business off
    -- every member's home screen at once, including people who are still
    -- using it. That is a platform-level act, not a shop-floor one.
    if not exists (select 1 from profiles where id = v_actor and is_platform_admin) then
        raise exception 'Only a platform admin can archive a business';
    end if;

    if not exists (select 1 from orgs where id = p_org_id) then
        raise exception 'No such business';
    end if;

    update orgs
       set archived_at = coalesce(archived_at, now()),
           archived_by = coalesce(archived_by, v_actor)
     where id = p_org_id;

    return p_org_id;
end;
$$;

create or replace function restore_org(p_org_id uuid)
returns uuid
language plpgsql
security definer
set search_path = public, auth
as $$
declare
    v_actor uuid := auth.uid();
begin
    if v_actor is null then
        raise exception 'restore_org() needs a signed-in caller';
    end if;

    if not exists (select 1 from profiles where id = v_actor and is_platform_admin) then
        raise exception 'Only a platform admin can restore a business';
    end if;

    update orgs set archived_at = null, archived_by = null where id = p_org_id;
    return p_org_id;
end;
$$;

-- ------------------------------------------------------------
-- 6. DESTROYING ONE
-- ------------------------------------------------------------
-- The only call in this schema that loses data on purpose. Everything about
-- it is arranged so that it cannot happen by accident, and so that the fact
-- it happened survives it.

create or replace function delete_org(
    p_org_id       uuid,
    p_confirm_name text,
    p_force        boolean default false
)
returns uuid
language plpgsql
security definer
set search_path = public, auth
as $$
declare
    v_actor   uuid := auth.uid();
    v_org     orgs%rowtype;
    v_label   text;
    v_entries int;
    v_members int;
begin
    if v_actor is null then
        raise exception 'delete_org() needs a signed-in caller';
    end if;

    if not exists (select 1 from profiles where id = v_actor and is_platform_admin) then
        raise exception 'Only a platform admin can delete a business';
    end if;

    select * into v_org from orgs where id = p_org_id;
    if not found then
        raise exception 'No such business';
    end if;

    -- Never the first thing that happens to a business. Archiving is
    -- reversible and takes it off everyone's screen already, so anyone who
    -- reaches here has had a chance to change their mind.
    if v_org.archived_at is null then
        raise exception
            'Archive % first. Deleting is permanent and archiving is not.',
            v_org.name;
    end if;

    -- The name, typed back. A uuid in a confirmation dialog is not read by
    -- anybody; a name that has to be copied out is.
    if lower(btrim(coalesce(p_confirm_name, ''))) <> lower(btrim(v_org.name)) then
        raise exception
            'Type the name exactly to confirm: %', v_org.name;
    end if;

    select count(*) into v_entries from journal_entries where org_id = p_org_id;
    select count(*) into v_members from memberships    where org_id = p_org_id;

    -- A business nobody ever recorded anything in is a mistake to be swept
    -- up. A business with books is somebody's history, and destroying it
    -- takes a second, explicit act rather than the same click.
    if v_entries > 0 and not coalesce(p_force, false) then
        raise exception
            '% has % entries in its books. Deleting destroys them permanently.',
            v_org.name, v_entries;
    end if;

    select full_name into v_label from profiles where id = v_actor;

    -- Written before the delete, and outside the org's own scope, because
    -- audit_log.org_id cascades and would take this record with it.
    insert into deleted_orgs (
        id, name, slug, profile, deleted_by, deleted_label,
        entry_count, member_count, created_at
    )
    values (
        v_org.id, v_org.name, v_org.slug, v_org.profile, v_actor, v_label,
        v_entries, v_members, v_org.created_at
    )
    on conflict (id) do nothing;

    -- Every audited child table fires AFTER DELETE during the cascade below
    -- and writes an audit_log row pointing at an org that no longer exists.
    -- Deferring the key lets the cascade finish; the sweep afterwards removes
    -- those rows, so the check at commit finds nothing dangling. See the note
    -- beside the constraint above for why this is here rather than inside
    -- audit_row().
    set constraints audit_log_org_id_fkey deferred;

    -- Leaf-first, by hand, and this is not paranoia. Most org-scoped tables
    -- cascade from `orgs`, but plenty of the references *between* them are
    -- NO ACTION — journal_lines.account_id, sales.entry_id,
    -- staff_payments.employee_id, invoices.customer_id — and a cascade does
    -- not order itself by dependency, so it aborts halfway with a foreign key
    -- error and the business survives its own deletion.
    --
    -- The tempting fix is to make those keys cascade too. That would mean
    -- deleting an account silently destroys every ledger line posted to it,
    -- which is the guard those keys exist to provide and is worth far more
    -- than the convenience here. So the destruction is spelled out instead.
    --
    -- A new module with a new table belongs on this list. `test_org_lifecycle`
    -- deletes a business holding one of everything, so forgetting shows up as
    -- a failing suite rather than as a platform admin who cannot delete.
    delete from journal_lines jl using journal_entries je
        where jl.journal_entry_id = je.id and je.org_id = p_org_id;
    delete from contribution_attributions ca using journal_entries je
        where ca.journal_entry_id = je.id and je.org_id = p_org_id;
    delete from sale_lines sl using sales s
        where sl.sale_id = s.id and s.org_id = p_org_id;

    delete from staff_payments  where org_id = p_org_id;
    delete from shifts          where org_id = p_org_id;
    delete from employees       where org_id = p_org_id;

    -- invoice_payments, invoice_lines, flock_events and sale_lines carry no
    -- org_id of their own: they are reached through their parent, which is
    -- how they were written and is not worth changing here.
    delete from invoice_payments ip using invoices i
        where ip.invoice_id = i.id and i.org_id = p_org_id;
    delete from invoice_lines il using invoices i
        where il.invoice_id = i.id and i.org_id = p_org_id;
    delete from invoices        where org_id = p_org_id;
    delete from customers       where org_id = p_org_id;

    delete from egg_production  where org_id = p_org_id;
    delete from flock_events fe using flocks f
        where fe.flock_id = f.id and f.org_id = p_org_id;
    delete from flocks          where org_id = p_org_id;
    delete from stock_movements where org_id = p_org_id;
    delete from items           where org_id = p_org_id;

    delete from documents       where org_id = p_org_id;

    -- Self-referencing: a return points at the sale it reverses, and a
    -- reversing entry at the entry it reverses. Broken before the rows go,
    -- because a delete cannot order a table against itself either.
    update sales set reverses_id = null where org_id = p_org_id;
    delete from sales           where org_id = p_org_id;
    delete from products        where org_id = p_org_id;

    update journal_entries set reverses_entry_id = null where org_id = p_org_id;
    delete from journal_entries where org_id = p_org_id;
    delete from accounts        where org_id = p_org_id;
    delete from church_members  where org_id = p_org_id;

    -- What is left cascades cleanly: memberships, entities, departments,
    -- pending_invitations, audit_log.
    delete from orgs where id = p_org_id;

    -- The org's own audit trail was already cascaded away by the same
    -- statement; this clears what the cascade's own triggers wrote on the way
    -- out. Both are gone either way — which is the argument for the tombstone
    -- and not a shortcut around it.
    delete from audit_log where org_id = p_org_id;

    return p_org_id;
end;
$$;

-- ------------------------------------------------------------
-- 7. WHAT A PLATFORM ADMIN SEES
-- ------------------------------------------------------------
-- my_orgs() answers "which businesses do I open"; this answers "what exists
-- on this platform, and how big is it". Separate because the second one has
-- to include archived businesses, and my_orgs() must not.

create or replace function all_orgs(p_include_archived boolean default true)
returns table (
    org_id       uuid,
    name         text,
    slug         text,
    profile      text,
    currency     text,
    archived_at  timestamptz,
    member_count int,
    entry_count  int,
    created_at   timestamptz
)
language plpgsql
stable
security definer
set search_path = public, auth
as $$
begin
    if not exists (select 1 from profiles where id = auth.uid() and is_platform_admin) then
        raise exception 'Only a platform admin can list every business';
    end if;

    return query
    select o.id, o.name, o.slug, o.profile, o.default_currency, o.archived_at,
           (select count(*)::int from memberships m    where m.org_id = o.id),
           (select count(*)::int from journal_entries j where j.org_id = o.id),
           o.created_at
    from orgs o
    where coalesce(p_include_archived, true) or o.archived_at is null
    order by o.archived_at nulls first, o.name;
end;
$$;

-- ------------------------------------------------------------
-- 8. ARCHIVED BUSINESSES LEAVE THE LIST
-- ------------------------------------------------------------
-- Redefined rather than patched: my_orgs() is what the app calls after
-- sign-in to decide which businesses a person can open, and an archived one
-- must not be among them. A platform admin still sees archived businesses,
-- because somebody has to be able to find one to restore it.

create or replace function my_orgs()
returns table (
    org_id           uuid,
    name             text,
    slug             text,
    profile          text,
    default_currency text,
    roles            text[],
    visibility       text
)
language sql
stable
security definer
set search_path = public, auth
as $$
    select
        o.id, o.name, o.slug, o.profile, o.default_currency,
        array['platform_admin'::text],
        'full'::text
    from orgs o
    where exists(select 1 from profiles where id = auth.uid() and is_platform_admin)

    union all

    select
        o.id, o.name, o.slug, o.profile, o.default_currency,
        array_agg(distinct m.role::text order by m.role::text),
        case when bool_or(m.visibility = 'full') then 'full' else 'summary' end
    from memberships m
    join orgs o on o.id = m.org_id
    where m.user_id = auth.uid()
      and o.archived_at is null
      and not exists(select 1 from profiles where id = auth.uid() and is_platform_admin)
    group by o.id, o.name, o.slug, o.profile, o.default_currency

    order by name;
$$;

-- ------------------------------------------------------------
-- 9. GRANTS
-- ------------------------------------------------------------
-- Every SECURITY DEFINER function above starts life executable by PUBLIC,
-- which includes anon. Each refuses a caller with no session already; the
-- revoke makes it deliberate rather than inherited, as in 005-007 and 013.
revoke execute on function update_org(uuid, text, text, text, text) from public;
revoke execute on function archive_org(uuid) from public;
revoke execute on function restore_org(uuid) from public;
revoke execute on function delete_org(uuid, text, boolean) from public;
revoke execute on function all_orgs(boolean) from public;

-- `authenticated` is a Supabase role and does not exist on a bare Postgres,
-- which is what CI starts from. Roles are cluster-wide, so a developer whose
-- cluster has ever run a suite already has it and cannot reproduce the
-- failure by creating a fresh database — which is exactly how 013 shipped
-- this wrong once.
do $$
begin
    if exists (select 1 from pg_roles where rolname = 'authenticated') then
        grant execute on function update_org(uuid, text, text, text, text) to authenticated;
        grant execute on function archive_org(uuid) to authenticated;
        grant execute on function restore_org(uuid) to authenticated;
        grant execute on function delete_org(uuid, text, boolean) to authenticated;
        grant execute on function all_orgs(boolean) to authenticated;
        grant execute on function org_slug_problem(text) to authenticated;
        grant select on deleted_orgs to authenticated;
    end if;
end $$;

notify pgrst, 'reload schema';


-- ============================================================
-- 015_product_serial.sql
-- ============================================================
-- ============================================================
-- 015_product_serial.sql — the field M5 asked for and 011 did not build.
--
-- The plan's product list is "name, serial, barcode, expiry, cost, price,
-- quantity, photos". 011 built `sku` and called that close enough. It is not:
-- a SKU is the shop's own code for a *kind* of thing and there is one per
-- product, while a serial number identifies *one physical unit* and matters
-- for exactly the goods Esperance sells at the top of her range — a phone, a
-- radio, a solar panel. It is what a customer's warranty claim is looked up
-- by, and what a theft is reported with.
--
-- Kept as a nullable column beside `sku` rather than replacing it, because
-- most of what a shop sells has neither and both are already true of the rows
-- that exist.
--
-- Not made unique. Two units of the same model can arrive with the same
-- number printed badly, OCR reads a 0 as an 8, and a shopkeeper typing at a
-- counter should not be stopped by a constraint over a field nobody is
-- required to fill in. The index exists so it can be searched, which is the
-- thing it is actually for.
-- ============================================================

alter table products add column if not exists serial text;

comment on column products.serial is
    'The serial number of one physical unit — a phone, a radio, a panel. Not unique on purpose: a mistyped duplicate must not block a sale.';

create index if not exists products_by_serial
    on products (org_id, serial) where serial is not null;

-- Finding a unit by the number on its back, which is how a warranty claim
-- arrives: somebody at the counter holding the thing. Matches on a trimmed,
-- case-insensitive prefix, the same way a person reads one out.
create or replace function product_by_serial(p_org_id uuid, p_serial text)
returns table (
    id         uuid,
    name       text,
    serial     text,
    sale_price numeric,
    quantity   numeric
)
language sql
stable
security invoker
set search_path = public
as $$
    select p.id, p.name, p.serial, p.sale_price, p.quantity
    from products p
    where p.org_id = p_org_id
      and p.serial is not null
      and lower(btrim(p.serial)) like lower(btrim(coalesce(p_serial, ''))) || '%'
    order by p.name
    limit 20;
$$;

-- ------------------------------------------------------------
-- The photographs of a product
-- ------------------------------------------------------------
-- `documents.product_id` has existed since 013 and nothing read it back the
-- other way round. The plan's product list ends with "photos", and this is
-- what makes that true: the delivery note a thing arrived on, and the picture
-- of the thing itself, reachable from the product rather than only from the
-- gallery.
--
-- Security invoker, like every other read here: 006 decides who may see a
-- document, and an observer entitled to totals is not entitled to the
-- paperwork behind them. A definer would hand it to them.
create or replace function product_photos(p_product_id uuid, p_limit int default 20)
returns table (
    id           uuid,
    r2_key       text,
    kind         text,
    caption      text,
    content_type text,
    captured_at  timestamptz
)
language sql
stable
security invoker
set search_path = public
as $$
    select d.id, d.r2_key, d.kind, d.caption, d.content_type,
           coalesce(d.captured_at, d.created_at)
    from documents d
    where d.product_id = p_product_id
    order by coalesce(d.captured_at, d.created_at) desc
    limit greatest(coalesce(p_limit, 20), 1);
$$;

-- ------------------------------------------------------------
-- Setting it
-- ------------------------------------------------------------
-- `update_product` in the app writes sale_price, cost_price, expiry and the
-- reorder point straight through RLS. The serial goes the same way and needs
-- no function of its own — the update policy from 011 already says who may
-- change a product. This exists only so `ensure_product` can carry one in
-- from a scan or a reading, which is the moment it is actually known.
create or replace function set_product_serial(
    p_product_id uuid,
    p_serial     text
)
returns uuid
language plpgsql
security definer
set search_path = public, auth
as $$
declare
    v_actor  uuid := auth.uid();
    v_org_id uuid;
begin
    if v_actor is null then
        raise exception 'set_product_serial() needs a signed-in caller';
    end if;

    select org_id into v_org_id from products where id = p_product_id;
    if not found then
        raise exception 'No such product';
    end if;

    if not can_write_org(v_org_id) then
        raise exception 'You cannot change products in this business';
    end if;

    update products
       set serial = nullif(btrim(coalesce(p_serial, '')), '')
     where id = p_product_id;

    return p_product_id;
end;
$$;

-- ------------------------------------------------------------
-- GRANTS
-- ------------------------------------------------------------
revoke execute on function set_product_serial(uuid, text) from public;

-- `authenticated` is a Supabase role and does not exist on a bare Postgres.
-- Roles are cluster-wide, so a developer whose cluster has ever run a suite
-- already has it and cannot reproduce the failure by making a fresh database
-- — which is how 013 shipped this wrong once.
do $$
begin
    if exists (select 1 from pg_roles where rolname = 'authenticated') then
        grant execute on function set_product_serial(uuid, text) to authenticated;
        grant execute on function product_by_serial(uuid, text) to authenticated;
        grant execute on function product_photos(uuid, int) to authenticated;
    end if;
end $$;

notify pgrst, 'reload schema';


-- ============================================================
-- 016_stock_receipts.sql
-- ============================================================
-- ============================================================
-- 016_stock_receipts.sql — a delivery, recorded once.
--
-- Found by test_delivery.sql while building the photograph-to-stock flow, and
-- it is worse than an ordinary duplicate.
--
-- `receive_products()` already passed its `client_uuid` down to
-- `record_entry()`, so a retried delivery posted its money exactly once. But
-- the line above it —
--
--     update products set quantity = quantity + p_quantity
--
-- ran unconditionally. So pressing "add to stock" a second time after a
-- connection dropped added the goods again and the money not at all. The
-- count and the books then disagree by exactly one delivery, in the direction
-- that makes the shop look like it has stock it does not have, and nothing on
-- any screen says so. A plain double-entry would at least have been visible
-- in the ledger.
--
-- The confirm screen mints one client_uuid per line and keeps it across
-- retries precisely so this is safe. It was not.
--
-- The fix also closes something 011 claimed and did not do. Its own header
-- says of `products.quantity`: "Every movement is still recorded in
-- `sale_lines`, so the column can be rebuilt from history if it ever drifts."
-- That is true of sales and returns and was never true of deliveries — stock
-- arriving was recorded nowhere except as an expense in the ledger, which
-- does not carry a count. `stock_receipts` is what makes the sentence true.
-- ============================================================

create table if not exists stock_receipts (
    id           uuid primary key default gen_random_uuid(),
    org_id       uuid not null references orgs(id) on delete cascade,
    product_id   uuid not null references products(id) on delete cascade,
    quantity     numeric(14,3) not null check (quantity > 0),
    unit_cost    numeric(14,2) not null default 0 check (unit_cost >= 0),
    expires_on   date,
    -- The purchase this delivery posted, when it posted one. Null for stock
    -- received on credit or with no cost recorded, which still moves goods.
    entry_id     uuid references journal_entries(id),
    client_uuid  uuid,
    device_id    text,
    received_at  timestamptz not null default now(),
    received_by  uuid references profiles(id)
);

-- The whole point. One delivery per client_uuid per shop, however many times
-- the phone sends it.
create unique index if not exists stock_receipts_by_client_uuid
    on stock_receipts (org_id, client_uuid) where client_uuid is not null;

create index if not exists stock_receipts_by_product
    on stock_receipts (product_id, received_at desc);

comment on table stock_receipts is
    'Stock arriving, append-only. Makes products.quantity rebuildable and makes a retried delivery count once.';

-- ------------------------------------------------------------
-- receive_products, made re-runnable
-- ------------------------------------------------------------
-- Same signature and same behaviour for a first call. The only difference is
-- that a second call carrying a client_uuid this shop has already seen
-- returns the original entry and touches nothing.
create or replace function receive_products(
    p_org_id      uuid,
    p_product_id  uuid,
    p_quantity    numeric,
    p_unit_cost   numeric     default null,
    p_expires_on  date        default null,
    p_method      text        default 'cash',
    p_client_uuid uuid        default null,
    p_device_id   text        default null,
    p_occurred_at timestamptz default now()
)
returns uuid
language plpgsql
security definer
set search_path = public, auth
as $$
declare
    v_actor    uuid := auth.uid();
    v_name     text;
    v_cost     numeric;
    v_entry    uuid;
    v_existing stock_receipts%rowtype;
begin
    if p_quantity is null or p_quantity <= 0 then
        raise exception 'A delivery needs a quantity';
    end if;

    -- Before anything is moved. Checked against stock_receipts rather than
    -- journal_entries because a delivery with no cost posts no entry, and
    -- half an idempotency guarantee is the kind of thing that is discovered
    -- by a shopkeeper rather than by a test.
    if p_client_uuid is not null then
        select * into v_existing from stock_receipts
        where org_id = p_org_id and client_uuid = p_client_uuid;
        if found then
            return v_existing.entry_id;
        end if;
    end if;

    select name, cost_price into v_name, v_cost
    from products where id = p_product_id and org_id = p_org_id;

    if v_name is null then
        raise exception 'No such product in this business';
    end if;

    v_cost := coalesce(p_unit_cost, v_cost, 0);

    update products set
        quantity   = quantity + p_quantity,
        cost_price = case when p_unit_cost is not null then p_unit_cost
                          else cost_price end,
        expires_on = coalesce(p_expires_on, expires_on)
    where id = p_product_id;

    -- Only money that actually moved gets a ledger entry. Stock received on
    -- credit, or with no cost recorded, still updates the count.
    if v_cost > 0 then
        v_entry := record_entry(
            p_org_id      => p_org_id,
            p_amount      => v_cost * p_quantity,
            p_direction   => 'out',
            p_label       => 'Achat de marchandise',
            p_recorded_by => v_actor,
            p_category    => 'Achats de marchandises',
            p_method      => p_method,
            p_memo        => v_name,
            p_details     => jsonb_build_object('product', v_name,
                                                'quantity', p_quantity),
            p_client_uuid => p_client_uuid,
            p_device_id   => p_device_id,
            p_occurred_at => p_occurred_at
        );
    end if;

    insert into stock_receipts (
        org_id, product_id, quantity, unit_cost, expires_on,
        entry_id, client_uuid, device_id, received_at, received_by
    )
    values (
        p_org_id, p_product_id, p_quantity, v_cost, p_expires_on,
        v_entry, p_client_uuid, p_device_id, p_occurred_at, v_actor
    );

    return v_entry;
end;
$$;

-- ------------------------------------------------------------
-- What arrived, and when
-- ------------------------------------------------------------
-- Security invoker: a delivery is a purchase, and 006 already decided that an
-- observer entitled to totals is not entitled to the line items behind them.
--
-- Dropped before creating so the bundle stays re-runnable: 042 later adds a
-- column to this function's return type, and on a second pass of the bundle
-- this create-or-replace would otherwise meet that wider shape and fail with
-- "cannot change return type". The drop makes the two definitions agree to
-- disagree in order.
drop function if exists recent_deliveries(uuid, int);
create or replace function recent_deliveries(
    p_org_id uuid,
    p_limit  int default 50
)
returns table (
    id           uuid,
    product_id   uuid,
    product_name text,
    quantity     numeric,
    unit_cost    numeric,
    line_total   numeric,
    received_at  timestamptz,
    received_by  text
)
language sql
stable
security invoker
set search_path = public
as $$
    select r.id, r.product_id, p.name, r.quantity, r.unit_cost,
           r.quantity * r.unit_cost, r.received_at, pr.full_name
    from stock_receipts r
    join products p on p.id = r.product_id
    left join profiles pr on pr.id = r.received_by
    where r.org_id = p_org_id
    order by r.received_at desc, r.id desc
    limit greatest(coalesce(p_limit, 50), 1);
$$;

-- ------------------------------------------------------------
-- RLS
-- ------------------------------------------------------------
alter table stock_receipts enable row level security;

-- Readable by anyone entitled to the entries behind it, written by anyone who
-- may record — the same pair as `sales` in 011. No update and no delete
-- policy at all: a delivery that can be edited is a count nobody can trust,
-- and correcting one is another movement rather than a rewrite.
drop policy if exists "deliveries readable with full visibility" on stock_receipts;
create policy "deliveries readable with full visibility"
on stock_receipts for select
using (has_full_visibility(org_id));

drop policy if exists "deliveries written by staff" on stock_receipts;
create policy "deliveries written by staff"
on stock_receipts for insert
with check (can_write_org(org_id));

-- ------------------------------------------------------------
-- GRANTS
-- ------------------------------------------------------------
revoke execute on function receive_products(uuid, uuid, numeric, numeric, date, text, uuid, text, timestamptz) from public;

do $$
begin
    if exists (select 1 from pg_roles where rolname = 'authenticated') then
        grant execute on function receive_products(uuid, uuid, numeric, numeric, date, text, uuid, text, timestamptz) to authenticated;
        grant execute on function recent_deliveries(uuid, int) to authenticated;
        grant select, insert on stock_receipts to authenticated;
    end if;
end $$;

notify pgrst, 'reload schema';


-- ============================================================
-- 017_people_and_onboarding.sql
-- ============================================================
-- ============================================================
-- 017_people_and_onboarding.sql — who a person is, and the two ways in.
--
-- Until now a `profiles` row held a `full_name` and a phone number, and both
-- came from whatever the auth provider happened to have. That is enough to
-- greet somebody by name and not enough for anything a business does with a
-- person: a payslip needs a legal name, a contract needs a date of birth, and
-- a directory that cannot tell two Ouédraogos apart is a directory nobody
-- uses twice.
--
-- Two routes in, and they are deliberately different shapes.
--
-- **An employee joins a business that already exists.** They make an account,
-- say who they are, and enter a code their manager sent them. The code is
-- what grants access — nothing about filling in a form does — so a stranger
-- who completes the whole profile still belongs to no business.
--
-- **A manager asks for a business to exist.** They make an account, say who
-- they are, describe the business, and wait. `create_org()` has been platform
-- admin only since 010 and stays that way: the thing that decides whether a
-- new tenant appears on this platform is a person at Kaj-consulting, not a
-- sign-up form. What changes is that there is now a queue for them to look
-- at instead of an email nobody sent.
--
-- Three decisions worth knowing.
--
-- 1. **A profile is never half-written by the server.** Everything added here
--    is nullable, and `profile_is_complete()` is a question rather than a
--    constraint. Somebody signed up before this migration existed and must
--    keep working; somebody who abandons the form halfway must not be locked
--    out of an account they already have.
--
-- 2. **The phone typed twice is checked in the app, not here.** Two identical
--    strings arriving in one call prove nothing about what was typed. The
--    confirmation exists to catch a mistyped digit at the keyboard, which is
--    where it has to be caught.
--
-- 3. **An application is not a business.** `org_applications` holds what
--    somebody asked for. Approving one calls `create_org()` and makes the
--    applicant its owner in the same transaction; until then there is no org,
--    no slug reserved, and nothing for them to sign into.
-- ============================================================

-- ------------------------------------------------------------
-- 1. WHO SOMEBODY IS
-- ------------------------------------------------------------
-- Split names rather than one field, because the parts get used separately:
-- a payslip wants "OUÉDRAOGO Awa", a greeting wants "Awa", and a directory
-- sorts on the family name. `full_name` stays and stays authoritative for
-- display — every screen in the app already reads it — and is kept in step by
-- the function below rather than by a trigger, so importing a row never
-- silently rewrites what somebody typed.

alter table profiles add column if not exists first_name    text;
alter table profiles add column if not exists middle_name   text;
alter table profiles add column if not exists last_name     text;
alter table profiles add column if not exists date_of_birth date;
alter table profiles add column if not exists title         text;
alter table profiles add column if not exists profile_completed_at timestamptz;

comment on column profiles.title is
    'What they do — "Vendeuse", "Gérant", "Comptable". Their own words, not a role in the permission sense.';
comment on column profiles.date_of_birth is
    'Needed by a contract and a payslip. Nullable: an account that predates this must keep working.';

-- A date of birth that is in the future or implies a 12-year-old is a typo,
-- and a typo in this field ends up on a contract. Checked as a constraint
-- because unlike the rest of the form there is a right answer.
do $$
begin
    if not exists (
        select 1 from pg_constraint where conname = 'profiles_dob_is_plausible'
    ) then
        alter table profiles add constraint profiles_dob_is_plausible
            check (
                date_of_birth is null
                or (date_of_birth > current_date - interval '120 years'
                    and date_of_birth < current_date - interval '14 years')
            );
    end if;
end $$;

-- Sorting a directory by family name, which is how a list of people is read.
create index if not exists profiles_by_last_name
    on profiles (lower(last_name)) where last_name is not null;

-- Whether there is enough here to put on a contract. A question, never a gate
-- on signing in: an incomplete profile is a prompt, not a lockout.
create or replace function profile_is_complete(p_user_id uuid default null)
returns boolean
language sql
stable
security definer
set search_path = public, auth
as $$
    select coalesce(
        (select first_name is not null and btrim(first_name) <> ''
            and last_name is not null and btrim(last_name) <> ''
            and date_of_birth is not null
            and phone is not null and btrim(phone) <> ''
         from profiles
         where id = coalesce(p_user_id, auth.uid())),
        false);
$$;

-- What somebody tells us about themselves, in one call.
--
-- Security definer and self-only: the 004 policy already lets a person edit
-- their own profile, and this adds the name assembly and the refusal to write
-- somebody else's. A manager correcting a colleague's spelling is a different
-- act and is not this one.
create or replace function save_my_profile(
    p_first_name    text,
    p_last_name     text,
    p_middle_name   text default null,
    p_date_of_birth date default null,
    p_title         text default null,
    p_phone         text default null
)
returns uuid
language plpgsql
security definer
set search_path = public, auth
as $$
declare
    v_actor uuid := auth.uid();
    v_first text := nullif(btrim(coalesce(p_first_name, '')), '');
    v_last  text := nullif(btrim(coalesce(p_last_name, '')), '');
    v_mid   text := nullif(btrim(coalesce(p_middle_name, '')), '');
    v_phone text := nullif(btrim(coalesce(p_phone, '')), '');
    v_full  text;
begin
    if v_actor is null then
        raise exception 'save_my_profile() needs a signed-in caller';
    end if;

    if v_first is null or v_last is null then
        raise exception 'A first name and a family name are needed';
    end if;

    -- The family name last, which is how a name is written on screen here.
    -- `full_name` stays the one field every existing screen reads, so it is
    -- assembled rather than left to drift out of step with its parts.
    v_full := btrim(concat_ws(' ', v_first, v_mid, v_last));

    -- A number already on somebody else's account is a mistyped digit far
    -- more often than it is a genuine collision, and the unique index would
    -- otherwise answer with a constraint name.
    if v_phone is not null and exists (
        select 1 from profiles where phone = v_phone and id <> v_actor
    ) then
        raise exception 'Ce numéro est déjà utilisé par un autre compte.';
    end if;

    update profiles set
        first_name    = v_first,
        middle_name   = v_mid,
        last_name     = v_last,
        full_name     = v_full,
        date_of_birth = coalesce(p_date_of_birth, date_of_birth),
        title         = coalesce(nullif(btrim(coalesce(p_title, '')), ''), title),
        phone         = coalesce(v_phone, phone)
    where id = v_actor;

    update profiles
       set profile_completed_at = coalesce(profile_completed_at, now())
     where id = v_actor and profile_is_complete(v_actor);

    return v_actor;
end;
$$;

-- ------------------------------------------------------------
-- 2. THE CODE A MANAGER SENDS
-- ------------------------------------------------------------
-- 005 built invitations and the app made the *invitee* find them: a menu
-- entry called "J'ai un code" that assumed somebody had already been given
-- one, by some means the app knew nothing about. That is backwards. The
-- person with the app open is the manager, and the person without it is the
-- one who needs to be reached.
--
-- So the generating side gets a function that returns everything needed to
-- send an invitation over WhatsApp — which is where these conversations
-- actually happen — and the app builds a message around it.

alter table pending_invitations add column if not exists title text;
alter table pending_invitations add column if not exists full_name text;
alter table pending_invitations add column if not exists note text;

comment on column pending_invitations.full_name is
    'Who the manager thinks they are inviting. Pre-fills the sign-up form; never overrides what the person then types about themselves.';

-- Issues an invitation and hands back the code plus the name of the business,
-- so the app can compose the message without a second round trip.
--
-- Security definer because it writes on behalf of the caller and checks the
-- same thing 005's insert policy checks. The refusal is a sentence rather
-- than a policy violation, which is what the sharing sheet shows.
create or replace function invite_employee(
    p_org_id     uuid,
    p_role       role_name default 'employee',
    p_full_name  text default null,
    p_title      text default null,
    p_phone      text default null,
    p_visibility text default 'full',
    p_valid_days int  default 14,
    p_note       text default null
)
returns table (
    invitation_id uuid,
    code          text,
    org_name      text,
    expires_at    timestamptz
)
language plpgsql
security definer
set search_path = public, auth
as $$
declare
    v_actor uuid := auth.uid();
    v_id    uuid;
begin
    if v_actor is null then
        raise exception 'invite_employee() needs a signed-in caller';
    end if;

    if not is_org_admin(p_org_id) then
        raise exception 'You cannot invite people to this business';
    end if;

    insert into pending_invitations (
        org_id, role, scope_kind, scope_id, visibility,
        code, phone, full_name, title, note, expires_at, created_by
    )
    values (
        p_org_id, p_role, 'org', p_org_id, coalesce(p_visibility, 'full'),
        new_invitation_code(),
        nullif(btrim(coalesce(p_phone, '')), ''),
        nullif(btrim(coalesce(p_full_name, '')), ''),
        nullif(btrim(coalesce(p_title, '')), ''),
        nullif(btrim(coalesce(p_note, '')), ''),
        now() + make_interval(days => greatest(coalesce(p_valid_days, 14), 1)),
        v_actor
    )
    returning id into v_id;

    return query
    select i.id, i.code, o.name, i.expires_at
    from pending_invitations i
    join orgs o on o.id = i.org_id
    where i.id = v_id;
end;
$$;

-- ------------------------------------------------------------
-- 2b. THE NUMBER SOMEBODY GAVE, AND THE NUMBER THEY SIGNED IN WITH
-- ------------------------------------------------------------
-- 005 pins an invitation to `auth.users.phone` — the number the account was
-- created with. That was the only number there was.
--
-- It is not any more. `save_my_profile()` above lets somebody set the number
-- they actually want to be reached on, and those two legitimately differ: an
-- account made with an email has no auth phone at all, and a second SIM is
-- normal here. A manager types the number their new employee gave them,
-- which is the profile one, and 005 then refuses the claim with "ce code a
-- été émis pour un autre numéro" — an error the employee cannot act on and
-- the manager cannot see.
--
-- So the check widens by exactly one number: an invitation pinned to a phone
-- is claimable by somebody for whom that is *either* their sign-in number or
-- the number on their profile. It stays a pin — a stranger holding the code
-- is still refused — and the only thing that changes is which of a person's
-- own numbers counts as theirs.
--
-- Everything else in both functions is 005's, unchanged.
create or replace function claim_invitation(p_code text)
returns uuid
language plpgsql
volatile
security definer
set search_path = public, auth
as $$
declare
    v_uid    uuid := auth.uid();
    v_phone  text;
    v_email  text;
    v_alt    text;
    v_inv    pending_invitations%rowtype;
    v_code   text := normalize_invitation_code(p_code);
begin
    if v_uid is null then
        raise exception 'Connectez-vous avant d''utiliser un code d''invitation.'
            using errcode = 'invalid_authorization_specification';
    end if;

    if not exists (select 1 from profiles where id = v_uid) then
        raise exception 'Ce compte n''est pas encore prêt. Réessayez dans un instant.';
    end if;

    select u.phone, u.email into v_phone, v_email from auth.users u where u.id = v_uid;
    select p.phone into v_alt from profiles p where p.id = v_uid;

    select * into v_inv
    from pending_invitations i
    where normalize_invitation_code(i.code) = v_code
    for update;

    if not found then
        raise exception 'Code inconnu. Vérifiez les caractères saisis.'
            using errcode = 'no_data_found';
    end if;

    if v_inv.claimed_at is not null then
        if v_inv.claimed_by = v_uid then
            return v_inv.org_id;
        end if;
        raise exception 'Ce code a déjà été utilisé.'
            using errcode = 'no_data_found';
    end if;

    if v_inv.expires_at <= now() then
        raise exception 'Ce code a expiré. Demandez-en un nouveau.'
            using errcode = 'no_data_found';
    end if;

    -- Either of their own numbers. See the note above.
    if v_inv.phone is not null
       and v_inv.phone is distinct from v_phone
       and v_inv.phone is distinct from v_alt then
        raise exception 'Ce code a été émis pour un autre numéro de téléphone.'
            using errcode = 'insufficient_privilege';
    end if;

    if v_inv.email is not null and lower(v_inv.email) is distinct from lower(v_email) then
        raise exception 'Ce code a été émis pour une autre adresse e-mail.'
            using errcode = 'insufficient_privilege';
    end if;

    insert into memberships (org_id, user_id, role, scope_kind, scope_id, visibility)
    values (v_inv.org_id, v_uid, v_inv.role, v_inv.scope_kind, v_inv.scope_id, v_inv.visibility)
    on conflict (user_id, scope_kind, scope_id, role) do nothing;

    update pending_invitations
    set claimed_at = now(), claimed_by = v_uid
    where id = v_inv.id and claimed_at is null;

    return v_inv.org_id;
end;
$$;

-- The sign-in sweep, widened the same way and for the same reason: an
-- invitation written to the number somebody gave their manager should find
-- them when they appear, with nothing to type.
create or replace function claim_my_invitations()
returns int
language plpgsql
volatile
security definer
set search_path = public, auth
as $$
declare
    v_uid   uuid := auth.uid();
    v_phone text;
    v_email text;
    v_alt   text;
    v_count int := 0;
    v_inv   pending_invitations%rowtype;
begin
    if v_uid is null then
        return 0;
    end if;

    if not exists (select 1 from profiles where id = v_uid) then
        return 0;
    end if;

    select u.phone, u.email into v_phone, v_email from auth.users u where u.id = v_uid;
    select p.phone into v_alt from profiles p where p.id = v_uid;

    for v_inv in
        select * from pending_invitations i
        where i.claimed_at is null
          and i.expires_at > now()
          and (
              (v_phone is not null and i.phone = v_phone)
              or (v_alt is not null and i.phone = v_alt)
              or (v_email is not null and lower(i.email) = lower(v_email))
          )
        for update
    loop
        insert into memberships (org_id, user_id, role, scope_kind, scope_id, visibility)
        values (v_inv.org_id, v_uid, v_inv.role, v_inv.scope_kind,
                v_inv.scope_id, v_inv.visibility)
        on conflict (user_id, scope_kind, scope_id, role) do nothing;

        update pending_invitations
        set claimed_at = now(), claimed_by = v_uid
        where id = v_inv.id and claimed_at is null;

        v_count := v_count + 1;
    end loop;

    return v_count;
end;
$$;

-- ------------------------------------------------------------
-- 3. A MANAGER ASKING FOR A BUSINESS
-- ------------------------------------------------------------
-- The other route in. `create_org()` stays platform admin only — whether a
-- new tenant appears on this platform is a decision, not a form submission —
-- and this is the queue that decision is made from.

create table if not exists org_applications (
    id            uuid primary key default gen_random_uuid(),
    applicant_id  uuid not null references profiles(id) on delete cascade,

    -- What they are asking for. Held here rather than in `orgs`, because
    -- until somebody approves it there is no business: no slug reserved, no
    -- books, nothing to sign into.
    name          text not null,
    slug          text not null,
    profile       text not null default 'generic',
    currency      text not null default 'XOF',

    -- Who they are and how to reach them, as they told it. Kept on the
    -- application rather than read from the profile at review time, so the
    -- reviewer sees what was actually submitted.
    contact_name  text,
    contact_phone text,
    contact_email text,
    description   text,

    status        text not null default 'pending'
                  check (status in ('pending', 'approved', 'rejected')),
    -- Filled by the reviewer. A rejection with no reason is one the applicant
    -- cannot act on, and they will simply apply again.
    decision_note text,
    reviewed_by   uuid references profiles(id) on delete set null,
    reviewed_at   timestamptz,

    -- Set on approval. The one link between an application and the business
    -- it became.
    org_id        uuid references orgs(id) on delete set null,

    created_at    timestamptz not null default now()
);

comment on table org_applications is
    'Somebody asking for a business to exist. Approving one calls create_org() and makes the applicant its owner.';

-- One open application per person. Somebody who applies four times while
-- waiting produces four things to review and one business.
create unique index if not exists org_applications_one_pending
    on org_applications (applicant_id) where status = 'pending';

create index if not exists org_applications_pending
    on org_applications (created_at desc) where status = 'pending';

alter table org_applications enable row level security;

-- An applicant sees their own; a platform admin sees all. Nobody else sees
-- anything: what businesses are being asked for is not a tenant's business.
drop policy if exists "applications readable by applicant and platform" on org_applications;
create policy "applications readable by applicant and platform"
on org_applications for select
using (
    applicant_id = auth.uid()
    or exists (select 1 from profiles where id = auth.uid() and is_platform_admin)
);

-- Written through apply_for_org() only, which is definer — but the policy is
-- what holds if somebody posts to the table directly, and it must not let
-- them file an application in somebody else's name or pre-approve it.
drop policy if exists "applications written by their applicant" on org_applications;
create policy "applications written by their applicant"
on org_applications for insert
with check (applicant_id = auth.uid() and status = 'pending');

-- Deciding is a platform act. No delete policy at all: a rejected
-- application is the record of a decision somebody made.
drop policy if exists "applications decided by platform admins" on org_applications;
create policy "applications decided by platform admins"
on org_applications for update
using (exists (select 1 from profiles where id = auth.uid() and is_platform_admin))
with check (exists (select 1 from profiles where id = auth.uid() and is_platform_admin));

create or replace function apply_for_org(
    p_name        text,
    p_slug        text,
    p_profile     text default 'generic',
    p_currency    text default 'XOF',
    p_description text default null,
    p_phone       text default null,
    p_email       text default null
)
returns uuid
language plpgsql
security definer
set search_path = public, auth
as $$
declare
    v_actor   uuid := auth.uid();
    v_name    text := nullif(btrim(coalesce(p_name, '')), '');
    v_slug    text := nullif(lower(btrim(coalesce(p_slug, ''))), '');
    v_problem text;
    v_id      uuid;
    v_full    text;
    v_phone   text;
begin
    if v_actor is null then
        raise exception 'apply_for_org() needs a signed-in caller';
    end if;

    if v_name is null then
        raise exception 'A business needs a name';
    end if;

    v_problem := org_slug_problem(v_slug);
    if v_problem is not null then
        raise exception '%', v_problem;
    end if;

    -- Checked now as well as at approval. Telling somebody their address is
    -- taken while they are filling the form in is worth far more than telling
    -- them a week later.
    if exists (select 1 from orgs where slug = v_slug) then
        raise exception 'That address is already taken.';
    end if;

    -- Who this is, as the platform will see it in the queue.
    select full_name, phone into v_full, v_phone from profiles where id = v_actor;

    insert into org_applications (
        applicant_id, name, slug, profile, currency,
        contact_name, contact_phone, contact_email, description
    )
    values (
        v_actor, v_name, v_slug,
        coalesce(nullif(btrim(coalesce(p_profile, '')), ''), 'generic'),
        coalesce(nullif(btrim(coalesce(p_currency, '')), ''), 'XOF'),
        v_full,
        coalesce(nullif(btrim(coalesce(p_phone, '')), ''), v_phone),
        nullif(btrim(coalesce(p_email, '')), ''),
        nullif(btrim(coalesce(p_description, '')), '')
    )
    -- Applying twice while waiting is a person pressing a button again, not a
    -- second business. The partial unique index makes it one row; this makes
    -- it one row without an error.
    on conflict (applicant_id) where status = 'pending'
    do update set
        name        = excluded.name,
        slug        = excluded.slug,
        profile     = excluded.profile,
        currency    = excluded.currency,
        description = excluded.description,
        created_at  = now()
    returning id into v_id;

    return v_id;
end;
$$;

-- Approving one: the business is created and the applicant owns it, in one
-- transaction. Nothing here trusts the application's own status column —
-- `for update` takes the row so two admins pressing approve at the same
-- moment cannot make two businesses.
create or replace function approve_org_application(
    p_application_id uuid,
    p_note           text default null
)
returns uuid
language plpgsql
security definer
set search_path = public, auth
as $$
declare
    v_actor uuid := auth.uid();
    v_app   org_applications%rowtype;
    v_org   uuid;
begin
    if v_actor is null then
        raise exception 'approve_org_application() needs a signed-in caller';
    end if;

    if not exists (select 1 from profiles where id = v_actor and is_platform_admin) then
        raise exception 'Only a platform admin can approve a business';
    end if;

    select * into v_app from org_applications
    where id = p_application_id for update;
    if not found then
        raise exception 'No such application';
    end if;
    if v_app.status <> 'pending' then
        raise exception 'This application has already been %', v_app.status;
    end if;

    if exists (select 1 from orgs where slug = v_app.slug) then
        raise exception
            'The address % was taken while this was waiting. Ask them for another.',
            v_app.slug;
    end if;

    insert into orgs (name, slug, profile, default_currency)
    values (v_app.name, v_app.slug, v_app.profile, v_app.currency)
    returning id into v_org;

    -- The applicant owns it. This is the whole point of approving rather than
    -- creating: the business exists because they asked for it, so it is
    -- theirs and not the reviewer's.
    insert into memberships (org_id, user_id, role, scope_kind, scope_id)
    values (v_org, v_app.applicant_id, 'owner', 'org', v_org)
    on conflict do nothing;

    -- The same starter chart create_org() lays down, chosen by profile.
    if v_app.profile = 'church' then
        perform seed_church_accounts(v_org);
    elsif v_app.profile = 'retail' then
        perform seed_retail_accounts(v_org);
    elsif v_app.profile = 'farm' then
        perform seed_farm_accounts(v_org);
    else
        insert into accounts (org_id, code, name, type) values
            (v_org, '1000', 'Cash on Hand',      'asset'),
            (v_org, '1010', 'Bank Account',      'asset'),
            (v_org, '1020', 'Mobile Money',      'asset'),
            (v_org, '4000', 'Sales',             'income'),
            (v_org, '5000', 'Purchases',         'expense'),
            (v_org, '5010', 'Operating Expenses','expense')
        on conflict (org_id, code) do nothing;
    end if;

    update org_applications set
        status        = 'approved',
        decision_note = nullif(btrim(coalesce(p_note, '')), ''),
        reviewed_by   = v_actor,
        reviewed_at   = now(),
        org_id        = v_org
    where id = p_application_id;

    return v_org;
end;
$$;

create or replace function reject_org_application(
    p_application_id uuid,
    p_note           text
)
returns uuid
language plpgsql
security definer
set search_path = public, auth
as $$
declare
    v_actor uuid := auth.uid();
begin
    if v_actor is null then
        raise exception 'reject_org_application() needs a signed-in caller';
    end if;

    if not exists (select 1 from profiles where id = v_actor and is_platform_admin) then
        raise exception 'Only a platform admin can decide an application';
    end if;

    -- A rejection with no reason is one the applicant cannot act on, so they
    -- apply again with the same details and the queue grows.
    if nullif(btrim(coalesce(p_note, '')), '') is null then
        raise exception 'Say why, so they can fix it and apply again';
    end if;

    update org_applications set
        status        = 'rejected',
        decision_note = btrim(p_note),
        reviewed_by   = v_actor,
        reviewed_at   = now()
    where id = p_application_id and status = 'pending';

    if not found then
        raise exception 'No pending application with that id';
    end if;

    return p_application_id;
end;
$$;

-- The queue, and one person's own application. Security definer with an
-- explicit check, because a summary observer of some unrelated business must
-- not be able to read the platform's pipeline through a policy gap.
create or replace function pending_org_applications()
returns table (
    id            uuid,
    applicant_id  uuid,
    applicant     text,
    name          text,
    slug          text,
    profile       text,
    currency      text,
    contact_phone text,
    contact_email text,
    description   text,
    created_at    timestamptz
)
language plpgsql
stable
security definer
set search_path = public, auth
as $$
begin
    -- `pr.id`, not `id`: this function has an OUT column called `id`, and an
    -- unqualified one inside the body is the variable rather than the column.
    -- Postgres says so — "It could refer to either a PL/pgSQL variable or a
    -- table column" — but only at call time, so an unqualified reference here
    -- ships and fails in front of somebody.
    if not exists (
        select 1 from profiles pr where pr.id = auth.uid() and pr.is_platform_admin
    ) then
        raise exception 'Only a platform admin can read the applications';
    end if;

    return query
    select a.id, a.applicant_id, coalesce(a.contact_name, p.full_name),
           a.name, a.slug, a.profile, a.currency,
           a.contact_phone, a.contact_email, a.description, a.created_at
    from org_applications a
    left join profiles p on p.id = a.applicant_id
    where a.status = 'pending'
    order by a.created_at;
end;
$$;

-- What the applicant sees while they wait, and after. Their own row only.
--
-- Security definer, and not for reach: the `authenticated` role has no rights
-- in the auth schema, so an invoker function calling `auth.uid()` in its own
-- body fails with "permission denied for schema auth". (A policy may do it —
-- the quals are evaluated differently — which is why the select policy above
-- can.) The filter is the same one the policy makes, so definer grants
-- nothing the policy would not.
create or replace function my_org_application()
returns table (
    id            uuid,
    name          text,
    slug          text,
    profile       text,
    status        text,
    decision_note text,
    created_at    timestamptz,
    reviewed_at   timestamptz,
    org_id        uuid
)
language sql
stable
security definer
set search_path = public, auth
as $$
    select a.id, a.name, a.slug, a.profile, a.status, a.decision_note,
           a.created_at, a.reviewed_at, a.org_id
    from org_applications a
    where a.applicant_id = auth.uid()
    order by a.created_at desc
    limit 1;
$$;

-- ------------------------------------------------------------
-- 4. GRANTS
-- ------------------------------------------------------------
revoke execute on function save_my_profile(text, text, text, date, text, text) from public;
revoke execute on function invite_employee(uuid, role_name, text, text, text, text, int, text) from public;
revoke execute on function apply_for_org(text, text, text, text, text, text, text) from public;
revoke execute on function approve_org_application(uuid, text) from public;
revoke execute on function reject_org_application(uuid, text) from public;
revoke execute on function pending_org_applications() from public;

-- `authenticated` is a Supabase role and does not exist on a bare Postgres,
-- which is what CI starts from. Roles are cluster-wide, so a developer whose
-- cluster has ever run a suite already has it and cannot reproduce the
-- failure by making a fresh database — which is how 013 shipped this wrong.
do $$
begin
    if exists (select 1 from pg_roles where rolname = 'authenticated') then
        grant execute on function save_my_profile(text, text, text, date, text, text) to authenticated;
        grant execute on function profile_is_complete(uuid) to authenticated;
        grant execute on function invite_employee(uuid, role_name, text, text, text, text, int, text) to authenticated;
        grant execute on function apply_for_org(text, text, text, text, text, text, text) to authenticated;
        grant execute on function approve_org_application(uuid, text) to authenticated;
        grant execute on function reject_org_application(uuid, text) to authenticated;
        grant execute on function pending_org_applications() to authenticated;
        grant execute on function my_org_application() to authenticated;
        grant select, insert on org_applications to authenticated;
        grant update on org_applications to authenticated;
    end if;
end $$;

notify pgrst, 'reload schema';


-- ============================================================
-- 018_employment.sql
-- ============================================================
-- ============================================================
-- 018_employment.sql — staff management that a church and a farm can use too.
--
-- 012 built a payroll for a shop: a name, a rate, hours worked, money paid.
-- That is the right core and it is not staff management. Four things were
-- missing that any business with more than two people needs, and none of them
-- are shop things:
--
--   1. **Where somebody works.** A church with three campuses and a farm with
--      two sites both need to know which one a person belongs to. The scope
--      machinery for this has existed since 004 — entities and departments —
--      and `employees` did not use it.
--   2. **What kind of engagement it is.** 012 has `permanent | casual`, which
--      is a pay model rather than a contract. A volunteer at a church is
--      neither, and recording them as a casual on zero francs an hour makes
--      the payroll say something untrue about what the church owes.
--   3. **Why somebody left.** `ended_on` said when and never why, so a person
--      who resigned and a person who was dismissed read the same a year
--      later, which is exactly when it matters.
--   4. **The link to their account.** `user_id` existed and nothing ever set
--      it, so the person on the payroll and the person holding the phone were
--      two unconnected records with the same name.
--
-- One decision worth stating: **the directory is not the permission system.**
-- Adding somebody as an employee still grants nothing — that is `memberships`
-- and an invitation code, as it has always been — and linking an employee to
-- an account does not change what the account may do. A payroll that could
-- hand out access would make every bookkeeper an administrator.
-- ============================================================

-- ------------------------------------------------------------
-- 1. THE ENGAGEMENT
-- ------------------------------------------------------------

alter table employees add column if not exists entity_id     uuid;
alter table employees add column if not exists department_id uuid;
alter table employees add column if not exists employment    text;
alter table employees add column if not exists end_reason    text;
alter table employees add column if not exists national_id   text;
alter table employees add column if not exists emergency_contact text;
alter table employees add column if not exists emergency_phone   text;
alter table employees add column if not exists notes         text;

do $$
begin
    if not exists (select 1 from pg_constraint where conname = 'employees_entity_fkey') then
        alter table employees add constraint employees_entity_fkey
            foreign key (entity_id) references entities(id) on delete set null;
    end if;
    if not exists (select 1 from pg_constraint where conname = 'employees_department_fkey') then
        alter table employees add constraint employees_department_fkey
            foreign key (department_id) references departments(id) on delete set null;
    end if;

    -- The kinds of engagement a business here actually has. `volunteer` is
    -- the one that matters most for a church: somebody who works and is not
    -- paid is not a casual on zero francs, and the payroll must not imply a
    -- debt to them.
    if not exists (select 1 from pg_constraint where conname = 'employees_employment_kind') then
        alter table employees add constraint employees_employment_kind
            check (employment is null or employment in
                ('permanent', 'fixed_term', 'daily', 'apprentice', 'volunteer'));
    end if;

    if not exists (select 1 from pg_constraint where conname = 'employees_end_reason_kind') then
        alter table employees add constraint employees_end_reason_kind
            check (end_reason is null or end_reason in
                ('resigned', 'dismissed', 'contract_ended', 'retired', 'other'));
    end if;
end $$;

comment on column employees.employment is
    'The engagement: permanent, fixed_term, daily, apprentice, volunteer. Distinct from `kind`, which is how they are paid.';
comment on column employees.end_reason is
    'Why they left. ended_on alone makes a resignation and a dismissal read identically a year later.';
comment on column employees.national_id is
    'CNIB or passport number. Needed on a contract; nullable because most casual work here has no paperwork.';

-- Everything already recorded is a paid engagement of one of the two 012
-- shapes, so it can be filled in rather than left null.
update employees
   set employment = case when kind = 'permanent' then 'permanent' else 'daily' end
 where employment is null;

create index if not exists employees_by_entity
    on employees (org_id, entity_id) where entity_id is not null;

-- One account is one person. Without this, two employee rows can point at the
-- same profile and "who am I on this payroll" has two answers.
create unique index if not exists employees_one_per_account
    on employees (org_id, user_id) where user_id is not null;

-- ------------------------------------------------------------
-- 2. HIRING, MOVING, AND LEAVING
-- ------------------------------------------------------------

-- Everything about somebody that an admin may change. Null leaves a field
-- alone: a screen that saves one field must not blank the other ten.
create or replace function update_employee(
    p_employee_id  uuid,
    p_full_name    text default null,
    p_phone        text default null,
    p_role_title   text default null,
    p_employment   text default null,
    p_kind         text default null,
    p_salary       numeric default null,
    p_hourly_rate  numeric default null,
    p_entity_id    uuid default null,
    p_department_id uuid default null,
    p_national_id  text default null,
    p_emergency_contact text default null,
    p_emergency_phone   text default null,
    p_notes        text default null,
    p_started_on   date default null
)
returns uuid
language plpgsql
security definer
set search_path = public, auth
as $$
declare
    v_actor  uuid := auth.uid();
    v_org_id uuid;
begin
    if v_actor is null then
        raise exception 'update_employee() needs a signed-in caller';
    end if;

    select org_id into v_org_id from employees where id = p_employee_id;
    if not found then
        raise exception 'No such employee';
    end if;

    -- Org admin, like everything else about wages: what a colleague earns is
    -- the most sensitive number in a small business.
    if not is_org_admin(v_org_id) then
        raise exception 'You cannot change staff records in this business';
    end if;

    -- A site or a department belonging to another business would put somebody
    -- on a payroll in one org and a location in another.
    if p_entity_id is not null and not exists (
        select 1 from entities where id = p_entity_id and org_id = v_org_id
    ) then
        raise exception 'That site belongs to another business';
    end if;

    if p_department_id is not null and not exists (
        select 1 from departments d
        join entities e on e.id = d.entity_id
        where d.id = p_department_id and e.org_id = v_org_id
    ) then
        raise exception 'That department belongs to another business';
    end if;

    update employees set
        full_name     = coalesce(nullif(btrim(coalesce(p_full_name, '')), ''), full_name),
        phone         = coalesce(nullif(btrim(coalesce(p_phone, '')), ''), phone),
        role_title    = coalesce(nullif(btrim(coalesce(p_role_title, '')), ''), role_title),
        employment    = coalesce(nullif(btrim(coalesce(p_employment, '')), ''), employment),
        kind          = coalesce(nullif(btrim(coalesce(p_kind, '')), ''), kind),
        salary        = coalesce(p_salary, salary),
        hourly_rate   = coalesce(p_hourly_rate, hourly_rate),
        entity_id     = coalesce(p_entity_id, entity_id),
        department_id = coalesce(p_department_id, department_id),
        national_id   = coalesce(nullif(btrim(coalesce(p_national_id, '')), ''), national_id),
        emergency_contact = coalesce(nullif(btrim(coalesce(p_emergency_contact, '')), ''), emergency_contact),
        emergency_phone   = coalesce(nullif(btrim(coalesce(p_emergency_phone, '')), ''), emergency_phone),
        notes         = coalesce(nullif(btrim(coalesce(p_notes, '')), ''), notes),
        started_on    = coalesce(p_started_on, started_on)
    where id = p_employee_id;

    return p_employee_id;
end;
$$;

-- Somebody leaving. Not a deletion: they worked here, they were paid, and
-- both of those are history. `unpaid_shifts` still owes them what it owed
-- them, which is the point of ending an engagement rather than removing it.
create or replace function end_employment(
    p_employee_id uuid,
    p_reason      text,
    p_ended_on    date default current_date,
    p_note        text default null
)
returns uuid
language plpgsql
security definer
set search_path = public, auth
as $$
declare
    v_actor  uuid := auth.uid();
    v_org_id uuid;
    v_owed   numeric;
begin
    if v_actor is null then
        raise exception 'end_employment() needs a signed-in caller';
    end if;

    select org_id into v_org_id from employees where id = p_employee_id;
    if not found then
        raise exception 'No such employee';
    end if;

    if not is_org_admin(v_org_id) then
        raise exception 'You cannot change staff records in this business';
    end if;

    if p_reason is null or p_reason not in
       ('resigned', 'dismissed', 'contract_ended', 'retired', 'other') then
        raise exception 'Say why they left: resigned, dismissed, contract_ended, retired or other';
    end if;

    -- Refused while money is owed, and this is the assertion that earns the
    -- function. Marking somebody inactive takes them off the payroll screen,
    -- and unpaid hours that vanish from the screen are unpaid hours nobody
    -- pays. Pay them, then close it.
    select coalesce(sum(owed), 0) into v_owed
    from unpaid_shifts(v_org_id) where employee_id = p_employee_id;

    if v_owed > 0 then
        raise exception
            'Pay what is owed first: % remains unpaid', v_owed;
    end if;

    update employees set
        ended_on   = coalesce(p_ended_on, current_date),
        end_reason = p_reason,
        is_active  = false,
        notes      = coalesce(nullif(btrim(coalesce(p_note, '')), ''), notes)
    where id = p_employee_id;

    return p_employee_id;
end;
$$;

-- Connecting somebody on the payroll to the account they sign in with.
--
-- Deliberately one-directional and deliberately grants nothing: this says
-- "the Awa on the payroll is the Awa holding this phone", and says nothing
-- about what she may do. Access is `memberships`, and it comes from an
-- invitation code as it always has.
create or replace function link_employee_account(
    p_employee_id uuid,
    p_user_id     uuid
)
returns uuid
language plpgsql
security definer
set search_path = public, auth
as $$
declare
    v_actor  uuid := auth.uid();
    v_org_id uuid;
begin
    if v_actor is null then
        raise exception 'link_employee_account() needs a signed-in caller';
    end if;

    select org_id into v_org_id from employees where id = p_employee_id;
    if not found then
        raise exception 'No such employee';
    end if;

    if not is_org_admin(v_org_id) then
        raise exception 'You cannot change staff records in this business';
    end if;

    -- Only somebody who is already a member. Linking an arbitrary account
    -- would let an admin attach a stranger's profile to their payroll and
    -- read their name and number out of it.
    if p_user_id is not null and not exists (
        select 1 from memberships where org_id = v_org_id and user_id = p_user_id
    ) then
        raise exception 'That person is not a member of this business';
    end if;

    update employees set user_id = p_user_id where id = p_employee_id;
    return p_employee_id;
end;
$$;

-- ------------------------------------------------------------
-- 3. THE DIRECTORY
-- ------------------------------------------------------------
-- One read for the staff screen: who is here, where they work, what they are
-- owed, and whether they hold an account.
--
-- Security definer with an explicit admin check, matching 012's policies:
-- reading a payroll needs an org admin, not mere membership.
create or replace function staff_directory(
    p_org_id      uuid,
    p_include_past boolean default false
)
returns table (
    id            uuid,
    full_name     text,
    phone         text,
    role_title    text,
    employment    text,
    kind          text,
    salary        numeric,
    hourly_rate   numeric,
    entity_id     uuid,
    entity_name   text,
    department_id uuid,
    department_name text,
    started_on    date,
    ended_on      date,
    end_reason    text,
    is_active     boolean,
    user_id       uuid,
    account_name  text,
    unpaid_hours  numeric,
    owed          numeric
)
language plpgsql
stable
security definer
set search_path = public, auth
as $$
begin
    if not is_org_admin(p_org_id) then
        raise exception 'You cannot read the staff of this business';
    end if;

    return query
    select e.id, e.full_name, e.phone, e.role_title, e.employment, e.kind,
           e.salary, e.hourly_rate,
           e.entity_id, en.name, e.department_id, d.name,
           e.started_on, e.ended_on, e.end_reason, e.is_active,
           e.user_id, pr.full_name,
           coalesce(u.hours, 0), coalesce(u.owed, 0)
    from employees e
    left join entities    en on en.id = e.entity_id
    left join departments d  on d.id  = e.department_id
    left join profiles    pr on pr.id = e.user_id
    left join (
        select s.employee_id,
               sum(s.hours) as hours,
               sum(s.hours * emp.hourly_rate) as owed
        from shifts s
        join employees emp on emp.id = s.employee_id
        where s.org_id = p_org_id and s.payment_id is null
        group by s.employee_id
    ) u on u.employee_id = e.id
    where e.org_id = p_org_id
      and (coalesce(p_include_past, false) or e.is_active)
    order by e.is_active desc, e.full_name;
end;
$$;

-- What the business owes and pays, per month, for a payroll register — the
-- one report an accountant asks for and 012 had no answer to.
create or replace function payroll_summary(
    p_org_id uuid,
    p_from   date default null,
    p_to     date default null
)
returns table (
    employee_id  uuid,
    full_name    text,
    employment   text,
    payments     int,
    paid         numeric,
    hours        numeric
)
language plpgsql
stable
security definer
set search_path = public, auth
as $$
begin
    if not is_org_admin(p_org_id) then
        raise exception 'You cannot read the payroll of this business';
    end if;

    return query
    select e.id, e.full_name, e.employment,
           count(sp.id)::int,
           coalesce(sum(sp.amount), 0),
           coalesce((
               select sum(s.hours) from shifts s
               where s.employee_id = e.id
                 and (p_from is null or s.worked_on >= p_from)
                 and (p_to   is null or s.worked_on <= p_to)
           ), 0)
    from employees e
    left join staff_payments sp
           on sp.employee_id = e.id
          and (p_from is null or sp.paid_on >= p_from)
          and (p_to   is null or sp.paid_on <= p_to)
    where e.org_id = p_org_id
    group by e.id, e.full_name, e.employment
    order by e.full_name;
end;
$$;

-- ------------------------------------------------------------
-- 4. GRANTS
-- ------------------------------------------------------------
revoke execute on function update_employee(uuid, text, text, text, text, text, numeric, numeric, uuid, uuid, text, text, text, text, date) from public;
revoke execute on function end_employment(uuid, text, date, text) from public;
revoke execute on function link_employee_account(uuid, uuid) from public;
revoke execute on function staff_directory(uuid, boolean) from public;
revoke execute on function payroll_summary(uuid, date, date) from public;

do $$
begin
    if exists (select 1 from pg_roles where rolname = 'authenticated') then
        grant execute on function update_employee(uuid, text, text, text, text, text, numeric, numeric, uuid, uuid, text, text, text, text, date) to authenticated;
        grant execute on function end_employment(uuid, text, date, text) to authenticated;
        grant execute on function link_employee_account(uuid, uuid) to authenticated;
        grant execute on function staff_directory(uuid, boolean) to authenticated;
        grant execute on function payroll_summary(uuid, date, date) to authenticated;
    end if;
end $$;

notify pgrst, 'reload schema';


-- ============================================================
-- 019_farm_general.sql
-- ============================================================
-- ============================================================
-- 019_farm_general.sql — a farm that is not only chickens.
--
-- 009 built one farm: Ignace's, which is poultry. `flocks` counts birds,
-- `egg_production` counts eggs, and the home screen leads with both. Every
-- other farm in the country is at best half-served — a herd of goats has no
-- table, a field of onions has no table, and a farmer with both is expected
-- to record their harvest as "other income" and their animals as a flock with
-- a batch code.
--
-- What is added, and what is deliberately not.
--
-- **Herds, not just flocks.** `herds` is what `flocks` should have been: a
-- group of animals of any species, counted, with the same arrival and closing
-- shape. `flocks` is not touched and not migrated — Ignace's history is in
-- it, `flock_status()` reads it, and rewriting a working module to make a
-- name tidier is how live data gets lost. A poultry farm keeps using flocks;
-- everyone else uses herds; the home screen shows whichever a farm has.
--
-- **Crop cycles, because a field is a period and not a thing.** The same plot
-- grows onions from October and maize from June, and asking what a plot
-- produced without asking when is a question with no answer. So the unit of
-- record is one planting: a crop, a plot, a date in, a date expected out.
--
-- **Harvests, weighed and then sold separately.** Bringing a crop in and
-- selling it are two events that happen days apart, and a module that
-- conflates them either books income the farmer has not received or loses the
-- harvest entirely when it is eaten at home. So `harvests` records what came
-- off the field, and selling is `record_farm_sale()` from 009 as it already
-- was.
--
-- **Animal events, reusing the shape that works.** 009's `flock_events`
-- handles mortality, weight and vaccination for birds. `herd_events` is the
-- same three things for anything else, plus births — which poultry does not
-- have and every other animal does.
--
-- What is not here: feed rations per species, milk yields per animal,
-- veterinary schedules, and anything that needs a farmer to tell us how they
-- actually work. Those are the next conversation, not a guess.
-- ============================================================

-- ------------------------------------------------------------
-- 1. ANIMALS OF ANY KIND
-- ------------------------------------------------------------

create table if not exists herds (
    id          uuid primary key default gen_random_uuid(),
    org_id      uuid not null references orgs(id) on delete cascade,
    entity_id   uuid references entities(id) on delete set null,

    -- Free text, on purpose. A list of species compiled into this file is a
    -- list that is wrong for the first farmer with guinea fowl, and the same
    -- argument that opened up account names in 007 applies here.
    species     text not null,
    label       text not null,
    breed       text,

    head_count  int not null check (head_count >= 0),
    arrived_on  date not null default current_date,
    closed_on   date,

    -- What this group is for. Drives nothing in the schema and is worth
    -- recording anyway: a dairy herd and a herd being fattened for Tabaski
    -- are managed differently and the farmer knows which is which.
    purpose     text,

    created_at  timestamptz not null default now(),
    created_by  uuid references profiles(id),
    unique (org_id, label)
);

comment on table herds is
    'A group of animals of any species. `flocks` (009) is the poultry-specific ancestor and is left alone: Ignace''s history is in it.';

create index if not exists herds_open on herds (org_id) where closed_on is null;

create table if not exists herd_events (
    id          uuid primary key default gen_random_uuid(),
    org_id      uuid not null references orgs(id) on delete cascade,
    herd_id     uuid not null references herds(id) on delete cascade,

    -- birth is the one 009 has no equivalent for: a flock arrives and never
    -- grows by itself, and a herd does.
    kind        text not null check (kind in
                ('mortality', 'birth', 'weight', 'vaccination', 'treatment', 'sold')),
    occurred_on date not null default current_date,

    -- Head for mortality, birth and sold; kilograms for a weight sample;
    -- ignored for a vaccination.
    quantity    numeric(14,3) not null default 0 check (quantity >= 0),
    note        text,

    created_at  timestamptz not null default now(),
    created_by  uuid references profiles(id),
    device_id   text,
    client_uuid uuid
);

create unique index if not exists herd_events_by_client_uuid
    on herd_events (org_id, client_uuid) where client_uuid is not null;

create index if not exists herd_events_by_date
    on herd_events (org_id, occurred_on desc);

-- ------------------------------------------------------------
-- 2. WHAT GROWS IN THE GROUND
-- ------------------------------------------------------------

create table if not exists plots (
    id         uuid primary key default gen_random_uuid(),
    org_id     uuid not null references orgs(id) on delete cascade,
    entity_id  uuid references entities(id) on delete set null,
    name       text not null,
    area       numeric(12,3),
    -- 'ha' | 'm2' — recorded rather than assumed, because a market gardener
    -- thinks in square metres and a maize farmer in hectares.
    area_unit  text not null default 'ha',
    note       text,
    created_at timestamptz not null default now(),
    created_by uuid references profiles(id),
    unique (org_id, name)
);

-- One planting. The unit of record is a period on a plot, not the plot
-- itself: the same field grows onions from October and maize from June, and
-- "what did this field produce" is unanswerable without a when.
create table if not exists crop_cycles (
    id            uuid primary key default gen_random_uuid(),
    org_id        uuid not null references orgs(id) on delete cascade,
    plot_id       uuid references plots(id) on delete set null,

    crop          text not null,
    variety       text,
    planted_on    date not null default current_date,
    expected_on   date,
    closed_on     date,

    -- What the farmer hopes for, in the unit they will actually harvest in.
    expected_yield numeric(14,3),
    unit          text not null default 'kg',

    note          text,
    created_at    timestamptz not null default now(),
    created_by    uuid references profiles(id)
);

create index if not exists crop_cycles_open
    on crop_cycles (org_id, expected_on) where closed_on is null;

-- What actually came off the field. Separate from selling it, which happens
-- days later and sometimes never — a sack eaten at home is still a harvest,
-- and a module that only counts what was sold cannot tell a farmer their
-- yield.
create table if not exists harvests (
    id            uuid primary key default gen_random_uuid(),
    org_id        uuid not null references orgs(id) on delete cascade,
    crop_cycle_id uuid references crop_cycles(id) on delete set null,

    harvested_on  date not null default current_date,
    quantity      numeric(14,3) not null check (quantity > 0),
    unit          text not null default 'kg',
    -- 'first' | 'second' | 'damaged' — the same grading idea as eggs, and for
    -- the same reason: what is sold at full price and what is not.
    grade         text not null default 'first',
    note          text,

    created_at    timestamptz not null default now(),
    created_by    uuid references profiles(id),
    device_id     text,
    client_uuid   uuid
);

create unique index if not exists harvests_by_client_uuid
    on harvests (org_id, client_uuid) where client_uuid is not null;

create index if not exists harvests_by_date
    on harvests (org_id, harvested_on desc);

-- ------------------------------------------------------------
-- 3. RECORDING
-- ------------------------------------------------------------
-- All idempotent by client_uuid, like every other field-recorded thing in
-- this project: a phone at the far end of a field retries.

create or replace function open_herd(
    p_org_id     uuid,
    p_species    text,
    p_label      text,
    p_head_count int,
    p_breed      text default null,
    p_purpose    text default null,
    p_entity_id  uuid default null,
    p_arrived_on date default current_date
)
returns uuid
language plpgsql
security definer
set search_path = public, auth
as $$
declare
    v_actor uuid := auth.uid();
    v_id    uuid;
    v_label text := nullif(btrim(coalesce(p_label, '')), '');
begin
    if v_actor is null then
        raise exception 'open_herd() needs a signed-in caller';
    end if;
    if not can_write_org(p_org_id) then
        raise exception 'You cannot record for this business';
    end if;
    if v_label is null then
        raise exception 'A group of animals needs a name';
    end if;
    if p_head_count is null or p_head_count <= 0 then
        raise exception 'How many animals?';
    end if;

    -- Same rule as a flock's batch code: opening a group is one of the two
    -- things on a farm that needs the server, because two phones inventing
    -- the same name would split a season's figures in half.
    select id into v_id from herds
    where org_id = p_org_id and lower(btrim(label)) = lower(v_label);
    if found then
        raise exception 'A group called % already exists', v_label;
    end if;

    insert into herds (org_id, entity_id, species, label, breed, head_count,
                       purpose, arrived_on, created_by)
    values (p_org_id, p_entity_id,
            coalesce(nullif(btrim(coalesce(p_species, '')), ''), 'autre'),
            v_label,
            nullif(btrim(coalesce(p_breed, '')), ''),
            p_head_count,
            nullif(btrim(coalesce(p_purpose, '')), ''),
            coalesce(p_arrived_on, current_date), v_actor)
    returning id into v_id;

    return v_id;
end;
$$;

-- A death, a birth, a weighing, a vaccination. The head count moves for the
-- first two and stays put for the rest.
create or replace function record_herd_event(
    p_org_id      uuid,
    p_herd_id     uuid,
    p_kind        text,
    p_quantity    numeric default 0,
    p_occurred_on date default current_date,
    p_note        text default null,
    p_client_uuid uuid default null,
    p_device_id   text default null
)
returns uuid
language plpgsql
security definer
set search_path = public, auth
as $$
declare
    v_actor    uuid := auth.uid();
    v_org      uuid;
    v_head     int;
    v_existing uuid;
    v_id       uuid;
begin
    if v_actor is null then
        raise exception 'record_herd_event() needs a signed-in caller';
    end if;
    if not can_write_org(p_org_id) then
        raise exception 'You cannot record for this business';
    end if;

    if p_kind not in ('mortality', 'birth', 'weight', 'vaccination',
                      'treatment', 'sold') then
        raise exception 'Unknown event: %', p_kind;
    end if;

    if p_client_uuid is not null then
        select id into v_existing from herd_events
        where org_id = p_org_id and client_uuid = p_client_uuid;
        if found then
            return v_existing;
        end if;
    end if;

    select org_id, head_count into v_org, v_head from herds where id = p_herd_id;
    if v_org is null or v_org <> p_org_id then
        raise exception 'No such group in this business';
    end if;

    -- More animals dead or sold than there are is a typo, and left in it
    -- makes a herd's count negative and every figure after it wrong.
    if p_kind in ('mortality', 'sold') and coalesce(p_quantity, 0) > v_head then
        raise exception
            'There are only % animals in this group', v_head;
    end if;

    insert into herd_events (org_id, herd_id, kind, occurred_on, quantity,
                             note, created_by, device_id, client_uuid)
    values (p_org_id, p_herd_id, p_kind,
            coalesce(p_occurred_on, current_date),
            greatest(coalesce(p_quantity, 0), 0),
            nullif(btrim(coalesce(p_note, '')), ''),
            v_actor, p_device_id, p_client_uuid)
    returning id into v_id;

    if p_kind in ('mortality', 'sold') then
        update herds set head_count = head_count - coalesce(p_quantity, 0)
        where id = p_herd_id;
    elsif p_kind = 'birth' then
        update herds set head_count = head_count + coalesce(p_quantity, 0)
        where id = p_herd_id;
    end if;

    return v_id;
end;
$$;

create or replace function open_crop_cycle(
    p_org_id      uuid,
    p_crop        text,
    p_plot_name   text default null,
    p_variety     text default null,
    p_planted_on  date default current_date,
    p_expected_on date default null,
    p_expected_yield numeric default null,
    p_unit        text default 'kg',
    p_entity_id   uuid default null
)
returns uuid
language plpgsql
security definer
set search_path = public, auth
as $$
declare
    v_actor uuid := auth.uid();
    v_crop  text := nullif(btrim(coalesce(p_crop, '')), '');
    v_plot  text := nullif(btrim(coalesce(p_plot_name, '')), '');
    v_plot_id uuid;
    v_id    uuid;
begin
    if v_actor is null then
        raise exception 'open_crop_cycle() needs a signed-in caller';
    end if;
    if not can_write_org(p_org_id) then
        raise exception 'You cannot record for this business';
    end if;
    if v_crop is null then
        raise exception 'What is being planted?';
    end if;

    -- The plot is found or made from its name, the same bargain
    -- `ensure_account()` makes: a farmer types "Bas-fond 2" and gets the same
    -- plot every time without having had to define it first.
    if v_plot is not null then
        select id into v_plot_id from plots
        where org_id = p_org_id and lower(btrim(name)) = lower(v_plot);
        if v_plot_id is null then
            insert into plots (org_id, entity_id, name, created_by)
            values (p_org_id, p_entity_id, v_plot, v_actor)
            returning id into v_plot_id;
        end if;
    end if;

    insert into crop_cycles (org_id, plot_id, crop, variety, planted_on,
                             expected_on, expected_yield, unit, created_by)
    values (p_org_id, v_plot_id, v_crop,
            nullif(btrim(coalesce(p_variety, '')), ''),
            coalesce(p_planted_on, current_date),
            p_expected_on, p_expected_yield,
            coalesce(nullif(btrim(coalesce(p_unit, '')), ''), 'kg'),
            v_actor)
    returning id into v_id;

    return v_id;
end;
$$;

create or replace function record_harvest(
    p_org_id      uuid,
    p_crop_cycle_id uuid,
    p_quantity    numeric,
    p_unit        text default null,
    p_grade       text default 'first',
    p_harvested_on date default current_date,
    p_note        text default null,
    p_client_uuid uuid default null,
    p_device_id   text default null
)
returns uuid
language plpgsql
security definer
set search_path = public, auth
as $$
declare
    v_actor    uuid := auth.uid();
    v_org      uuid;
    v_unit     text;
    v_existing uuid;
    v_id       uuid;
begin
    if v_actor is null then
        raise exception 'record_harvest() needs a signed-in caller';
    end if;
    if not can_write_org(p_org_id) then
        raise exception 'You cannot record for this business';
    end if;
    if p_quantity is null or p_quantity <= 0 then
        raise exception 'How much was harvested?';
    end if;

    if p_client_uuid is not null then
        select id into v_existing from harvests
        where org_id = p_org_id and client_uuid = p_client_uuid;
        if found then
            return v_existing;
        end if;
    end if;

    select org_id, unit into v_org, v_unit from crop_cycles
    where id = p_crop_cycle_id;
    if v_org is null or v_org <> p_org_id then
        raise exception 'No such planting in this business';
    end if;

    -- No ledger entry. Bringing a crop in is not earning money — it is earning
    -- money later, or eating it — and booking income here would inflate the
    -- income statement by every sack that never reached a market. Selling it
    -- goes through record_farm_sale() as it already did.
    insert into harvests (org_id, crop_cycle_id, harvested_on, quantity, unit,
                          grade, note, created_by, device_id, client_uuid)
    values (p_org_id, p_crop_cycle_id,
            coalesce(p_harvested_on, current_date),
            p_quantity,
            coalesce(nullif(btrim(coalesce(p_unit, '')), ''), v_unit, 'kg'),
            coalesce(nullif(btrim(coalesce(p_grade, '')), ''), 'first'),
            nullif(btrim(coalesce(p_note, '')), ''),
            v_actor, p_device_id, p_client_uuid)
    returning id into v_id;

    return v_id;
end;
$$;

-- ------------------------------------------------------------
-- 4. READING IT BACK
-- ------------------------------------------------------------

create or replace function herd_status(p_org_id uuid, p_include_closed boolean default false)
returns table (
    id          uuid,
    species     text,
    label       text,
    breed       text,
    purpose     text,
    head_count  int,
    arrived_on  date,
    closed_on   date,
    losses      numeric,
    births      numeric,
    last_event  date
)
language sql
stable
security invoker
set search_path = public
as $$
    select h.id, h.species, h.label, h.breed, h.purpose, h.head_count,
           h.arrived_on, h.closed_on,
           coalesce((select sum(e.quantity) from herd_events e
                     where e.herd_id = h.id and e.kind = 'mortality'), 0),
           coalesce((select sum(e.quantity) from herd_events e
                     where e.herd_id = h.id and e.kind = 'birth'), 0),
           (select max(e.occurred_on) from herd_events e where e.herd_id = h.id)
    from herds h
    where h.org_id = p_org_id
      and (coalesce(p_include_closed, false) or h.closed_on is null)
    order by h.closed_on nulls first, h.label;
$$;

create or replace function crop_status(p_org_id uuid, p_include_closed boolean default false)
returns table (
    id             uuid,
    crop           text,
    variety        text,
    plot_name      text,
    planted_on     date,
    expected_on    date,
    closed_on      date,
    expected_yield numeric,
    unit           text,
    harvested      numeric,
    days_to_harvest int
)
language sql
stable
security invoker
set search_path = public
as $$
    select c.id, c.crop, c.variety, p.name, c.planted_on, c.expected_on,
           c.closed_on, c.expected_yield, c.unit,
           coalesce((select sum(h.quantity) from harvests h
                     where h.crop_cycle_id = c.id), 0),
           case when c.expected_on is null then null
                else (c.expected_on - current_date) end
    from crop_cycles c
    left join plots p on p.id = c.plot_id
    where c.org_id = p_org_id
      and (coalesce(p_include_closed, false) or c.closed_on is null)
    order by c.closed_on nulls first, c.expected_on nulls last, c.crop;
$$;

-- What this farm is, as a farm rather than as a set of tables. The home
-- screen asks this first and shows whichever sections have anything in them,
-- so a poultry farm still opens on birds and eggs and a market gardener does
-- not have to look at an empty flock panel.
create or replace function farm_profile_summary(p_org_id uuid)
returns table (
    flocks        int,
    birds         int,
    herds         int,
    animals       int,
    crop_cycles   int,
    plots         int,
    eggs_today    int,
    harvest_7days numeric
)
language sql
stable
security invoker
set search_path = public
as $$
    select
        (select count(*)::int from flocks f
          where f.org_id = p_org_id and f.closed_on is null),
        (select coalesce(sum(f.bird_count), 0)::int from flocks f
          where f.org_id = p_org_id and f.closed_on is null),
        (select count(*)::int from herds h
          where h.org_id = p_org_id and h.closed_on is null),
        (select coalesce(sum(h.head_count), 0)::int from herds h
          where h.org_id = p_org_id and h.closed_on is null),
        (select count(*)::int from crop_cycles c
          where c.org_id = p_org_id and c.closed_on is null),
        (select count(*)::int from plots p where p.org_id = p_org_id),
        (select coalesce(sum(e.egg_count), 0)::int from egg_production e
          where e.org_id = p_org_id and e.produced_on = current_date),
        (select coalesce(sum(h.quantity), 0) from harvests h
          where h.org_id = p_org_id
            and h.harvested_on >= current_date - 7);
$$;

-- ------------------------------------------------------------
-- 5. RLS
-- ------------------------------------------------------------
-- The same shape 009 gives its own tables: counts are readable to members,
-- the events behind them need full visibility, and writing needs a
-- non-observer.

alter table herds        enable row level security;
alter table herd_events  enable row level security;
alter table plots        enable row level security;
alter table crop_cycles  enable row level security;
alter table harvests     enable row level security;

drop policy if exists "herds readable within org" on herds;
create policy "herds readable within org"
on herds for select using (is_org_member(org_id));

drop policy if exists "herds managed by non-observers" on herds;
create policy "herds managed by non-observers"
on herds for insert with check (can_write_org(org_id));

drop policy if exists "herds amended by non-observers" on herds;
create policy "herds amended by non-observers"
on herds for update using (can_write_org(org_id)) with check (can_write_org(org_id));

drop policy if exists "herd events readable with full visibility" on herd_events;
create policy "herd events readable with full visibility"
on herd_events for select using (has_full_visibility(org_id));

drop policy if exists "herd events written by non-observers" on herd_events;
create policy "herd events written by non-observers"
on herd_events for insert with check (can_write_org(org_id));

drop policy if exists "plots readable within org" on plots;
create policy "plots readable within org"
on plots for select using (is_org_member(org_id));

drop policy if exists "plots managed by non-observers" on plots;
create policy "plots managed by non-observers"
on plots for insert with check (can_write_org(org_id));

drop policy if exists "plots amended by non-observers" on plots;
create policy "plots amended by non-observers"
on plots for update using (can_write_org(org_id)) with check (can_write_org(org_id));

drop policy if exists "crop cycles readable within org" on crop_cycles;
create policy "crop cycles readable within org"
on crop_cycles for select using (is_org_member(org_id));

drop policy if exists "crop cycles managed by non-observers" on crop_cycles;
create policy "crop cycles managed by non-observers"
on crop_cycles for insert with check (can_write_org(org_id));

drop policy if exists "crop cycles amended by non-observers" on crop_cycles;
create policy "crop cycles amended by non-observers"
on crop_cycles for update using (can_write_org(org_id)) with check (can_write_org(org_id));

drop policy if exists "harvests readable with full visibility" on harvests;
create policy "harvests readable with full visibility"
on harvests for select using (has_full_visibility(org_id));

drop policy if exists "harvests written by non-observers" on harvests;
create policy "harvests written by non-observers"
on harvests for insert with check (can_write_org(org_id));

-- ------------------------------------------------------------
-- 6. A FARM'S CHART, WIDENED
-- ------------------------------------------------------------
-- 009 seeds "Ventes d'œufs" and "Ventes de volailles" and stops. A farm with
-- goats and onions has nowhere sensible to post either, so it posts to
-- "Autres ventes" and the income statement says nothing useful.
create or replace function seed_farm_accounts(p_org_id uuid)
returns void
language plpgsql
as $$
begin
    insert into accounts (org_id, code, name, type) values
        (p_org_id, '1000', 'Cash on Hand',        'asset'),
        (p_org_id, '1010', 'Bank Account',        'asset'),
        (p_org_id, '1020', 'Mobile Money',        'asset'),
        (p_org_id, '1300', 'Créances clients',    'asset'),
        (p_org_id, '4100', 'Ventes d''œufs',      'income'),
        (p_org_id, '4110', 'Ventes de volailles', 'income'),
        (p_org_id, '4130', 'Ventes de bétail',    'income'),
        (p_org_id, '4140', 'Ventes de récoltes',  'income'),
        (p_org_id, '4150', 'Ventes de lait',      'income'),
        (p_org_id, '4120', 'Autres ventes',       'income'),
        (p_org_id, '5100', 'Aliment',             'expense'),
        (p_org_id, '5110', 'Vétérinaire',         'expense'),
        (p_org_id, '5120', 'Main-d''œuvre',       'expense'),
        (p_org_id, '5140', 'Semences',            'expense'),
        (p_org_id, '5150', 'Engrais et traitements', 'expense'),
        (p_org_id, '5130', 'Fournitures ferme',   'expense')
    on conflict (org_id, code) do nothing;
end;
$$;

-- Existing farms get the new accounts too, rather than only farms created
-- from now on. Idempotent, so a farm that already has them is untouched.
do $$
declare
    v_org uuid;
begin
    for v_org in select id from orgs where profile = 'farm' loop
        perform seed_farm_accounts(v_org);
    end loop;
end $$;

-- ------------------------------------------------------------
-- 7. GRANTS
-- ------------------------------------------------------------
revoke execute on function open_herd(uuid, text, text, int, text, text, uuid, date) from public;
revoke execute on function record_herd_event(uuid, uuid, text, numeric, date, text, uuid, text) from public;
revoke execute on function open_crop_cycle(uuid, text, text, text, date, date, numeric, text, uuid) from public;
revoke execute on function record_harvest(uuid, uuid, numeric, text, text, date, text, uuid, text) from public;

do $$
begin
    if exists (select 1 from pg_roles where rolname = 'authenticated') then
        grant execute on function open_herd(uuid, text, text, int, text, text, uuid, date) to authenticated;
        grant execute on function record_herd_event(uuid, uuid, text, numeric, date, text, uuid, text) to authenticated;
        grant execute on function open_crop_cycle(uuid, text, text, text, date, date, numeric, text, uuid) to authenticated;
        grant execute on function record_harvest(uuid, uuid, numeric, text, text, date, text, uuid, text) to authenticated;
        grant execute on function herd_status(uuid, boolean) to authenticated;
        grant execute on function crop_status(uuid, boolean) to authenticated;
        grant execute on function farm_profile_summary(uuid) to authenticated;
        grant select, insert, update on herds to authenticated;
        grant select, insert on herd_events to authenticated;
        grant select, insert, update on plots to authenticated;
        grant select, insert, update on crop_cycles to authenticated;
        grant select, insert on harvests to authenticated;
    end if;
end $$;

notify pgrst, 'reload schema';


-- ============================================================
-- 020_invoicing.sql
-- ============================================================
-- ============================================================
-- 020 — INVOICING FOR EVERY BUSINESS
-- ============================================================
-- The invoice tables have existed since 009. They were built inside the farm
-- migration for Ignace selling trays to a hotel, and everything about the way
-- they were reached said "farm": the only screen that opened them was the
-- farm's, and `create_invoice()` defaulted its income category to
-- "Ventes d'œufs".
--
-- None of that was ever true of the tables themselves. `invoices` is org
-- scoped, `create_invoice()` checks `can_write_org()` and nothing else, and a
-- shop invoicing a wholesaler or a church invoicing a hall hire is the same
-- three rows. So this migration does not build invoicing — it stops invoicing
-- from being farm-shaped, and adds the three things a business needs before it
-- can send one of these to an actual customer.
--
-- 1. A BILLING HEADER. An invoice has to say who is billing, and `orgs` held
--    a name and nothing else. No address, no telephone, no tax number — which
--    in Burkina Faso means no IFU, and an invoice without an IFU is not a
--    document a business customer can put in their own books.
--
-- 2. A DOCUMENT TO SEND. `outstanding_invoices()` answers "who has not paid",
--    which is the collections question. Nothing answered "what does invoice
--    2026-0007 actually say", which is the question you need to answer to put
--    it in somebody's hand.
--
-- 3. NUMBERING THAT SURVIVES TWO PEOPLE. See section 3 — the old scheme was
--    `count(*) + 1`, and it has a race in it that produces a hard failure the
--    first time a business is busy enough to have two people invoicing at
--    once. That is a production bug, not a tidiness one, and it is fixed here.
--
-- Also added: cancelling. `invoices.cancelled_at` has existed since 009 and
-- nothing has ever set it, so an invoice raised for the wrong customer or the
-- wrong amount could be neither corrected nor withdrawn — the receivable
-- simply stayed on the books for ever.

-- ------------------------------------------------------------
-- 1. WHO IS BILLING
-- ------------------------------------------------------------
-- On `orgs` rather than a separate table: there is exactly one of these per
-- business, it is read on every invoice, and a second table would be a join
-- that is never optional.
--
-- Every column is nullable. A business that has not filled these in still
-- invoices — the header simply carries less — because refusing to invoice
-- until a form is complete is how an app stops somebody trading.
alter table orgs add column if not exists address     text;
alter table orgs add column if not exists phone       text;
alter table orgs add column if not exists email       text;

-- IFU in Burkina Faso, NIF elsewhere in the region, VAT number in Europe.
-- Deliberately one free-text field rather than a column per jurisdiction:
-- what goes on the invoice is a label and a number, and which label is
-- correct is the accountant's business, not the schema's.
alter table orgs add column if not exists tax_id      text;
alter table orgs add column if not exists tax_label   text;

-- What the business wants written at the bottom of every invoice: payment
-- terms, a mobile-money number, "merci de votre confiance".
alter table orgs add column if not exists invoice_footer text;

-- An invoice is addressed to somebody. 009 stored a customer's name and phone,
-- which is enough to chase a debt and not enough to head a document.
--
-- Added here rather than further down because a `language sql` function body
-- is parsed when it is created: invoice_header() selects c.address, so the
-- column has to exist before that definition is reached.
alter table customers add column if not exists address text;

create or replace function set_org_billing(
    p_org_id         uuid,
    p_address        text default null,
    p_phone          text default null,
    p_email          text default null,
    p_tax_id         text default null,
    p_tax_label      text default null,
    p_invoice_footer text default null
)
returns void
language plpgsql
security definer
set search_path = public, auth
as $$
declare
    v_actor uuid := auth.uid();
begin
    if v_actor is null then
        raise exception 'set_org_billing() needs a signed-in caller';
    end if;
    -- An admin, not merely a writer. What is on the header is what the
    -- business is claiming about itself to a customer and to a tax office;
    -- that is not a thing for whoever happens to be raising the invoice.
    if not is_org_admin(p_org_id) then
        raise exception 'Only an administrator can change the billing details';
    end if;

    update orgs
       set address        = nullif(btrim(coalesce(p_address, address, '')), ''),
           phone          = nullif(btrim(coalesce(p_phone, phone, '')), ''),
           email          = nullif(btrim(coalesce(p_email, email, '')), ''),
           tax_id         = nullif(btrim(coalesce(p_tax_id, tax_id, '')), ''),
           tax_label      = nullif(btrim(coalesce(p_tax_label, tax_label, '')), ''),
           invoice_footer = nullif(btrim(coalesce(p_invoice_footer, invoice_footer, '')), '')
     where id = p_org_id;
end;
$$;

-- ------------------------------------------------------------
-- 2. WHAT AN INVOICE EARNS, PER PROFILE
-- ------------------------------------------------------------
-- `create_invoice()` posts the credit side to an income account chosen by
-- name, and its default was 'Ventes d''œufs'. For a shop that is wrong, for a
-- church it is absurd, and the caller should not have to know the right
-- answer for a business it is merely displaying.
--
-- Resolved from the profile instead, and only when the caller said nothing.
create or replace function default_invoice_category(p_org_id uuid)
returns text
language sql
stable
as $$
    select case (select profile from orgs where id = p_org_id)
        when 'farm'   then 'Ventes de la ferme'
        when 'retail' then 'Ventes'
        when 'church' then 'Produits divers'
        else 'Ventes'
    end;
$$;

-- ------------------------------------------------------------
-- 3. NUMBERING THAT SURVIVES TWO PEOPLE INVOICING AT ONCE
-- ------------------------------------------------------------
-- What 009 did:
--
--     select to_char(...) || lpad((count(*) + 1)::text, 4, '0')
--       from invoices where org_id = ... and year = ...
--
-- Read the count, add one, insert. Two sessions that read before either
-- inserts both compute the same number, and `unique (org_id, number)` turns
-- the loser into a raised exception — so the second person to press the
-- button on a busy morning is simply told the invoice failed.
--
-- A sequence cannot fix it: sequences are global to the database, and two
-- businesses sharing this one would interleave their invoice numbers, which
-- is exactly what an auditor asks about. So the counter is a row per org per
-- year, and the bump is a single atomic upsert whose RETURNING is the number.
-- Concurrent callers serialise on that row and get consecutive values.
create table if not exists invoice_counters (
    org_id uuid not null references orgs(id) on delete cascade,
    year   int  not null,
    -- The last number issued. Next is this plus one, taken and stored in the
    -- same statement.
    issued int  not null default 0,
    primary key (org_id, year)
);

alter table invoice_counters enable row level security;

-- No policy grants direct access, and none should: the counter is only ever
-- touched by next_invoice_number(), which is SECURITY DEFINER. A client that
-- could write here could renumber a business's invoices.
drop policy if exists "invoice counters readable within org" on invoice_counters;
create policy "invoice counters readable within org"
    on invoice_counters for select
    using (is_org_member(org_id));

create or replace function next_invoice_number(p_org_id uuid, p_issued_on date)
returns text
language plpgsql
security definer
set search_path = public, auth
as $$
declare
    v_year int := extract(year from p_issued_on)::int;
    v_next int;
begin
    -- Not granted to `authenticated` — create_invoice() is the only caller and
    -- it is DEFINER, so it reaches this regardless. The check is here anyway,
    -- because the cost is one line and the failure it prevents is silent:
    -- anybody who could advance another business's counter would put gaps in
    -- that business's invoice sequence, and a gap in a numbered sequence is
    -- precisely what an auditor asks a business to explain. A future migration
    -- adding a blanket grant must not turn that on by accident.
    if not can_write_org(p_org_id) then
        raise exception 'You cannot issue invoice numbers for this business';
    end if;

    -- The whole point: read, increment and write are one statement, so two
    -- callers cannot both see the same "before" value.
    insert into invoice_counters (org_id, year, issued)
    values (p_org_id, v_year, 1)
    on conflict (org_id, year)
    do update set issued = invoice_counters.issued + 1
    returning issued into v_next;

    return v_year::text || '-' || lpad(v_next::text, 4, '0');
end;
$$;

-- Businesses that already have invoices start their counter above the highest
-- number they have used, so this migration cannot hand out a number that
-- collides with one already issued. Only numbers of the shape this function
-- produces are considered; a hand-typed number is not part of the sequence.
insert into invoice_counters (org_id, year, issued)
select i.org_id,
       extract(year from i.issued_on)::int,
       max((split_part(i.number, '-', 2))::int)
  from invoices i
 where i.number ~ '^\d{4}-\d+$'
   and split_part(i.number, '-', 1) = extract(year from i.issued_on)::text
 group by 1, 2
on conflict (org_id, year) do update
    set issued = greatest(invoice_counters.issued, excluded.issued);

-- ------------------------------------------------------------
-- 4. CREATING ONE
-- ------------------------------------------------------------
-- Same function as 009 with three changes: the category default is resolved
-- from the profile instead of being a farm string, the number comes from the
-- atomic counter instead of a count, and a due date can be expressed as a
-- number of days because that is how anybody actually says it.
--
-- The signature keeps every parameter 009 had, in the same order, so calls
-- already in the wild keep working.
-- The 009 signature took eleven arguments; this one takes thirteen, and
-- `create or replace` on a different argument list makes a second overload
-- rather than replacing the first. Two candidates is worse than either:
-- PostgREST cannot choose, and callers get "function is not unique". So the
-- old one is dropped by its exact signature first.
drop function if exists create_invoice(
    uuid, text, jsonb, uuid, text, text, date, text, text, uuid, date);

create or replace function create_invoice(
    p_org_id        uuid,
    p_customer_name text,
    p_lines         jsonb,
    p_recorded_by   uuid        default null,
    p_category      text        default null,
    p_customer_phone text       default null,
    p_due_on        date        default null,
    p_number        text        default null,
    p_memo          text        default null,
    p_client_uuid   uuid        default null,
    p_issued_on     date        default current_date,
    p_due_days      int         default null,
    p_customer_address text     default null
)
returns uuid
language plpgsql
security definer
set search_path = public, auth
as $$
declare
    v_actor      uuid := auth.uid();
    v_customer   uuid;
    v_invoice    uuid;
    v_entry      uuid;
    v_total      numeric := 0;
    v_number     text;
    v_line       jsonb;
    v_qty        numeric;
    v_price      numeric;
    v_amount     numeric;
    v_desc       text;
    v_recv_acct  uuid;
    v_inc_acct   uuid;
    v_existing   uuid;
    v_due        date;
begin
    if v_actor is null then
        raise exception 'create_invoice() needs a signed-in caller';
    end if;
    if p_recorded_by is not null and p_recorded_by <> v_actor then
        raise exception 'create_invoice() cannot record on behalf of another user';
    end if;
    if not can_write_org(p_org_id) then
        raise exception 'You cannot invoice for this business';
    end if;
    if nullif(btrim(coalesce(p_customer_name, '')), '') is null then
        raise exception 'An invoice needs a customer';
    end if;
    if p_lines is null or jsonb_array_length(p_lines) = 0 then
        raise exception 'An invoice needs at least one line';
    end if;

    -- Idempotent by client_uuid, like every other write in this schema: a
    -- phone that retries must not raise the same invoice twice.
    if p_client_uuid is not null then
        select id into v_existing
          from invoices where org_id = p_org_id and client_uuid = p_client_uuid;
        if found then
            return v_existing;
        end if;
    end if;

    for v_line in select * from jsonb_array_elements(p_lines) loop
        v_qty   := coalesce((v_line ->> 'quantity')::numeric, 1);
        v_price := coalesce((v_line ->> 'unit_price')::numeric, 0);
        v_desc  := nullif(btrim(coalesce(v_line ->> 'description', '')), '');
        if v_desc is null then
            raise exception 'Every invoice line needs a description';
        end if;
        if v_qty <= 0 or v_price <= 0 then
            raise exception 'Every invoice line needs a quantity and a price';
        end if;
        v_total := v_total + (v_qty * v_price);
    end loop;

    if v_total <= 0 then
        raise exception 'An invoice cannot be for nothing';
    end if;

    -- "Payable in 30 days" is how the terms are agreed; a date is what the
    -- table stores. Explicit p_due_on wins if both are given.
    v_due := p_due_on;
    if v_due is null and p_due_days is not null and p_due_days > 0 then
        v_due := p_issued_on + p_due_days;
    end if;

    v_number := nullif(btrim(coalesce(p_number, '')), '');
    if v_number is null then
        v_number := next_invoice_number(p_org_id, p_issued_on);
    end if;

    v_customer := ensure_customer(p_org_id, p_customer_name, p_customer_phone, v_actor);
    if nullif(btrim(coalesce(p_customer_address, '')), '') is not null then
        update customers
           set address = btrim(p_customer_address)
         where id = v_customer
           and coalesce(btrim(address), '') = '';
    end if;

    v_recv_acct := ensure_account_by_code(
        p_org_id, '1300', 'Créances clients', 'asset', v_actor
    );
    v_inc_acct := ensure_account(
        p_org_id,
        coalesce(nullif(btrim(coalesce(p_category, '')), ''),
                 default_invoice_category(p_org_id)),
        'income',
        v_actor
    );

    -- The customer owes us (asset up), and we have earned it (income up).
    -- No cash account is touched, which is the whole point of an invoice.
    v_entry := post_ledger_pair(
        p_org_id      => p_org_id,
        p_debit_acct  => v_recv_acct,
        p_credit_acct => v_inc_acct,
        p_amount      => v_total,
        p_label       => 'Facture ' || v_number || ' — ' || btrim(p_customer_name),
        p_actor       => v_actor,
        p_memo        => p_memo,
        p_details     => jsonb_build_object('facture', v_number,
                                            'client', btrim(p_customer_name)),
        p_occurred_at => p_issued_on::timestamptz
    );

    insert into invoices (
        org_id, customer_id, number, issued_on, due_on, total,
        journal_entry_id, created_by, client_uuid
    )
    values (
        p_org_id, v_customer, v_number, p_issued_on, v_due, v_total,
        v_entry, v_actor, p_client_uuid
    )
    returning id into v_invoice;

    for v_line in select * from jsonb_array_elements(p_lines) loop
        v_qty    := coalesce((v_line ->> 'quantity')::numeric, 1);
        v_price  := coalesce((v_line ->> 'unit_price')::numeric, 0);
        v_amount := v_qty * v_price;
        insert into invoice_lines (invoice_id, description, quantity, unit_price, amount)
        values (v_invoice, btrim(v_line ->> 'description'), v_qty, v_price, v_amount);
    end loop;

    return v_invoice;
end;
$$;

-- ------------------------------------------------------------
-- 5. WITHDRAWING ONE
-- ------------------------------------------------------------
-- `cancelled_at` has been on the table since 009 with nothing to set it, so an
-- invoice raised for the wrong customer or the wrong amount stayed on the
-- books as a receivable that would never be collected and could never be
-- removed.
--
-- Cancelling reverses the journal entry rather than deleting it. Same rule as
-- everywhere else here: what happened, happened, and the correction is its own
-- fact. A paid invoice cannot be cancelled — the money arrived, and pretending
-- otherwise would leave the payment posted against nothing.
create or replace function cancel_invoice(
    p_invoice_id uuid,
    p_reason     text default null
)
returns void
language plpgsql
security definer
set search_path = public, auth
as $$
declare
    v_actor  uuid := auth.uid();
    v_org    uuid;
    v_entry  uuid;
    v_paid   numeric;
    v_cancelled timestamptz;
begin
    if v_actor is null then
        raise exception 'cancel_invoice() needs a signed-in caller';
    end if;

    select org_id, journal_entry_id, cancelled_at
      into v_org, v_entry, v_cancelled
      from invoices where id = p_invoice_id;

    if v_org is null then
        raise exception 'No such invoice';
    end if;
    if not can_write_org(v_org) then
        raise exception 'You cannot change invoices for this business';
    end if;
    if v_cancelled is not null then
        -- Not an error worth failing over: two taps on a slow connection
        -- should not produce a scary message.
        return;
    end if;

    select coalesce(sum(amount), 0) into v_paid
      from invoice_payments where invoice_id = p_invoice_id;

    if v_paid > 0 then
        raise exception
            'This invoice has already been paid in part. Record a refund or a credit note instead.';
    end if;

    if v_entry is not null then
        perform reverse_entry(v_entry, v_actor,
                              coalesce(nullif(btrim(coalesce(p_reason, '')), ''),
                                       'Facture annulée'));
    end if;

    update invoices set cancelled_at = now() where id = p_invoice_id;
end;
$$;

-- ------------------------------------------------------------
-- 6. READING ONE BACK
-- ------------------------------------------------------------
-- `outstanding_invoices()` answers "who has not paid". These two answer "what
-- does this invoice say" and "what have we issued", which is what you need to
-- put a document in somebody's hand and to find one again afterwards.
--
-- SECURITY INVOKER, deliberately, unlike the writes above. These read
-- org-scoped tables that carry RLS, so the caller's own policies decide what
-- comes back — exactly the reasoning in the project notes for
-- record_contribution. A DEFINER read here would hand every org's invoices to
-- anyone holding the publishable key.
create or replace function invoice_header(p_invoice_id uuid)
returns table (
    invoice_id      uuid,
    number          text,
    issued_on       date,
    due_on          date,
    total           numeric,
    paid            numeric,
    outstanding     numeric,
    cancelled_at    timestamptz,
    customer_name   text,
    customer_phone  text,
    customer_address text,
    org_name        text,
    org_address     text,
    org_phone       text,
    org_email       text,
    org_tax_id      text,
    org_tax_label   text,
    org_currency    text,
    invoice_footer  text
)
language sql
stable
security invoker
set search_path = public
as $$
    select
        i.id, i.number, i.issued_on, i.due_on, i.total,
        coalesce(p.paid, 0),
        i.total - coalesce(p.paid, 0),
        i.cancelled_at,
        c.name, c.phone, c.address,
        o.name, o.address, o.phone, o.email, o.tax_id, o.tax_label,
        o.default_currency, o.invoice_footer
    from invoices i
    join customers c on c.id = i.customer_id
    join orgs o      on o.id = i.org_id
    left join (
        select invoice_id, sum(amount) as paid
          from invoice_payments group by invoice_id
    ) p on p.invoice_id = i.id
    where i.id = p_invoice_id;
$$;

create or replace function invoice_lines_of(p_invoice_id uuid)
returns table (
    description text,
    quantity    numeric,
    unit_price  numeric,
    amount      numeric
)
language sql
stable
security invoker
set search_path = public
as $$
    -- The join to invoices is what makes RLS apply: invoice_lines is keyed by
    -- invoice_id and its own policy is written against the parent, so reading
    -- through the parent is how the tenant check happens.
    select l.description, l.quantity, l.unit_price, l.amount
      from invoice_lines l
      join invoices i on i.id = l.invoice_id
     where l.invoice_id = p_invoice_id
     order by l.id;
$$;

-- Everything issued, not only what is unpaid — you cannot re-send a receipt
-- for an invoice the collections list has already dropped.
create or replace function list_invoices(
    p_org_id       uuid,
    p_include_paid boolean default true,
    p_limit        int     default 200
)
returns table (
    invoice_id    uuid,
    number        text,
    customer_name text,
    issued_on     date,
    due_on        date,
    total         numeric,
    paid          numeric,
    outstanding   numeric,
    cancelled     boolean,
    days_overdue  int
)
language sql
stable
security invoker
set search_path = public
as $$
    select
        i.id, i.number, c.name, i.issued_on, i.due_on, i.total,
        coalesce(p.paid, 0),
        i.total - coalesce(p.paid, 0),
        i.cancelled_at is not null,
        case
            when i.due_on is null or i.cancelled_at is not null then 0
            when i.total - coalesce(p.paid, 0) <= 0 then 0
            else greatest((current_date - i.due_on)::int, 0)
        end
    from invoices i
    join customers c on c.id = i.customer_id
    left join (
        select invoice_id, sum(amount) as paid
          from invoice_payments group by invoice_id
    ) p on p.invoice_id = i.id
    where i.org_id = p_org_id
      and (p_include_paid or i.total - coalesce(p.paid, 0) > 0)
    order by i.issued_on desc, i.number desc
    limit greatest(coalesce(p_limit, 200), 1);
$$;

-- ------------------------------------------------------------
-- 7. GRANTS
-- ------------------------------------------------------------
-- Wrapped in a role check because a bare Postgres — which is what CI runs —
-- has no `authenticated` role, and roles are cluster-wide, so a development
-- machine that has ever run the Supabase stub would hide the failure.
revoke execute on function set_org_billing(uuid, text, text, text, text, text, text) from public;
revoke execute on function next_invoice_number(uuid, date) from public;
revoke execute on function cancel_invoice(uuid, text) from public;
revoke execute on function create_invoice(uuid, text, jsonb, uuid, text, text, date, text, text, uuid, date, int, text) from public;

do $$
begin
    if exists (select 1 from pg_roles where rolname = 'authenticated') then
        grant execute on function set_org_billing(uuid, text, text, text, text, text, text) to authenticated;
        grant execute on function cancel_invoice(uuid, text) to authenticated;
        grant execute on function create_invoice(uuid, text, jsonb, uuid, text, text, date, text, text, uuid, date, int, text) to authenticated;
        grant execute on function invoice_header(uuid) to authenticated;
        grant execute on function invoice_lines_of(uuid) to authenticated;
        grant execute on function list_invoices(uuid, boolean, int) to authenticated;
        grant execute on function default_invoice_category(uuid) to authenticated;
        -- Deliberately NOT next_invoice_number: it mutates the counter, and
        -- nothing outside create_invoice() has any business advancing it.
        grant select on invoice_counters to authenticated;
    end if;
end $$;

notify pgrst, 'reload schema';


-- ============================================================
-- 021_platform_console.sql
-- ============================================================
-- ============================================================
-- 021 — A PLATFORM CONSOLE THAT SURVIVES A THOUSAND BUSINESSES
-- ============================================================
-- `all_orgs()` from 014 was written when the platform had three businesses on
-- it, and it shows. It returns *every* row, and for each row it runs two
-- correlated subqueries:
--
--     (select count(*) from memberships     where org_id = o.id),
--     (select count(*) from journal_entries where org_id = o.id)
--
-- At a thousand businesses that is two thousand subqueries per page load, one
-- of them counting every accounting entry the platform has ever recorded. The
-- app then puts all thousand rows into a single ListView. Neither half of that
-- survives the scale this migration is named for, and the failure is the worst
-- kind: it degrades smoothly, so nobody notices until the console takes eleven
-- seconds and the person running the platform quietly stops opening it.
--
-- Three changes fix it.
--
-- 1. ACTIVITY BECOMES A COLUMN, NOT A SCAN. `orgs.last_activity_at` is
--    maintained by a trigger. Sorting and filtering by "which businesses have
--    gone quiet" is then an indexed read instead of an aggregate over the
--    whole ledger — and "gone quiet" is the single most useful question the
--    platform admin has, because it predicts churn weeks before it happens.
--
-- 2. THE EXPENSIVE COUNTS ARE COMPUTED FOR ONE PAGE, NOT ALL ROWS. The
--    filtering and ordering happen on indexed columns of `orgs`; only the
--    fifty rows actually being returned pay for a member count. That is the
--    whole trick, and it keeps the query flat as the platform grows.
--
-- 3. THE AGGREGATES COME BACK IN ONE ROW. `platform_overview()` answers "how
--    many, how healthy" without returning a single business — so the console
--    can lead with the shape of the platform rather than with page one of an
--    alphabetical list, which is not information.
--
-- `all_orgs()` is deliberately left in place. It is what the current screen
-- calls, and a migration that breaks the app already deployed is how this
-- project has hurt itself before.

-- ------------------------------------------------------------
-- 1. WHEN DID THIS BUSINESS LAST DO ANYTHING
-- ------------------------------------------------------------
alter table orgs add column if not exists last_activity_at timestamptz;

comment on column orgs.last_activity_at is
    'When this business last posted a journal entry. Maintained by trigger so '
    'the platform console can sort and filter on activity without scanning '
    'the ledger. Approximate by design: it is a health signal, not an audit '
    'record — journal_entries remains the source of truth.';

-- One extra UPDATE per journal entry. Journal entries are a handful per
-- business per day, so this is cheap on the write side and turns the console's
-- most important question into an index scan on the read side.
--
-- Guarded on the value actually moving forward: a backdated entry must not
-- drag a business's activity date backwards and make a live business look
-- abandoned.
create or replace function touch_org_activity()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
    update orgs
       set last_activity_at = greatest(
             coalesce(last_activity_at, new.created_at), new.created_at)
     where id = new.org_id
       and (last_activity_at is null or last_activity_at < new.created_at);
    return null;
end;
$$;

drop trigger if exists journal_entries_touch_org on journal_entries;
create trigger journal_entries_touch_org
    after insert on journal_entries
    for each row execute function touch_org_activity();

-- Existing businesses get their real figure rather than starting blank, so
-- the console is correct the moment this migration lands.
update orgs o
   set last_activity_at = j.last_at
  from (select org_id, max(created_at) as last_at
          from journal_entries group by org_id) j
 where j.org_id = o.id
   and (o.last_activity_at is null or o.last_activity_at < j.last_at);

-- ------------------------------------------------------------
-- 2. INDEXES THE CONSOLE ACTUALLY USES
-- ------------------------------------------------------------
-- Search is on lower(name) because a person hunting for a business types it
-- in whatever case they please. This is a prefix/equality index; substring
-- search still falls back to a scan, which is acceptable while a scan of
-- `orgs` alone is cheap and a trigram extension is not guaranteed present.
create index if not exists orgs_by_lower_name on orgs (lower(name));
create index if not exists orgs_by_activity   on orgs (last_activity_at desc nulls last);
create index if not exists orgs_by_created    on orgs (created_at desc);
create index if not exists orgs_by_profile    on orgs (profile);

-- ------------------------------------------------------------
-- 3. THE SHAPE OF THE PLATFORM, IN ONE ROW
-- ------------------------------------------------------------
-- What the console leads with. None of these return a business; they answer
-- "is anything wrong today" in a single round trip.
create or replace function platform_overview()
returns table (
    total          int,
    active         int,
    archived       int,
    farms          int,
    shops          int,
    churches       int,
    other_profiles int,
    new_this_week  int,
    active_7d      int,
    silent_30d     int,
    never_active   int
)
language plpgsql
stable
security definer
set search_path = public, auth
as $$
begin
    if not exists (
        select 1 from profiles where id = auth.uid() and is_platform_admin
    ) then
        raise exception 'Only a platform admin can read the platform overview';
    end if;

    return query
    select
        count(*)::int,
        count(*) filter (where o.archived_at is null)::int,
        count(*) filter (where o.archived_at is not null)::int,
        count(*) filter (where o.profile = 'farm')::int,
        count(*) filter (where o.profile = 'retail')::int,
        count(*) filter (where o.profile = 'church')::int,
        count(*) filter (where o.profile not in ('farm','retail','church'))::int,
        count(*) filter (where o.created_at > now() - interval '7 days')::int,
        count(*) filter (where o.last_activity_at > now() - interval '7 days')::int,
        -- The churn signal: alive once, silent for a month.
        count(*) filter (
            where o.archived_at is null
              and o.last_activity_at is not null
              and o.last_activity_at < now() - interval '30 days')::int,
        -- Onboarded and never used. A different failure, and a different fix:
        -- this one belongs to whoever signed them up.
        count(*) filter (
            where o.archived_at is null and o.last_activity_at is null)::int
    from orgs o;
end;
$$;

-- ------------------------------------------------------------
-- 4. FINDING ONE BUSINESS AMONG THOUSANDS
-- ------------------------------------------------------------
-- Search, filter, sort and paginate — all server side. The client never holds
-- more than one page.
--
-- `total_count` rides along on every row via a window function so the pager
-- knows how many pages there are without a second round trip. It is the same
-- number on every row of the page; the client reads it from the first.
create or replace function search_orgs(
    p_query    text    default null,
    p_profile  text    default null,   -- 'farm' | 'retail' | 'church' | null
    p_status   text    default 'active', -- 'active' | 'archived' | 'all'
    p_activity text    default null,   -- 'active7' | 'silent30' | 'never'
    p_sort     text    default 'activity', -- 'activity' | 'name' | 'newest'
    p_limit    int     default 50,
    p_offset   int     default 0
)
returns table (
    org_id           uuid,
    name             text,
    slug             text,
    profile          text,
    currency         text,
    archived_at      timestamptz,
    created_at       timestamptz,
    last_activity_at timestamptz,
    member_count     int,
    total_count      int
)
language plpgsql
stable
security definer
set search_path = public, auth
as $$
declare
    v_limit  int := least(greatest(coalesce(p_limit, 50), 1), 200);
    v_offset int := greatest(coalesce(p_offset, 0), 0);
    v_query  text := nullif(btrim(coalesce(p_query, '')), '');
begin
    if not exists (
        select 1 from profiles where id = auth.uid() and is_platform_admin
    ) then
        raise exception 'Only a platform admin can search every business';
    end if;

    return query
    with filtered as (
        select o.id, o.name, o.slug, o.profile, o.default_currency,
               o.archived_at, o.created_at, o.last_activity_at,
               count(*) over () as total
        from orgs o
        where
            -- Status
            (   coalesce(p_status, 'active') = 'all'
             or (p_status = 'archived' and o.archived_at is not null)
             or (coalesce(p_status, 'active') = 'active' and o.archived_at is null))
            -- Profile
        and (p_profile is null or o.profile = p_profile)
            -- Activity
        and (   p_activity is null
             or (p_activity = 'active7'
                 and o.last_activity_at > now() - interval '7 days')
             or (p_activity = 'silent30'
                 and o.last_activity_at is not null
                 and o.last_activity_at < now() - interval '30 days')
             or (p_activity = 'never' and o.last_activity_at is null))
            -- Text: name or slug. Both lowered, so case never matters.
        and (   v_query is null
             or lower(o.name) like '%' || lower(v_query) || '%'
             or lower(o.slug) like '%' || lower(v_query) || '%')
        order by
            case when p_sort = 'name'   then lower(o.name) end asc,
            case when p_sort = 'newest' then o.created_at  end desc,
            -- Default: the businesses that have done something most recently,
            -- with the never-active ones last rather than first — a null is
            -- not "the most recent".
            case when coalesce(p_sort, 'activity') = 'activity'
                 then o.last_activity_at end desc nulls last,
            lower(o.name) asc
        limit v_limit offset v_offset
    )
    -- Only the page pays for this. That is the whole point of the CTE.
    select f.id, f.name, f.slug, f.profile, f.default_currency,
           f.archived_at, f.created_at, f.last_activity_at,
           (select count(*)::int from memberships m where m.org_id = f.id),
           f.total::int
    from filtered f;
end;
$$;

-- ------------------------------------------------------------
-- 5. GRANTS
-- ------------------------------------------------------------
-- Both functions make their own platform-admin check, which is why they are
-- DEFINER: they read across every tenant on purpose, and RLS would correctly
-- refuse them.
revoke execute on function platform_overview() from public;
revoke execute on function search_orgs(text, text, text, text, text, int, int) from public;
revoke execute on function touch_org_activity() from public;

do $$
begin
    if exists (select 1 from pg_roles where rolname = 'authenticated') then
        grant execute on function platform_overview() to authenticated;
        grant execute on function search_orgs(text, text, text, text, text, int, int) to authenticated;
        -- touch_org_activity() is a trigger function and is never called
        -- directly; it is deliberately not granted.
    end if;
end $$;

notify pgrst, 'reload schema';


-- ============================================================
-- 022_org_theme.sql
-- ============================================================
-- ============================================================
-- 022 — A BUSINESS PICKS ITS OWN COLOURS
-- ============================================================
-- Since 019 the colour of the app has been decided by `orgs.profile`: green
-- for a farm, indigo for a church, terracotta for a shop. That is a good
-- default and a bad ceiling. A tailor's shop and a hardware shop are both
-- `retail` and have no reason to look identical, and the one thing a business
-- owner asks for after "does it add up" is that it looks like *theirs*.
--
-- So the palette becomes a setting. Three decisions in it are worth stating,
-- because each had a plausible alternative:
--
-- 1. IT BELONGS TO THE BUSINESS, NOT TO THE DEVICE. A per-phone preference
--    would be easier — no migration at all — but it means two people in the
--    same shop describing different screens to each other down the phone, and
--    it means the owner cannot make the app look like their business for the
--    staff who actually use it. This is branding, and branding is not a
--    personal preference.
--
-- 2. IT IS SET BY AN ADMIN, VIA `is_org_admin()`. The same bar as renaming
--    the business, and for the same reason: it changes what every member
--    sees. An employee repainting the shop is not a catastrophe, but it is
--    also not theirs to do.
--
-- 3. THE COLUMN IS NOT AN ENUM. A check constraint listing today's palettes
--    would mean a database migration every time a colour is added, and worse,
--    it would mean the server refusing a palette that a newer app already
--    offers. The constraint here is on the *shape* of the name — a short
--    lowercase slug — so junk is still refused but the list of colours stays
--    where it belongs, in the app. An app that meets a name it does not know
--    falls back to the profile's colour, which is exactly what it did before
--    this migration existed.
--
-- Null means "never chose one", which is every business the moment this runs.

-- ------------------------------------------------------------
-- 1. THE COLUMN
-- ------------------------------------------------------------
alter table orgs add column if not exists theme text;

comment on column orgs.theme is
    'The palette this business chose, as a short slug the app resolves to '
    'colours (''ocean'', ''prune'', …). Null means the profile decides, which '
    'is the default and what every business had before 022. Deliberately not '
    'an enum: the list of palettes lives in the app, and the server must not '
    'refuse one that a newer build already offers.';

-- Shape, not membership. Lowercase slug, 2-32 characters, which is enough to
-- refuse a stray sentence or a colour code pasted in by hand without freezing
-- the palette list into the schema.
alter table orgs drop constraint if exists orgs_theme_is_a_slug;
alter table orgs add constraint orgs_theme_is_a_slug
    check (theme is null or theme ~ '^[a-z][a-z0-9-]{1,31}$');

-- ------------------------------------------------------------
-- 2. SETTING IT
-- ------------------------------------------------------------
-- A separate function rather than another argument on update_org(), because
-- the two are used by different people at different moments: update_org() is
-- the settings form an admin fills in once, and this is a picker that fires on
-- every tap while somebody tries colours out. Folding it in would mean the
-- colour picker having to send the name and the currency to change a hue.
--
-- SECURITY DEFINER for the same reason update_org() is: `orgs` has no update
-- policy for members, and the gate is is_org_admin(), which is also true for
-- a platform admin of every business.
create or replace function set_org_theme(
    p_org_id uuid,
    p_theme  text default null   -- null clears it, back to the profile colour
)
returns uuid
language plpgsql
security definer
set search_path = public, auth
as $$
declare
    v_actor uuid := auth.uid();
    v_theme text := nullif(btrim(lower(coalesce(p_theme, ''))), '');
begin
    if v_actor is null then
        raise exception 'set_org_theme() needs a signed-in caller';
    end if;

    if not is_org_admin(p_org_id) then
        raise exception 'You cannot change this business';
    end if;

    if not exists (select 1 from orgs where id = p_org_id) then
        raise exception 'No such business';
    end if;

    -- Same rule as update_org(): an archived business is a closed one, and
    -- repainting it puts a colour on something nobody is looking at.
    if exists (select 1 from orgs where id = p_org_id and archived_at is not null) then
        raise exception 'This business is archived. Restore it before changing it.';
    end if;

    -- Checked here as well as by the constraint so the caller gets a sentence
    -- rather than a constraint violation.
    if v_theme is not null and v_theme !~ '^[a-z][a-z0-9-]{1,31}$' then
        raise exception 'Unknown colour: %', p_theme;
    end if;

    update orgs set theme = v_theme where id = p_org_id;

    return p_org_id;
end;
$$;

-- ------------------------------------------------------------
-- 3. THE APP HAS TO BE TOLD
-- ------------------------------------------------------------
-- my_orgs() is what the app calls after sign-in, and the result is cached on
-- the device — which is the whole reason the theme rides along here rather
-- than being fetched per screen. A phone that has been out of range since
-- Tuesday still opens in the right colour, and no home screen flashes its old
-- palette before correcting itself.
--
-- Dropped and recreated rather than replaced: `create or replace` cannot
-- change a function's return type, and this adds a column to it.
drop function if exists my_orgs();

create or replace function my_orgs()
returns table (
    org_id           uuid,
    name             text,
    slug             text,
    profile          text,
    default_currency text,
    roles            text[],
    visibility       text,
    theme            text
)
language sql
stable
security definer
set search_path = public, auth
as $$
    select
        o.id, o.name, o.slug, o.profile, o.default_currency,
        array['platform_admin'::text],
        'full'::text,
        o.theme
    from orgs o
    where exists(select 1 from profiles where id = auth.uid() and is_platform_admin)

    union all

    select
        o.id, o.name, o.slug, o.profile, o.default_currency,
        array_agg(distinct m.role::text order by m.role::text),
        case when bool_or(m.visibility = 'full') then 'full' else 'summary' end,
        o.theme
    from memberships m
    join orgs o on o.id = m.org_id
    where m.user_id = auth.uid()
      and o.archived_at is null
      and not exists(select 1 from profiles where id = auth.uid() and is_platform_admin)
    group by o.id, o.name, o.slug, o.profile, o.default_currency, o.theme

    order by name;
$$;

-- ------------------------------------------------------------
-- 4. GRANTS
-- ------------------------------------------------------------
-- set_org_theme() starts life executable by PUBLIC, which includes anon. It
-- refuses a caller with no session already; the revoke makes that deliberate
-- rather than inherited, as in 005-007, 013 and 014.
revoke execute on function set_org_theme(uuid, text) from public;

-- my_orgs() is deliberately *not* revoked. It never was before, and a freshly
-- created function gets PUBLIC execute back by default — so recreating it
-- above already restored exactly the grants it had. Tightening it here would
-- be an unrelated change smuggled into a colour migration, and it would take
-- every signed-in user's business list with it on any deployment where
-- `authenticated` happens not to exist. The function returns nothing to a
-- caller with no session anyway: every branch is keyed on auth.uid().

-- `authenticated` is a Supabase role and does not exist on a bare Postgres,
-- which is what CI starts from. Roles are cluster-wide, so a developer whose
-- cluster has ever run a suite already has it and cannot reproduce the
-- failure on a fresh database — which is how 013 shipped this wrong once.
do $$
begin
    if exists (select 1 from pg_roles where rolname = 'authenticated') then
        grant execute on function set_org_theme(uuid, text) to authenticated;
        grant execute on function my_orgs() to authenticated;
    end if;
end $$;

notify pgrst, 'reload schema';


-- ============================================================
-- 023_invitation_code_without_pgcrypto.sql
-- ============================================================
-- ============================================================
-- 023 — MINTING AN INVITATION CODE WITHOUT PGCRYPTO
-- ============================================================
-- Generating an invitation code failed in production with:
--
--     function gen_random_bytes(integer) does not exist
--
-- which meant nobody could invite an employee at all. The button was dead in
-- front of the person trying to hire.
--
-- WHAT WENT WRONG. `gen_random_bytes()` belongs to the **pgcrypto**
-- extension. `gen_random_uuid()`, which every table in this schema defaults
-- to, is core Postgres 13+ — which is exactly why nothing else broke and this
-- looked fine everywhere anyone checked. And `create extension pgcrypto` is
-- written down in precisely one place: `database/schema.sql`, the bootstrap
-- file. It is in no migration, and therefore in none of the
-- `apply_006_to_0XX.sql` bundles, which is what actually gets pasted into the
-- Supabase SQL editor. A database brought up through the bundles never had
-- pgcrypto, and nothing in the migration history would ever have added it.
--
-- Supabase makes it worse than a missing extension: it installs extensions
-- into an `extensions` schema rather than `public`, so even "just enable
-- pgcrypto" leaves any function carrying `set search_path = public` unable to
-- see it. Fixing this by adding the extension would work on CI and stay
-- fragile on the only deployment that matters.
--
-- SO THE DEPENDENCY GOES AWAY INSTEAD. `gen_random_uuid()` is core and is
-- itself CSPRNG-backed, which is the property the original comment cared
-- about — a guessable invitation code is a guessable way into somebody's
-- books. One UUID carries 122 random bits; a code needs 40. No extension, no
-- schema ambiguity, and identical behaviour on a bare Postgres and on
-- Supabase.
--
-- The code itself is unchanged in every respect a user can see: eight
-- characters, the same 32-symbol alphabet with 0/O and 1/I stripped out
-- because these are read over a bad line, formatted XXXX-XXXX. Codes already
-- issued keep working — this replaces how the next one is minted, nothing
-- else.

create or replace function new_invitation_code()
returns text
language plpgsql
volatile
as $$
declare
    alphabet constant text := '23456789ABCDEFGHJKLMNPQRSTUVWXYZ';
    v_code text;
    v_hex  text;
    v_try  int := 0;
begin
    loop
        -- 32 hex characters from core Postgres's CSPRNG.
        v_hex := replace(gen_random_uuid()::text, '-', '');

        -- Drop the version nibble (13th) and the variant nibble (17th).
        -- RFC 4122 fixes both, so they carry no entropy: leaving them in
        -- would quietly pin two of the eight characters to a short set and
        -- cost roughly ten bits of the code's strength.
        v_hex := substr(v_hex, 1, 12) || substr(v_hex, 14, 3)
                                      || substr(v_hex, 18, 15);

        v_code := '';
        for i in 1..8 loop
            -- One byte per character. 256 is an exact multiple of 32, so the
            -- modulo is uniform — with an alphabet that did not divide 256
            -- this would bias every code toward its first symbols.
            v_code := v_code || substr(
                alphabet,
                (('x' || substr(v_hex, i * 2 - 1, 2))::bit(8)::int % 32) + 1,
                1);
        end loop;

        v_code := substr(v_code, 1, 4) || '-' || substr(v_code, 5, 4);

        exit when not exists (
            select 1 from pending_invitations
            where normalize_invitation_code(code) = normalize_invitation_code(v_code)
        );

        v_try := v_try + 1;
        if v_try > 20 then
            raise exception 'could not allocate an unused invitation code';
        end if;
    end loop;
    return v_code;
end;
$$;

-- The default still points at this function; `create or replace` keeps the
-- column default pointing at the same name, so nothing else needs changing.
-- Restated anyway, so a database that somehow lost the default gets it back
-- and this migration is a complete description of the fix.
alter table pending_invitations alter column code set default new_invitation_code();

notify pgrst, 'reload schema';


-- ============================================================
-- 024_credit_book.sql
-- ============================================================
-- ============================================================
-- 024 — THE CREDIT BOOK (LE CARNET DE CRÉDIT)
-- ============================================================
-- The daily reality of a boutique here is the carnet: customers who take
-- goods and pay at month-end, the trader who takes eggs weekly and settles
-- monthly. Until now the app recorded sales as if everything were cash,
-- which means the most common transaction in the market could not be
-- written down — and books that cannot hold the normal case go quiet.
--
-- The shape: a **debt** is a sale whose payment is a promise. It posts to
-- the ledger immediately — debit "Créances clients" (an asset: money owed
-- to you is something you own), credit the income category — so the income
-- statement is honest about what was earned even before it is collected.
-- A **repayment** moves value from the receivable to a cash account. The
-- double entry underneath is exactly the machinery from 007; nothing new is
-- invented, which is the point.
--
-- Two deliberate limits:
--   * A repayment can never exceed what remains. An overpayment is not a
--     generosity to record silently — it is a typo, or a new deposit that
--     deserves its own entry.
--   * Debts are per named customer. "Somebody owes me 5000" is not a debt,
--     it is a loss waiting to be admitted.

-- ------------------------------------------------------------
-- 1. TABLES
-- ------------------------------------------------------------
create table if not exists debts (
    id               uuid primary key default gen_random_uuid(),
    org_id           uuid not null references orgs(id) on delete cascade,
    customer_id      uuid not null references customers(id) on delete restrict,
    journal_entry_id uuid not null references journal_entries(id),
    client_uuid      uuid unique,
    label            text not null,
    amount           numeric(14,2) not null check (amount > 0),
    occurred_at      timestamptz not null default now(),
    created_by       uuid not null references profiles(id),
    created_at       timestamptz not null default now()
);

create index if not exists debts_by_org      on debts (org_id, occurred_at);
create index if not exists debts_by_customer on debts (org_id, customer_id);

create table if not exists debt_payments (
    id               uuid primary key default gen_random_uuid(),
    debt_id          uuid not null references debts(id) on delete restrict,
    org_id           uuid not null references orgs(id) on delete cascade,
    journal_entry_id uuid not null references journal_entries(id),
    client_uuid      uuid unique,
    amount           numeric(14,2) not null check (amount > 0),
    method           text not null default 'cash',
    paid_at          timestamptz not null default now(),
    created_by       uuid not null references profiles(id)
);

create index if not exists debt_payments_by_debt on debt_payments (debt_id);

-- RLS: same posture as every other org table. Reads for members, writes only
-- through the functions below (which are DEFINER and check membership
-- themselves) — so no insert/update/delete policy at all, exactly like the
-- audit log. A direct write is refused by default-deny.
alter table debts enable row level security;
alter table debt_payments enable row level security;

drop policy if exists "debts readable within org" on debts;
create policy "debts readable within org"
on debts for select using (is_org_member(org_id));

drop policy if exists "debt payments readable within org" on debt_payments;
create policy "debt payments readable within org"
on debt_payments for select using (is_org_member(org_id));

-- ------------------------------------------------------------
-- 2. RECORDING A SALE ON CREDIT
-- ------------------------------------------------------------
-- The customer arrives as a name (and optionally a phone), not an id: the
-- person at the counter types "Awa" while the queue waits. Matching is by
-- lowered, trimmed name within the org — the same rule ensure_account()
-- uses, for the same reason: the second "awa " must not become a second
-- customer holding half the history.
--
-- SECURITY DEFINER for the same reasons record_entry() is: it may mint a
-- customer and an account, and it writes ledger rows. It makes the same
-- membership check the policies would have made.
create or replace function record_credit_sale(
    p_org_id         uuid,
    p_customer_name  text,
    p_amount         numeric,
    p_label          text,
    p_customer_phone text        default null,
    p_category       text        default null,   -- income account; defaults to the label
    p_recorded_by    uuid        default null,
    p_client_uuid    uuid        default null,
    p_device_id      text        default null,
    p_occurred_at    timestamptz default now()
)
returns uuid
language plpgsql
security definer
set search_path = public, auth
as $$
declare
    v_actor       uuid := auth.uid();
    v_name        text := btrim(coalesce(p_customer_name, ''));
    v_label       text := btrim(coalesce(p_label, ''));
    v_customer    uuid;
    v_entry       uuid;
    v_receivable  uuid;
    v_income      uuid;
    v_debt        uuid;
begin
    if v_actor is null then
        raise exception 'record_credit_sale() needs a signed-in caller';
    end if;
    if p_recorded_by is not null and p_recorded_by <> v_actor then
        raise exception 'record_credit_sale() cannot record on behalf of another user';
    end if;
    if not can_write_org(p_org_id) then
        raise exception 'You cannot record entries for this business';
    end if;
    if p_amount is null or p_amount <= 0 then
        raise exception 'Amount must be greater than zero (got %)', p_amount;
    end if;
    if v_name = '' then
        raise exception 'A credit sale needs the customer''s name';
    end if;
    if v_label = '' then
        raise exception 'A credit sale needs a label';
    end if;

    -- Same idempotency as record_entry(): the outbox may deliver twice, and
    -- the second delivery must find the first rather than double the debt.
    if p_client_uuid is not null then
        select id into v_debt from debts where client_uuid = p_client_uuid;
        if found then
            return v_debt;
        end if;
    end if;

    select id into v_customer
      from customers
     where org_id = p_org_id
       and lower(btrim(name)) = lower(v_name)
     order by created_at
     limit 1;
    if v_customer is null then
        insert into customers (org_id, name, phone, created_by)
        values (p_org_id, v_name, nullif(btrim(coalesce(p_customer_phone, '')), ''), v_actor)
        returning id into v_customer;
    end if;

    -- Money owed to the business is an asset. One account carries every
    -- customer; the per-customer breakdown lives in `debts`, which is what
    -- the screen reads. 1100 sits in the asset band beside the cash codes.
    v_receivable := ensure_account_by_code(
        p_org_id, '1100', 'Créances clients', 'asset', v_actor);
    v_income := ensure_account(
        p_org_id, coalesce(nullif(btrim(coalesce(p_category, '')), ''), v_label),
        'income', v_actor);

    insert into journal_entries
        (org_id, memo, created_by, device_id, client_uuid, created_at)
    values
        (p_org_id, v_label || ' — crédit ' || v_name, v_actor, p_device_id,
         p_client_uuid, p_occurred_at)
    returning id into v_entry;

    insert into journal_lines (journal_entry_id, account_id, debit, credit) values
        (v_entry, v_receivable, p_amount, 0),
        (v_entry, v_income, 0, p_amount);

    insert into debts (org_id, customer_id, journal_entry_id, client_uuid,
                       label, amount, occurred_at, created_by)
    values (p_org_id, v_customer, v_entry, p_client_uuid,
            v_label, p_amount, p_occurred_at, v_actor)
    returning id into v_debt;

    return v_debt;
end;
$$;

-- ------------------------------------------------------------
-- 3. A REPAYMENT
-- ------------------------------------------------------------
create or replace function record_debt_payment(
    p_debt_id     uuid,
    p_amount      numeric,
    p_method      text        default 'cash',
    p_recorded_by uuid        default null,
    p_client_uuid uuid        default null,
    p_device_id   text        default null,
    p_paid_at     timestamptz default now()
)
returns uuid
language plpgsql
security definer
set search_path = public, auth
as $$
declare
    v_actor      uuid := auth.uid();
    v_debt       debts%rowtype;
    v_remaining  numeric;
    v_entry      uuid;
    v_cash       uuid;
    v_receivable uuid;
    v_payment    uuid;
    v_name       text;
begin
    if v_actor is null then
        raise exception 'record_debt_payment() needs a signed-in caller';
    end if;
    if p_recorded_by is not null and p_recorded_by <> v_actor then
        raise exception 'record_debt_payment() cannot record on behalf of another user';
    end if;
    if p_amount is null or p_amount <= 0 then
        raise exception 'Amount must be greater than zero (got %)', p_amount;
    end if;

    if p_client_uuid is not null then
        select id into v_payment from debt_payments where client_uuid = p_client_uuid;
        if found then
            return v_payment;
        end if;
    end if;

    select * into v_debt from debts where id = p_debt_id;
    if not found then
        raise exception 'No such debt';
    end if;
    if not can_write_org(v_debt.org_id) then
        raise exception 'You cannot record entries for this business';
    end if;

    -- The rule that keeps the screen truthful: what remains can reach zero
    -- and never cross it. Locked against a racing second device by taking
    -- the debt's row lock before summing.
    perform 1 from debts where id = p_debt_id for update;
    select v_debt.amount - coalesce(sum(amount), 0) into v_remaining
      from debt_payments where debt_id = p_debt_id;
    if p_amount > v_remaining then
        raise exception
            'Ce paiement (%) dépasse ce qui reste dû (%)', p_amount, v_remaining;
    end if;

    select name into v_name from customers where id = v_debt.customer_id;
    v_cash := resolve_cash_account(v_debt.org_id, p_method, v_actor);
    v_receivable := ensure_account_by_code(
        v_debt.org_id, '1100', 'Créances clients', 'asset', v_actor);

    insert into journal_entries
        (org_id, memo, created_by, device_id, client_uuid, created_at)
    values
        (v_debt.org_id, 'Remboursement — ' || coalesce(v_name, ''), v_actor,
         p_device_id, p_client_uuid, p_paid_at)
    returning id into v_entry;

    insert into journal_lines (journal_entry_id, account_id, debit, credit) values
        (v_entry, v_cash, p_amount, 0),
        (v_entry, v_receivable, 0, p_amount);

    insert into debt_payments (debt_id, org_id, journal_entry_id, client_uuid,
                               amount, method, paid_at, created_by)
    values (p_debt_id, v_debt.org_id, v_entry, p_client_uuid,
            p_amount, coalesce(p_method, 'cash'), p_paid_at, v_actor)
    returning id into v_payment;

    return v_payment;
end;
$$;

-- ------------------------------------------------------------
-- 4. WHO OWES WHAT
-- ------------------------------------------------------------
-- SECURITY INVOKER on purpose: these are reads, and RLS on debts/payments is
-- exactly the right gate — a member sees their business's carnet, nobody
-- else sees anything, and no check needs writing twice.
create or replace function customer_debts(p_org_id uuid)
returns table (
    customer_id   uuid,
    customer_name text,
    phone         text,
    total_owed    numeric,
    oldest_debt   timestamptz,
    open_debts    int
)
language sql
stable
security invoker
as $$
    select c.id, c.name, c.phone,
           sum(d.amount - coalesce(p.paid, 0)) as total_owed,
           min(d.occurred_at) filter (where d.amount > coalesce(p.paid, 0)),
           count(*) filter (where d.amount > coalesce(p.paid, 0))::int
      from debts d
      join customers c on c.id = d.customer_id
      left join lateral (
          select sum(amount) as paid from debt_payments where debt_id = d.id
      ) p on true
     where d.org_id = p_org_id
     group by c.id, c.name, c.phone
    having sum(d.amount - coalesce(p.paid, 0)) > 0
     order by min(d.occurred_at) filter (where d.amount > coalesce(p.paid, 0));
$$;

create or replace function debts_of_customer(p_org_id uuid, p_customer_id uuid)
returns table (
    debt_id     uuid,
    label       text,
    amount      numeric,
    paid        numeric,
    remaining   numeric,
    occurred_at timestamptz
)
language sql
stable
security invoker
as $$
    select d.id, d.label, d.amount, coalesce(p.paid, 0),
           d.amount - coalesce(p.paid, 0), d.occurred_at
      from debts d
      left join lateral (
          select sum(amount) as paid from debt_payments where debt_id = d.id
      ) p on true
     where d.org_id = p_org_id and d.customer_id = p_customer_id
     order by d.occurred_at;
$$;

-- ------------------------------------------------------------
-- 5. GRANTS
-- ------------------------------------------------------------
revoke execute on function record_credit_sale(uuid, text, numeric, text, text, text, uuid, uuid, text, timestamptz) from public;
revoke execute on function record_debt_payment(uuid, numeric, text, uuid, uuid, text, timestamptz) from public;

do $$
begin
    if exists (select 1 from pg_roles where rolname = 'authenticated') then
        grant select on debts, debt_payments to authenticated;
        grant execute on function record_credit_sale(uuid, text, numeric, text, text, text, uuid, uuid, text, timestamptz) to authenticated;
        grant execute on function record_debt_payment(uuid, numeric, text, uuid, uuid, text, timestamptz) to authenticated;
        grant execute on function customer_debts(uuid) to authenticated;
        grant execute on function debts_of_customer(uuid, uuid) to authenticated;
    end if;
end $$;

notify pgrst, 'reload schema';


-- ============================================================
-- 025_tontines.sql
-- ============================================================
-- ============================================================
-- 025 — TONTINES
-- ============================================================
-- The rotating savings group is how a large share of working capital moves
-- here: each member pays a fixed amount each round, and each round one
-- member takes the pot, in an order fixed when the group forms. A church or
-- shop owner is almost certainly in one, and today they track it in a
-- school notebook.
--
-- Version 1 is deliberately the **rotating** form and deliberately a
-- **tracker**: it records who has paid this round and whose turn the pot
-- is, and it does not write to the ledger. Two reasons, both about honesty:
--
--   * The tontine's money is usually not the business's money. Posting
--     contributions into the business's books would mix personal savings
--     into a shop's income statement — precisely the confusion the app
--     exists to end. The organiser who *does* run it through the till can
--     record that movement with record_entry(), which already exists.
--   * The variants (accumulating tontines, penalty rules, interest) differ
--     more than the business profiles do. The build plan says design those
--     with three real organisers first; this schema holds the common core
--     every variant shares and no rule it would have to unlearn.
--
-- Members are names, not accounts. Most tontine members will never touch
-- the app; requiring them to sign up would kill the feature on day one.

create table if not exists tontines (
    id            uuid primary key default gen_random_uuid(),
    org_id        uuid not null references orgs(id) on delete cascade,
    name          text not null,
    amount        numeric(14,2) not null check (amount > 0),  -- per member, per round
    period        text not null default 'monthly'
                  check (period in ('daily', 'weekly', 'monthly')),
    current_round int  not null default 1 check (current_round >= 1),
    is_active     boolean not null default true,
    created_by    uuid not null references profiles(id),
    created_at    timestamptz not null default now()
);

create index if not exists tontines_by_org on tontines (org_id) where is_active;

create table if not exists tontine_members (
    id         uuid primary key default gen_random_uuid(),
    tontine_id uuid not null references tontines(id) on delete cascade,
    org_id     uuid not null references orgs(id) on delete cascade,
    name       text not null,
    phone      text,
    -- Whose turn: the member at position N takes the pot in round N (and
    -- again at N + member-count, if the group runs on). Unique per tontine,
    -- so two people cannot hold the same turn.
    position   int not null check (position >= 1),
    created_at timestamptz not null default now(),
    unique (tontine_id, position)
);

create table if not exists tontine_contributions (
    id          uuid primary key default gen_random_uuid(),
    tontine_id  uuid not null references tontines(id) on delete cascade,
    member_id   uuid not null references tontine_members(id) on delete restrict,
    org_id      uuid not null references orgs(id) on delete cascade,
    round       int not null check (round >= 1),
    amount      numeric(14,2) not null check (amount > 0),
    client_uuid uuid unique,
    paid_at     timestamptz not null default now(),
    created_by  uuid not null references profiles(id),
    -- One payment per member per round: the second is a mistake, not a
    -- bonus. Corrections are a delete by the organiser, visible in the
    -- audit trigger like any other.
    unique (tontine_id, member_id, round)
);

alter table tontines enable row level security;
alter table tontine_members enable row level security;
alter table tontine_contributions enable row level security;

-- The whole surface is org-scoped, and unlike the ledger these rows carry no
-- money of the business's — so ordinary member CRUD under RLS is the right
-- gate, with writes for non-observers exactly as customers/products have.
drop policy if exists "tontines readable within org" on tontines;
create policy "tontines readable within org"
on tontines for select using (is_org_member(org_id));
drop policy if exists "tontines managed by writers" on tontines;
create policy "tontines managed by writers"
on tontines for all using (can_write_org(org_id)) with check (can_write_org(org_id));

drop policy if exists "tontine members readable within org" on tontine_members;
create policy "tontine members readable within org"
on tontine_members for select using (is_org_member(org_id));
drop policy if exists "tontine members managed by writers" on tontine_members;
create policy "tontine members managed by writers"
on tontine_members for all using (can_write_org(org_id)) with check (can_write_org(org_id));

drop policy if exists "contributions readable within org" on tontine_contributions;
create policy "contributions readable within org"
on tontine_contributions for select using (is_org_member(org_id));
drop policy if exists "contributions recorded by writers" on tontine_contributions;
create policy "contributions recorded by writers"
on tontine_contributions for insert with check (can_write_org(org_id));
drop policy if exists "contributions corrected by writers" on tontine_contributions;
create policy "contributions corrected by writers"
on tontine_contributions for delete using (can_write_org(org_id));

-- ------------------------------------------------------------
-- THE ROUND, ANSWERED IN ONE CALL
-- ------------------------------------------------------------
-- Who has paid, who has not, whose turn the pot is. SECURITY INVOKER: RLS
-- on the three tables is the gate, and it is the right one.
create or replace function tontine_round_status(p_tontine_id uuid)
returns table (
    member_id     uuid,
    member_name   text,
    phone         text,
    turn_position int,
    has_paid      boolean,
    is_taker      boolean
)
language sql
stable
security invoker
as $$
    select m.id, m.name, m.phone, m.position,
           exists (
               select 1 from tontine_contributions c
                where c.tontine_id = t.id
                  and c.member_id = m.id
                  and c.round = t.current_round),
           -- The pot rotates: position N takes round N, then N + count.
           ((t.current_round - 1) % (select count(*) from tontine_members
                                      where tontine_id = t.id)) + 1 = m.position
      from tontines t
      join tontine_members m on m.tontine_id = t.id
     where t.id = p_tontine_id
     order by m.position;
$$;

-- Closing a round: refused while somebody has not paid, because "everyone
-- paid" is the tontine's whole contract and skipping it silently is how
-- notebook tontines end in a quarrel. The organiser who must move on anyway
-- deletes the defaulter or records the payment — both visible acts.
create or replace function advance_tontine_round(p_tontine_id uuid)
returns int
language plpgsql
security definer
set search_path = public, auth
as $$
declare
    v_org     uuid;
    v_round   int;
    v_unpaid  int;
begin
    select org_id, current_round into v_org, v_round
      from tontines where id = p_tontine_id and is_active;
    if not found then
        raise exception 'No such tontine';
    end if;
    if not can_write_org(v_org) then
        raise exception 'You cannot manage this tontine';
    end if;

    select count(*) into v_unpaid
      from tontine_members m
     where m.tontine_id = p_tontine_id
       and not exists (
           select 1 from tontine_contributions c
            where c.tontine_id = p_tontine_id
              and c.member_id = m.id and c.round = v_round);
    if v_unpaid > 0 then
        raise exception
            'Impossible de clore le tour : % membre(s) n''ont pas encore payé',
            v_unpaid;
    end if;

    update tontines set current_round = current_round + 1
     where id = p_tontine_id
    returning current_round into v_round;
    return v_round;
end;
$$;

revoke execute on function advance_tontine_round(uuid) from public;

do $$
begin
    if exists (select 1 from pg_roles where rolname = 'authenticated') then
        grant select, insert, update, delete on tontines, tontine_members to authenticated;
        grant select, insert, delete on tontine_contributions to authenticated;
        grant execute on function tontine_round_status(uuid) to authenticated;
        grant execute on function advance_tontine_round(uuid) to authenticated;
    end if;
end $$;

notify pgrst, 'reload schema';


-- ============================================================
-- 026_production.sql
-- ============================================================
-- ============================================================
-- 026_production.sql — the transformation tool.
--
-- The cake lady's migration. She buys flour, oil and sugar at the market,
-- turns them into forty cakes, and sells the cakes. Until now the app could
-- say what she bought and what she sold, but the step in the middle — the
-- transformation — happened off the books, and she had to divide "what I
-- spent" by "how many came out" in her head to know what a cake costs her.
--
-- A production run is that middle step, recorded: *I used these products,
-- I made that product.* The run
--
--   * decrements each ingredient's count,
--   * increments the finished product's count,
--   * and moves the ingredients' cost onto the finished product, so
--     `products.cost_price` on the cake becomes what one cake actually
--     costs to make — which is the number every later sale snapshots into
--     its margin.
--
-- Two decisions worth knowing before reading the rest.
--
-- 1. **No journal entry.** The money left the business on the day the
--    ingredients were bought — receive_products() posted 'Achat de
--    marchandise' then, the same rule the farm applies to feed. Production
--    moves value from one shelf to another inside the business; nothing is
--    earned and nothing is spent. Writing an entry here would count the
--    same ingredients twice in the income statement.
--
-- 2. **Ingredients are ordinary products.** Flour is a product the shop
--    happens not to sell, received at its real price through the existing
--    delivery flow. No parallel "raw materials" table: the same count, the
--    same cost column, the same screens. A farm pressing shea nuts into
--    butter and a shop baking cakes use the identical mechanics.
--
-- Same posture as the carnet in 024: the tables are readable under RLS and
-- writable only through the function, because the whole value of the run is
-- that its cost arithmetic was done by the server, not typed.
-- ============================================================

-- ------------------------------------------------------------
-- 1. THE TABLES
-- ------------------------------------------------------------

create table if not exists production_runs (
    id           uuid primary key default gen_random_uuid(),
    org_id       uuid not null references orgs(id) on delete cascade,
    -- What came out of the transformation.
    product_id   uuid not null references products(id),
    -- The name as it was that day; a product renamed next month must not
    -- rewrite last month's history. Same rule as sale_lines.name.
    product_name text not null,
    quantity     numeric(14,3) not null check (quantity > 0),
    -- What the consumed ingredients cost, summed from the snapshots below.
    total_cost   numeric(14,2) not null default 0,
    -- total_cost / quantity: what one unit costs to make. Four decimals
    -- because a batch of 40 rarely divides evenly, and the rounding error
    -- multiplied back by the batch should stay under a franc.
    unit_cost    numeric(14,4) not null default 0,
    note         text,
    occurred_at  timestamptz not null default now(),
    recorded_by  uuid references profiles(id),
    device_id    text,
    -- Two phones retrying the same run must produce one run. Same contract
    -- as every other recording function since 002.
    client_uuid  uuid,
    created_at   timestamptz not null default now()
);

create unique index if not exists production_runs_client_uuid_key
    on production_runs (org_id, client_uuid) where client_uuid is not null;

create index if not exists production_runs_by_day
    on production_runs (org_id, occurred_at desc);

create table if not exists production_inputs (
    id         uuid primary key default gen_random_uuid(),
    run_id     uuid not null references production_runs(id) on delete cascade,
    product_id uuid not null references products(id),
    -- Snapshots, for the same reason sale_lines carries them: the run must
    -- keep saying what it consumed and at what cost, whatever happens to
    -- the product row afterwards.
    name       text not null,
    quantity   numeric(14,3) not null check (quantity > 0),
    unit_cost  numeric(14,4) not null default 0,
    line_total numeric(14,2) not null default 0
);

create index if not exists production_inputs_by_run
    on production_inputs (run_id);

comment on table production_runs is
    'One transformation: these ingredients became that product, at this cost.';
comment on table production_inputs is
    'What a run consumed, with name and cost as they were at the time.';

-- ------------------------------------------------------------
-- 2. RECORDING A RUN
-- ------------------------------------------------------------

-- [p_inputs] is a json array of {product_id?, name?, quantity}. An input may
-- arrive by id (the screen's dropdown) or by name (typed, matched the way
-- every name is matched here: case-insensitively, on trimmed text). An input
-- that names a product this business has never received is refused rather
-- than minted at cost zero — a silent zero-cost ingredient would make every
-- later margin a lie.
--
-- The output may arrive by id or by name, and *is* created if absent,
-- because "Gâteau" legitimately begins to exist at the first baking.
--
-- SECURITY DEFINER for the same reasons record_credit_sale() is: it may mint
-- the output product and it writes rows no policy allows directly. It makes
-- the same membership check the policies would have made.
create or replace function record_production(
    p_org_id       uuid,
    p_quantity     numeric,
    p_inputs       jsonb,
    p_product_id   uuid        default null,
    p_product_name text        default null,
    p_note         text        default null,
    p_recorded_by  uuid        default null,
    p_client_uuid  uuid        default null,
    p_device_id    text        default null,
    p_occurred_at  timestamptz default now()
)
returns uuid
language plpgsql
security definer
set search_path = public, auth
as $$
declare
    v_actor    uuid := auth.uid();
    v_run      uuid;
    v_output   uuid;
    v_out_name text;
    v_line     jsonb;
    v_input    uuid;
    v_in_name  text;
    v_qty      numeric;
    v_cost     numeric;
    v_total    numeric := 0;
    v_unit     numeric;
begin
    if v_actor is null then
        raise exception 'record_production() needs a signed-in caller';
    end if;
    if p_recorded_by is not null and p_recorded_by <> v_actor then
        raise exception 'record_production() cannot record on behalf of another user';
    end if;
    if not can_write_org(p_org_id) then
        raise exception 'You cannot record entries for this business';
    end if;
    if p_quantity is null or p_quantity <= 0 then
        raise exception 'A production needs the quantity that was made';
    end if;
    if p_inputs is null or jsonb_typeof(p_inputs) <> 'array'
       or jsonb_array_length(p_inputs) = 0 then
        raise exception 'A production needs at least one ingredient';
    end if;

    -- The outbox may deliver twice; the second delivery must find the first
    -- rather than bake the same forty cakes again.
    if p_client_uuid is not null then
        select id into v_run from production_runs
        where org_id = p_org_id and client_uuid = p_client_uuid;
        if found then
            return v_run;
        end if;
    end if;

    -- The output: by id, or by name — created at the first baking.
    v_output := p_product_id;
    if v_output is null then
        if btrim(coalesce(p_product_name, '')) = '' then
            raise exception 'A production needs the product that was made';
        end if;
        v_output := ensure_product(p_org_id, p_product_name,
                                   p_actor => v_actor);
    end if;

    select name into v_out_name
    from products where id = v_output and org_id = p_org_id;
    if v_out_name is null then
        raise exception 'No such product in this business';
    end if;

    insert into production_runs (org_id, product_id, product_name, quantity,
                                 note, occurred_at, recorded_by, device_id,
                                 client_uuid)
    values (p_org_id, v_output, v_out_name, p_quantity,
            nullif(btrim(coalesce(p_note, '')), ''), p_occurred_at, v_actor,
            p_device_id, p_client_uuid)
    returning id into v_run;

    for v_line in select * from jsonb_array_elements(p_inputs)
    loop
        v_qty := coalesce((v_line ->> 'quantity')::numeric, 0);
        if v_qty <= 0 then
            raise exception 'Every ingredient needs a quantity greater than zero';
        end if;

        v_input := nullif(v_line ->> 'product_id', '')::uuid;
        if v_input is null then
            v_in_name := btrim(coalesce(v_line ->> 'name', ''));
            if v_in_name = '' then
                raise exception 'Every ingredient needs a product or a name';
            end if;
            select id into v_input from products
            where org_id = p_org_id
              and lower(btrim(name)) = lower(v_in_name);
        end if;

        select name, cost_price into v_in_name, v_cost
        from products where id = v_input and org_id = p_org_id;
        if v_in_name is null then
            raise exception 'Unknown ingredient: % — receive it into stock first',
                coalesce(btrim(v_line ->> 'name'), v_line ->> 'product_id');
        end if;
        if v_input = v_output then
            raise exception 'A product cannot be its own ingredient';
        end if;

        insert into production_inputs (run_id, product_id, name, quantity,
                                       unit_cost, line_total)
        values (v_run, v_input, v_in_name, v_qty,
                coalesce(v_cost, 0), round(v_qty * coalesce(v_cost, 0), 2));

        -- The count can go negative, deliberately — the same rule as a sale.
        -- The cakes exist; refusing to record them because the flour count
        -- was wrong would make the count more important than the cakes, and
        -- the count is the thing more likely to be wrong.
        update products set quantity = quantity - v_qty where id = v_input;

        v_total := v_total + round(v_qty * coalesce(v_cost, 0), 2);
    end loop;

    v_unit := round(v_total / p_quantity, 4);

    update production_runs
       set total_cost = v_total, unit_cost = v_unit
     where id = v_run;

    -- The finished product: more on the shelf, at what this batch cost per
    -- unit. Overwriting cost_price with the latest batch is the same rule
    -- receive_products() applies to a delivery with a new unit cost, and it
    -- is what every later sale line snapshots as its margin base.
    update products
       set quantity   = quantity + p_quantity,
           cost_price = case when v_total > 0 then round(v_unit, 2)
                             else cost_price end
     where id = v_output;

    return v_run;
end;
$$;

-- ------------------------------------------------------------
-- 3. WHAT THE MAKER LOOKS AT
-- ------------------------------------------------------------

-- Recent runs, newest first, each carrying its ingredient list as one json
-- value so the screen renders a run without a second round trip.
create or replace function production_history(
    p_org_id uuid,
    p_limit  int default 50
)
returns table (
    run_id       uuid,
    product_name text,
    quantity     numeric,
    total_cost   numeric,
    unit_cost    numeric,
    occurred_at  timestamptz,
    inputs       jsonb
)
language sql
stable
security invoker
as $$
    select r.id, r.product_name, r.quantity, r.total_cost, r.unit_cost,
           r.occurred_at,
           coalesce((
               select jsonb_agg(jsonb_build_object(
                          'name', i.name, 'quantity', i.quantity)
                      order by i.name)
               from production_inputs i
               where i.run_id = r.id
           ), '[]'::jsonb)
      from production_runs r
     where r.org_id = p_org_id
     order by r.occurred_at desc
     limit p_limit;
$$;

-- ------------------------------------------------------------
-- 4. ROW LEVEL SECURITY
-- ------------------------------------------------------------

alter table production_runs   enable row level security;
alter table production_inputs enable row level security;

drop policy if exists "production readable within org" on production_runs;
create policy "production readable within org"
on production_runs for select using (is_org_member(org_id));

drop policy if exists "production inputs readable with their run" on production_inputs;
create policy "production inputs readable with their run"
on production_inputs for select using (
    exists (select 1 from production_runs r
            where r.id = run_id and is_org_member(r.org_id))
);

-- No insert, update or delete policies, on purpose. A run's arithmetic —
-- the snapshots, the decrements, the cost moved onto the product — is done
-- by record_production() or not at all; a hand-written row would be a run
-- whose numbers nobody computed.

-- ------------------------------------------------------------
-- 5. GRANTS
-- ------------------------------------------------------------

revoke execute on function record_production(uuid, numeric, jsonb, uuid, text, text, uuid, uuid, text, timestamptz) from public;

do $$
begin
    if exists (select 1 from pg_roles where rolname = 'authenticated') then
        grant select on production_runs, production_inputs to authenticated;
        grant execute on function record_production(uuid, numeric, jsonb, uuid, text, text, uuid, uuid, text, timestamptz) to authenticated;
        grant execute on function production_history(uuid, int) to authenticated;
    end if;
end $$;

notify pgrst, 'reload schema';


-- ============================================================
-- 027_product_lifecycle.sql
-- ============================================================
-- ============================================================
-- 027_product_lifecycle.sql — taking a product off the shelves.
--
-- The owner asked for two things: to fix a product's name, and to delete a
-- product. The first needs no schema at all — `products` has been updatable
-- by staff under RLS since 011, and every sale line, production input and
-- receipt snapshots the name it saw, so a rename cannot rewrite history.
--
-- The second is deliberately not a DELETE. A product that has ever been
-- sold, received or produced is referenced by that history, and history
-- here is never erased — the same rule that makes a wrong sale a return
-- rather than an edit. "Deleting" a product means archiving it:
-- `is_active` goes false, it disappears from the shelves, the sale sheet
-- and the pickers, and every number it ever touched stays exactly where
-- it is. Archiving is reversible for the same reason.
--
-- Who may do it: an owner or admin, checked by the server. Prices and
-- names are the daily texture of running a shop and stay open to staff;
-- making a product vanish is a decision about what the business sells,
-- and that belongs to the person who answers for the business. RLS
-- cannot gate one column more tightly than the rest of the row, so the
-- flip goes through a SECURITY DEFINER function that makes the check
-- the policy cannot.
-- ============================================================

create or replace function archive_product(
    p_product_id uuid,
    p_archived   boolean default true
)
returns void
language plpgsql
security definer
set search_path = public, auth
as $$
declare
    v_org uuid;
begin
    if auth.uid() is null then
        raise exception 'archive_product() needs a signed-in caller';
    end if;

    select org_id into v_org from products where id = p_product_id;
    if v_org is null then
        raise exception 'No such product';
    end if;

    if not is_org_admin(v_org) then
        raise exception 'Only an owner or admin can remove a product from the shop';
    end if;

    update products set is_active = not p_archived where id = p_product_id;
end;
$$;

comment on function archive_product(uuid, boolean) is
    'Removes a product from the shelves without touching its history, or puts it back. Owner/admin only.';

revoke execute on function archive_product(uuid, boolean) from public;

do $$
begin
    if exists (select 1 from pg_roles where rolname = 'authenticated') then
        grant execute on function archive_product(uuid, boolean) to authenticated;
    end if;
end $$;

notify pgrst, 'reload schema';


-- ============================================================
-- 028_ingredient_flag.sql
-- ============================================================
-- ============================================================
-- 028_ingredient_flag.sql — what is cooked with, not sold.
--
-- The flour question, settled. A shop that transforms — cakes, soap, shea
-- butter — holds two kinds of product on the same shelf: things it sells
-- and things it only cooks with. The tables and the accounting treat them
-- identically on purpose (an ingredient is an ordinary product received at
-- its real price), but the *screens* should not: at two hundred articles,
-- the sale picker offering flour at 0 F is an accident waiting for a
-- thumb, and the production picker burying ten real ingredients under a
-- hundred and ninety finished goods is a scroll nobody should do twice.
--
-- One boolean, no rules attached. `is_ingredient` is a signpost for the
-- pickers — the sale sheet hides flagged products, the production sheet
-- surfaces them first. It is deliberately NOT enforced server-side:
-- record_sale() still accepts an ingredient, because the shop that bakes
-- with flour on Monday and sells the surplus sack on Friday is not an
-- edge case here, it is the neighbourhood. Staff can flip the flag the
-- same way they edit a price.
-- ============================================================

alter table products
    add column if not exists is_ingredient boolean not null default false;

comment on column products.is_ingredient is
    'A signpost for the pickers: hidden from the sale sheet, surfaced first in production. Not a rule — selling one is still allowed.';

notify pgrst, 'reload schema';


-- ============================================================
-- 029_sale_on_credit.sql
-- ============================================================
-- ============================================================
-- 029_sale_on_credit.sql — crédit becomes a payment method.
--
-- The carnet (024) records money faithfully but never touched the goods:
-- a sack of rice taken on credit stayed on the shelf count, missed the
-- day's totals, and carried no cost — the shop knew what Awa owed but not
-- what the sale earned. The fix is not to bolt products onto the carnet;
-- it is to let the normal sale flow say "crédit" where it says "espèces".
--
-- A credit sale through record_sale() is a *sale* in every respect —
-- lines, stock decrements, cost snapshots, the day's numbers — except
-- where the money lands: debit 1100 Créances clients instead of the cash
-- box, plus a debt in the carnet naming the customer and linked to the
-- sale, so the carnet can show what was taken. Repayments were already
-- built in 024 and need nothing new.
--
-- record_sale() is dropped and recreated because its signature grows two
-- parameters; CREATE OR REPLACE alone would leave the old seven-argument
-- version alongside as an overload, and PostgREST would refuse the
-- ambiguity. The rewrite also adds the explicit caller checks the 011
-- version left to its callees.
--
-- record_return() now refuses credit sales, loudly. A return posts money
-- out of a cash account, which is simply false for a sale nobody has paid
-- yet; the honest correction path for credit is a repayment in the carnet
-- (or a correcting entry), and a clear refusal beats books that lie.
-- ============================================================

-- What the carnet can now show: the sale a debt came from.
alter table debts
    add column if not exists sale_id uuid references sales(id);

comment on column debts.sale_id is
    'Set when the debt was created by a credit sale through record_sale(); the carnet shows what was taken.';

drop function if exists record_sale(uuid, jsonb, text, text, uuid, text, timestamptz);

create or replace function record_sale(
    p_org_id         uuid,
    p_lines          jsonb,
    p_method         text        default 'cash',
    p_note           text        default null,
    p_client_uuid    uuid        default null,
    p_device_id      text        default null,
    p_occurred_at    timestamptz default now(),
    p_customer_name  text        default null,
    p_customer_phone text        default null
)
returns uuid
language plpgsql
security definer
set search_path = public, auth
as $$
declare
    v_actor     uuid := auth.uid();
    v_credit    boolean := lower(coalesce(p_method, '')) in ('credit', 'crédit');
    v_cust_name text := btrim(coalesce(p_customer_name, ''));
    v_sale_id   uuid;
    v_existing  uuid;
    v_line      jsonb;
    v_product   uuid;
    v_name      text;
    v_qty       numeric;
    v_price     numeric;
    v_cost      numeric;
    v_total     numeric := 0;
    v_entry     uuid;
    v_customer  uuid;
    v_receivable uuid;
    v_income    uuid;
    v_label     text;
begin
    if v_actor is null then
        raise exception 'record_sale() needs a signed-in caller';
    end if;
    if not can_write_org(p_org_id) then
        raise exception 'You cannot record entries for this business';
    end if;
    if p_lines is null or jsonb_typeof(p_lines) <> 'array'
       or jsonb_array_length(p_lines) = 0 then
        raise exception 'A sale needs at least one line';
    end if;
    if v_credit and v_cust_name = '' then
        raise exception 'A credit sale needs the customer''s name';
    end if;

    -- A retried sale returns the original rather than selling twice. The
    -- phone in a market retries whenever signal returns, which is often.
    if p_client_uuid is not null then
        select id into v_existing from sales
        where org_id = p_org_id and client_uuid = p_client_uuid;
        if v_existing is not null then
            return v_existing;
        end if;
    end if;

    insert into sales (org_id, kind, occurred_at, method, note, recorded_by,
                       device_id, client_uuid)
    values (p_org_id, 'sale', p_occurred_at,
            case when v_credit then 'credit' else p_method end,
            p_note, v_actor, p_device_id, p_client_uuid)
    returning id into v_sale_id;

    for v_line in select * from jsonb_array_elements(p_lines)
    loop
        v_name  := btrim(coalesce(v_line ->> 'name', ''));
        v_qty   := coalesce((v_line ->> 'quantity')::numeric, 0);
        v_price := coalesce((v_line ->> 'unit_price')::numeric, 0);

        if v_qty <= 0 then
            raise exception 'Every line needs a quantity greater than zero';
        end if;

        v_product := nullif(v_line ->> 'product_id', '')::uuid;

        if v_product is null then
            if v_name = '' then
                raise exception 'Every line needs a product or a name';
            end if;
            v_product := ensure_product(p_org_id, v_name,
                                        p_sale_price => v_price,
                                        p_actor      => v_actor);
        end if;

        select name, cost_price into v_name, v_cost
        from products where id = v_product and org_id = p_org_id;

        if v_name is null then
            raise exception 'No such product in this business';
        end if;

        insert into sale_lines (sale_id, product_id, name, quantity,
                                unit_price, unit_cost, line_total)
        values (v_sale_id, v_product, v_name, v_qty, v_price,
                coalesce(v_cost, 0), v_qty * v_price);

        -- Stock can go negative. That is deliberate: refusing the sale
        -- because the count is wrong would make the count more important than
        -- the customer standing there, and the count is the thing more likely
        -- to be wrong. A credit sale moves the goods exactly like a cash one
        -- — the sack leaves with Awa either way.
        update products set quantity = quantity - v_qty where id = v_product;

        v_total := v_total + (v_qty * v_price);
    end loop;

    if v_total > 0 then
        if v_credit then
            -- Same customer matching as the carnet in 024: case-insensitive,
            -- trimmed, oldest first — "awa " is Awa.
            select id into v_customer
              from customers
             where org_id = p_org_id
               and lower(btrim(name)) = lower(v_cust_name)
             order by created_at
             limit 1;
            if v_customer is null then
                insert into customers (org_id, name, phone, created_by)
                values (p_org_id, v_cust_name,
                        nullif(btrim(coalesce(p_customer_phone, '')), ''),
                        v_actor)
                returning id into v_customer;
            end if;

            -- What was taken, in the carnet's own words: "2× Riz, 1× Huile".
            select string_agg(
                       format('%s× %s', trim_scale(l.quantity), l.name),
                       ', ' order by l.id)
              into v_label
              from sale_lines l where l.sale_id = v_sale_id;
            v_label := left(coalesce(v_label, 'Vente à crédit'), 200);

            -- The money lands in créances instead of the cash box; the
            -- income side is identical to a cash sale, so the résultat
            -- reads both the same.
            v_receivable := ensure_account_by_code(
                p_org_id, '1100', 'Créances clients', 'asset', v_actor);
            v_income := ensure_account(p_org_id, 'Ventes', 'income', v_actor);

            insert into journal_entries
                (org_id, memo, created_by, device_id, client_uuid, created_at)
            values
                (p_org_id, v_label || ' — crédit ' || v_cust_name, v_actor,
                 p_device_id, p_client_uuid, p_occurred_at)
            returning id into v_entry;

            insert into journal_lines (journal_entry_id, account_id, debit, credit)
            values (v_entry, v_receivable, v_total, 0),
                   (v_entry, v_income, 0, v_total);

            -- The debt the repayment flow from 024 already knows how to
            -- settle. No separate client_uuid: the sale's own idempotency
            -- guard above means this insert can only run once per uuid.
            insert into debts (org_id, customer_id, journal_entry_id, sale_id,
                               label, amount, occurred_at, created_by)
            values (p_org_id, v_customer, v_entry, v_sale_id,
                    v_label, v_total, p_occurred_at, v_actor);
        else
            v_entry := record_entry(
                p_org_id      => p_org_id,
                p_amount      => v_total,
                p_direction   => 'in',
                p_label       => 'Vente',
                p_recorded_by => v_actor,
                p_category    => 'Ventes',
                p_method      => p_method,
                p_memo        => p_note,
                p_details     => jsonb_build_object('sale_id', v_sale_id),
                p_client_uuid => p_client_uuid,
                p_device_id   => p_device_id,
                p_occurred_at => p_occurred_at
            );
        end if;
    end if;

    update sales set total = v_total, entry_id = v_entry where id = v_sale_id;

    return v_sale_id;
end;
$$;

-- Same body as 011 plus one guard: a return posts money out of a cash
-- account, which is false for a sale nobody has paid yet. The correction
-- path for credit is the carnet.
create or replace function record_return(
    p_sale_id     uuid,
    p_note        text default null,
    p_client_uuid uuid default null
)
returns uuid
language plpgsql
security definer
set search_path = public, auth
as $$
declare
    v_actor    uuid := auth.uid();
    v_org      uuid;
    v_method   text;
    v_total    numeric;
    v_kind     text;
    v_return   uuid;
    v_existing uuid;
    v_line     record;
    v_entry    uuid;
begin
    select org_id, method, total, kind
      into v_org, v_method, v_total, v_kind
    from sales where id = p_sale_id;

    if v_org is null then
        raise exception 'No such sale';
    end if;
    if v_kind = 'return' then
        raise exception 'That is already a return';
    end if;
    if v_method = 'credit' then
        raise exception 'A credit sale is settled in the carnet, not by a return';
    end if;
    if exists (select 1 from sales where reverses_id = p_sale_id) then
        raise exception 'That sale has already been returned';
    end if;

    if p_client_uuid is not null then
        select id into v_existing from sales
        where org_id = v_org and client_uuid = p_client_uuid;
        if v_existing is not null then
            return v_existing;
        end if;
    end if;

    insert into sales (org_id, kind, method, note, total, reverses_id,
                       recorded_by, client_uuid)
    values (v_org, 'return', v_method, p_note, v_total, p_sale_id,
            v_actor, p_client_uuid)
    returning id into v_return;

    for v_line in select * from sale_lines where sale_id = p_sale_id
    loop
        insert into sale_lines (sale_id, product_id, name, quantity,
                                unit_price, unit_cost, line_total)
        values (v_return, v_line.product_id, v_line.name, v_line.quantity,
                v_line.unit_price, v_line.unit_cost, v_line.line_total);

        update products set quantity = quantity + v_line.quantity
        where id = v_line.product_id;
    end loop;

    if v_total > 0 then
        v_entry := record_entry(
            p_org_id      => v_org,
            p_amount      => v_total,
            p_direction   => 'out',
            p_label       => 'Retour de vente',
            p_recorded_by => v_actor,
            p_category    => 'Ventes',
            p_method      => v_method,
            p_memo        => p_note,
            p_details     => jsonb_build_object('reverses', p_sale_id),
            p_client_uuid => p_client_uuid
        );
        update sales set entry_id = v_entry where id = v_return;
    end if;

    return v_return;
end;
$$;

-- ------------------------------------------------------------
-- GRANTS — the drop above took record_sale's grants with it.
-- ------------------------------------------------------------
revoke execute on function record_sale(uuid, jsonb, text, text, uuid, text, timestamptz, text, text) from public;

do $$
begin
    if exists (select 1 from pg_roles where rolname = 'authenticated') then
        grant execute on function record_sale(uuid, jsonb, text, text, uuid, text, timestamptz, text, text) to authenticated;
        grant execute on function record_return(uuid, text, uuid) to authenticated;
    end if;
end $$;

notify pgrst, 'reload schema';


-- ============================================================
-- 030_notifications.sql
-- ============================================================
-- ============================================================
-- 030_notifications.sql — the bell.
--
-- One table, one row per recipient, written by the server at the few
-- moments worth interrupting somebody for, read under RLS by the person
-- it names. The design rules, in order:
--
--   * **Notify only what the recipient can act on.** An employee's bell
--     is nearly silent by design; an owner hears about money and stock;
--     the platform admin hears about the platform. Fan-out picks the
--     audience at write time, one row each, so read/unread is personal.
--
--   * **A notification must never block the work.** Every trigger body
--     is wrapped: if writing the bell row fails for any reason, the sale
--     (or the payment, or the join) goes through and the bell stays
--     silent. Books beat bells.
--
--   * **No schedulers.** Everything here fires synchronously off writes
--     that already happen. The events that want a clock — "credit older
--     than 30 days", the end-of-day digest — are deliberately absent
--     until there is a job runner to fire them; a fake cron bolted onto
--     reads would ring at random times.
--
-- Phase 1 events: stock crossing below its threshold, somebody joining
-- the business, a credit fully repaid, a tontine round ready to close,
-- and (platform-level) a new business application.
-- ============================================================

create table if not exists notifications (
    id           uuid primary key default gen_random_uuid(),
    recipient_id uuid not null references profiles(id) on delete cascade,
    -- Null for platform-level notifications, which belong to no business.
    org_id       uuid references orgs(id) on delete cascade,
    kind         text not null,
    message      text not null,
    created_at   timestamptz not null default now(),
    read_at      timestamptz
);

create index if not exists notifications_by_recipient
    on notifications (recipient_id, created_at desc);
create index if not exists notifications_unread
    on notifications (recipient_id) where read_at is null;

comment on table notifications is
    'One row per recipient per event. Written by triggers, read by the bell.';

-- ------------------------------------------------------------
-- FAN-OUT
-- ------------------------------------------------------------

-- The audience for business events: the people who answer for the
-- business. Employees are deliberately not in it — their bell stays
-- quiet unless an event is truly theirs.
create or replace function notify_org_admins(
    p_org_id  uuid,
    p_kind    text,
    p_message text,
    p_except  uuid default null
)
returns void
language sql
security definer
set search_path = public
as $$
    insert into notifications (recipient_id, org_id, kind, message)
    select distinct m.user_id, p_org_id, p_kind, p_message
      from memberships m
     where m.org_id = p_org_id
       and m.role in ('owner', 'super_admin', 'admin')
       and (p_except is null or m.user_id <> p_except);
$$;

revoke execute on function notify_org_admins(uuid, text, text, uuid) from public;

-- ------------------------------------------------------------
-- THE EVENTS
--
-- All SECURITY DEFINER (an RLS table with no insert policy needs it) and
-- all swallowing their own failures — see the header.
-- ------------------------------------------------------------

-- Stock crossing below its threshold. On the crossing only, not on every
-- sale below it: a shelf at 3 of 5 must not ring the bell ten times a day.
create or replace function trg_notify_low_stock()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
    if new.low_stock_at is not null
       and new.is_active
       and new.quantity <= new.low_stock_at
       and old.quantity > new.low_stock_at then
        perform notify_org_admins(new.org_id, 'low_stock',
            format('Stock bas : %s (%s restant)',
                   new.name, trim_scale(new.quantity)));
    end if;
    return new;
exception when others then
    return new;
end;
$$;

drop trigger if exists notify_low_stock on products;
create trigger notify_low_stock
after update of quantity on products
for each row execute function trg_notify_low_stock();

-- Somebody joined the business. The new member is excluded from their own
-- announcement; the first owner of a fresh org notifies nobody, since
-- there is nobody yet.
create or replace function trg_notify_member_joined()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
declare
    v_who text;
    v_org text;
begin
    select coalesce(nullif(btrim(coalesce(full_name, '')), ''), 'Quelqu''un')
      into v_who from profiles where id = new.user_id;
    select name into v_org from orgs where id = new.org_id;
    perform notify_org_admins(new.org_id, 'member_joined',
        format('%s a rejoint %s', coalesce(v_who, 'Quelqu''un'),
               coalesce(v_org, 'votre activité')),
        p_except => new.user_id);
    return new;
exception when others then
    return new;
end;
$$;

drop trigger if exists notify_member_joined on memberships;
create trigger notify_member_joined
after insert on memberships
for each row execute function trg_notify_member_joined();

-- A credit fully repaid — the carnet's good news.
create or replace function trg_notify_debt_settled()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
declare
    v_debt debts%rowtype;
    v_paid numeric;
    v_customer text;
begin
    select * into v_debt from debts where id = new.debt_id;
    select coalesce(sum(amount), 0) into v_paid
      from debt_payments where debt_id = new.debt_id;
    if v_paid >= v_debt.amount then
        select name into v_customer from customers where id = v_debt.customer_id;
        perform notify_org_admins(v_debt.org_id, 'debt_settled',
            format('Crédit soldé : %s a fini de payer %s',
                   coalesce(v_customer, 'un client'),
                   trim_scale(v_debt.amount)));
    end if;
    return new;
exception when others then
    return new;
end;
$$;

drop trigger if exists notify_debt_settled on debt_payments;
create trigger notify_debt_settled
after insert on debt_payments
for each row execute function trg_notify_debt_settled();

-- A tontine round where everyone has paid: ready to close, pot ready to
-- hand over.
create or replace function trg_notify_tontine_ready()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
declare
    v_t tontines%rowtype;
    v_members int;
    v_paid int;
begin
    select * into v_t from tontines where id = new.tontine_id;
    if new.round <> v_t.current_round then
        return new;
    end if;
    select count(*) into v_members
      from tontine_members where tontine_id = new.tontine_id;
    select count(*) into v_paid
      from tontine_contributions
     where tontine_id = new.tontine_id and round = v_t.current_round;
    if v_members > 0 and v_paid >= v_members then
        perform notify_org_admins(v_t.org_id, 'tontine_ready',
            format('Tontine %s : tour %s prêt à clore, tout le monde a payé',
                   v_t.name, v_t.current_round));
    end if;
    return new;
exception when others then
    return new;
end;
$$;

drop trigger if exists notify_tontine_ready on tontine_contributions;
create trigger notify_tontine_ready
after insert on tontine_contributions
for each row execute function trg_notify_tontine_ready();

-- Platform level: a new business application, for the people who approve
-- them. org_id stays null — this belongs to the platform, not a business.
create or replace function trg_notify_org_application()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
    insert into notifications (recipient_id, org_id, kind, message)
    select p.id, null, 'org_application',
           format('Nouvelle demande d''entreprise : %s', new.name)
      from profiles p
     where p.is_platform_admin;
    return new;
exception when others then
    return new;
end;
$$;

drop trigger if exists notify_org_application on org_applications;
create trigger notify_org_application
after insert on org_applications
for each row execute function trg_notify_org_application();

-- ------------------------------------------------------------
-- ROW LEVEL SECURITY
-- ------------------------------------------------------------

alter table notifications enable row level security;

drop policy if exists "own notifications readable" on notifications;
create policy "own notifications readable"
on notifications for select using (recipient_id = auth.uid());

-- Marking read is the only write a recipient makes, and only on their own.
drop policy if exists "own notifications markable" on notifications;
create policy "own notifications markable"
on notifications for update using (recipient_id = auth.uid())
with check (recipient_id = auth.uid());

-- No insert or delete policies: rows are written by the triggers above
-- and age out of relevance rather than being erased.

do $$
begin
    if exists (select 1 from pg_roles where rolname = 'authenticated') then
        grant select, update on notifications to authenticated;
    end if;
end $$;

notify pgrst, 'reload schema';


-- ============================================================
-- 031_team_access.sql
-- ============================================================
-- ============================================================
-- 031_team_access.sql — the owner decides who sees what.
--
-- Until now the app had two speeds: admins could do everything, and
-- everybody else who wasn't an observer could do nearly everything —
-- including changing prices and renaming products, which is fine while
-- the owner is the only user and wrong the day a vendeuse is hired.
--
-- This migration gives the owner a dial per tool, per tier:
--
--   * **Tiers**: 'employee' (the employee role) and 'supervisor' (the
--     manager and supervisor roles). Owners and admins are never dialled
--     down — somebody must always be able to see everything — and the
--     observer keeps the read-only contract it has had since 004.
--   * **Features**: stable keys — products, production, credits,
--     tontines, invoices, photos, reports, staff.
--   * **Access**: 'hidden' (the tool is not offered), 'view' (look,
--     never change), 'edit' (today's behaviour).
--
-- **Defaults preserve today.** A business that never opens the screen
-- behaves exactly as before: every feature defaults to 'edit' except
-- reports, which defaults to 'view' because its screens were always
-- read-only. Rules only ever tighten.
--
-- **Where the server enforces, and where it defers.** Hiding a button is
-- courtesy; the server is the contract. Enforced here:
--
--   * product edits — the RLS update policy now demands 'edit' on
--     products, closing the price-tampering gap;
--   * the carnet — BEFORE INSERT triggers on debts and debt_payments
--     catch *every* path that grants credit or records a repayment,
--     including record_sale's credit branch and any function added
--     later, without redefining any of them;
--   * production — the same trigger on production_runs.
--
-- Deliberately not server-enforced in this round: selling (a vendeuse
-- who cannot sell is not an employee, and hiding the sale screen would
-- be configuration error, not protection), receiving stock (restocking
-- is counter work; at 'view' the UI hides the buttons), and the reports,
-- whose line-level privacy has been enforced by 006 since it shipped.
-- ============================================================

-- ------------------------------------------------------------
-- 1. THE RULES
-- ------------------------------------------------------------

create table if not exists org_feature_rules (
    org_id     uuid not null references orgs(id) on delete cascade,
    tier       text not null check (tier in ('employee', 'supervisor')),
    feature    text not null,
    access     text not null check (access in ('hidden', 'view', 'edit')),
    updated_by uuid references profiles(id),
    updated_at timestamptz not null default now(),
    primary key (org_id, tier, feature)
);

comment on table org_feature_rules is
    'The owner''s dial: per tier, per tool, hidden / view / edit. Absence means today''s default.';

alter table org_feature_rules enable row level security;

-- Everybody in the business reads the rules — the app needs them to know
-- what to draw. Only admins write them.
drop policy if exists "feature rules readable within org" on org_feature_rules;
create policy "feature rules readable within org"
on org_feature_rules for select using (is_org_member(org_id));

drop policy if exists "feature rules written by admins" on org_feature_rules;
create policy "feature rules written by admins"
on org_feature_rules for all using (is_org_admin(org_id))
with check (is_org_admin(org_id));

-- ------------------------------------------------------------
-- 2. THE QUESTION EVERY GUARD ASKS
-- ------------------------------------------------------------

-- What may the current caller do with this feature in this business?
-- 'edit' for admins always; the tier's rule otherwise; the preserving
-- default when no rule exists; 'hidden' for a stranger. A null auth.uid()
-- (a suite running as postgres, a server-side job) gets 'edit': those
-- contexts are gated elsewhere, and a guard that broke them would be
-- enforcing against the furniture.
create or replace function feature_access(p_org_id uuid, p_feature text)
returns text
language plpgsql
stable
security definer
set search_path = public, auth
as $$
declare
    v_roles  text[];
    v_tier   text;
    v_access text;
begin
    if auth.uid() is null then
        return 'edit';
    end if;

    select array_agg(distinct role) into v_roles
      from memberships
     where org_id = p_org_id and user_id = auth.uid();

    if v_roles is null then
        return 'hidden';
    end if;
    if v_roles && array['owner', 'super_admin', 'admin'] then
        return 'edit';
    end if;

    v_tier := case
        when v_roles && array['manager', 'supervisor'] then 'supervisor'
        else 'employee'
    end;

    select access into v_access
      from org_feature_rules
     where org_id = p_org_id and tier = v_tier and feature = p_feature;

    return coalesce(v_access,
        case when p_feature = 'reports' then 'view' else 'edit' end);
end;
$$;

-- ------------------------------------------------------------
-- 3. ENFORCEMENT
-- ------------------------------------------------------------

-- Prices and names: the update policy itself now demands the dial. The
-- DEFINER functions that move stock (record_sale, receive_products,
-- record_production) bypass RLS and keep working — the counter never
-- stops — but a direct edit of price, name or threshold needs 'edit'.
drop policy if exists "products updatable by staff" on products;
create policy "products updatable by staff"
on products for update
using (can_write_org(org_id) and feature_access(org_id, 'products') = 'edit')
with check (can_write_org(org_id) and feature_access(org_id, 'products') = 'edit');

-- One guard per money table, catching every writer present and future.
create or replace function trg_guard_feature_edit()
returns trigger
language plpgsql
security definer
set search_path = public, auth
as $$
begin
    if feature_access(new.org_id, tg_argv[0]) <> 'edit' then
        raise exception '%', tg_argv[1];
    end if;
    return new;
end;
$$;

drop trigger if exists guard_credits on debts;
create trigger guard_credits
before insert on debts
for each row execute function trg_guard_feature_edit(
    'credits', 'Le carnet de crédit vous est fermé. Voyez le propriétaire.');

drop trigger if exists guard_production on production_runs;
create trigger guard_production
before insert on production_runs
for each row execute function trg_guard_feature_edit(
    'production', 'La production vous est fermée. Voyez le propriétaire.');

-- debt_payments carries no org_id; the debt knows it.
create or replace function trg_guard_repayment()
returns trigger
language plpgsql
security definer
set search_path = public, auth
as $$
declare
    v_org uuid;
begin
    select org_id into v_org from debts where id = new.debt_id;
    if v_org is not null and feature_access(v_org, 'credits') <> 'edit' then
        raise exception 'Le carnet de crédit vous est fermé. Voyez le propriétaire.';
    end if;
    return new;
end;
$$;

drop trigger if exists guard_repayments on debt_payments;
create trigger guard_repayments
before insert on debt_payments
for each row execute function trg_guard_repayment();

-- ------------------------------------------------------------
-- 4. GRANTS
-- ------------------------------------------------------------

do $$
begin
    if exists (select 1 from pg_roles where rolname = 'authenticated') then
        grant select, insert, update, delete on org_feature_rules to authenticated;
        grant execute on function feature_access(uuid, text) to authenticated;
    end if;
end $$;

notify pgrst, 'reload schema';


-- ============================================================
-- 032_security_hardening.sql
-- ============================================================
-- ============================================================
-- 032_security_hardening.sql — closing the holes a full audit found.
--
-- One migration, several unrelated fixes, bundled because they share a
-- single theme: a SECURITY DEFINER function or a permissive grant that let a
-- caller do something the table's own RLS would have refused. Each is small;
-- together they are the difference between "RLS is the security model" being
-- true and being nearly true.
--
-- The headline is the first one. The rest are the same shape, found while
-- looking for more of it.
-- ============================================================

-- ------------------------------------------------------------
-- 1. profiles.is_platform_admin — the one that mattered
--
-- THE HOLE. `is_platform_admin` is a column on `profiles`, and the profiles
-- UPDATE policy is `with check (id = auth.uid())`. RLS gates rows, never
-- columns, so that policy — correctly — lets a person edit their own row, and
-- therefore lets them set ANY column on it, this flag included. One line from
-- any signed-in account:
--
--     update profiles set is_platform_admin = true where id = auth.uid();
--
-- and `is_org_member`, `is_org_admin`, `can_write_org` and `my_org_ids` all
-- start returning true for every org on the platform (see 010). Total
-- multi-tenant compromise from a free sign-up.
--
-- TWO LAYERS, because either alone is not enough on Supabase:
--
--   Layer 1 — column privileges. A table-wide GRANT UPDATE (which is what
--   Supabase hands `authenticated` by default) covers every column, so a bare
--   REVOKE of one column does nothing against it. The fix is to drop the
--   table-wide UPDATE and re-grant only the personal columns a person owns.
--   After this the attack statement fails with "permission denied for column
--   is_platform_admin" before RLS is even consulted, and — the reason to
--   prefer a column list over a blocklist — any column added later is
--   non-writable until someone deliberately adds it here. Fail-closed.
--
--   Layer 2 — a guard trigger. Several Supabase dashboard actions re-run
--   GRANT ALL and would silently undo Layer 1. A trigger survives that: it
--   refuses to let the flag change unless the caller is already a platform
--   admin, or there is no JWT at all (the trusted server / SQL-editor context
--   that seeds the very first admin, and the only place the flag is ever
--   legitimately set — nothing in the app writes it).
-- ------------------------------------------------------------

do $$
begin
    if exists (select 1 from pg_roles where rolname = 'authenticated') then
        -- Drop the table-wide UPDATE so the column grant below is the whole of
        -- what `authenticated` may write.
        execute 'revoke update on profiles from authenticated';
        execute 'grant update (full_name, first_name, middle_name, last_name, '
             || 'date_of_birth, title, phone, preferred_locale) '
             || 'on profiles to authenticated';
    end if;
    -- anon can never satisfy id = auth.uid() (auth.uid() is null for it), so
    -- this only removes a privilege it could not use — but leaving it granted
    -- is the kind of thing a future policy change turns into a hole.
    if exists (select 1 from pg_roles where rolname = 'anon') then
        execute 'revoke update on profiles from anon';
    end if;
end $$;

create or replace function guard_is_platform_admin()
returns trigger
language plpgsql
security definer
set search_path = public, auth
as $$
declare
    v_caller uuid := auth.uid();
    v_becoming boolean;
begin
    -- Did this statement try to grant or change platform access?
    if tg_op = 'INSERT' then
        v_becoming := coalesce(new.is_platform_admin, false);
    else
        v_becoming := new.is_platform_admin is distinct from old.is_platform_admin;
    end if;

    if v_becoming then
        -- No JWT: the trusted context that seeds the first admin. A signed-in
        -- caller must already hold the flag to touch it — so nobody can hand
        -- it to themselves.
        if v_caller is not null
           and not exists (select 1 from profiles
                           where id = v_caller and is_platform_admin) then
            raise exception 'Only a platform administrator can change platform access'
                using errcode = 'insufficient_privilege';
        end if;
    end if;
    return new;
end;
$$;

drop trigger if exists trg_guard_is_platform_admin on profiles;
create trigger trg_guard_is_platform_admin
    before insert or update on profiles
    for each row execute function guard_is_platform_admin();

-- ------------------------------------------------------------
-- 2. receive_products — the membership check on the zero-cost path
--
-- The only authorisation was inside record_entry(), which this function calls
-- ONLY when the delivery has a cost (`if v_cost > 0`). A delivery with no cost
-- recorded — a normal thing, stock arriving on credit — skipped it and updated
-- another business's product counts and wrote a stock_receipts row with no
-- gate, bypassing that table's own `can_write_org` insert policy. Assert it
-- up front, on every path. Everything else is 016 verbatim.
-- ------------------------------------------------------------

create or replace function receive_products(
    p_org_id      uuid,
    p_product_id  uuid,
    p_quantity    numeric,
    p_unit_cost   numeric     default null,
    p_expires_on  date        default null,
    p_method      text        default 'cash',
    p_client_uuid uuid        default null,
    p_device_id   text        default null,
    p_occurred_at timestamptz default now()
)
returns uuid
language plpgsql
security definer
set search_path = public, auth
as $$
declare
    v_actor    uuid := auth.uid();
    v_name     text;
    v_cost     numeric;
    v_entry    uuid;
    v_existing stock_receipts%rowtype;
begin
    if p_quantity is null or p_quantity <= 0 then
        raise exception 'A delivery needs a quantity';
    end if;

    -- SECURITY (032): the gate that used to exist only for priced deliveries.
    if not can_write_org(p_org_id) then
        raise exception 'You cannot receive stock for this business';
    end if;

    if p_client_uuid is not null then
        select * into v_existing from stock_receipts
        where org_id = p_org_id and client_uuid = p_client_uuid;
        if found then
            return v_existing.entry_id;
        end if;
    end if;

    select name, cost_price into v_name, v_cost
    from products where id = p_product_id and org_id = p_org_id;

    if v_name is null then
        raise exception 'No such product in this business';
    end if;

    v_cost := coalesce(p_unit_cost, v_cost, 0);

    update products set
        quantity   = quantity + p_quantity,
        cost_price = case when p_unit_cost is not null then p_unit_cost
                          else cost_price end,
        expires_on = coalesce(p_expires_on, expires_on)
    where id = p_product_id;

    if v_cost > 0 then
        v_entry := record_entry(
            p_org_id      => p_org_id,
            p_amount      => v_cost * p_quantity,
            p_direction   => 'out',
            p_label       => 'Achat de marchandise',
            p_recorded_by => v_actor,
            p_category    => 'Achats de marchandises',
            p_method      => p_method,
            p_memo        => v_name,
            p_details     => jsonb_build_object('product', v_name,
                                                'quantity', p_quantity),
            p_client_uuid => p_client_uuid,
            p_device_id   => p_device_id,
            p_occurred_at => p_occurred_at
        );
    end if;

    insert into stock_receipts (
        org_id, product_id, quantity, unit_cost, expires_on,
        entry_id, client_uuid, device_id, received_at, received_by
    )
    values (
        p_org_id, p_product_id, p_quantity, v_cost, p_expires_on,
        v_entry, p_client_uuid, p_device_id, p_occurred_at, v_actor
    );

    return v_entry;
end;
$$;

-- ------------------------------------------------------------
-- 3. pay_employee — wages are admin-only
--
-- staff_payments' insert policy is is_org_admin, deliberately stricter than
-- can_write_org because "wages are the most sensitive numbers in a small
-- business" (012). But this definer function was gated only by record_entry's
-- can_write_org, so any non-observer — a cashier, an employee — could record
-- staff payments and post the salary entry, including paying themselves.
-- Assert the table's own rule. Otherwise 012 verbatim.
-- ------------------------------------------------------------

create or replace function pay_employee(
    p_org_id       uuid,
    p_employee_id  uuid,
    p_amount       numeric default null,
    p_label        text    default null,
    p_method       text    default 'cash',
    p_paid_on      date    default current_date,
    p_cover_shifts boolean default true,
    p_client_uuid  uuid    default null
)
returns uuid
language plpgsql
security definer
set search_path = public, auth
as $$
declare
    v_actor    uuid := auth.uid();
    v_name     text;
    v_kind     text;
    v_rate     numeric;
    v_salary   numeric;
    v_amount   numeric;
    v_payment  uuid;
    v_existing uuid;
    v_entry    uuid;
begin
    select full_name, kind, hourly_rate, salary
      into v_name, v_kind, v_rate, v_salary
    from employees where id = p_employee_id and org_id = p_org_id;

    if v_name is null then
        raise exception 'No such employee in this business';
    end if;

    -- SECURITY (032): match staff_payments' own is_org_admin insert policy.
    if not is_org_admin(p_org_id) then
        raise exception 'Only an administrator can record staff payments';
    end if;

    if p_client_uuid is not null then
        select id into v_existing from staff_payments
        where org_id = p_org_id and client_uuid = p_client_uuid;
        if v_existing is not null then
            return v_existing;
        end if;
    end if;

    v_amount := p_amount;
    if v_amount is null then
        if v_kind = 'casual' then
            select round(coalesce(sum(s.hours), 0) * v_rate, 2) into v_amount
            from shifts s
            where s.employee_id = p_employee_id and s.payment_id is null;
        else
            v_amount := v_salary;
        end if;
    end if;

    if v_amount is null or v_amount <= 0 then
        raise exception 'There is nothing to pay %', v_name;
    end if;

    insert into staff_payments (org_id, employee_id, amount, label, method,
                                paid_on, paid_by, client_uuid)
    values (p_org_id, p_employee_id, v_amount,
            coalesce(nullif(btrim(coalesce(p_label, '')), ''),
                     case when v_kind = 'casual' then 'Journées' else 'Salaire' end),
            p_method, p_paid_on, v_actor, p_client_uuid)
    returning id into v_payment;

    if p_cover_shifts then
        update shifts set payment_id = v_payment
        where employee_id = p_employee_id and payment_id is null;
    end if;

    v_entry := record_entry(
        p_org_id      => p_org_id,
        p_amount      => v_amount,
        p_direction   => 'out',
        p_label       => 'Salaires',
        p_recorded_by => v_actor,
        p_category    => 'Salaires',
        p_method      => p_method,
        p_memo        => v_name,
        p_details     => jsonb_build_object('employee', v_name,
                                            'payment_id', v_payment),
        p_client_uuid => p_client_uuid,
        p_occurred_at => p_paid_on::timestamptz
    );

    update staff_payments set entry_id = v_entry where id = v_payment;

    return v_payment;
end;
$$;

-- ------------------------------------------------------------
-- 4. record_shift — a privileged write with no membership check
--
-- Definer, and it checked only that the employee belonged to the org, never
-- that the CALLER did. Anyone who knew an employee id could log shifts into a
-- business they have no part in, bypassing the shifts insert policy. Assert
-- membership. Otherwise 012 verbatim.
-- ------------------------------------------------------------

create or replace function record_shift(
    p_org_id      uuid,
    p_employee_id uuid,
    p_hours       numeric,
    p_worked_on   date default current_date,
    p_note        text default null,
    p_client_uuid uuid default null
)
returns uuid
language plpgsql
security definer
set search_path = public, auth
as $$
declare
    v_actor    uuid := auth.uid();
    v_id       uuid;
    v_existing uuid;
begin
    if not exists (select 1 from employees
                   where id = p_employee_id and org_id = p_org_id) then
        raise exception 'No such employee in this business';
    end if;

    -- SECURITY (032): the shifts insert policy is can_write_org; assert it.
    if not can_write_org(p_org_id) then
        raise exception 'You cannot record shifts for this business';
    end if;

    if p_client_uuid is not null then
        select id into v_existing from shifts
        where org_id = p_org_id and client_uuid = p_client_uuid;
        if v_existing is not null then
            return v_existing;
        end if;
    end if;

    insert into shifts (org_id, employee_id, worked_on, hours, note,
                        recorded_by, client_uuid)
    values (p_org_id, p_employee_id, p_worked_on, p_hours, p_note,
            v_actor, p_client_uuid)
    returning id into v_id;

    return v_id;
end;
$$;

-- ------------------------------------------------------------
-- 5. record_return — assert membership up front
--
-- record_entry() enforces can_write_org for a return that posts money, but a
-- zero-total return posts none and reached no check while still updating
-- stock. Same shape as receive_products. Rather than restate the whole of
-- 029, the guard is added by CREATE OR REPLACE with the body carried over.
-- ------------------------------------------------------------

create or replace function record_return(
    p_sale_id     uuid,
    p_note        text default null,
    p_client_uuid uuid default null
)
returns uuid
language plpgsql
security definer
set search_path = public, auth
as $$
declare
    v_actor    uuid := auth.uid();
    v_org      uuid;
    v_method   text;
    v_total    numeric;
    v_kind     text;
    v_return   uuid;
    v_existing uuid;
    v_line     record;
    v_entry    uuid;
begin
    select org_id, method, total, kind
      into v_org, v_method, v_total, v_kind
    from sales where id = p_sale_id;

    if v_org is null then
        raise exception 'No such sale';
    end if;

    -- SECURITY (032): a zero-total return posts no entry and so met no gate.
    if not can_write_org(v_org) then
        raise exception 'You cannot record a return for this business';
    end if;

    if v_kind = 'return' then
        raise exception 'That is already a return';
    end if;
    if v_method = 'credit' then
        raise exception 'A credit sale is settled in the carnet, not by a return';
    end if;
    if exists (select 1 from sales where reverses_id = p_sale_id) then
        raise exception 'That sale has already been returned';
    end if;

    if p_client_uuid is not null then
        select id into v_existing from sales
        where org_id = v_org and client_uuid = p_client_uuid;
        if v_existing is not null then
            return v_existing;
        end if;
    end if;

    insert into sales (org_id, kind, method, note, total, reverses_id,
                       recorded_by, client_uuid)
    values (v_org, 'return', v_method, p_note, v_total, p_sale_id,
            v_actor, p_client_uuid)
    returning id into v_return;

    for v_line in select * from sale_lines where sale_id = p_sale_id
    loop
        insert into sale_lines (sale_id, product_id, name, quantity,
                                unit_price, unit_cost, line_total)
        values (v_return, v_line.product_id, v_line.name, v_line.quantity,
                v_line.unit_price, v_line.unit_cost, v_line.line_total);

        update products set quantity = quantity + v_line.quantity
        where id = v_line.product_id;
    end loop;

    if v_total > 0 then
        v_entry := record_entry(
            p_org_id      => v_org,
            p_amount      => v_total,
            p_direction   => 'out',
            p_label       => 'Retour de vente',
            p_recorded_by => v_actor,
            p_category    => 'Ventes',
            p_method      => v_method,
            p_memo        => p_note,
            p_details     => jsonb_build_object('reverses', p_sale_id),
            p_client_uuid => p_client_uuid
        );
        update sales set entry_id = v_entry where id = v_return;
    end if;

    return v_return;
end;
$$;

-- ------------------------------------------------------------
-- 6. notifications — a recipient may mark read, nothing more
--
-- The UPDATE policy checks `recipient_id = auth.uid()`, which — being row
-- level — let a recipient rewrite the message, kind or org_id of their own
-- notifications, not merely the read timestamp the feature intends. Same
-- column-grant treatment as profiles: read_at only.
-- ------------------------------------------------------------

do $$
begin
    if exists (select 1 from pg_roles where rolname = 'authenticated') then
        execute 'revoke update on notifications from authenticated';
        execute 'grant update (read_at) on notifications to authenticated';
    end if;
end $$;

-- ------------------------------------------------------------
-- 7. feature_access — fail closed for an anonymous caller
--
-- It returned 'edit' when auth.uid() is null. Nothing reachable depends on
-- that (every caller pairs it with can_write_org, which an anon fails), but a
-- permission function whose most-open answer is its answer for "nobody signed
-- in" is a landmine for the next policy that forgets the pairing. 'hidden'.
-- Otherwise 031 verbatim.
-- ------------------------------------------------------------

create or replace function feature_access(p_org_id uuid, p_feature text)
returns text
language plpgsql
stable
security definer
set search_path = public, auth
as $$
declare
    v_roles  text[];
    v_tier   text;
    v_access text;
begin
    if auth.uid() is null then
        return 'hidden';
    end if;

    select array_agg(distinct role) into v_roles
      from memberships
     where org_id = p_org_id and user_id = auth.uid();

    if v_roles is null then
        return 'hidden';
    end if;
    if v_roles && array['owner', 'super_admin', 'admin'] then
        return 'edit';
    end if;

    v_tier := case
        when v_roles && array['manager', 'supervisor'] then 'supervisor'
        else 'employee'
    end;

    select access into v_access
      from org_feature_rules
     where org_id = p_org_id and tier = v_tier and feature = p_feature;

    return coalesce(v_access,
        case when p_feature = 'reports' then 'view' else 'edit' end);
end;
$$;

notify pgrst, 'reload schema';


-- ============================================================
-- 033_farm_edits.sql
-- ============================================================
-- ============================================================
-- 033_farm_edits.sql — correcting a farm entry after it is recorded.
--
-- The farm records events the way a notebook does: a line per mortality, per
-- weighing, per harvest. A notebook lets you cross a wrong number out and write
-- the right one, and until now the app did not — a mistyped "70 dead" instead
-- of "7" could only be lived with. These three functions let an entry be
-- corrected in place.
--
-- Why a plain UPDATE and not a reversal, when sales and stock use reversals:
-- those post to the double-entry ledger, where a figure, once booked, has to
-- be unbooked by an equal and opposite figure so the books always balance. A
-- flock event, a herd event and a harvest post NO ledger entry (bringing a
-- crop in is not earning money — see record_harvest). There is nothing to keep
-- balanced, so the honest correction is to fix the number, exactly as the
-- notebook does. Selling still goes through the ledger and still corrects by
-- reversal; this is only for the physical counts.
--
-- All three are SECURITY DEFINER with a can_write_org() guard, the same shape
-- as the record_* functions they mirror: the event tables have no UPDATE
-- policy (writing was always through a function), so the guard here IS the
-- authorization. An observer cannot correct what an observer cannot record.
-- ============================================================

-- ------------------------------------------------------------
-- Flock events (009): org is reached through the flock, which carries it.
-- ------------------------------------------------------------
create or replace function update_flock_event(
    p_event_id    uuid,
    p_quantity    numeric     default null,
    p_kind        text        default null,
    p_note        text        default null,
    p_occurred_at timestamptz default null
)
returns uuid
language plpgsql
security definer
set search_path = public, auth
as $$
declare
    v_org uuid;
begin
    if auth.uid() is null then
        raise exception 'update_flock_event() needs a signed-in caller';
    end if;

    select f.org_id into v_org
      from flock_events e
      join flocks f on f.id = e.flock_id
     where e.id = p_event_id;

    if v_org is null then
        raise exception 'No such flock event';
    end if;
    if not can_write_org(v_org) then
        raise exception 'You cannot correct entries for this business';
    end if;
    if p_quantity is not null and p_quantity < 0 then
        raise exception 'A count cannot be negative (got %)', p_quantity;
    end if;

    update flock_events set
        quantity    = coalesce(p_quantity, quantity),
        kind        = coalesce(nullif(btrim(coalesce(p_kind, '')), ''), kind),
        note        = coalesce(p_note, note),
        occurred_at = coalesce(p_occurred_at, occurred_at)
    where id = p_event_id;

    return p_event_id;
end;
$$;

-- ------------------------------------------------------------
-- Herd events (019): org_id is on the row.
-- ------------------------------------------------------------
create or replace function update_herd_event(
    p_event_id    uuid,
    p_quantity    numeric default null,
    p_kind        text    default null,
    p_note        text    default null,
    p_occurred_on date    default null
)
returns uuid
language plpgsql
security definer
set search_path = public, auth
as $$
declare
    v_org uuid;
begin
    if auth.uid() is null then
        raise exception 'update_herd_event() needs a signed-in caller';
    end if;

    select org_id into v_org from herd_events where id = p_event_id;

    if v_org is null then
        raise exception 'No such herd event';
    end if;
    if not can_write_org(v_org) then
        raise exception 'You cannot correct entries for this business';
    end if;
    if p_quantity is not null and p_quantity < 0 then
        raise exception 'A count cannot be negative (got %)', p_quantity;
    end if;

    update herd_events set
        quantity    = coalesce(p_quantity, quantity),
        kind        = coalesce(nullif(btrim(coalesce(p_kind, '')), ''), kind),
        note        = coalesce(p_note, note),
        occurred_on = coalesce(p_occurred_on, occurred_on)
    where id = p_event_id;

    return p_event_id;
end;
$$;

-- ------------------------------------------------------------
-- Harvests (019): org_id is on the row. Quantity must stay positive — a
-- harvest of nothing is not a harvest, it is a deletion, which is a different
-- act the app does not offer here.
-- ------------------------------------------------------------
create or replace function update_harvest(
    p_harvest_id   uuid,
    p_quantity     numeric default null,
    p_grade        text    default null,
    p_note         text    default null,
    p_harvested_on date    default null
)
returns uuid
language plpgsql
security definer
set search_path = public, auth
as $$
declare
    v_org uuid;
begin
    if auth.uid() is null then
        raise exception 'update_harvest() needs a signed-in caller';
    end if;

    select org_id into v_org from harvests where id = p_harvest_id;

    if v_org is null then
        raise exception 'No such harvest';
    end if;
    if not can_write_org(v_org) then
        raise exception 'You cannot correct entries for this business';
    end if;
    if p_quantity is not null and p_quantity <= 0 then
        raise exception 'How much was harvested? (got %)', p_quantity;
    end if;

    update harvests set
        quantity     = coalesce(p_quantity, quantity),
        grade        = coalesce(nullif(btrim(coalesce(p_grade, '')), ''), grade),
        note         = coalesce(p_note, note),
        harvested_on = coalesce(p_harvested_on, harvested_on)
    where id = p_harvest_id;

    return p_harvest_id;
end;
$$;

-- ------------------------------------------------------------
-- GRANTS
-- ------------------------------------------------------------
do $$
begin
    if exists (select 1 from pg_roles where rolname = 'authenticated') then
        grant execute on function update_flock_event(uuid, numeric, text, text, timestamptz) to authenticated;
        grant execute on function update_herd_event(uuid, numeric, text, text, date) to authenticated;
        grant execute on function update_harvest(uuid, numeric, text, text, date) to authenticated;
    end if;
end $$;

notify pgrst, 'reload schema';


-- ============================================================
-- 034_production_edit.sql
-- ============================================================
-- ============================================================
-- 034_production_edit.sql — correcting a production run after it is recorded.
--
-- A batch is recorded the morning it is made: "40 cakes from this much flour,
-- sugar, eggs". A wrong output count — 40 typed as 20 — could only be lived
-- with until now. update_production_run() corrects the run in place, the same
-- shape as the farm corrections (033) and for the same reason: a production run
-- posts NO ledger entry (see 026), so there is nothing to keep balanced and the
-- honest fix is to change the number.
--
-- What a correction does NOT do: re-run the stock math. The ingredients a batch
-- consumed are snapshotted per run and are a fact about what left the shelf that
-- morning; correcting how many cakes came out does not un-consume flour. So the
-- inputs and the run's total_cost are left exactly as recorded, and only the
-- OUTPUT is corrected — with one derived consequence: unit_cost is total_cost
-- over quantity, so fixing "20" to "40" halves what each cake costs to make,
-- which is precisely the correction intended. A wrong INGREDIENT is a different
-- act (re-record the run); this is for the output count, its name, its note.
--
-- SECURITY DEFINER with a can_write_org() guard, mirroring record_production.
-- Note it also passes under the trg_guard_feature_edit trigger 031 put on
-- production_runs: an employee dialled to 'view' on production cannot correct a
-- run any more than they can record one. That is enforced by the trigger on the
-- UPDATE below, on top of the guard here.
-- ============================================================

create or replace function update_production_run(
    p_run_id       uuid,
    p_quantity     numeric     default null,
    p_product_name text        default null,
    p_note         text        default null,
    p_occurred_at  timestamptz default null
)
returns uuid
language plpgsql
security definer
set search_path = public, auth
as $$
declare
    v_org uuid;
begin
    if auth.uid() is null then
        raise exception 'update_production_run() needs a signed-in caller';
    end if;

    select org_id into v_org from production_runs where id = p_run_id;

    if v_org is null then
        raise exception 'No such production run';
    end if;
    if not can_write_org(v_org) then
        raise exception 'You cannot correct entries for this business';
    end if;
    if p_quantity is not null and p_quantity <= 0 then
        raise exception 'A production needs the quantity that was made (got %)',
            p_quantity;
    end if;

    update production_runs set
        quantity     = coalesce(p_quantity, quantity),
        product_name = coalesce(nullif(btrim(coalesce(p_product_name, '')), ''),
                                product_name),
        note         = coalesce(p_note, note),
        occurred_at  = coalesce(p_occurred_at, occurred_at),
        -- The ingredients, and so total_cost, are unchanged by a correction to
        -- the output count. Unit cost re-derives from the fixed total.
        unit_cost    = case
                         when p_quantity is not null and p_quantity > 0
                         then round(total_cost / p_quantity, 4)
                         else unit_cost
                       end
    where id = p_run_id;

    return p_run_id;
end;
$$;

do $$
begin
    if exists (select 1 from pg_roles where rolname = 'authenticated') then
        grant execute on function update_production_run(uuid, numeric, text, text, timestamptz) to authenticated;
    end if;
end $$;

notify pgrst, 'reload schema';


-- ============================================================
-- 035_church_to_association.sql
-- ============================================================
-- ============================================================
-- 035_church_to_association.sql — the church profile becomes association.
--
-- A church and a neighbourhood association keep books the same way: members,
-- and money given by them or spent for them. The app was written church-first
-- and the word was everywhere; this makes "Association" the name a new business
-- picks and the word it reads, and migrates the businesses already on the
-- church profile so they read as associations too — with every row of their
-- data intact.
--
-- HOW DEEP, AND WHY NOT DEEPER. This renames what a user sees (the profile
-- value, and every French label — done in the app) and nothing the database
-- names internally. The physical `church_members` table keeps its name. That
-- is deliberate, not laziness: functions created in earlier migrations (member
-- giving statements in 006, the console's data catalog in 008) name
-- `church_members` in their bodies, and those migrations run *before* this one
-- every single time the paste-once bundle is applied. Renaming the table here
-- and recreating those functions to say `members` would work on a first run and
-- fail on the second, when 006 and 008 rebuild their references against a table
-- that no longer exists. Re-runnability is a hard requirement of the bundle, so
-- the table name stays `church_members` and only the profile value moves.
--
-- What DOES change here: the profile value 'church' -> 'association' on existing
-- businesses, and the three functions that decide behaviour by profile now
-- accept both values, so nothing depends on the migration having reached every
-- row before the code does.
-- ============================================================

-- ------------------------------------------------------------
-- 1. Businesses already on the church profile read as associations now.
--    Idempotent.
-- ------------------------------------------------------------
update orgs set profile = 'association' where profile = 'church';

-- ------------------------------------------------------------
-- 2. The three functions that branch on profile accept both values, so a
--    business created or approved as either seeds the same chart, and so this
--    does not depend on step 1 having run first. Only that one condition each
--    changes; the rest is 011 / 017 / 014 verbatim.
-- ------------------------------------------------------------

-- create_org (011): seed the members/association chart for either value.
create or replace function create_org(
    p_name     text,
    p_slug     text,
    p_profile  text default 'generic',
    p_currency text default 'XOF'
)
returns uuid
language plpgsql
security definer
set search_path = public, auth
as $$
declare
    v_org_id uuid;
begin
    if not exists(select 1 from profiles where id = auth.uid() and is_platform_admin) then
        raise exception 'Only a platform admin can create a new business';
    end if;

    insert into orgs (name, slug, profile, default_currency)
    values (p_name, p_slug, p_profile, p_currency)
    returning id into v_org_id;

    insert into memberships (org_id, user_id, role, scope_kind, scope_id)
    values (v_org_id, auth.uid(), 'owner', 'org', v_org_id);

    if p_profile in ('church', 'association') then
        perform seed_church_accounts(v_org_id);
    elsif p_profile = 'retail' then
        perform seed_retail_accounts(v_org_id);
    else
        insert into accounts (org_id, code, name, type) values
            (v_org_id, '1000', 'Cash on Hand',        'asset'),
            (v_org_id, '1010', 'Bank Account',        'asset'),
            (v_org_id, '1020', 'Mobile Money',        'asset'),
            (v_org_id, '4000', 'Sales',                'income'),
            (v_org_id, '5000', 'Purchases',            'expense'),
            (v_org_id, '5010', 'Operating Expenses',   'expense')
        on conflict (org_id, code) do nothing;
    end if;

    return v_org_id;
end;
$$;

-- approve_org_application (017): same, for a business born from an application.
create or replace function approve_org_application(
    p_application_id uuid,
    p_note           text default null
)
returns uuid
language plpgsql
security definer
set search_path = public, auth
as $$
declare
    v_actor uuid := auth.uid();
    v_app   org_applications%rowtype;
    v_org   uuid;
begin
    if v_actor is null then
        raise exception 'approve_org_application() needs a signed-in caller';
    end if;

    if not exists (select 1 from profiles where id = v_actor and is_platform_admin) then
        raise exception 'Only a platform admin can approve a business';
    end if;

    select * into v_app from org_applications
    where id = p_application_id for update;
    if not found then
        raise exception 'No such application';
    end if;
    if v_app.status <> 'pending' then
        raise exception 'This application has already been %', v_app.status;
    end if;

    if exists (select 1 from orgs where slug = v_app.slug) then
        raise exception
            'The address % was taken while this was waiting. Ask them for another.',
            v_app.slug;
    end if;

    insert into orgs (name, slug, profile, default_currency)
    values (v_app.name, v_app.slug, v_app.profile, v_app.currency)
    returning id into v_org;

    insert into memberships (org_id, user_id, role, scope_kind, scope_id)
    values (v_org, v_app.applicant_id, 'owner', 'org', v_org)
    on conflict do nothing;

    if v_app.profile in ('church', 'association') then
        perform seed_church_accounts(v_org);
    elsif v_app.profile = 'retail' then
        perform seed_retail_accounts(v_org);
    elsif v_app.profile = 'farm' then
        perform seed_farm_accounts(v_org);
    else
        insert into accounts (org_id, code, name, type) values
            (v_org, '1000', 'Cash on Hand',      'asset'),
            (v_org, '1010', 'Bank Account',      'asset'),
            (v_org, '1020', 'Mobile Money',      'asset'),
            (v_org, '4000', 'Sales',             'income'),
            (v_org, '5000', 'Purchases',         'expense'),
            (v_org, '5010', 'Operating Expenses','expense')
        on conflict (org_id, code) do nothing;
    end if;

    update org_applications set
        status        = 'approved',
        decision_note = nullif(btrim(coalesce(p_note, '')), ''),
        reviewed_by   = v_actor,
        reviewed_at   = now(),
        org_id        = v_org
    where id = p_application_id;

    return v_org;
end;
$$;

-- update_org (014): 'association' is a known profile; 'church' stays accepted
-- so a business mid-migration is never refused its own edit.
create or replace function update_org(
    p_org_id   uuid,
    p_name     text default null,
    p_slug     text default null,
    p_profile  text default null,
    p_currency text default null
)
returns uuid
language plpgsql
security definer
set search_path = public, auth
as $$
declare
    v_actor   uuid := auth.uid();
    v_name    text := nullif(btrim(coalesce(p_name, '')), '');
    v_slug    text := nullif(lower(btrim(coalesce(p_slug, ''))), '');
    v_profile text := nullif(btrim(coalesce(p_profile, '')), '');
    v_problem text;
begin
    if v_actor is null then
        raise exception 'update_org() needs a signed-in caller';
    end if;

    if not is_org_admin(p_org_id) then
        raise exception 'You cannot change this business';
    end if;

    if not exists (select 1 from orgs where id = p_org_id) then
        raise exception 'No such business';
    end if;

    if exists (select 1 from orgs where id = p_org_id and archived_at is not null) then
        raise exception 'This business is archived. Restore it before changing it.';
    end if;

    if v_slug is not null then
        v_problem := org_slug_problem(v_slug);
        if v_problem is not null then
            raise exception '%', v_problem;
        end if;
        if exists (select 1 from orgs where slug = v_slug and id <> p_org_id) then
            raise exception 'That address is already taken.';
        end if;
    end if;

    if v_profile is not null
       and v_profile not in ('church', 'association', 'farm', 'retail', 'generic') then
        raise exception 'Unknown profile: %', v_profile;
    end if;

    update orgs set
        name             = coalesce(v_name, name),
        slug             = coalesce(v_slug, slug),
        profile          = coalesce(v_profile, profile),
        default_currency = coalesce(nullif(btrim(coalesce(p_currency, '')), ''),
                                    default_currency)
    where id = p_org_id;

    return p_org_id;
end;
$$;

notify pgrst, 'reload schema';


-- ============================================================
-- 036_analytics.sql
-- ============================================================
-- ============================================================
-- 036_analytics.sql — the numbers a business owner and the platform actually
-- want to see, computed on the server where the rows live.
--
-- The user asked, in their words, to know "what sells more or less, when, how
-- fast, and other smart things" for a business owner, and the same across every
-- business for the platform. That is five owner-facing read functions and two
-- platform-wide ones. All of them read the sales the retail/church/farm modules
-- already write (sales + sale_lines from 011); none of them stores a derived
-- number, because a cached analytic shown without a date is a lie waiting to
-- happen (the same reason the reports in 006 cache nothing).
--
-- WHO MAY READ WHAT. The five owner functions raise unless the caller has full
-- visibility of that one business — an employee restricted to the till never
-- computes the owner's margins — and they read as the caller so RLS still
-- covers every table underneath (006 already limits sale_lines to full
-- visibility). The two platform functions are SECURITY DEFINER and raise unless
-- the caller is a platform admin; they cross every org on purpose, which is
-- exactly what RLS would stop, so the is_platform_admin gate is the whole guard
-- and is checked first.
--
-- WHY FUNCTIONS, NOT VIEWS. A view added to this schema must carry
-- security_invoker = on or it reads as its owner and leaks (the standing rule).
-- Aggregates that must branch on the caller's role are clearer and safer as
-- functions with an explicit gate, so there are no views here.
-- ============================================================

-- ------------------------------------------------------------
-- 1. Owner: the headline. One row of the numbers that go on the cards at the
--    top — revenue, margin, how many sales, the average basket, units moved —
--    over a window ending now. p_since null means "all of time".
-- ------------------------------------------------------------
create or replace function org_sales_headline(
    p_org_id uuid,
    p_since  timestamptz default null
)
returns table (
    sale_count      bigint,
    revenue         numeric,
    cost            numeric,
    margin          numeric,
    units           numeric,
    avg_basket      numeric,
    products_sold   bigint
)
language plpgsql
stable
security invoker
set search_path = public
as $$
begin
    if not has_full_visibility(p_org_id) then
        raise exception 'You cannot read this business''s analytics';
    end if;

    return query
    with s as (
        select sa.id, sa.total
        from sales sa
        where sa.org_id = p_org_id
          and sa.kind = 'sale'
          and (p_since is null or sa.occurred_at >= p_since)
    ),
    lines as (
        select sl.quantity, sl.unit_cost, sl.line_total, sl.name
        from sale_lines sl
        join s on s.id = sl.sale_id
    )
    select
        (select count(*) from s),
        coalesce((select sum(total) from s), 0),
        coalesce((select sum(quantity * unit_cost) from lines), 0),
        coalesce((select sum(line_total) from lines), 0)
            - coalesce((select sum(quantity * unit_cost) from lines), 0),
        coalesce((select sum(quantity) from lines), 0),
        case when (select count(*) from s) = 0 then 0
             else round(coalesce((select sum(total) from s), 0)
                  / (select count(*) from s), 2) end,
        (select count(distinct lower(btrim(name))) from lines);
end;
$$;

-- ------------------------------------------------------------
-- 2. Owner: what sells more or less, and how fast. One row per product name
--    sold in the window, ranked by revenue: units, revenue, margin, and a
--    velocity — units per day across the span it actually sold on, which is
--    the "how fast" the user asked for.
-- ------------------------------------------------------------
create or replace function org_product_performance(
    p_org_id uuid,
    p_since  timestamptz default null,
    p_limit  int default 100
)
returns table (
    name          text,
    units         numeric,
    revenue       numeric,
    margin        numeric,
    sale_count    bigint,
    first_sold    timestamptz,
    last_sold     timestamptz,
    per_day       numeric
)
language plpgsql
stable
security invoker
set search_path = public
as $$
begin
    if not has_full_visibility(p_org_id) then
        raise exception 'You cannot read this business''s analytics';
    end if;

    return query
    with lines as (
        select lower(btrim(sl.name)) as key,
               sl.name as raw_name,
               sl.quantity, sl.unit_cost, sl.line_total, sa.occurred_at
        from sale_lines sl
        join sales sa on sa.id = sl.sale_id
        where sa.org_id = p_org_id
          and sa.kind = 'sale'
          and (p_since is null or sa.occurred_at >= p_since)
    )
    select
        min(raw_name),
        sum(quantity),
        sum(line_total),
        sum(line_total) - sum(quantity * unit_cost),
        count(*),
        min(occurred_at),
        max(occurred_at),
        -- Units per day over the span it sold on; a product that sold within a
        -- single day counts its run as one day rather than dividing by zero.
        round(
            sum(quantity)
            / greatest(1, extract(epoch from (max(occurred_at) - min(occurred_at))) / 86400.0),
            2
        )
    from lines
    group by key
    order by 3 desc
    limit greatest(1, p_limit);
end;
$$;

-- ------------------------------------------------------------
-- 3. Owner: when. Revenue and count by hour of the day (0-23), so the owner
--    sees the hours the shop actually earns in.
-- ------------------------------------------------------------
create or replace function org_sales_by_hour(
    p_org_id uuid,
    p_since  timestamptz default null
)
returns table (
    hour        int,
    sale_count  bigint,
    revenue     numeric
)
language plpgsql
stable
security invoker
set search_path = public
as $$
begin
    if not has_full_visibility(p_org_id) then
        raise exception 'You cannot read this business''s analytics';
    end if;

    return query
    select
        extract(hour from sa.occurred_at)::int,
        count(*),
        coalesce(sum(sa.total), 0)
    from sales sa
    where sa.org_id = p_org_id
      and sa.kind = 'sale'
      and (p_since is null or sa.occurred_at >= p_since)
    group by 1
    order by 1;
end;
$$;

-- ------------------------------------------------------------
-- 4. Owner: when, the other axis. Revenue and count by day of week
--    (0 = Sunday .. 6 = Saturday, Postgres dow).
-- ------------------------------------------------------------
create or replace function org_sales_by_weekday(
    p_org_id uuid,
    p_since  timestamptz default null
)
returns table (
    dow         int,
    sale_count  bigint,
    revenue     numeric
)
language plpgsql
stable
security invoker
set search_path = public
as $$
begin
    if not has_full_visibility(p_org_id) then
        raise exception 'You cannot read this business''s analytics';
    end if;

    return query
    select
        extract(dow from sa.occurred_at)::int,
        count(*),
        coalesce(sum(sa.total), 0)
    from sales sa
    where sa.org_id = p_org_id
      and sa.kind = 'sale'
      and (p_since is null or sa.occurred_at >= p_since)
    group by 1
    order by 1;
end;
$$;

-- ------------------------------------------------------------
-- 5. Owner: the trend. Revenue and count per calendar day, for the line the
--    owner watches go up or down.
-- ------------------------------------------------------------
create or replace function org_sales_daily(
    p_org_id uuid,
    p_since  timestamptz default null
)
returns table (
    day         date,
    sale_count  bigint,
    revenue     numeric
)
language plpgsql
stable
security invoker
set search_path = public
as $$
begin
    if not has_full_visibility(p_org_id) then
        raise exception 'You cannot read this business''s analytics';
    end if;

    return query
    select
        (sa.occurred_at at time zone 'UTC')::date,
        count(*),
        coalesce(sum(sa.total), 0)
    from sales sa
    where sa.org_id = p_org_id
      and sa.kind = 'sale'
      and (p_since is null or sa.occurred_at >= p_since)
    group by 1
    order by 1;
end;
$$;

-- ------------------------------------------------------------
-- 6. Platform: every business, side by side. One row per org — its name,
--    profile, revenue, margin, sale count, last sale — for the console.
--    SECURITY DEFINER, platform admin only, crosses RLS on purpose.
-- ------------------------------------------------------------
create or replace function platform_business_performance(
    p_since timestamptz default null
)
returns table (
    org_id      uuid,
    org_name    text,
    profile     text,
    sale_count  bigint,
    revenue     numeric,
    margin      numeric,
    units       numeric,
    last_sale   timestamptz
)
language plpgsql
stable
security definer
set search_path = public, auth
as $$
begin
    if not exists (select 1 from profiles
                   where id = auth.uid() and is_platform_admin) then
        raise exception 'Only a platform admin can read cross-business analytics';
    end if;

    return query
    with line_agg as (
        select sa.org_id,
               sum(sl.line_total)              as revenue_lines,
               sum(sl.quantity * sl.unit_cost) as cost_lines,
               sum(sl.quantity)                as units
        from sales sa
        join sale_lines sl on sl.sale_id = sa.id
        where sa.kind = 'sale'
          and (p_since is null or sa.occurred_at >= p_since)
        group by sa.org_id
    ),
    sale_agg as (
        select sa.org_id,
               count(*)            as sale_count,
               sum(sa.total)       as revenue,
               max(sa.occurred_at) as last_sale
        from sales sa
        where sa.kind = 'sale'
          and (p_since is null or sa.occurred_at >= p_since)
        group by sa.org_id
    )
    select
        o.id,
        o.name,
        o.profile,
        coalesce(sag.sale_count, 0),
        coalesce(sag.revenue, 0),
        coalesce(lag.revenue_lines, 0) - coalesce(lag.cost_lines, 0),
        coalesce(lag.units, 0),
        sag.last_sale
    from orgs o
    left join sale_agg sag on sag.org_id = o.id
    left join line_agg lag on lag.org_id = o.id
    where o.archived_at is null
    order by coalesce(sag.revenue, 0) desc;
end;
$$;

-- ------------------------------------------------------------
-- 7. Platform: the one-line total across the whole platform.
-- ------------------------------------------------------------
create or replace function platform_analytics_headline(
    p_since timestamptz default null
)
returns table (
    businesses        bigint,
    active_businesses bigint,
    sale_count        bigint,
    revenue           numeric,
    margin            numeric
)
language plpgsql
stable
security definer
set search_path = public, auth
as $$
begin
    if not exists (select 1 from profiles
                   where id = auth.uid() and is_platform_admin) then
        raise exception 'Only a platform admin can read platform analytics';
    end if;

    return query
    with s as (
        select sa.id, sa.org_id, sa.total
        from sales sa
        where sa.kind = 'sale'
          and (p_since is null or sa.occurred_at >= p_since)
    ),
    lines as (
        select sl.quantity, sl.unit_cost, sl.line_total
        from sale_lines sl
        join s on s.id = sl.sale_id
    )
    select
        (select count(*) from orgs where archived_at is null),
        (select count(distinct org_id) from s),
        (select count(*) from s),
        coalesce((select sum(total) from s), 0),
        coalesce((select sum(line_total) from lines), 0)
            - coalesce((select sum(quantity * unit_cost) from lines), 0);
end;
$$;

-- Guarded because the migration runs before any test creates the role, and on
-- a fresh cluster `authenticated` (a Supabase-managed role) does not exist yet
-- — every grant in this schema is wrapped this way for the same reason.
do $$
begin
    if exists (select 1 from pg_roles where rolname = 'authenticated') then
        grant execute on function org_sales_headline(uuid, timestamptz)           to authenticated;
        grant execute on function org_product_performance(uuid, timestamptz, int) to authenticated;
        grant execute on function org_sales_by_hour(uuid, timestamptz)            to authenticated;
        grant execute on function org_sales_by_weekday(uuid, timestamptz)         to authenticated;
        grant execute on function org_sales_daily(uuid, timestamptz)              to authenticated;
        grant execute on function platform_business_performance(timestamptz)      to authenticated;
        grant execute on function platform_analytics_headline(timestamptz)        to authenticated;
    end if;
end $$;

notify pgrst, 'reload schema';


-- ============================================================
-- 037_wave_payment.sql
-- ============================================================
-- ============================================================
-- 037_wave_payment.sql — preparing the ground for Wave mobile payments.
--
-- The plan the user set: at a sale, offer Wave; show the merchant's Wave QR so
-- the customer scans and pays; later, when a payment signal can be wired in,
-- the app confirms automatically and prints a receipt carrying the Wave
-- sender's name. This migration builds everything that does not need the live
-- signal — the data model, the account routing, and the two small functions the
-- app calls — and leaves a clean seam where the webhook will attach later.
--
-- WHAT IS DELIBERATELY NOT HERE. No Wave API call, no secret, no webhook. Those
-- need a Wave merchant credential held as a Worker secret, which is a separate,
-- guarded step. Until then the owner confirms a Wave payment by hand (they are
-- standing there watching the customer's phone), and `attach_wave_payment`
-- records it exactly as the webhook eventually will — so wiring the signal is a
-- matter of calling the same function from the Worker, not reworking this.
--
-- WHY record_sale IS NOT REWRITTEN. A Wave sale is an ordinary sale whose money
-- lands in mobile money; the only new facts are the payer's name and a
-- reference. Reproducing the 180-line record_sale (029) just to store two
-- columns is how the two copies drift apart. Instead 'wave' is taught to the
-- account router, and a second small call stamps the Wave facts onto the sale
-- record_sale already returned.
-- ============================================================

-- ------------------------------------------------------------
-- 1. The merchant's Wave handle, per business. This is what the QR encodes;
--    the owner sets it once in settings. Null until they do — the sale sheet
--    then knows not to offer Wave.
-- ------------------------------------------------------------
alter table orgs add column if not exists wave_merchant text;

-- ------------------------------------------------------------
-- 2. The Wave facts on a sale. All null for every non-Wave sale, so nothing
--    existing changes and the columns mean something only where they are set.
--      wave_sender    — the name Wave reports for the payer, for the receipt.
--      payment_ref    — Wave's transaction id, for reconciliation later.
--      payment_status — 'pending' | 'confirmed'. The seam for auto-confirm:
--                       today it is written 'confirmed' by the owner's hand;
--                       tomorrow by the webhook, unchanged here.
-- ------------------------------------------------------------
alter table sales add column if not exists wave_sender    text;
alter table sales add column if not exists payment_ref    text;
alter table sales add column if not exists payment_status text
    check (payment_status is null or payment_status in ('pending', 'confirmed'));

-- ------------------------------------------------------------
-- 3. A Wave sale's money is mobile money. The router in 007 sent any unknown
--    method to an account named after it; 'wave' would have minted a stray
--    "wave" asset account. Teach it that Wave is mobile money (1020), so the
--    books read a Wave sale beside every other mobile-money one. Rest verbatim.
-- ------------------------------------------------------------
create or replace function resolve_cash_account(
    p_org_id uuid,
    p_method text,
    p_actor  uuid default null
)
returns uuid
language plpgsql
as $$
begin
    return case btrim(lower(coalesce(p_method, 'cash')))
        when 'cash'         then ensure_account_by_code(p_org_id, '1000', 'Cash on Hand', 'asset', p_actor)
        when 'bank'         then ensure_account_by_code(p_org_id, '1010', 'Bank Account', 'asset', p_actor)
        when 'mobile_money' then ensure_account_by_code(p_org_id, '1020', 'Mobile Money', 'asset', p_actor)
        when 'wave'         then ensure_account_by_code(p_org_id, '1020', 'Mobile Money', 'asset', p_actor)
        else ensure_account(p_org_id, p_method, 'asset', p_actor)
    end;
end;
$$;
revoke execute on function resolve_cash_account(uuid, text, uuid) from public;

-- ------------------------------------------------------------
-- 4. The owner sets (or clears) their Wave handle. Admin-only, their own
--    business only — the same gate update_org uses.
-- ------------------------------------------------------------
create or replace function set_org_wave(
    p_org_id   uuid,
    p_merchant text
)
returns void
language plpgsql
security definer
set search_path = public, auth
as $$
begin
    if auth.uid() is null then
        raise exception 'set_org_wave() needs a signed-in caller';
    end if;
    if not is_org_admin(p_org_id) then
        raise exception 'Only an administrator can change the Wave account';
    end if;
    update orgs
       set wave_merchant = nullif(btrim(coalesce(p_merchant, '')), '')
     where id = p_org_id;
end;
$$;

-- ------------------------------------------------------------
-- 5. Stamp the Wave facts onto a sale. Called by the app right after
--    record_sale for a Wave payment, and — once the signal is wired — by the
--    Worker webhook with the same arguments. Idempotent: re-running with the
--    same values changes nothing, so a retried confirmation is safe.
--
--    Gated by can_write_org on the sale's own org: whoever may record the sale
--    may confirm its payment, and no one may touch another business's sale.
-- ------------------------------------------------------------
create or replace function attach_wave_payment(
    p_sale_id uuid,
    p_sender  text,
    p_ref     text default null,
    p_status  text default 'confirmed'
)
returns void
language plpgsql
security definer
set search_path = public, auth
as $$
declare
    v_org uuid;
begin
    if auth.uid() is null then
        raise exception 'attach_wave_payment() needs a signed-in caller';
    end if;

    select org_id into v_org from sales where id = p_sale_id;
    if v_org is null then
        raise exception 'No such sale';
    end if;
    if not can_write_org(v_org) then
        raise exception 'You cannot confirm payment for this business';
    end if;
    if coalesce(p_status, 'confirmed') not in ('pending', 'confirmed') then
        raise exception 'Unknown payment status: %', p_status;
    end if;

    update sales set
        wave_sender    = nullif(btrim(coalesce(p_sender, '')), ''),
        payment_ref    = nullif(btrim(coalesce(p_ref, '')), ''),
        payment_status = coalesce(p_status, 'confirmed')
    where id = p_sale_id;
end;
$$;

do $$
begin
    if exists (select 1 from pg_roles where rolname = 'authenticated') then
        grant execute on function set_org_wave(uuid, text)                      to authenticated;
        grant execute on function attach_wave_payment(uuid, text, text, text)   to authenticated;
    end if;
end $$;

notify pgrst, 'reload schema';


-- ============================================================
-- 038_trainer_accounts.sql
-- ============================================================
-- ============================================================
-- 038_trainer_accounts.sql — accounts for the people who train the businesses.
--
-- The user hires students to go out and train businesses and their staff on the
-- app. The question was whether each needs a special account and what it should
-- look like. The answer built here: a trainer is an ordinary account marked as
-- a trainer, whom the platform assigns to the specific businesses they help.
-- Inside one of those businesses the trainer sees everything, so they can guide,
-- and can change nothing, so a lesson can never cost the business its data.
--
-- HOW IT REUSES WHAT EXISTS, AND WHY THAT IS THE SAFE CHOICE. A training
-- assignment is a membership with role 'observer' and full visibility, flagged
-- is_trainer. That one modelling choice buys the whole feature from rules that
-- already hold and are already tested:
--   * has_full_visibility() is true → the trainer reads every report and line,
--     which is what advising needs.
--   * can_write_org() excludes 'observer' → the trainer records nothing.
--   * is_org_admin() excludes 'observer' → the trainer cannot rename, archive,
--     delete, or change who owns the business.
-- So no read/write policy is touched; the access is exactly an investor's,
-- narrowed by intent rather than by new plumbing. The is_trainer flag only
-- distinguishes these grants so a business's own team roster can leave them out
-- — a trainer is not the business's staff.
--
-- WHO MAY DO WHAT. Only a platform admin marks an account as a trainer and
-- assigns or unassigns it; a business cannot conscript a trainer, and a trainer
-- cannot enrol themselves. Every function here checks is_platform_admin first.
-- ============================================================

-- ------------------------------------------------------------
-- 1. The flags. On the account: this user is a trainer. On the membership:
--    this grant is a training assignment, not the business's own team.
-- ------------------------------------------------------------
alter table profiles    add column if not exists is_trainer boolean not null default false;
alter table memberships add column if not exists is_trainer boolean not null default false;

-- ------------------------------------------------------------
-- 2. Mark (or unmark) a trainer account, found by the phone the platform admin
--    knows them by. Returns the account id. Unmarking does not touch existing
--    assignments — a paused trainer keeps their history until unassigned.
-- ------------------------------------------------------------
create or replace function set_trainer_by_phone(
    p_phone      text,
    p_is_trainer boolean default true
)
returns uuid
language plpgsql
security definer
set search_path = public, auth
as $$
declare
    v_phone text := nullif(btrim(coalesce(p_phone, '')), '');
    v_user  uuid;
begin
    if not exists (select 1 from profiles where id = auth.uid() and is_platform_admin) then
        raise exception 'Only a platform admin can manage trainers';
    end if;
    if v_phone is null then
        raise exception 'A phone number is required';
    end if;

    select id into v_user from profiles where phone = v_phone;
    if v_user is null then
        raise exception 'No account has the phone %', v_phone;
    end if;

    update profiles set is_trainer = coalesce(p_is_trainer, false) where id = v_user;
    return v_user;
end;
$$;

-- ------------------------------------------------------------
-- 3. Assign a trainer to a business — the observer/full/is_trainer grant.
--    Idempotent: re-assigning re-affirms the grant rather than doubling it.
-- ------------------------------------------------------------
create or replace function assign_trainer(
    p_org_id  uuid,
    p_user_id uuid
)
returns void
language plpgsql
security definer
set search_path = public, auth
as $$
begin
    if not exists (select 1 from profiles where id = auth.uid() and is_platform_admin) then
        raise exception 'Only a platform admin can assign a trainer';
    end if;
    if not exists (select 1 from orgs where id = p_org_id) then
        raise exception 'No such business';
    end if;
    if not exists (select 1 from profiles where id = p_user_id and is_trainer) then
        raise exception 'That account is not a trainer';
    end if;

    insert into memberships (org_id, user_id, role, scope_kind, scope_id,
                             visibility, is_trainer)
    values (p_org_id, p_user_id, 'observer', 'org', p_org_id, 'full', true)
    on conflict (user_id, scope_kind, scope_id, role)
    do update set is_trainer = true, visibility = 'full';
end;
$$;

-- ------------------------------------------------------------
-- 4. Remove a training assignment. Only the training grant is deleted; if the
--    person somehow also holds another role here, that one is untouched.
-- ------------------------------------------------------------
create or replace function unassign_trainer(
    p_org_id  uuid,
    p_user_id uuid
)
returns void
language plpgsql
security definer
set search_path = public, auth
as $$
begin
    if not exists (select 1 from profiles where id = auth.uid() and is_platform_admin) then
        raise exception 'Only a platform admin can unassign a trainer';
    end if;

    delete from memberships
    where org_id = p_org_id
      and user_id = p_user_id
      and role = 'observer'
      and is_trainer;
end;
$$;

-- ------------------------------------------------------------
-- 5. The trainer directory, for the console: every trainer account with how
--    many businesses they currently cover. Platform admin only.
-- ------------------------------------------------------------
create or replace function list_trainers()
returns table (
    user_id     uuid,
    full_name   text,
    phone       text,
    assignments bigint
)
language plpgsql
stable
security definer
set search_path = public, auth
as $$
begin
    if not exists (select 1 from profiles where id = auth.uid() and is_platform_admin) then
        raise exception 'Only a platform admin can list trainers';
    end if;

    return query
    select p.id, p.full_name, p.phone,
           count(m.*) filter (where m.is_trainer)
    from profiles p
    left join memberships m on m.user_id = p.id
    where p.is_trainer
    group by p.id, p.full_name, p.phone
    order by p.full_name nulls last, p.phone;
end;
$$;

-- ------------------------------------------------------------
-- 6. The businesses a trainer covers. A trainer sees their own list; a platform
--    admin may ask for anyone's. Returns nothing to anyone else.
-- ------------------------------------------------------------
create or replace function trainer_orgs(
    p_user_id uuid default null
)
returns table (
    org_id  uuid,
    name    text,
    slug    text,
    profile text
)
language plpgsql
stable
security definer
set search_path = public, auth
as $$
declare
    v_target uuid := coalesce(p_user_id, auth.uid());
begin
    if v_target <> auth.uid()
       and not exists (select 1 from profiles where id = auth.uid() and is_platform_admin) then
        raise exception 'You cannot read another trainer''s businesses';
    end if;

    return query
    select o.id, o.name, o.slug, o.profile
    from memberships m
    join orgs o on o.id = m.org_id
    where m.user_id = v_target
      and m.is_trainer
      and o.archived_at is null
    order by o.name;
end;
$$;

-- ------------------------------------------------------------
-- 7. The trainers on one business — for the console, and for the business's own
--    admin, who is entitled to know who is training them.
-- ------------------------------------------------------------
create or replace function org_trainers(
    p_org_id uuid
)
returns table (
    user_id   uuid,
    full_name text,
    phone     text
)
language plpgsql
stable
security definer
set search_path = public, auth
as $$
begin
    if not exists (select 1 from profiles where id = auth.uid() and is_platform_admin)
       and not is_org_admin(p_org_id) then
        raise exception 'You cannot read this business''s trainers';
    end if;

    return query
    select p.id, p.full_name, p.phone
    from memberships m
    join profiles p on p.id = m.user_id
    where m.org_id = p_org_id
      and m.is_trainer
    order by p.full_name nulls last, p.phone;
end;
$$;

do $$
begin
    if exists (select 1 from pg_roles where rolname = 'authenticated') then
        grant execute on function set_trainer_by_phone(text, boolean) to authenticated;
        grant execute on function assign_trainer(uuid, uuid)          to authenticated;
        grant execute on function unassign_trainer(uuid, uuid)        to authenticated;
        grant execute on function list_trainers()                     to authenticated;
        grant execute on function trainer_orgs(uuid)                  to authenticated;
        grant execute on function org_trainers(uuid)                  to authenticated;
    end if;
end $$;

notify pgrst, 'reload schema';


-- ============================================================
-- 039_currency_rates.sql
-- ============================================================
-- ============================================================
-- 039_currency_rates.sql — a customer pays in their currency; the books stay
-- in the shop's.
--
-- The user's ask: goods are sometimes bought in one currency and customers
-- sometimes hold another, and the person at the till must never do mental
-- arithmetic. The design that keeps everyone unlost: the business's own
-- currency remains the ONLY currency in the ledger, reports and analytics —
-- mixing currencies inside double-entry books produces totals that add francs
-- to dollars — and conversion happens at exactly two moments: when goods come
-- in, and when a customer pays.
--
-- RATES ARE THE OWNER'S, NOT AN API'S. The rate a shop in Ouaga actually gets
-- is the street or bank rate the owner knows, not the internet's mid-market
-- number — and a till in a market with two bars of signal cannot wait on a
-- rate service. So rates live in a per-business table the owner edits in
-- Paramètres, and the till only ever reads them. (EUR↔XOF is a fixed peg the
-- app pre-fills; nothing here hard-codes it, because the owner may still
-- prefer their bank's effective rate.)
--
-- WHAT A FOREIGN-CURRENCY SALE IS. An ordinary sale, booked in the home
-- currency from its lines exactly as before. The only new facts are what cash
-- physically crossed the counter — currency, amount, and the rate used — and
-- they are stamped onto the sale afterwards, the same seam Wave uses (037).
-- They are metadata for the receipt and any later dispute; the ledger amount
-- comes from the lines and can never be steered by them.
-- ============================================================

-- ------------------------------------------------------------
-- 1. The owner's rate table. One row per foreign currency:
--    1 <currency> = <rate> in the business's home currency.
-- ------------------------------------------------------------
create table if not exists org_currency_rates (
    org_id     uuid not null references orgs(id) on delete cascade,
    -- ISO code, stored normalized so 'usd ' can never sit beside 'USD'.
    currency   text not null check (currency ~ '^[A-Z]{3}$'),
    rate       numeric(18,6) not null check (rate > 0),
    updated_by uuid references profiles(id),
    updated_at timestamptz not null default now(),
    primary key (org_id, currency)
);

alter table org_currency_rates enable row level security;

-- Everybody in the business reads the rates — the till needs them to offer the
-- chips. Only admins write them: a cashier must never set the rate they are
-- about to be measured against. Same shape as the feature rules in 031.
drop policy if exists "currency rates readable within org" on org_currency_rates;
create policy "currency rates readable within org"
on org_currency_rates for select using (is_org_member(org_id));

drop policy if exists "currency rates written by admins" on org_currency_rates;
create policy "currency rates written by admins"
on org_currency_rates for all using (is_org_admin(org_id))
with check (is_org_admin(org_id));

-- ------------------------------------------------------------
-- 2. What cash actually crossed the counter, when it was not the home
--    currency. Null on every other sale, so nothing existing changes.
-- ------------------------------------------------------------
alter table sales add column if not exists tendered_currency text
    check (tendered_currency is null or tendered_currency ~ '^[A-Z]{3}$');
alter table sales add column if not exists tendered_amount numeric(14,2)
    check (tendered_amount is null or tendered_amount > 0);
alter table sales add column if not exists tendered_rate numeric(18,6)
    check (tendered_rate is null or tendered_rate > 0);

-- ------------------------------------------------------------
-- 3. Stamp the tender onto a sale — called by the app right after record_sale
--    when the customer paid in a foreign currency. Idempotent; gated by
--    can_write_org on the sale's own org, so whoever may record the sale may
--    describe how it was paid, and nobody may touch another business's sale.
--    record_sale itself is deliberately not rewritten (same reasoning as 037):
--    these three columns are receipt facts, not ledger inputs.
-- ------------------------------------------------------------
create or replace function attach_sale_tender(
    p_sale_id  uuid,
    p_currency text,
    p_amount   numeric,
    p_rate     numeric
)
returns void
language plpgsql
security definer
set search_path = public, auth
as $$
declare
    v_org uuid;
    v_cur text := upper(btrim(coalesce(p_currency, '')));
begin
    if auth.uid() is null then
        raise exception 'attach_sale_tender() needs a signed-in caller';
    end if;

    select org_id into v_org from sales where id = p_sale_id;
    if v_org is null then
        raise exception 'No such sale';
    end if;
    if not can_write_org(v_org) then
        raise exception 'You cannot describe payment for this business';
    end if;
    if v_cur !~ '^[A-Z]{3}$' then
        raise exception 'Unknown currency: %', p_currency;
    end if;
    if coalesce(p_amount, 0) <= 0 or coalesce(p_rate, 0) <= 0 then
        raise exception 'A tender needs a positive amount and rate';
    end if;

    update sales set
        tendered_currency = v_cur,
        tendered_amount   = p_amount,
        tendered_rate     = p_rate
    where id = p_sale_id;
end;
$$;

do $$
begin
    if exists (select 1 from pg_roles where rolname = 'authenticated') then
        grant select, insert, update, delete on org_currency_rates to authenticated;
        grant execute on function attach_sale_tender(uuid, text, numeric, numeric) to authenticated;
    end if;
end $$;

notify pgrst, 'reload schema';


-- ============================================================
-- 040_invoice_revision.sql
-- ============================================================
-- ============================================================
-- 040_invoice_revision.sql — the owner corrects an invoice.
--
-- An invoice is not a row to edit: creating one posted income and a
-- receivable into the ledger (020), so silently rewriting its lines would
-- leave a document that disagrees with the books it came from. The correct
-- correction — the one an accountant would make — is to withdraw the wrong
-- document and issue a right one, and cancel_invoice already knows how to
-- withdraw (it contre-passes the entry and refuses an invoice money has
-- already arrived against).
--
-- So revise_invoice is exactly that, in one transaction: cancel the old,
-- create the new, and say on the new document which one it replaces. One
-- call, because two calls from a phone that loses signal in between would
-- leave a business with a cancelled invoice and no replacement.
--
-- Admin-only, deliberately tighter than cancel_invoice's can_write_org: the
-- employee who may bill a customer does not get to rewrite what was already
-- billed — that is the owner's pen.
-- ============================================================

create or replace function revise_invoice(
    p_invoice_id       uuid,
    p_customer_name    text,
    p_lines            jsonb,
    p_customer_phone   text default null,
    p_customer_address text default null,
    p_due_on           date default null,
    p_due_days         int  default null,
    p_memo             text default null,
    p_issued_on        date default current_date
)
returns uuid
language plpgsql
security definer
set search_path = public, auth
as $$
declare
    v_actor      uuid := auth.uid();
    v_org        uuid;
    v_old_number text;
    v_cancelled  timestamptz;
    v_memo       text;
    v_new        uuid;
begin
    if v_actor is null then
        raise exception 'revise_invoice() needs a signed-in caller';
    end if;

    select org_id, number, cancelled_at
      into v_org, v_old_number, v_cancelled
      from invoices where id = p_invoice_id;

    if v_org is null then
        raise exception 'No such invoice';
    end if;
    if not is_org_admin(v_org) then
        raise exception 'Only an administrator can revise an invoice';
    end if;
    if v_cancelled is not null then
        raise exception
            'Invoice % is already cancelled. Issue a new invoice instead.',
            v_old_number;
    end if;

    -- Withdraws the old document and contre-passes its entry; refuses when
    -- money has already arrived against it, with a message that says what to
    -- do instead. Its own checks run in this same transaction.
    perform cancel_invoice(p_invoice_id,
                           'Remplacée par une facture corrigée');

    -- The replacement carries its own (next) number — a corrected invoice is
    -- a new document, not history rewritten — and names the one it replaces.
    v_memo := nullif(btrim(coalesce(p_memo, '')), '');
    v_memo := coalesce(v_memo || ' — ', '')
              || 'Remplace la facture ' || v_old_number;

    v_new := create_invoice(
        p_org_id           => v_org,
        p_customer_name    => p_customer_name,
        p_lines            => p_lines,
        p_customer_phone   => p_customer_phone,
        p_customer_address => p_customer_address,
        p_due_on           => p_due_on,
        p_due_days         => p_due_days,
        p_memo             => v_memo,
        p_issued_on        => p_issued_on
    );

    return v_new;
end;
$$;

do $$
begin
    if exists (select 1 from pg_roles where rolname = 'authenticated') then
        grant execute on function revise_invoice(
            uuid, text, jsonb, text, text, date, int, text, date
        ) to authenticated;
    end if;
end $$;

notify pgrst, 'reload schema';


-- ============================================================
-- 041_platform_admin_edit.sql
-- ============================================================
-- ============================================================
-- 041_platform_admin_edit.sql — a platform admin can edit again.
--
-- THE BUG. is_org_admin(), is_org_member() and can_write_org() (010) all treat
-- a platform admin as full-access — they carry an explicit is_platform_admin
-- clause. But two guards written later were never given the same clause:
--   * feature_access() (031) returns 'hidden' when the caller has no
--     membership in the org — which a platform admin managing a business from
--     the console does not.
--   * has_full_visibility() (006) is likewise membership-only.
--
-- The products UPDATE policy (031) is `can_write_org AND feature_access =
-- 'edit'`. For a platform admin that is `true AND 'hidden'` → the row does not
-- match, and PostgREST reports a successful UPDATE of zero rows. The app sees
-- no error and reloads the unchanged product: "editing an article does
-- nothing." The same gap silently blocks a platform admin from adding a credit,
-- running production, or recording a repayment (the trg_guard_feature_edit
-- triggers), and refuses them a business's owner-analytics and report line
-- items (has_full_visibility).
--
-- THE FIX. Give both functions the platform-admin clause the other guards have,
-- so full access is decided the same way everywhere. Each body is the LATEST
-- version of the function verbatim — feature_access from 032, has_full_visibility
-- from 006 — apart from that one added branch. Rebuilding from an older copy
-- would silently revert whatever landed in between; 032 hardened the anonymous
-- answer to 'hidden' and made 'reports' default to 'view', and both stay.
-- ============================================================

-- feature_access: a platform admin edits everything, as they can already read
-- and administer everything. This is 032 verbatim with one branch added.
create or replace function feature_access(p_org_id uuid, p_feature text)
returns text
language plpgsql
stable
security definer
set search_path = public, auth
as $$
declare
    v_roles  text[];
    v_tier   text;
    v_access text;
begin
    -- No session: fail closed, as 032 made it. A permission function's answer
    -- for "nobody signed in" must never be its most-open one.
    if auth.uid() is null then
        return 'hidden';
    end if;

    -- The clause is_org_admin/can_write_org already carry, missing here until
    -- now: the platform runs the platform. After the anon check, so a session
    -- is still required to reach it.
    if exists (select 1 from profiles where id = auth.uid() and is_platform_admin) then
        return 'edit';
    end if;

    select array_agg(distinct role) into v_roles
      from memberships
     where org_id = p_org_id and user_id = auth.uid();

    if v_roles is null then
        return 'hidden';
    end if;
    if v_roles && array['owner', 'super_admin', 'admin'] then
        return 'edit';
    end if;

    v_tier := case
        when v_roles && array['manager', 'supervisor'] then 'supervisor'
        else 'employee'
    end;

    select access into v_access
      from org_feature_rules
     where org_id = p_org_id and tier = v_tier and feature = p_feature;

    -- No rule set: full access by default, so a business that never touched
    -- the dial works exactly as before 031 — except reports, which 032
    -- defaults to 'view'. Keep both; reverting either is a silent change.
    return coalesce(v_access,
        case when p_feature = 'reports' then 'view' else 'edit' end);
end;
$$;

-- has_full_visibility: a platform admin sees every figure — the same posture as
-- is_org_member, which they already pass.
create or replace function has_full_visibility(p_org_id uuid)
returns boolean
language sql
stable
security definer
set search_path = public, auth
as $$
    select
        exists (select 1 from profiles where id = auth.uid() and is_platform_admin)
        or exists (
            select 1 from memberships m
            where m.user_id = auth.uid()
              and m.org_id = p_org_id
              and m.visibility = 'full'
        );
$$;

notify pgrst, 'reload schema';


-- ============================================================
-- 042_corrections.sql
-- ============================================================
-- ============================================================
-- 042_corrections.sql — undo a transaction the honest way: a reversal, not a
-- deletion.
--
-- The report: a shop was tested with a few sales and purchases; deleting the
-- article afterwards left the money in the books, because deleting a product
-- (archive_product) only takes it off the shelf and never touches the ledger.
-- That is correct — history is permanent here — but it left no sanctioned way
-- to undo a transaction, so the only tool reached for was the wrong one.
--
-- The right tool is a reversal: a compensating movement, dated now, that
-- cancels the original in both places it lives — the stock count AND the
-- ledger — so accounting, analysis and reports all correct themselves from
-- today rather than rewriting the past. A sale already has one (record_return,
-- 011). A manual entry already has one (reverse_entry, 002). The gap is a
-- delivery: stock_receipts is append-only with no reversal at all. This adds
-- it, and the two read functions the corrections screen lists from.
-- ============================================================

-- A delivery can now carry the mark of its own reversal. Not an edit of the
-- delivery — the quantity and cost it recorded stay exactly as they were — a
-- stamp that says "a compensating movement has cancelled this", so it cannot
-- be reversed twice and the screen can show it struck through.
alter table stock_receipts
    add column if not exists reversed_at timestamptz;
alter table stock_receipts
    add column if not exists reversed_by uuid references profiles(id);

-- reverse_receipt: put a delivery back the way it came in.
--
-- Owner/admin only — the same posture as archiving a product. A clerk records
-- deliveries and returns at the counter; unwinding a purchase after the fact
-- is a correction, and corrections belong to whoever answers for the books.
create or replace function reverse_receipt(
    p_receipt_id uuid,
    p_reason     text default null
)
returns uuid  -- the reversing ledger entry, or null when the delivery booked none
language plpgsql
security definer
set search_path = public, auth
as $$
declare
    v_actor uuid := auth.uid();
    v_rec   stock_receipts%rowtype;
    v_rev   uuid;
begin
    if v_actor is null then
        raise exception 'reverse_receipt() needs a signed-in caller';
    end if;

    select * into v_rec from stock_receipts where id = p_receipt_id;
    if v_rec.id is null then
        raise exception 'No such delivery';
    end if;

    if not is_org_admin(v_rec.org_id) then
        raise exception 'Only an owner or admin can reverse a delivery';
    end if;

    if v_rec.reversed_at is not null then
        raise exception 'That delivery has already been reversed';
    end if;

    -- Take back exactly what this delivery added. Stock may go negative, as it
    -- may on a sale (011): a reversal that drives the count below zero is the
    -- true statement that the goods have since moved, not a reason to refuse.
    update products set quantity = quantity - v_rec.quantity
     where id = v_rec.product_id;

    -- Unwind the purchase in the books, if it posted one. reverse_entry swaps
    -- the debits and credits into a new entry dated now, so the correction
    -- lands in the current period and every report built on the ledger nets
    -- to zero without excluding anything.
    if v_rec.entry_id is not null then
        v_rev := reverse_entry(v_rec.entry_id, v_actor,
                               coalesce(p_reason, 'Correction'));
    end if;

    update stock_receipts
       set reversed_at = now(), reversed_by = v_actor
     where id = p_receipt_id;

    return v_rev;
end;
$$;

-- recent_deliveries, now carrying whether each has been reversed, so the
-- corrections screen can strike the undone ones through and hide their button.
-- Otherwise 016 verbatim. Dropped first: adding a column to the returned table
-- changes the return type, which `create or replace` cannot do.
drop function if exists recent_deliveries(uuid, int);
create or replace function recent_deliveries(
    p_org_id uuid,
    p_limit  int default 50
)
returns table (
    id           uuid,
    product_id   uuid,
    product_name text,
    quantity     numeric,
    unit_cost    numeric,
    line_total   numeric,
    received_at  timestamptz,
    received_by  text,
    reversed     boolean
)
language sql
stable
security invoker
set search_path = public
as $$
    select r.id, r.product_id, p.name, r.quantity, r.unit_cost,
           r.quantity * r.unit_cost, r.received_at, pr.full_name,
           r.reversed_at is not null
    from stock_receipts r
    join products p on p.id = r.product_id
    left join profiles pr on pr.id = r.received_by
    where r.org_id = p_org_id
    order by r.received_at desc, r.id desc
    limit greatest(coalesce(p_limit, 50), 1);
$$;

-- recent_sales: the other half of the corrections screen. One row per sale,
-- newest first, carrying what a person needs to recognise it and whether it
-- has already been returned. Security invoker and gated on full visibility,
-- the same rule sales themselves read under (011): the money is a line item,
-- not a total.
create or replace function recent_sales(
    p_org_id uuid,
    p_limit  int default 50
)
returns table (
    id          uuid,
    kind        text,
    method      text,
    total       numeric,
    note        text,
    occurred_at timestamptz,
    sold_by     text,
    reversed    boolean
)
language sql
stable
security invoker
set search_path = public
as $$
    select s.id, s.kind, s.method, s.total, s.note, s.occurred_at, pr.full_name,
           exists (select 1 from sales r where r.reverses_id = s.id)
    from sales s
    left join profiles pr on pr.id = s.recorded_by
    where s.org_id = p_org_id
      and s.kind <> 'return'
    order by s.occurred_at desc, s.id desc
    limit greatest(coalesce(p_limit, 50), 1);
$$;

-- ------------------------------------------------------------
-- GRANTS
-- ------------------------------------------------------------
revoke execute on function reverse_receipt(uuid, text) from public;

do $$
begin
    if exists (select 1 from pg_roles where rolname = 'authenticated') then
        grant execute on function reverse_receipt(uuid, text) to authenticated;
        grant execute on function recent_sales(uuid, int) to authenticated;
    end if;
end $$;

notify pgrst, 'reload schema';


-- ============================================================
-- 043_analytics_net_returns.sql
-- ============================================================
-- ============================================================
-- 043_analytics_net_returns.sql — a corrected sale leaves the analytics.
--
-- The report: an owner reversed a sale in the corrections screen and the
-- analytics did not move — "they are not connected". They were not: every
-- function in 036 filters `kind = 'sale'` and stops there, so it counts the
-- original sale and ignores the `kind = 'return'` row that cancels it. The
-- ledger nets a reversal (reverse_entry posts a compensating entry) and the
-- day total nets it (store_day subtracts returns), but the analytics — what
-- sells, the revenue, the trend, the busy hours — did not.
--
-- record_return reverses a sale in full (it copies every line and sets
-- reverses_id), so there is no partial return to reason about: a reversed sale
-- is entirely cancelled. The fix is therefore one predicate, added to each
-- function's `kind = 'sale'` filter — drop any sale that has a reversal:
--
--     and not exists (select 1 from sales r where r.reverses_id = sa.id)
--
-- Bodies are 036 verbatim apart from that one added line. No return type
-- changes, so a plain create-or-replace stands.
-- ============================================================

create or replace function org_sales_headline(
    p_org_id uuid,
    p_since  timestamptz default null
)
returns table (
    sale_count      bigint,
    revenue         numeric,
    cost            numeric,
    margin          numeric,
    units           numeric,
    avg_basket      numeric,
    products_sold   bigint
)
language plpgsql
stable
security invoker
set search_path = public
as $$
begin
    if not has_full_visibility(p_org_id) then
        raise exception 'You cannot read this business''s analytics';
    end if;

    return query
    with s as (
        select sa.id, sa.total
        from sales sa
        where sa.org_id = p_org_id
          and sa.kind = 'sale'
          and not exists (select 1 from sales r where r.reverses_id = sa.id)
          and (p_since is null or sa.occurred_at >= p_since)
    ),
    lines as (
        select sl.quantity, sl.unit_cost, sl.line_total, sl.name
        from sale_lines sl
        join s on s.id = sl.sale_id
    )
    select
        (select count(*) from s),
        coalesce((select sum(total) from s), 0),
        coalesce((select sum(quantity * unit_cost) from lines), 0),
        coalesce((select sum(line_total) from lines), 0)
            - coalesce((select sum(quantity * unit_cost) from lines), 0),
        coalesce((select sum(quantity) from lines), 0),
        case when (select count(*) from s) = 0 then 0
             else round(coalesce((select sum(total) from s), 0)
                  / (select count(*) from s), 2) end,
        (select count(distinct lower(btrim(name))) from lines);
end;
$$;

create or replace function org_product_performance(
    p_org_id uuid,
    p_since  timestamptz default null,
    p_limit  int default 100
)
returns table (
    name          text,
    units         numeric,
    revenue       numeric,
    margin        numeric,
    sale_count    bigint,
    first_sold    timestamptz,
    last_sold     timestamptz,
    per_day       numeric
)
language plpgsql
stable
security invoker
set search_path = public
as $$
begin
    if not has_full_visibility(p_org_id) then
        raise exception 'You cannot read this business''s analytics';
    end if;

    return query
    with lines as (
        select lower(btrim(sl.name)) as key,
               sl.name as raw_name,
               sl.quantity, sl.unit_cost, sl.line_total, sa.occurred_at
        from sale_lines sl
        join sales sa on sa.id = sl.sale_id
        where sa.org_id = p_org_id
          and sa.kind = 'sale'
          and not exists (select 1 from sales r where r.reverses_id = sa.id)
          and (p_since is null or sa.occurred_at >= p_since)
    )
    select
        min(raw_name),
        sum(quantity),
        sum(line_total),
        sum(line_total) - sum(quantity * unit_cost),
        count(*),
        min(occurred_at),
        max(occurred_at),
        round(
            sum(quantity)
            / greatest(1, extract(epoch from (max(occurred_at) - min(occurred_at))) / 86400.0),
            2
        )
    from lines
    group by key
    order by 3 desc
    limit greatest(1, p_limit);
end;
$$;

create or replace function org_sales_by_hour(
    p_org_id uuid,
    p_since  timestamptz default null
)
returns table (
    hour        int,
    sale_count  bigint,
    revenue     numeric
)
language plpgsql
stable
security invoker
set search_path = public
as $$
begin
    if not has_full_visibility(p_org_id) then
        raise exception 'You cannot read this business''s analytics';
    end if;

    return query
    select
        extract(hour from sa.occurred_at)::int,
        count(*),
        coalesce(sum(sa.total), 0)
    from sales sa
    where sa.org_id = p_org_id
      and sa.kind = 'sale'
      and not exists (select 1 from sales r where r.reverses_id = sa.id)
      and (p_since is null or sa.occurred_at >= p_since)
