-- ============================================================
-- 044_account_management.sql
-- ============================================================
-- ============================================================
-- 044_account_management.sql — an admin manages the people in their business.
--
-- The People screen could invite and remove. This adds the rest of a real
-- account manager: change someone's responsibility (their role), and the two
-- authorisation checks a separate service-role Worker forwards here before it
-- resets a password or deletes an account. The Worker holds the service-role
-- key; it never decides who may use it — it asks Postgres, as the caller,
-- exactly the way the uploads Worker asks "are you a member of this org".
--
-- Owners are protected throughout: an owner's role cannot be reassigned and an
-- owner cannot be deleted, because either would leave a business no one can
-- administer. Transferring ownership or deleting the business come first.
-- ============================================================

-- Change a member's responsibility. Admin of that member's org only (which
-- includes a platform admin, via is_org_admin). Not the owner — reassigning the
-- owner's role is how a business loses its last administrator — and not *to*
-- owner, since minting a second owner is a transfer, not a role change.
create or replace function set_membership_role(
    p_membership_id uuid,
    p_role          role_name
)
returns void
language plpgsql
security definer
set search_path = public, auth
as $$
declare
    v_org  uuid;
    v_role role_name;
begin
    if auth.uid() is null then
        raise exception 'set_membership_role() needs a signed-in caller';
    end if;

    select org_id, role into v_org, v_role
    from memberships where id = p_membership_id;
    if v_org is null then
        raise exception 'No such membership';
    end if;

    if not is_org_admin(v_org) then
        raise exception 'Only an owner or admin can change a role';
    end if;
    if v_role = 'owner' then
        raise exception 'The owner''s role cannot be changed here';
    end if;
    if p_role = 'owner' then
        raise exception 'Use a transfer of ownership, not a role change';
    end if;

    update memberships set role = p_role where id = p_membership_id;
end;
$$;

-- Whether the caller may reset this user's password: a platform admin, or an
-- admin of some business the target belongs to. Read by the account Worker,
-- as the caller, before it uses the service-role key.
create or replace function manages_user(p_user_id uuid)
returns boolean
language sql
stable
security definer
set search_path = public, auth
as $$
    select
        exists (select 1 from profiles
                where id = auth.uid() and is_platform_admin)
        or exists (
            select 1
            from memberships me
            join memberships them on them.org_id = me.org_id
            where me.user_id = auth.uid()
              and me.role in ('owner', 'super_admin', 'admin')
              and them.user_id = p_user_id
        );
$$;

-- Whether the caller may delete this user's account outright. Stricter than
-- managing them, because deletion is global — it removes the person from every
-- business, not only the caller's:
--
--   * an owner of any business is never deletable here (the business would be
--     orphaned); transfer or delete the business first;
--   * a platform admin may delete anyone else;
--   * a business admin may delete someone only if every business that person
--     belongs to is one this caller administers — so a deletion can never
--     reach into a business the caller has no authority over.
create or replace function can_delete_user(p_user_id uuid)
returns boolean
language sql
stable
security definer
set search_path = public, auth
as $$
    select
        p_user_id <> auth.uid()
        and not exists (
            select 1 from memberships where user_id = p_user_id and role = 'owner'
        )
        and (
            exists (select 1 from profiles
                    where id = auth.uid() and is_platform_admin)
            or (
                manages_user(p_user_id)
                and not exists (
                    select 1 from memberships t
                    where t.user_id = p_user_id
                      and not is_org_admin(t.org_id)
                )
            )
        );
$$;

-- ------------------------------------------------------------
-- GRANTS
-- ------------------------------------------------------------
revoke execute on function set_membership_role(uuid, role_name) from public;

do $$
begin
    if exists (select 1 from pg_roles where rolname = 'authenticated') then
        grant execute on function set_membership_role(uuid, role_name) to authenticated;
        grant execute on function manages_user(uuid)    to authenticated;
        grant execute on function can_delete_user(uuid) to authenticated;
    end if;
end $$;

notify pgrst, 'reload schema';


-- ============================================================
-- 045_account_rank.sql
-- ============================================================
-- ============================================================
-- 045_account_rank.sql — password resets and role changes follow the hierarchy.
--
-- 044 let any admin of a shared business reset any co-member's password and
-- change any non-owner's role. The owner asked for rank, and named the order:
-- super_admin is Kaj's own platform staff and sits above a store's owner; the
-- owner is the top of their own store, above the admins they appoint; an admin
-- reaches the responsables and staff beneath them. So a super_admin reaches an
-- owner and everyone below, an owner reaches the admins and below, an admin the
-- responsables and staff — and no one a peer or someone above them. The
-- platform's own is_platform_admin flag stays above all of this and bypasses
-- it. The same order governs who may reassign whose responsibility.
--
-- The rule is one comparison against a rank ladder. manages_user() is what the
-- account Worker asks before it resets a password, and what can_delete_user()
-- (unchanged) is built on — so a deletion inherits the same ceiling. Bodies are
-- 044 verbatim apart from the rank clause.
-- ============================================================

-- The ladder. Higher manages lower; equal manages neither. super_admin is
-- Kaj's platform staff and sits above a store's owner; the owner is the top of
-- their own store. An unknown role ranks at the bottom, so it can manage no one
-- and is managed by any admin.
create or replace function role_rank(p_role role_name)
returns int
language sql
immutable
as $$
    select case p_role
        when 'super_admin' then 100
        when 'owner'       then 90
        when 'admin'       then 80
        when 'manager'     then 60
        when 'supervisor'  then 50
        when 'approver'    then 40
        when 'employee'    then 30
        when 'observer'    then 20
        else 0
    end;
$$;

-- Whether the caller may reset this user's password: a platform admin, or an
-- admin of a shared business who outranks the target's highest role anywhere.
-- The "highest role anywhere" is deliberate: it stops an admin of a small shop
-- resetting the login of someone who is a super_admin or owner in another
-- business, since the password is one global credential, not a per-org one.
create or replace function manages_user(p_user_id uuid)
returns boolean
language sql
stable
security definer
set search_path = public, auth
as $$
    select
        exists (select 1 from profiles
                where id = auth.uid() and is_platform_admin)
        or exists (
            select 1
            from memberships me
            where me.user_id = auth.uid()
              and me.role in ('owner', 'super_admin', 'admin')
              and me.org_id in (
                  select org_id from memberships where user_id = p_user_id
              )
              and role_rank(me.role) > (
                  select coalesce(max(role_rank(t.role)), 0)
                  from memberships t where t.user_id = p_user_id
              )
        );
$$;

-- Change a member's responsibility — now rank-bound. 044's guards stay (admin
-- of the org, never the owner's role, never *to* owner); added: the caller must
-- outrank both the role held and the role assigned, so an admin can shuffle the
-- staff and responsables below them but cannot touch a peer, promote anyone to
-- their own level, or lift themselves. A platform admin, who holds no
-- membership, runs the platform and is exempt from the rank test.
create or replace function set_membership_role(
    p_membership_id uuid,
    p_role          role_name
)
returns void
language plpgsql
security definer
set search_path = public, auth
as $$
declare
    v_org         uuid;
    v_role        role_name;
    v_caller_rank int;
begin
    if auth.uid() is null then
        raise exception 'set_membership_role() needs a signed-in caller';
    end if;

    select org_id, role into v_org, v_role
    from memberships where id = p_membership_id;
    if v_org is null then
        raise exception 'No such membership';
    end if;

    if not is_org_admin(v_org) then
        raise exception 'Only an owner or admin can change a role';
    end if;
    if v_role = 'owner' then
        raise exception 'The owner''s role cannot be changed here';
    end if;
    if p_role = 'owner' then
        raise exception 'Use a transfer of ownership, not a role change';
    end if;

    if not exists (select 1 from profiles
                   where id = auth.uid() and is_platform_admin) then
        select coalesce(max(role_rank(m.role)), 0) into v_caller_rank
        from memberships m
        where m.org_id = v_org and m.user_id = auth.uid();

        if v_caller_rank <= role_rank(v_role)
           or v_caller_rank <= role_rank(p_role) then
            raise exception 'You can only assign a responsibility below your own';
        end if;
    end if;

    update memberships set role = p_role where id = p_membership_id;
end;
$$;

notify pgrst, 'reload schema';


-- ============================================================
-- 046_admin_edit_member.sql
-- ============================================================
-- ============================================================
-- 046_admin_edit_member.sql — an admin edits a member's own information.
--
-- profiles are editable by their owner alone (004): a person fixes the spelling
-- of their own name. The owner asked for the People tab to let an admin see and
-- edit everyone's information. Seeing already works — the profiles select policy
-- lets colleagues read one another — so this adds only the edit, through one
-- SECURITY DEFINER function so no table policy has to be widened.
--
-- Who may edit whom follows the same ladder as a password reset: the function
-- is gated by manages_user() (045), so an admin reaches the staff and the
-- responsables beneath them, a super_admin the admins and below, an owner
-- everyone — and no one a peer or someone above. Body mirrors save_my_profile
-- (017): the same name assembly, the same friendly phone-collision message.
-- ============================================================

create or replace function admin_save_member_profile(
    p_user_id       uuid,
    p_first_name    text,
    p_last_name     text,
    p_middle_name   text default null,
    p_date_of_birth date default null,
    p_title         text default null,
    p_phone         text default null
)
returns void
language plpgsql
security definer
set search_path = public, auth
as $$
declare
    v_first text := nullif(btrim(coalesce(p_first_name, '')), '');
    v_last  text := nullif(btrim(coalesce(p_last_name, '')), '');
    v_mid   text := nullif(btrim(coalesce(p_middle_name, '')), '');
    v_phone text := nullif(btrim(coalesce(p_phone, '')), '');
    v_full  text;
begin
    if auth.uid() is null then
        raise exception 'admin_save_member_profile() needs a signed-in caller';
    end if;

    -- The whole authorisation, and it is the ladder: a caller may edit only
    -- someone they outrank. manages_user() is false for oneself, so an admin
    -- fixes their own details through the personal form, not here.
    if not manages_user(p_user_id) then
        raise exception 'Vous ne pouvez pas modifier les informations de ce compte.';
    end if;

    if v_first is null or v_last is null then
        raise exception 'Un prénom et un nom de famille sont requis.';
    end if;

    -- full_name stays the one field every screen reads, assembled from the
    -- parts so it never drifts out of step (family name last, as written here).
    v_full := btrim(concat_ws(' ', v_first, v_mid, v_last));

    -- A number already on another account is a mistyped digit far more often
    -- than a real collision; answer in words, not with a constraint name.
    if v_phone is not null and exists (
        select 1 from profiles where phone = v_phone and id <> p_user_id
    ) then
        raise exception 'Ce numéro est déjà utilisé par un autre compte.';
    end if;

    update profiles set
        first_name    = v_first,
        middle_name   = v_mid,
        last_name     = v_last,
        full_name     = v_full,
        date_of_birth = coalesce(p_date_of_birth, date_of_birth),
        title         = coalesce(nullif(btrim(coalesce(p_title, '')), ''), title),
        phone         = coalesce(v_phone, phone)
    where id = p_user_id;
end;
$$;

do $$
begin
    if exists (select 1 from pg_roles where rolname = 'authenticated') then
        grant execute on function admin_save_member_profile(uuid, text, text, text, date, text, text)
            to authenticated;
    end if;
end $$;

notify pgrst, 'reload schema';


-- ============================================================
-- 047_platform_people.sql
-- ============================================================
-- ============================================================
-- 047_platform_people.sql — the platform admin's global directory of people.
--
-- The console is business-first: it can find a business, but not a person. To
-- moderate the platform you need the other axis — search any account across
-- every business, see where they appear and as what, and act (reset a password
-- and delete an account through the existing account Worker; grant or revoke
-- platform access here). All three functions are platform-admin only and cross
-- every tenant on purpose, so — like the console's own reads (036) — the
-- is_platform_admin gate is the whole guard and is checked first.
-- ============================================================

-- Search every account by name, phone or email. Empty query lists everyone,
-- newest-relevant first. email lives on auth.users, which only a definer
-- function may read — one more reason this is not a view.
create or replace function platform_people(
    p_query  text default null,
    p_limit  int  default 50,
    p_offset int  default 0
)
returns table (
    user_id           uuid,
    full_name         text,
    phone             text,
    email             text,
    title             text,
    is_platform_admin boolean,
    business_count    bigint,
    created_at        timestamptz
)
language plpgsql
stable
security definer
set search_path = public, auth
as $$
declare
    v_q text := nullif(btrim(coalesce(p_query, '')), '');
begin
    -- Qualified: this function returns a column also named is_platform_admin,
    -- so a bare reference here is ambiguous.
    if not exists (select 1 from profiles
                   where profiles.id = auth.uid()
                     and profiles.is_platform_admin) then
        raise exception 'Only a platform admin can list people';
    end if;

    return query
    select
        p.id,
        p.full_name,
        p.phone,
        u.email,
        p.title,
        p.is_platform_admin,
        (select count(distinct m.org_id) from memberships m where m.user_id = p.id),
        p.created_at
    from profiles p
    join auth.users u on u.id = p.id
    where v_q is null
       or p.full_name ilike '%' || v_q || '%'
       or p.phone     ilike '%' || v_q || '%'
       or u.email     ilike '%' || v_q || '%'
    order by coalesce(p.full_name, u.email, p.phone) nulls last
    limit greatest(1, least(coalesce(p_limit, 50), 200))
    offset greatest(0, coalesce(p_offset, 0));
end;
$$;

-- The businesses one person belongs to, and their role in each — the footprint
-- a moderator wants before they act on an account.
create or replace function platform_user_orgs(p_user_id uuid)
returns table (
    org_id   uuid,
    org_name text,
    profile  text,
    role     role_name,
    archived boolean
)
language plpgsql
stable
security definer
set search_path = public, auth
as $$
begin
    if not exists (select 1 from profiles
                   where id = auth.uid() and is_platform_admin) then
        raise exception 'Only a platform admin can read a person''s businesses';
    end if;

    return query
    select o.id, o.name, o.profile, m.role, (o.archived_at is not null)
    from memberships m
    join orgs o on o.id = m.org_id
    where m.user_id = p_user_id
    order by o.name;
end;
$$;

-- Grant or revoke platform access. Platform admin only (the guard trigger from
-- 032 enforces the same, so this is belt and braces); never on oneself, so a
-- misclick cannot lock the platform's operator out of their own console.
create or replace function set_platform_admin(p_user_id uuid, p_value boolean)
returns void
language plpgsql
security definer
set search_path = public, auth
as $$
begin
    if not exists (select 1 from profiles
                   where id = auth.uid() and is_platform_admin) then
        raise exception 'Only a platform admin can grant or revoke platform access';
    end if;
    if p_user_id = auth.uid() then
        raise exception 'You cannot change your own platform access';
    end if;
    if not exists (select 1 from profiles where id = p_user_id) then
        raise exception 'No such account';
    end if;

    update profiles set is_platform_admin = coalesce(p_value, false)
     where id = p_user_id;
end;
$$;

do $$
begin
    if exists (select 1 from pg_roles where rolname = 'authenticated') then
        grant execute on function platform_people(text, int, int)   to authenticated;
        grant execute on function platform_user_orgs(uuid)          to authenticated;
        grant execute on function set_platform_admin(uuid, boolean) to authenticated;
    end if;
end $$;

notify pgrst, 'reload schema';


commit;

-- ------------------------------------------------------------
-- PostgREST caches the list of functions it will expose. Without this it
-- can keep answering "Could not find the function ... in the schema cache"
-- for a minute or so after the functions exist.
-- ------------------------------------------------------------
notify pgrst, 'reload schema';
